        \includegraphics[width=0.75\linewidth]{feyn.pdf}
\caption{\label{fig:feyn} Examples of spin configurations of the longitudinal and transverse photon channels
at $\theta =\frac{\pi}{2}$ ($z = 0$) and the production threshold $\beta = 0$.}
\end{figure}

For the longitudinal polarization contribution, we find that the coefficient
matrix $C$ is given by
\begin{eqnarray}
     &&  C =   \begin{pmatrix} 
                1 & 0 & 0 \\
                0 & -\chi_1& -\chi_2\\
                0 & -\chi_2& \chi_1       
        \end{pmatrix}\\
%\begin{align}
       \text{with} \quad
      &&   \chi_1 =\frac{1-2z^2+z^2 \beta^2}{1-z^2 \beta^2}, \\ 
     &&    \chi_2 =\frac{2z \sqrt{(1-z^2)(1-\beta^2)}}{1-z^2 \beta^2}.
%\end{align}
\end{eqnarray}
Note that $ \chi_1^2+\chi_2^2 = 1$.
In this case, the concurrence $\mathcal C[\rho_L] \equiv 1$ and the nonlocality measure $\mathcal{N} [\rho_L] =1$,
indicating maximal entanglement and maximal violation of Bell inequality. We find that the quark pair in a maximally entangled spin triplet state and the corresponding density matrix is always in the form of a pure state $\rho_L = \ket{\Psi} \bra{\Psi}$, where 
\begin{equation}
        \ket{\Psi} = \frac{1}{2}(\sqrt{1+\chi_1}, \mathrm i \sqrt{1-\chi_1}, 
        \mathrm i \sqrt{1-\chi_1}, \sqrt{1+\chi_1} ). 
\end{equation}
For example as illustrated in Fig.~\ref{fig:feyn}, when $z=0$ ($\theta = \pi/2$), one finds $C=\mathrm{diag}(1,-1,1)$, which indicates $\ket{\Psi} = \ket{\Phi^+}$ and
$\rho_L = \ket{\Phi^+} \bra{\Phi^+}$ 
where $\ket{\Phi^+}= (\ket{\uparrow \uparrow}+\ket{\downarrow \downarrow}) 
/\sqrt{2}$. Interestingly, we also find the same $\rho$ for $\beta =1$ as in the relativistic limit. 

