\section{Results}\label{sec.res}

\begin{definition}[Uniform random dictatorship]\label{p}
    The \emph{uniform random dictatorship} $\varphi$ assigns to every voter equal probability of being a dictator. Formally,
\begin{equation}\label{def}
    \varphi=(1/n)\sum_{i\in N}d_i
\end{equation}
\end{definition}

Given any number $\tau\in\mathbb{N}$, any profile $P\in\mathcal{P}(A_\tau)$, and any alternative $x\in A_\tau$; let $N(x,P)=\{i\in N\mid(\forall y\in A_\tau\backslash\{x\})(x P_iy)\}$ be the \emph{set of all voters for whom alternative $x$ is top-ranked at profile $P$}, and let $n(x,P)=|N(x,P)|$ be \emph{its cardinality}. Then, given any number $\tau\in\mathbb{N}$, any profile $P\in\mathcal{P}(A_\tau)$, and any alternative $x\in A_\tau$;
\begin{equation}\label{obv}
    \varphi(P)(\{x\})=(1/n)n(x,P)
\end{equation}

\begin{theorem}\label{th}
    An \hyperref[a]{anonymous}, \hyperref[o]{optimal}, \hyperref[m]{monotonic}, and \hyperref[n]{neutral} voting rule is \hyperref[s]{self-equivalent} if and only if it is the \hyperref[p]{uniform random dictatorship}. Formally,
\begin{equation}
    (\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n)\Rightarrow[(\sigma\in\Sigma_s)\iff(\sigma=\varphi)]
\end{equation}
\end{theorem}

\begin{proof}\label{proof.th}
    There are three statements to show:
\begin{enumerate}
    \item $\varphi\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n$,
    \item $(\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n)\Rightarrow[(\sigma=\varphi)\Rightarrow(\sigma\in\Sigma_s)]$,
    \item $(\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n)\Rightarrow[(\sigma\in\Sigma_s)\Rightarrow(\sigma=\varphi)]$.
\end{enumerate}
\vspace{\parskip}

\begin{statement}\label{s1}
    $\varphi\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n$.
\end{statement}

\begin{claim}\label{cl11}
    $\varphi\in\Sigma_a$.
\end{claim}

    The proof is direct. Consider any number $\tau\in\mathbb{N}$, any permutation $\pi\in\Pi$, any profile $P\in\mathcal{P}(A_\tau)$, and any alternative $x\in A_\tau$. Then, $n(x,P)=n(x,\pi P)$. By \cref{obv}, $\varphi(P)(\{x\})=(1/n)n(x,P)=(1/n)n(x,\pi P)=\varphi(\pi P)(\{x\})$. Thus, $\varphi\in\Sigma_a$. 

\begin{claim}\label{cl12}
    $\varphi\in\Sigma_o$.
\end{claim}

    The proof is direct. Consider any number $\tau\in\mathbb{N}$, any two distinct alternatives $x,y\in A_\tau$, and any profile $P\in\mathcal{P}(A_\tau)$ such that $xP_iy$ for all voters $i\in N$. Then, $N(y,P)=\emptyset$. By \cref{obv}, $\varphi(P)(\{y\})=(1/n)n(y,P)=(1/n)0=0$. Hence, $\varphi\in\Sigma_o$.

\begin{claim}\label{cl13}
    $\varphi\in\Sigma_m$.
\end{claim}

    The proof is direct. Consider any number $\tau\in\mathbb{N}$, any alternative $x\in A_\tau$, any profile $P\in\mathcal{P}(A_\tau)$, and any profile $\tilde{P}\in\mathcal{P}(x,P)$. Then, $N(x,P)\subseteq N(x,\tilde{P})$. By \cref{obv}, $\varphi(P)(\{x\})=(1/n)n(x,P)\leqslant(1/n)n(x,\tilde{P})=\varphi(\tilde{P})(\{x\})$. Therefore, $\varphi\in\Sigma_m$.

\begin{claim}\label{cl14}
    $\varphi\in\Sigma_n$.
\end{claim}

    The proof is direct. Consider any number $\tau\in\mathbb{N}$, any permutation $\mu\in M_\tau$, any profile $P\in\mathcal{P}(A_\tau)$, and any alternative $x\in A_\tau$. Then, $N(x,P)=N(\mu(x),\mu P)$. By \cref{obv}, $\varphi(P)(\{x\})=(1/n)n(x,P)=(1/n)n(\mu(x),\mu P)=\varphi(\mu P)(\{\mu(x)\})$. Hence, $\varphi\in\Sigma_n$. 

\begin{statement}\label{s2}
    $(\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n)\Rightarrow[(\sigma=\varphi)\Rightarrow(\sigma\in\Sigma_s)]$.
\end{statement}

    The proof is direct. By \Cref{s1}, $\varphi\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n$. Thus, it suffices to show that $\varphi\in\Sigma_s$. Consider any number $\tau\in\mathbb{N}$, any profile $P\in\mathcal{P}(A_\tau)$, the lottery $\delta\in\Delta(S_n|\varphi)$ satisfying $\delta(\{d_i\})=1/n$ for all voters $i\in N$, and any finite set $T\subsetneq S_n$ satisfying $\Sigma_d\subseteq T$. Then, $d_i \boldsymbol{R}_i^{T\!P}s$ for all voters $i\in N$ and all voting rules $s\in T$. Hence, there exists some compatible profile $\boldsymbol{P}\in\mathcal{P}(T,P)$ such that $d_i\boldsymbol{P}_is$ for all voters $i\in N$ and all voting rules $s\in T\backslash\{d_i\}$. Fix any such compatible profile $\boldsymbol{P}\in\mathcal{P}(T,P)$. Then, $N(d_i,\boldsymbol{P})=\{i\}$ for all voters $i\in N$. Thus, by \cref{obv}, $\varphi(\boldsymbol{P})(\{d_i\})=(1/n)n(d_i,\boldsymbol{P})=1/n=\delta(\{d_i\})$ for all voters $i\in N$. Therefore, $\varphi\in\Sigma_s$.

\begin{statement}\label{s3}
    $(\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n)\Rightarrow[(\sigma\in\Sigma_s)\Rightarrow(\sigma=\varphi)]$.
\end{statement}

I now introduce two new axioms that will be useful to prove \Cref{s3}.

\begin{axiom}[Independence of irrelevant alternatives]\label{iia}
    A voting rule $\sigma$ is \emph{independent of irrelevant alternatives} if and only if it is invariant to the removal of alternatives with null measure. Formally, if and only if
\begin{equation}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{P}(A_\tau))(\forall B\subseteq A_\tau\backslash\text{supp}(\sigma(P)))
    [\sigma(P)|_{A_\tau\backslash B}=\sigma(P|_{A_\tau\backslash B})]
\end{equation}
\end{axiom}

    Let $\Sigma_i=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[iia]{independent of irrelevant alternatives}}\}$. 

\begin{axiom}[Regularity]\label{reg}
    A voting rule $\sigma$ is \emph{regular} if and only if removing alternatives does not reduce the measure of the remaining alternatives. Formally, if and only if
\begin{equation}
    (\forall\tau\in\mathbb{N})(\forall P\in\mathcal{P}(A_\tau))(\forall B\subseteq A_\tau)[(\forall x\in A_\tau\backslash B)(\sigma(P)(\{x\})\leqslant\sigma(P|_{A_\tau\backslash B})(\{x\}))]
\end{equation}
\end{axiom}

    Let $\Sigma_r=\{\sigma\in\Sigma\mid\sigma\text{ is \hyperref[reg]{regular}}\}$. 

    By \Cref{s1}, $\varphi\in\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_n$. Hence, the proof of \Cref{s3} follows from these three claims:
\begin{enumerate}[label=3.\arabic*.]
    \item $\Sigma_m\cap\Sigma_n\cap\Sigma_s\subseteq\Sigma_i$,
    \item $\Sigma_o\cap\Sigma_m\cap\Sigma_i\subseteq\Sigma_r$,
    \item $\Sigma_a\cap\Sigma_o\cap\Sigma_r=\{\varphi\}$.
\end{enumerate}

\begin{claim}\label{cl31}
    $\Sigma_m\cap\Sigma_n\cap\Sigma_s\subseteq\Sigma_i$.
\end{claim}

    The proof is direct. Consider any \hyperref[m]{monotonic}, \hyperref[n]{neutral}, and \hyperref[s]{self-equivalent} voting rule $\sigma\in\Sigma_m\cap\Sigma_n\cap\Sigma_s$; any number $\tau\in\mathbb{N}$; any profile $P\in\mathcal{P}(A_\tau)$; and any set $B\subseteq A_\tau\backslash \text{supp}(\sigma(P))$. If $B=\emptyset$, it trivially follows that $\sigma(P)|_{A_\tau\backslash B}=\sigma(P)=\sigma(P|_{A_\tau\backslash B})$. Hence, let $B\neq\emptyset$.

    Given any alternative $x\in A_\tau\backslash B$ and any finite set $T\subsetneq S_n$, let $T_x(P)=\{s\in T\mid s(P)(\{x\})=1\}$ and $T_x(P|_{A_\tau\backslash B})=\{s\in T\mid s(P|_{A_\tau\backslash B})(\{x\})=1\}$ respectively be the \emph{sets of all voting rules $s\in T$ assigning measure one to alternative $x$ at profiles $P$ and $P|_{A_\tau\backslash B}$}. By the \hyperref[s]{self-equivalence} axiom, there exists some lottery $\delta\in\Delta(S_n|\sigma)$ such that for all finite sets $T\subsetneq S_n$ satisfying $\text{supp}(\delta)\subseteq T$, there exist two compatible profiles $\boldsymbol{P}\in\mathcal{P}(T,P)$ and $\tilde{\boldsymbol{P}}\in\mathcal{P}(T,P|_{A_\tau\backslash B})$ such that $\sigma(\boldsymbol{P})(\{s\})=\sigma(\tilde{\boldsymbol{P}})(\{s\})=\delta(\{s\})$ for all voting rules $s\in T$. Fix any such lottery $\delta\in\Delta(S_n|\sigma)$ and any such finite set $T\subsetneq S_n$ satisfying $T_x(P)=T_x(P|_{A_\tau\backslash B})$ for all alternatives $x\in A_\tau\backslash B$. Then, $\sigma(P)(\{x\})=\sigma(\boldsymbol{P})(T_x(P))$ and $\sigma(P|_{A_\tau\backslash B})(\{x\})=\sigma(\tilde{\boldsymbol{P}})(T_x(P|_{A_\tau\backslash B}))$ for all alternatives $x\in A_\tau\backslash B$.

    Consider any permutation $\mu:T\to T$ satisfying $\mu(T_x(P|_{A_\tau\backslash B}))=T_x(P)$ for all alternatives $x\in A_\tau\backslash B$. Given any voter $i\in N$, any alternative $x\in A_\tau\backslash B$, and any profile $\boldsymbol{P}'\in\{\boldsymbol{P},\mu\tilde{\boldsymbol{P}}\}$; let $L_i(T_x(P),\boldsymbol{P}')=\{\tilde{s}\in T\backslash T_x(P)\mid(\forall s\in T_x(P))(s\boldsymbol{P}'_i\tilde{s})\}$ be \emph{voter $i$'s lower contour set at $(T_x(P),\boldsymbol{P}')$}. Then, $L_i(T_x(P),\boldsymbol{P})=L_i(T_x(P),\mu\tilde{\boldsymbol{P}})$ for all voters $i\in N$ and all alternatives $x\in A_\tau\backslash B$. Given any alternative $x\in A_\tau\backslash B$, \cref{k1} follows from the \hyperref[m]{monotonicity} axiom, \cref{k2} follows from the \hyperref[n]{neutrality} axiom, and \cref{k3} follows from the definition of $\mu:T\to T$:
\begin{align}\label{k1}
    \sigma(\boldsymbol{P})(T_x(P))&=\sigma(\mu\tilde{\boldsymbol{P}})(T_x(P))\\\label{k2}
    &=\sigma(\mu^{-1}\mu\tilde{\boldsymbol{P}})(\mu^{-1}(T_x(P)))\\\label{k3}
    &=\sigma(\tilde{\boldsymbol{P}})(T_x(P|_{A_\tau\backslash B}))
\end{align}    
     Therefore, $\sigma(P)(\{x\})=\sigma(P|_{A_\tau\backslash B})(\{x\})$ for all alternatives $x\in A_\tau\backslash B$. Thus, $\sigma\in\Sigma_i$. Consequently, $\Sigma_m\cap\Sigma_n\cap\Sigma_s\subseteq\Sigma_i$.

\begin{claim}\label{cl32}
    $\Sigma_o\cap\Sigma_m\cap\Sigma_i\subseteq \Sigma_r$.
\end{claim}

    The proof is direct. Consider any \hyperref[o]{optimal}, \hyperref[m]{monotonic}, and \hyperref[iia]{independent of irrelevant alternatives} voting rule $\sigma\in\Sigma_o\cap\Sigma_m\cap\Sigma_i$; any number $\tau\in\mathbb{N}$; any profile $P\in\mathcal{P}(A_\tau)$; and any set $B\subsetneq A_\tau$. If $B=\emptyset$, it trivially follows that $\sigma(P)=\sigma(P|_{A_\tau\backslash B})$. Hence, let $B\neq\emptyset$. Now, construct a profile $\tilde{P}\in\mathcal{P}(A_\tau)$ as follows: $P|_{A_\tau\backslash B}=\tilde{P}|_{A_\tau\backslash B}$; and for all voters $i\in N$ and all alternatives $x\in A_\tau\backslash B$ and $z\in B$, $x\tilde{P}_iz$. Then, $L_i(x,P)\subseteq L_i(x,\tilde{P})$ for all voters $i\in N$ and all alternatives $x\in A_\tau\backslash B$. Thus, $\tilde{P}\in\mathcal{P}(x,P)$ for all alternatives $x\in A_\tau\backslash B$.

    Then, by the \hyperref[m]{monotonicity} axiom, $\sigma(\tilde{P})(\{x\})\geqslant \sigma(P)(\{x\})$ for all alternatives $x\in A_\tau\backslash B$; by the \hyperref[o]{optimality} axiom, $\sigma(\tilde{P})(\{z\})=0$ for all alternatives $z\in B$; and by the \hyperref[iia]{independence of irrelevant alternatives} axiom, $\sigma(\tilde{P})(\{x\})=\sigma(\tilde{P}|_{A_\tau\backslash B})(\{x\})$ for all alternatives $x\in A_\tau\backslash B$. Since $P|_{A_\tau\backslash B}=\tilde{P}|_{A_\tau\backslash B}$, it follows that $\sigma(P|_{A_\tau\backslash B})=\sigma(\tilde{P}|_{A_\tau\backslash B})$. But then, $\sigma(P|_{A_\tau\backslash B})(\{x\})\geqslant\sigma(P)(\{x\})$. Therefore, $\sigma\in\Sigma_r$. Hence, $\Sigma_o\cap\Sigma_m\cap\Sigma_i\subseteq\Sigma_r$.

\begin{claim}\label{cl33}
    $\Sigma_a\cap\Sigma_o\cap\Sigma_r=\{\varphi\}$.
\end{claim}

    Let $A=\bigcup_{\tau\in\mathbb{N}}A_\tau$ be the \emph{universal alternative set}. Now, given any number $\tau\geqslant2$, any two distinct alternatives $x,y\in A_\tau$, any coalition $C\subseteq N$, and any profile $P\in\mathcal{P}(A_\tau)$ satisfying $t_1(P_i)=x$ for all voters $i\in C$ as well as $t_1(P_j)=y$ and $t_2(P_j)=x$ for all voters $j\in N\backslash C$; let
\savebox\strutbox{}
\begin{equation}\label{fun}
    \alpha(x,C,A_\tau,P,y)=\sigma(P)(\{x\})
\end{equation}
    Since \Cref{cl33} is trivially true when $\tau=1$, consider any number $\tau\geqslant2$. Then, the proof of \Cref{cl33} follows from these four lemmas:
\begin{enumerate}[label=3.3.\arabic*.]
    \item $(\forall\sigma\in\Sigma_o\cap\Sigma_r)[\alpha(x,C,A_\tau,P,y)=\alpha(x,C,y)=1-\alpha(y,N\backslash C,x)]$,
    \item $(\forall\sigma\in\Sigma_o\cap\Sigma_r)[\alpha(x,C,y)=\alpha(C)=1-\alpha(N\backslash C)]$,
    \item $(\forall\sigma\in\Sigma_o\cap\Sigma_r)(\forall P\in\mathcal{P}(A_\tau))(\forall x\in A_\tau)[\sigma(P)(\{x\})=\alpha(N(x,P))]$,
    \item $(\forall\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_r)(\forall P\in\mathcal{P}(A_\tau))(\forall x\in A_\tau)[\alpha(N(x,P))=(1/n)n(x,P)]$.
\end{enumerate}

\begin{lemma}\label{l331}
    $(\forall\sigma\in\Sigma_o\cap\Sigma_r)[\alpha(x,C,A_\tau,P,y)=\alpha(x,C,y)=1-\alpha(y,N\backslash C,x)]$.
\end{lemma}

    The proof is direct. Consider any \hyperref[o]{optimal} and \hyperref[reg]{regular} voting rule $\sigma\in\Sigma_o\cap\Sigma_r$, and any profile $P\in\mathcal{P}(A_\tau)$ for which there exists some coalition $C\subseteq N$ and two distinct alternatives $x,y\in A_\tau$ such that $t_1(P_i)=x$ for all voters $i\in C$ as well as $t_1(P_j)=y$ and $t_2(P_j)=x$ for all voters $j\in N\backslash C$. By the \hyperref[o]{optimality} axiom, $\sigma(P)(\{z\})=0$ for all alternatives $z\in A_\tau\backslash\{x,y\}$. Let $A_{\tilde{\tau}}=\{x,y\}$. Since $A_{\tilde{\tau}}\subseteq A_\tau$, the \hyperref[reg]{regularity} axiom implies that $\sigma(P)(\{a\})\leqslant\sigma(P|_{A_{\tilde{\tau}}})(\{a\})$ for all alternatives $a\in A_{\tilde{\tau}}$. Since $\text{supp}(\sigma(P))\subseteq A_{\tilde{\tau}}$, it follows that
\begin{align}
    1=\sum_{a\in A_{\tilde{\tau}}}\sigma(P|_{A_{\tilde{\tau}}})(\{a\})
    \geqslant\sum_{a\in A_{\tilde{\tau}}}\sigma(P)(\{a\})
    =1
\end{align}    
    Hence, $\sigma(P|_{A_{\tilde{\tau}}})(\{a\})=\sigma(P)(\{a\})$ for all alternatives $a\in A_{\tilde{\tau}}$. Then,
\begin{equation}\label{red}
    \alpha(x,C,A_\tau,P,y)=\sigma(P|_{A_{\tilde{\tau}}})(\{x\})
\end{equation}
    Since $\sigma(P|_{A_{\tilde{\tau}}})=\sigma(\tilde{P}|_{A_{\tilde{\tau}}})$ if $P|_{A_{\tilde{\tau}}}=\tilde{P}|_{A_{\tilde{\tau}}}$, it is now possible to write $\alpha(x,C,A_\tau,P,y)=\alpha(x,C,y)$. Since $\sigma(P|_{A_{\tilde{\tau}}})(\{x\})=1-\sigma(P|_{A_{\tilde{\tau}}})(\{y\})$, it follows that $\alpha(x,C,y)=1-\alpha(y,N\backslash C,x)$. Therefore, $\alpha(x,C,A_\tau,P,y)=\alpha(x,C,y)=1-\alpha(y,N\backslash C,x)$.

\begin{lemma}\label{l332}
    $(\forall\sigma\in\Sigma_o\cap\Sigma_r)[\alpha(x,C,y)=\alpha(C)=1-\alpha(N\backslash C)]$.
\end{lemma}

    Consider any \hyperref[o]{optimal} and \hyperref[reg]{regular} voting rule $\sigma\in\Sigma_o\cap\Sigma_r$. Then, the proof of \cref{l332} follows from \Cref{l331} and these two remarks:
\begin{enumerate}[label=3.3.2.\Alph*.]
    \item $(\forall z\in A\backslash\{x,y\})[\alpha(x,C,y)=\alpha(x,C,z)]$,
    \item $(\forall z\in A\backslash\{x,y\})[\alpha(x,C,y)=\alpha(z,C,y)]$.
\end{enumerate}

\begin{remark}\label{r332a}
    $(\forall z\in A\backslash\{x,y\})[\alpha(x,C,y)=\alpha(x,C,z)]$.
\end{remark}

    The proof is by contradiction. Let $\alpha(x,C,y)>\alpha(x,C,z)$, let $A_\tau=\{x,y,z\}$, and let the profile $P\in\mathcal{P}(A_\tau)$ satisfy $xP_iyP_iz$ for all voters $i\in C$ as well as $yP_jzP_jx$ for all voters $j\in N\backslash C$. Now, \cref{q1} follows from \cref{fun} \& \Cref{l331}, whereas \cref{q2} follows from \Cref{l331}:
\begin{align}\label{q1}
    \sigma(P)(\{x\})&=1-\alpha(y,N\backslash C,x)\\\label{q2}
    &=\alpha(x,C,y)
\end{align}    
    Let $A_{\tilde{\tau}}=\{x,z\}$. Then, \cref{red} \& \Cref{l331} together imply that $\sigma(P|_{A_{\tilde{\tau}}})(\{x\})=\alpha(x,C,z)$. Hence, $x\in A_{\tilde{\tau}}\subseteq A_\tau$ and $\sigma(P)(\{x\})>\sigma(P|_{A_{\tilde{\tau}}})(\{x\})$, thus contradicting the assumption that $\sigma\in\Sigma_r$. Therefore, $\alpha(x,C,y)=\alpha(x,C,z)$. 

\begin{remark}\label{r332b}
    $(\forall z\in A\backslash\{x,y\})[\alpha(x,C,y)=\alpha(z,C,y)]$.
\end{remark}

    The proof is direct. By \cref{r332a}, $\alpha(y,N\backslash C,x)=\alpha(y,N\backslash C,z)$. Then, it follows that $1-\alpha(y,N\backslash C,x)=1-\alpha(y,N\backslash C,z)$. Thus, by \cref{l331}, $\alpha(x,C,y)=\alpha(z,C,y)$.

\begin{lemma}\label{l333}
    $(\forall\sigma\in\Sigma_o\cap\Sigma_r)(\forall P\in\mathcal{P}(A_\tau))(\forall x\in A_\tau)[\sigma(P)(\{x\})=\alpha(N(x,P))]$.
\end{lemma}

    Consider any \hyperref[o]{optimal} and \hyperref[reg]{regular} voting rule $\sigma\in\Sigma_o\cap\Sigma_r$. Then, the proof of \cref{l333} follows from \cref{l332} and these three remarks:
\begin{enumerate}[label=3.3.3.\Alph*.]
    \item $(\forall P\in\mathcal{P}(A_\tau))(\forall x\in A_\tau)[\sigma(P)(\{x\})\geqslant \alpha(N(x,P))]$,
    \item $(\forall C\subseteq N)[\alpha(C)=\sum_{i\in C}\alpha(\{i\})]$,
    \item $\alpha(N)=\sum_{i\in N}\alpha(\{i\})=1$.
\end{enumerate}

\begin{remark}\label{r333a}
    $(\forall P\in\mathcal{P}(A_\tau))(\forall x\in A_\tau)[\sigma(P)(\{x\})\geqslant \alpha(N(x,P))]$.
\end{remark}

    The proof is direct. Consider any alternative $x\in A_\tau$, any alternative $y\in A\backslash A_\tau$, and let $A_{\tilde{\tau}}=A_\tau\cup\{y\}$. Then, consider two profiles $P\in\mathcal{P}(A_\tau)$ and $\tilde{P}\in\mathcal{P}(A_{\tilde{\tau}})$ such that $P=\tilde{P}|_{A_\tau}$, $t_1(\tilde{P}_i)=y$ for all voters $i\in N\backslash N(x,P)$, and $t_2(\tilde{P}_j)=y$ for all voters $j\in N(x,P)$. Since $P=\tilde{P}|_{A_\tau}$, it follows that $\sigma(P)(\{x\})=\sigma(\tilde{P}|_{A_\tau})(\{x\})$. Then, \cref{b1} follows from \cref{fun,l331}, whereas \cref{b2} follows from \Cref{l332}:
\begin{align}\label{b1}
    \sigma(\tilde{P})(\{x\})&=\alpha(x,N(x,P),y)\\\label{b2}
    &=\alpha(N(x,P))
\end{align}    
    Since $x\in A_\tau\subseteq A_{\tilde{\tau}}$, the \hyperref[reg]{regularity} axiom implies that $\sigma(\tilde{P}|_{A_\tau})(\{x\})\geqslant\sigma(\tilde{P})(\{x\})$. Therefore, $\sigma(P)(\{x\})\geqslant\alpha(N(x,P))$.

\begin{remark}\label{r333b}
    $(\forall C\subseteq N)[\alpha(C)=\sum_{i\in C}\alpha(\{i\})]$.
\end{remark}

    The proof is direct. Consider any two coalitions $D,E\subseteq N$ such that $D\cap E=\emptyset$. Let $A_\tau=\{x,y,z\}$, and let the profile $P\in\mathcal{P}(A_\tau)$ satisfy $xP_iyP_iz$ for all voters $i\in D$, $yP_jzP_jx$ for all voters $j\in E$, and $zP_kxP_ky$ for all voters $k\in N\backslash(D\cup E)$. Now, by \Cref{r333a}, $\sigma(P)(\{x\})\geqslant\alpha(D)$; by \cref{red} \& \Cref{l331,l332}, $\alpha(D)=\sigma(P|_{\{x,z\}})(\{x\})$; and by the \hyperref[reg]{regularity} axiom, $\sigma(P|_{\{x,z\}})(\{x\})\geqslant\sigma(P)(\{x\})$. Therefore, $\alpha(D)=\sigma(P)(\{x\})$. Similarly, $\alpha(E)=\sigma(P)(\{y\})$ as well as $\alpha(N\backslash(D\cup E))=\sigma(P)(\{z\})$. Hence, $\alpha(D)+\alpha(E)=1-\alpha(N\backslash(D\cup E))$. Thus, by \cref{l332}, $\alpha(D)+\alpha(E)=\alpha(D\cup E)$. Then, $\alpha(C)=\sum_{i\in C}\alpha(\{i\})$ for all coalitions $C\subseteq N$.

\begin{remark}\label{r333c}
    $\alpha(N)=\sum_{i\in N}\alpha(\{i\})=1$.
\end{remark}

    The proof is direct. By the \hyperref[o]{optimality} axiom, $\alpha(x,N,y)=1$; by \cref{l332}, $\alpha(N)=\alpha(x,N,y)$; and by \cref{r333b}, $\alpha(N)=\sum_{i\in N}\alpha(\{i\})$. Thus, $\alpha(N)=\sum_{i\in N}\alpha(\{i\})=1$.

\begin{lemma}\label{l334}
    $(\forall\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_r)(\forall P\in\mathcal{P}(A_\tau))(\forall x\in A_\tau)[\alpha(N(x,P))=(1/n)n(x,P)]$.
\end{lemma}

    The proof is by contradiction. Consider any \hyperref[a]{anonymous}, \hyperref[o]{optimal}, and \hyperref[reg]{regular} voting rule $\sigma\in\Sigma_a\cap\Sigma_o\cap\Sigma_r$. Further, suppose there are two distinct voters $i,j\in N$ such that $\alpha(\{i\})\neq\alpha(\{j\})$. Consider any profile $P\in\mathcal{P}(A_\tau)$ such that $t_1(P_i)=x\neq t_1(P_j)$, and the permutation $\pi\in\Pi$ satisfying $\pi(i)=j$, $\pi(j)=i$, and $\pi(k)=k$ for all voters $k\in N\backslash\{i,j\}$. By \cref{r333b}, $\alpha(N(x,P))\neq\alpha(N(x,\pi P))$; and by \Cref{l333}, $\sigma(P)(\{x\})\neq\sigma(\pi P)(\{x\})$, thus contradicting the assumption that $\sigma\in\Sigma_a$. Then, $\alpha(\{i\})=\alpha(\{j\})$ for all voters $i,j\in N$. Hence, by \Cref{r333c}, $\alpha(\{i\})=1/n$ for all voters $i\in N$; and by \cref{r333b}, $\alpha(N(x,P))=(1/n)n(x,P)$ for all alternatives $x\in A_\tau$.
\end{proof}

The proofs of \Cref{l331,l332,l333} are quite similar to some parts of \citeauthor{pattanaikpeleg_86}'s (\citeyear{pattanaikpeleg_86}, p. 917) proof of their Theorem 4.11. However, \Cref{l331,l332,l333} do not follow immediately from their results, for their probabilistic voting procedures are different from the voting rules of this paper. While it \emph{might} be possible to directly derive \Cref{l331,l332,l333} from their results by constructing an isomorphism between their probabilistic voting procedures and my notion of a voting rule, I choose to provide a complete proof to keep the paper fully self-contained.

Moreover, the proof of \Cref{th} gives away a second characterization of the \hyperref[p]{uniform random dictatorship}, which I state in \Cref{col}. Both this second characterization and the proof of \Cref{th} use a property called \hyperref[iia]{independence of irrelevant alternatives} that is different from \citeauthor{pattanaikpeleg_86}'s (\citeyear{pattanaikpeleg_86}, Definition 3.5, p. 913). The property I use states that a voting rule is invariant to the removal of alternatives that get zero measure, rather than invariant to changes in voters' preferences over unfeasible alternatives. Thus, both \textcite{koray_00} and myself use the term in the sense of \citeauthor{nash_50} (\citeyear{nash_50}, Assumption 7, p. 159; \citeyear{nash_53}, Axiom V, p. 137), whereas \textcite{pattanaikpeleg_86} use it in the sense of \citeauthor{arrow_50} (\citeyear{arrow_50}, Condition 3, p. 337; \citeyear{arrow_51}, Condition 3, p. 27). It turns out that the analogous condition to \citeauthor{pattanaikpeleg_86}'s \citeyearpar{pattanaikpeleg_86} independence of irrelevant alternatives is embedded in the definition of a voting rule of this paper.

\begin{corollary}\label{col}
    The unique \hyperref[a]{anonymous}, \hyperref[o]{optimal}, \hyperref[m]{monotonic}, and \hyperref[iia]{independent of irrelevant alternatives} voting rule is the \hyperref[p]{uniform random dictatorship}. Formally,
\begin{equation}
    \Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_i=\{\varphi\}
\end{equation}
\end{corollary}

\begin{cproof}
    The proof is direct. By \cref{s1,s2,cl31}, $\{\varphi\}\subseteq\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_i$; whereas by \Cref{cl32,cl33}, $\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_i\subseteq\{\varphi\}$. Consequently, $\Sigma_a\cap\Sigma_o\cap\Sigma_m\cap\Sigma_i=\{\varphi\}$.
\end{cproof}

