\chapter{Appendix: Matched comparisons}
\label{sec:append-match-comp}

By classic matching we refer to a scenario where we have the entire group of exposed and wish to compare them to a group of unexposed that is selected so that the two groups match on a set of variables $L$. For example we might for each exposed individual find an unexposed individual so that the two have the same $L$ (one-to-one matching). The classic matching is represented by the DAG in Figure \ref{fig:class-match}. Here $S$ is an indicator for being sampled in the study and we condition on $S=1$ corresponding to being sampled. Both the exposure $X$ and the matching variables $L$ will influence one's probability of being sampled.

\begin{figure}[htb]
  \centering
  \begin{tikzpicture}
    \node (X) {$X$};
    \node[right = of X] (invis) {};
    \node[right = of invis] (Y) {$Y$};
    \node[above = of invis] (L) {$L$};
    \node[below = of invis] (S) {$[S = 1]$};
    \draw[->] (X) -> (Y);
    \draw[->] (L) -- (X);
    \draw[->] (L) -- (Y);
    \draw[->] (L) -- (S);
    \draw[->] (X) -- (S);
  \end{tikzpicture}
  \caption{Classic matching: DAG representing the assumed relationship between the
    outcomes $Y$, exposures $X$ and confounders $L$. $S$ is an indicator for being sampled (being part of the study) and we have conditioned on being selected ($S = 1$).}
  \label{fig:class-match}
\end{figure}

This way of matching has two consequences: All exposed will be included in the sample (i.e. $\setdef{A=1} \subseteq \setdef{S = 1}$) and the distribution of $L$ will be the same among exposed and unexposed \emph{in the sample}. Estimation proceeds under the following causal assumptions,
\begin{description}
\item[Consistency] $Y$ equals $Y(x)$ on the event $\setdef{X = x}$
\item[Conditional exchangeability] $Y(x) \indep X \mid L, S = 1$
\end{description}

In our analysis, we compare the mean outcome among exposed and unexposed in our sample, which is an estimate of the following quantity,
\begin{equation}
  \label{eq:34}
  \begin{aligned}
    &\cexpect{Y}{X=1, S=1} - \cexpect{Y}{X=0, S=1} \\
    &=
      \int \cexpect{Y(1)}{X=1, S=1, L = l} f_{L \mid X, S}(l \mid 1, 1)\: dl
      -
      \int \cexpect{Y(0)}{X=0, S=1, L = l} f_{L \mid X, S}(l \mid 0, 1)\: dl
    \\
    &=
      \int \cexpect{Y(1)}{X=1, S=1, L = l} f_{L \mid X, S}(l \mid a, 1)\: dl
      -
      \int \cexpect{Y(0)}{X=0, S=1, L = l} f_{L \mid X, S}(l \mid a, 1)\: dl
    \\
    &=
      \int \cexpect{Y(1)}{L = l} f_{L \mid X, S}(l \mid a, 1)\: dl
      -
      \int \cexpect{Y(0)}{L = l} f_{L \mid X, S}(l \mid a, 1)\: dl
    \\
    &=
      \int
      \left\{
        \cexpect{Y(1) - Y(0)}{L = l}
      \right\}
      f_{L \mid X, S}(l \mid a, 1)\: dl
    \\
    &=
      \int
      \left\{
        \cexpect{Y(1) - Y(0)}{L = l, X= a, S=1}
      \right\}
      f_{L \mid X, S}(l \mid a, 1)\: dl
    \\
    &=
      \cexpect{Y(1) - Y(0)}{X= a, S=1}
    \\
    &=
      \begin{cases}
        \text{ATT} & a = 1 \\
        \cexpect{Y(1) - Y(0)}{X= 0, S=1} & a = 0
      \end{cases}
  \end{aligned}
\end{equation}

where we for the case $a=1$ have used that $\setdef{A=1} \subseteq \setdef{S = 1}$. In particular, we have supplied an argument for the fact, that matching supplies an estimate of the average treatment effect among the treated (ATT). Also note the analoguous situation where we start with the group of unexposed, which would then yield the average treatment effect among the unexposed. As argued in the main text for sibling comparison, if $L$ is not a modifier of the $X$-$Y$ relation, we obtain the ATE, $\expect{Y(1) - Y(0)}$.


\chapter{Appendix: Details of simulations}
\label{cha:append-deta-simul}

Below, we provide details about the simulations presented in Section \ref{sec:simulation-study}.

\section{Data-generating mechanisms}
\label{sec:data-gener-mech}

First, simulate the confounder $U \sim N(0, \sigma_U^2)$ and then simulate,
\begin{equation}
  \label{eq:16}
  \alpha = b_{\alpha} \cdot \exp(b_{\Lambda} \cdot U) + \tilde{\alpha},
\end{equation}
where $\tilde{\alpha} \sim N(0, \tau^2)$. We then simulate the overall family exposure level $\bar{X}_.$ from a multinomial distribution so that,
\begin{equation}
  \label{eq:17}
  \cproba{\bar{X}_. = x}{\alpha} =
  \begin{cases}
    (1 - \Lambda(b_X \cdot \alpha))/2 & \text{ if } x = 0 \\
    \Lambda(b_X \cdot \alpha) & \text{ if } x = 1/2 \\
    (1 - \Lambda(b_X \cdot \alpha))/2 & \text{ if } x = 1
  \end{cases}
\end{equation}
where $\Lambda: x \mapsto [1 + \exp(-x)]^{-1}$ is the logistic function.

The above simulations are performed for $N$ families. We then simulate the sibling-level exposure by setting $X_1 = X_2 = \bar{X}_.$ whenever $\bar{X}_. = 0$ or $\bar{X}_. = 1$ (i.e. in case of exposure concordance). When $\bar{X}_. = 1/2$ (exposure discordance), simulate $X_1 \sim \text{Bernoulli}(\pi_X)$ and set $X_2 = 1 - X_1$. Indexing the families by $i=1,\ldots,N$ and siblings by $j=1,2$ as in the main text, we simulate the outcomes as,
\begin{equation}
  \label{eq:19}
  Y_{ij} = \mu + \alpha_i + \beta^W \cdot X_{i j} + \beta^D \cdot X_{i j} \cdot \alpha_i + \beta^C \cdot X_{i (3 - j)} + \epsilon ,
\end{equation}
with $\epsilon \sim N(0, \sigma^2)$.

\section{Analysis methods}
\label{sec:analysis-methods}

We consider two methods for estimating the target $\target{3} = \expect{Y_1(1,1) - Y_1(0,0)}$.
\begin{enumerate}
\item Fit the between-within model to the selected data (i.e. with $S = 1$)
  \begin{equation}
    \label{eq:47}
    Y_{ij} = \mu + \tilde{\alpha}_i + \beta^B \bar{X}_{i.} + \left(X_{ij} - \bar{X}_{i.}\right) \beta^W + \epsilon_{ij} 
  \end{equation}
  and report $\widehat{\beta^W}$.
\item Weighted estimation
  \begin{enumerate}
  \item Obtain weights in one of three ways.
    \begin{enumerate}
    \item Calculate the true weights from (\ref{eq:17}).
    \item Estimate the weights from two logistic regressions
      \begin{equation}
        \label{eq:50}
        \begin{aligned}
          &M_1: \logit \cproba{X_1 = 1, X_2 = 1}{\alpha} = d_{0,1} + d_{1,1} \alpha \\
          &M_0: \logit \cproba{X_1 = 0, X_2 = 0}{\alpha} = d_{0,0} + d_{1,0} \alpha 
        \end{aligned}
      \end{equation}
      Note that the weight models are misspecified but contain the true weight model. Calculate the weights (note, only varying on family level) as
      \begin{equation}
        \label{eq:49}
        w_{ij} (1) = \indic{\bar{X}_{i.} = 1} \left[\hat{\pi}_1 \right]^{-1}, \quad
        w_{ij} (0) = \indic{\bar{X}_{i.} = 0} \left[\hat{\pi}_0 \right]^{-1}
      \end{equation}
      where $\pi$ is the predicted probability with subscript corresponding to the models from the preceding step. Note that the weights depend on $\alpha$ and are evaluated at the true $\alpha$.
    \item Same as the previous method but using an estimated $\hat{\alpha}$ rather than the true $\alpha$. The estimates are obtained by fitting the between-within model in equation (\ref{eq:47}) and setting,
      \begin{equation}
        \label{eq:36}
        \hat{\alpha}_i = \widehat{\tilde{\alpha}}_i + \hat{\beta}^B \bar{X}_{i.} ,
      \end{equation}
      where $\widehat{\tilde{\alpha}}$ are BLUPs for the family-level effects.
    \end{enumerate}
  \item Estimate the weighted means,
    \begin{equation}
      \label{eq:48}
      \mu(1) = \expect{w_{ij}(1) Y_{ij}}, \quad
      \mu(0) = \expect{w_{ij}(0) Y_{ij}}
    \end{equation}
  \item Report $\widehat{\mu(1)} - \widehat{\mu(0)}$.
  \end{enumerate}
\end{enumerate}

\section{Calculations}
\label{sec:calculations}

Under the simulation model,
\begin{equation}
  \label{eq:20}
  \begin{aligned}
    \cexpect{Y_1 (x_1, x_2)}{\alpha}
    &=
      \cexpect{Y_1}{\alpha, X_1 = x_1, X_2 = x_2}
    \\
    &=
      \mu + \alpha_i + \beta^W \cdot x_1 + \beta^D \cdot x_1 \cdot \alpha + \beta^C \cdot x_2
  \end{aligned}
\end{equation}
and thus,
\begin{equation}
  \label{eq:23}
  \begin{aligned}
    \cexpect{Y_1 (1, 0)}{\alpha} - \cexpect{Y_1 (0, 1)}{\alpha}
    &=
      \beta^W + \beta^D \cdot \alpha - \beta^C 
  \end{aligned}
\end{equation}
and we see that the (SA) assumption corresponds to $\beta^D = 0$. Further,
\begin{equation}
  \label{eq:24}
  \begin{aligned}
    \cexpect{Y_1 (1, 1)}{\alpha} - \cexpect{Y_1 (0, 0)}{\alpha}
    &=
      \beta^W + \beta^D \cdot \alpha + \beta^C
  \end{aligned}
\end{equation}
Comparing (\ref{eq:23}) with (\ref{eq:24}) we see that the (NDI) assumption corresponds to $\beta^C = 0$. Finally,
\begin{equation}
  \label{eq:32}
  \begin{aligned}
    \target{3}
    &=
      \expect{\cexpect{Y_1 (1, 1)}{\alpha} - \cexpect{Y_1 (0, 0)}{\alpha}} \\
    &=
      \beta^W + \beta^D \cdot  b_{\alpha} \cdot \exp(b_{\Lambda}^2 \sigma_U^2/2) + \beta^C
  \end{aligned}
\end{equation}

