\chapter{Appendix: A second weighting procedure}
\label{sec:append-weight-proc}

Consider the DAG in Figure \ref{fig:dag-weight}, which is a slight simplification of that in Figure \ref{fig:dag-potential}, where we have removed the arrow from $U$ to $S$, corresponding to the assumption that the confounders affect the selection only through $\alpha$. 

\begin{figure}
  \centering
  \begin{tikzpicture}
    \node[] (U) {$U$};
    \node[right = of U] (a) {$\alpha$};
    \node[above = 1.5cm of U] (S) {$\left[S = 1\right]$};
    \node[right = of a, above of = a] (X1) {$X_1$};
    \node[right = of a, below of = a] (X2) {$X_2$};
    \node[right = of X1] (Y1) {$Y_1$};
    \node[right = of X2] (Y2) {$Y_2$};
    \draw[->] (X1) -> (Y1);
    \draw[->] (X2) -> (Y2);
    \draw[->] (X1) -> (Y2);
    \draw[->] (X2) -> (Y1);
    \draw[->, dashed] (U) -- (a);
    \draw[->, dashed] (a) -- (X1);
    \draw[->, dashed] (a) -- (X2);
    \draw[dashed] (a.90) edge[bend left = 60, ->] (Y1.110);
    \draw[dashed] (a.270) edge[bend right = 60, ->] (Y2.250);
    \draw[dashed] (a) edge[->] (S);
    \draw[dashed] (U.90) edge[bend left = 55, ->] (Y1.90);
    \draw[dashed] (U.270) edge[bend right = 55, ->] (Y2.270);
  \end{tikzpicture}
  \caption{Slight simplification of the DAG in Figure \ref{fig:dag-potential} under which the weighting procedure is analysed. The simplification consists of the assumption that $U$ affects the selection $S$ only through $\alpha$.}
  \label{fig:dag-weight}
\end{figure}

Consider the set of weights defined in equation (\ref{eq:15}) of the main text,
\begin{equation}
  \label{eq:38}
  w(a, x_1, x_2) = \indic{X_1 = x_1, X_2 = x_2, S = 1} \left[f_{(X_1, X_2) \mid \alpha} (x_1, x_2 \mid a) f_{S \mid \alpha} (1 \mid a) \right]^{-1}
\end{equation}
We note from the DAG that $(X_1, X_2)$ is conditionally independent from $S$ given $\alpha$ and $U$, and thus, \begin{equation}
  \label{eq:40}
  \begin{aligned}
    \expect{w(\alpha, x_1, x_2) Y}
    &=
      \int
      \left[f_{(X_1, X_2) \mid \alpha} (x_1, x_2 \mid a) f_{S \mid \alpha} (1 \mid a) \right]^{-1} \\
    &\qquad\qquad \cexpect{\indic{X_1 = x_1, X_2 = x_2, S = 1} Y}{\alpha = a, U = u}
      f_{(\alpha, U)} (a, u)
      \: (da, du) \\
    &=
      \int
      \frac{
      f_{(X_1, X_2, S) \mid \alpha, U} (x_1, x_2, 1 \mid a, u)
      }{
      f_{(X_1, X_2) \mid \alpha} (x_1, x_2 \mid a) f_{S \mid \alpha} (1 \mid a)
      } \\
    &\qquad\qquad
      \cexpect{Y}{\alpha = a, X_1 = x_1, X_2 = x_2, S = 1, U = u}
      f_{(\alpha, U)} (a, u)
      \: (da, du) \\
    &=
      \int
      1 \cdot
      \cexpect{Y}{\alpha = a, X_1 = x_1, X_2 = x_2, S = 1, U = u}
      f_{(\alpha, U)} (a, u)
      \: (da, du) \\
    &=
      \int
      \cexpect{Y(x_1, x_2)}{\alpha = a, X_1 = x_1, X_2 = x_2, S = 1, U = u}
      f_{(\alpha, U)} (a, u)
      \: (da, du) \\
    &=
      \int
      \cexpect{Y(x_1, x_2)}{\alpha = a, U = u}
      f_{(\alpha, U)} (a, u)
      \: (da, du) \\
    &=
      \expect{Y(x_1, x_2)}
  \end{aligned}
\end{equation}

Since $\alpha$ is not observed one would in practise evaluate the weight at the BLUP and use the weight $w(\hat{\alpha}, x_1, x_2)$, see the Discussion in the main paper. Equation (\ref{eq:40}) shows that this weighting procedure allows estimation of any of the targets and does not rely on NDI or SA. 


