\draw [black,fill=black] (4,0.25) ellipse (0.05 and 0.05);
\end{tikzpicture}
\ee

Here, the factor of two means that the anyon $a_La_R$ has two ends on the physical boundary and thus splits into two local operators $\cO_{a_La_R}$ and $\cO_{a^2_La^2_R}$. Indeed, these are different conjugacy classes of $\Z_3^\diag$, which, from eq. \eqref{eq:Ftildes_S3}, is the subgroup corresponding to $\cL_2$ and labeling the fluxes on the physical boundary.

The fusion algebra of the charged local operators is simply given by $\Z_3^\diag$ group multiplication:
\be\ba
    \cO_{a_La_R}\times\cO_{a_La_R}&=\cO_{a^2_La^2_R}\,,\\
    \cO_{a_La_R}\times\cO_{a^2_La^2_R}&=1\,.
\ea\ee
and is diagonalized by:
\be\ba
    v_1&=(1+\cO_{a_La_R}+\cO_{a^2_La^2_R})\,,\\
    v_2&=(1+\omega\, \cO_{a_La_R}+\ol{\omega}\,\cO_{a^2_La^2_R})\,,\\
    v_3&=(1+\ol{\omega}\,\cO_{a_La_R}+\omega\,\cO_{a^2_La^2_R})\,,
\ea\ee
where $\omega+\ol{\omega}=-1$.
The strong $\Rep(S_3)$ symmetry action on the local operators can again be computed from \eqref{eq:S3_chars}:
\be\ba
 P_{L,R}:(\cO_{a_La_R}\,, \cO_{a^2_La^2_R})&\longrightarrow  (\cO_{a_La_R}\,, \cO_{a^2_La^2_R})\,,\\
 E_{L,R}:(\cO_{a_La_R}\,, \cO_{a^2_La^2_R})&\longrightarrow  (-\cO_{a_La_R}\,, -\cO_{a^2_La^2_R})\,.
\ea\ee
On the vacua we therefore have
\be\ba
 P_{L,R}:(v_1,\,v_2,\,v_3)&\longrightarrow  (v_1,\,v_2,\,v_3)\,,\\
 E_{L,R}:(v_1,\,v_2,\,v_3)&\longrightarrow  (v_2+v_3,\,v_1+v_3,\,v_1+v_2)\,,
\ea\ee
From which we see that the strong $\Z_2$ symmetry generated by $P_L$ and $P_R$ is preserved, while the strong non-invertible $E_L,\,E_R$ is SSB'ed. The action of the weak $E_LE_R$ non-invertible  symmetry is trivial:
\be\ba
 E_{L}E_{R}:(\cO_{a_La_R}\,, \cO_{a^2_La^2_R})&\longrightarrow  (\cO_{a_La_R}\,, \cO_{a^2_La^2_R})\,.
\ea\ee
Each local operator will thus give rise to a ${\Rep(S_3)/\Z_2}$ SWSSB density matrix, in which the non-invertible strong $E$ symmetry is broken to weak, while the strong $\Z_2$ symmetry generated by $P$ is fully preserved.







\vspace{2mm}
\noindent {\bf $\bm{\Z_2}$ SWSSB.}
Consider the sandwich $(\cL_{\Rep({S_3})}^{\text{strong}} , \cL_3)$
