\section{Theoretical Backdrop}
\label{sec:models_of_interest}

\subsection{The log Stationary fractional Brownian Motion}
\label{sec:logSfBM}

%In an attempt to reconcile  empirical observations of Hurst exponents both greater than 0.1 \cite{gatheral2018volatility} and  tending towards 0. , Wu \textit{et al.} introduced the log Stationary fractional Brownian Motion model (log S-fBM) in 2022. 

In this Section, we outline the main characteristics of the log S-fBM model introduced in \cite{wu2022rough} as a consistent interpolation between rough models with $0 < H < \frac12$ and the ``super-rough'' MRW, that corresponds to $H\xrightarrow[]{}0^+$. For more comprehensive details, we refer the reader to \cite{wu2022rough}. 


For any Hurst exponent $0<H<\frac{1}{2}$, the Stationary fractional Brownian Motion (S-fBM) $(\omega_{H,T}(t))_t$ is a stationary Gaussian process\footnote{Notice that all the framework introduced in this work can be naturally extended to a wide class of infinitely divisible laws along the same line as discussed in \cite{muzy2002multifractal,bacry2003log,wu2022rough}.} defined by its covariance function:
\begin{equation}
    C_{\omega_{H,T}}(\tau) = \text{cov}(\omega_{H,T}(t),\omega_{H,T}(t+\tau))\\
    = \begin{cases}
        \frac{\nu^2}{2}\left(1-(\frac{\tau}{T})^{2H} \right),\quad \text{ when } |\tau|<T\\
        0 \quad \text{otherwise}
    \end{cases}
    \label{eq:covSfBM}
\end{equation}
where $\nu$ is a dimensionless parameter that controls the amplitude of the process, and $T$ is the time range of correlations.  The mean value of $\omega_{H,T}$ can always be chosen is such a way that:
\begin{equation}
\label{eq:mean_omega}
 \mathbb{E}\left(e^{\omega_{H,T}(t)} \right) = 1 \; .
\end{equation}
The log S-fBM random measure $(M_{H,T}(t))_t$ is then defined as
\begin{equation}\label{eq:NFM_MRM_M_def}
    {\rm d}M_{H,T}(t) = \exp(\omega_{H,T}(t)){\rm d}t.
\end{equation}
Wu \textit{et al.} primarily demonstrate that as $H$ goes to 0 and $\nu$ tends toward infinity while keeping fixed the so-called dimensionless intermittency coefficient
\begin{equation} 
\label{eq:rel_nu_lambda2}
\lambda^2=H(1-2H)\nu^2,
\end{equation}
the log S-fBM $(M_{H,T}(t))_t$ converges toward a Multifractal Random Measure (MRM) (that will be consequently noted $M_{0,T}$) previously introduced in \cite{bacry2001multifractal,bacry2001modelling,muzy2000modelling,muzy2002multifractal}.
The MRM is classically defined as the limit measure
\begin{equation}\label{eq:NFM_MRM_M0_def}
    {\rm d}M_{0,T}(t) = \lim_{l \rightarrow 0^+} \exp(\tilde \omega_{l,T}(t)){\rm d}t
\end{equation}
where $\tilde \omega_{l,T}$ is a stationary Gaussian process, whose mean is chosen such that
$ \mathbb{E}(e^{\tilde \omega_{l,T}(t)}) = 1$, and whose covariance is given by\textbf{}
\begin{eqnarray}
    \begin{aligned}
    C_{\tilde \omega_{l,T}}(\tau) =\text{cov}(\tilde \omega_{l,T}(t),\tilde \omega_{l,T}(t+\tau)) =  \begin{cases}
        -\lambda^2 (\ln({l}/{T}) - 1 + \tau/l),\quad \text{ when } |\tau|<l\\
        -\lambda^2 \ln({\tau}/{T}),\quad \text{ when } l< |\tau|<T\\
        0 \quad \text{otherwise}
    \end{cases}.
\end{aligned}
\end{eqnarray}

