\section{The M-factor Nested Factor model}
\label{app:MfactorNFM}

\begin{equation}\label{eq:MfactorNFM_definition}
    {\rm d}x^i_t = \sum_{k=0}^{M-1} \beta^i_k \, {\rm d}f^k_t + {\rm d}e^i_t \quad \text{with} \quad
    \begin{cases}
        {\rm d}f^k_t = \exp \left( \frac{F_k \Omega_t + r^k_t}{2} \right) {\rm d}W^k_t, \\
        {\rm d}e^i_t = \exp \left( \frac{A_i \Omega_t + \omega^i_t}{2} \right) {\rm d}B^i_t,
    \end{cases}
\end{equation}


where 
\begin{itemize}
\setlength\itemsep{0.01em}
    \item the $M$ time series $(f^k_{t})_{k\in\llbracket0,M-1\rrbracket,t>0}$ are the factors, serving as ``benchmarks" derived from the market. The series $f$ represents the market itself, and $({\rm d}f_{t})_t$ are frequently materialized as the returns of the S\&P500 index. Conversely, for $k>0$, ${\rm d}f^k_{t}$ may depict returns from a specific industrial sector. These time series $(f^k_{t})_{k\in\llbracket0,M-1\rrbracket,t>0}$ are uncorrelated;
    \item $\beta^i_k$ represents the exposure of asset $i$ to a factor ${\rm d}f^k$;
    \item the time series $({\rm d}e^i_{t})_i$ represent the residuals of each asset's returns, signifying the portion of the asset's returns not accounted for by market movements. These residuals are uncorrelated with the factors and are idiosyncratic to the asset itself;
    \item $\Omega_t$ is the log-volatility  stochastic \textit{factor} involved in the dynamics of both the factors $(f^k_{t})_{k\in\llbracket0,M-1\rrbracket,t>0}$ and the residuals $(e^i_{t})_i$. $r^k_t$ denotes the stochastic \textit{idiosyncratic} log-volatility of factor $f^k$, while $\omega^i_t$ is the stochastic \textit{idiosyncratic} log-volatility of residual $e^i$;
    \item parameters $\gamma_i$'s and $F_k$'s quantify the contribution of each factor volatility mode. As discussed in\cite{chicheportiche2015nested}, they can be estimated using correlation functions (denoted $C^{ff}$ and $C^{rr}$ in \cite{chicheportiche2015nested}, note that, their dominant eigenvector provide a reliable initial estimate);
    \item finally, $W^k_t$ and $B^i_t$ are Brownian motions, all independent with each other.
\end{itemize}    

