\section{The log S-fBM model}
\label{app:appendixlog S-fBM}
In this Appendix, we will use the same notations as in \cite{wu2022rough}.\\\\
The log S-fBM model is a stochastic volatility model defined introduced in \cite{wu2022rough} whose dynamic is:
\begin{equation}
\label{eq:logsfBM}
        \begin{cases*}
      dX_t = e^{\frac{\omega_{H,T}(t)}{2}} dB_t\\*
      X_0=x_0 
    \end{cases*},
    \end{equation}

  where:
    \begin{itemize}

    \item $\omega_{H,T}(.)$ is the S-fBM process, a stationary Gaussian process with the following autocovariance function in Eq \ref{eq:covSfBM}, and mean:
 \begin{equation}
        \mu_{H,T}=-\frac{\lambda^2}{4H(1-2H)};
    \end{equation}
         \item $B$ is a standard brownian motion independent of $\omega_{H,T}$;
        \item $\lambda>0$, $H\in ]0,1]$, and $T>0$ are respectively the intermittency parameter, the Hurst exponent and the decorrelation parameter.
    \end{itemize}
By construction, for any $\tau>0$, the S-fBM increment process $\left(\delta_{\tau}\omega_{H,T}(t):=\omega_{H,T}(t+\tau)-\omega_{H,T}(t)\right)_t$ is a stationary Gaussian process, centered and  with variance $v\left(\tau,H\right)=\E\left(|\delta_{\tau}\omega_{H,T}(t)|^2 \right)$ expressed as:
\begin{eqnarray}
\label{eq:varianceSfBMincrementvariance}
    v\left(\tau,\nu,H\right)=\nu^2\left(\frac{\tau}{T}\right)^{2H},
\end{eqnarray}
where $\nu^2=\frac{\lambda^2}{H(1-2H)}$, which is a simple way to parametrize the S-fBM variance:
\begin{eqnarray}
    \forall t\geq 0,\tab  \text{var}\left(\omega_{H,T}(t) \right)=\frac{\nu^2}{2}. \nonumber
\end{eqnarray}
For any interval $K\subset \R_+$ of length $|K|$ such that $|K|\leq T$ and any sub-interval $ I\subset K$, 
let us introduce the integrated process:
\begin{eqnarray}
\label{eq:integratedlogvol}
    \Upsilon(I):=\frac{1}{\lambda}\int_I \left(\omega_{H,T}(u)-\mu_{H,T}\right) du,
\end{eqnarray}
and, for any $t >0$ and $0<\Delta\leq T$,
\begin{eqnarray}
   \Upsilon_{\Delta}(t):=\Upsilon([t,t+\Delta]).
\end{eqnarray}

In \cite{wu2022rough} it is established that:
\begin{prop}
\label{prop:propositioncovOmega}
   The process 
   $\Upsilon_{\Delta}$ is a stationary centered Gaussian process, with the following covariance structure:

    \begin{eqnarray}
   \label{eq:autocovOmegaDelta}
    \forall (t,s)\in\R_{+}^2,\tab  
    cov\left(\Upsilon_{\Delta}(t),\Upsilon_{\Delta}(s) \right)=\frac{\Delta^2}{2H(1-2H)}-\Delta^2\left(\frac{\tau}{T}\right)^{2H}\tilde{g}_{H}\left(\frac{\Delta}{\tau}\right), \nonumber \\
    \end{eqnarray}
   where $\tau=|t-s|$ and 
    $\tilde{g}_{H}\left(z\right):=\frac{|1+z|^{2H+2}+|1-z|^{2H+2}-2}{2Hz^2(1-(2H)^2)(2H+2)}$.
\end{prop}
\textbf{\textit{Proof}}
We fix $\Delta>0$.\\
By definition, $ \left(\omega_{H,T}(t)-\mu_{H,T}\right)_t$ is a centered Gaussian process. Consequently, $\Omega_{H,T,\Delta}$ is a centered Gaussian process too.\\\\
We suppose that $t>s$ as they play symmetric roles.\\
    We have:
    \begin{eqnarray}
        cov\left(\Upsilon_{\Delta}(t),\Upsilon_{\Delta}(s) \right)= \frac{1}{\lambda^2}\int_t^{t+\Delta}\int_s^{s+\Delta}cov\left(\omega_{H,T,\Delta}(t),\omega_{H,T,\Delta}(s) \right)dudv \nonumber
    \end{eqnarray}
    By definition, we have :
    \begin{eqnarray}
        \frac{1}{\lambda^2}\int_t^{t+\Delta}\int_s^{s+\Delta}cov\left(\omega_{H,T}(t),\omega_{H,T}(s) \right)dudv= \frac{1}{2H(1-2H)}\int_t^{t+\Delta}\int_s^{s+\Delta}\left(1-\left(\frac{|u-v|}{T}\right)^{2H}\right)dudv \nonumber
    \end{eqnarray}
    After some algebra, one has:
    \begin{eqnarray}
        \frac{1}{\lambda^2}\int_t^{t+\Delta}\int_s^{s+\Delta}cov\left(\omega_{H,T}(t),\omega_{H,T}(s) \right)dudv=\frac{\Delta^2}{2H(1-2H)}-\frac{|\tau+\Delta|^{2H+2}- 
        \tau^{2H+2}}{2HT^{2H}(1-(2H)^2)(2H+2)}\nonumber \\
        -\frac{1}{2HT^{2H}(1-(2H)^2)}\left(\int_t^{s+\Delta}|u-s-\Delta|^{2H}(u-s-\Delta) du+\int_{s+\Delta}^{t+\Delta}|u-s-\Delta|^{2H}(u-s-\Delta) du\right) \nonumber
    \end{eqnarray}
    \\
    By integrating the remaining term, we obtain:
    \begin{eqnarray}
        \frac{1}{\lambda^2}\int_t^{t+\Delta}\int_s^{s+\Delta}cov\left(\omega_{H,T}(t),\omega_{H,T}(s) \right)dudv=\frac{\Delta^2}{2H(1-2H)}-
        \frac{|\tau+\Delta|^{2H+2}-\tau^{2H+2}+|\tau-\Delta|^{2H+2}-\tau^{2H+2}}{2HT^{2H}(1-(2H)^2)(2H+2)}\nonumber
    \end{eqnarray}
    Which leads to:
    \begin{eqnarray}
        \frac{1}{\lambda^2}\int_t^{t+\Delta}\int_s^{s+\Delta}cov\left(\omega_{H,T}(t),\omega_{H,T}(s) \right)dudv=\frac{\Delta^2}{2H(1-2H)}-
        \frac{|\tau+\Delta|^{2H+2}-2\tau^{2H+2}+|\tau-\Delta|^{2H+2}}{2HT^{2H}(1-(2H)^2)(2H+2)}\nonumber
    \end{eqnarray}

Thus, $\Upsilon_{\Delta}(.)$ is a stationary Gaussian process with the claimed autocovariance structure. \\
