\section{Proof of Theorem \ref{theo:variancesumsmallintermit}}
\label{app:proofoftheovariancesumsmallintermit}
This Section is devoted to the proof of theorem \ref{theo:variancesumsmallintermit} using the notations of Section \ref{subsec:SIA}.\\\\
We consider here any sub-intervals $(I,J)\subset K^2$. We introduce the following notations:

\begin{eqnarray}
    \begin{cases}
         C^{log}_{\Sigma}(I,J):=\E\left(\ln\left(\frac{\Sigma\left(I\right)}{|I|}\right)\ln\left(\frac{\Sigma\left(J\right)}{|J|}\right)\right)\\
         C^{log}(I,J):=\E\left(\ln\left(\frac{M\left(I\right)}{|I|}\right)\ln\left(\frac{M\left(J\right)}{|J|}\right)\right)\\
          C_i(I,J):=\E\left(\frac{\Upsilon_{i}(I)}{|I|}\frac{\Upsilon_{i}(J)}{|J|}\right), i\in \llbracket 1,d \rrbracket
    \end{cases}
    \nonumber
    \end{eqnarray}
where $\Upsilon_{i}(I):=\frac{1}{\lambda_i}\int_I \left(\omega^i_u-\mu_i\right) du$.\\

Beforehand, we need this intermediary result.
\begin{lem}
\label{thm:smallinterautocovinterval}
For any sub intervals $I$ and $J$ of $K$, the following approximations holds:

\begin{enumerate}[label=\alph*)]  
    \item 
\begin{eqnarray}
      C^{log}(I,J)-C^{log}(I,I)=\sum_{i=1}^d a_i\lambda_{i}^2\left(C_i(I,J)-C_i(I,I)\right) + o\left(\left|\left|\LL\right|\right|^2\right),
\end{eqnarray}
  \item 
  \begin{eqnarray}
      C^{log}_{\Sigma}(I,J)-C^{log}_{\Sigma}(I,I)=\sum_{i=1}^d b_i^4 \lambda_{i}^2\left(C_i(I,J)-C_i(I,I)\right) + o\left(\left|\left|\LL\right|\right|^2\right),
\end{eqnarray}
\end{enumerate}

where $||.||$ is the $\mathcal{L}^2$ norm in $\R^d$ and the tuples $\left(a_i\right)_{i\in \llbracket 1,d \rrbracket}$ and $\left(b_i\right)_{i\in \llbracket 1,d \rrbracket} $ are defined in the subSection \ref{subsec:SIA}.
\end{lem}

\textbf{\textit{Proof}}
\begin{enumerate}[label=\alph*)]  
\item 
By straightforward computations, we have for any subintervals $I$ and $J$ of $K$ of length $T$:
\begin{eqnarray}
     \E\left(\left(\frac{M(I)}{|I|}-1\right)\left(\frac{M(J)}{|J|}-1\right) \right)=\E\left(\frac{M(I)}{|I|} \frac{M(J)}{|J|}\right)-\E\left( \frac{M(I)}{|I|}\right)-\E\left( \frac{M(J)}{|J|}\right)+1.\nonumber
    \end{eqnarray}
By construction, $\omega$ is a gaussian process. Thus,
using Fubini's theorem, we have:

\begin{eqnarray}
    \begin{cases}
        \E\left(\frac{M(I)}{|I|}\right)=\E\left(\frac{M(J)}{|J|}\right)=e^{\sum_{i=1}^d\frac{\left(a_i^2-a_i\right)\nu_i^2}{4}}\\
        \E\left(\frac{M(I)}{|I|} \frac{M(J)}{|J|}\right)=\frac{1}{\left|I\right|\left|J\right|}\int_{I}\int_{ J}e^{\sum_{i=1}^d\frac{\nu_i^2\left(a_i^2-a_i\right)}{4}+\sum_{i=1}^d a_icov\left(\omega^i_t,\omega^i_s\right)}{\rm d}t{\rm d}s 
    \end{cases}.
    \nonumber
\end{eqnarray}


As a result, we obtain:
\begin{eqnarray}
     \E\left(\left(\frac{M(I)}{|I|}-1\right)\left( \frac{M(J)}{|J|}-1\right) \right)=1+\sum_{i=1}^d\frac{\left(a_i^2-a_i\right)\nu_i^2}{4}+ 
     \sum_{i=1}^d\frac{a_i\lambda_i^2}{\left|I\right|\left|J\right|}\int_{I\times J}cov\left(\frac{1}{\lambda_i}\omega^i_t,\frac{1}{\lambda_i}\omega^i_s)\right){\rm d}t{\rm d}s \nonumber \\
     -2-\sum_{i=1}^d\frac{\left(a_i^2-a_i\right)\nu_i^2}{4}
     +1+o\left(\left|\left|\LL\right|\right|^2\right). \nonumber\nonumber
    \end{eqnarray}
After some algebra, this leads to:
    \begin{eqnarray}
     \E\left(\left(\frac{M(I)}{|I|}-1\right)\left(\frac{M(J)}{|J|}-1\right) \right)=\sum_{i=1}^d\frac{a_i\lambda_i^2}{\left|I\right|\left|J\right|}\int_{I\times J}cov\left(\frac{1}{\lambda_i}\omega^i_t,\frac{1}{\lambda_i}\omega^i_s\right){\rm d}t{\rm d}s+o\left(\left|\left|\LL\right|\right|^2\right),\nonumber
    \end{eqnarray}
Using the Proposition C.1 in \cite{bacry2008log}, we have:
\begin{eqnarray}
         \E\left(\ln\left(\frac{M\left(I\right)}{|I|}\right)\ln\left(\frac{M\left(J\right)}{|J|}\right)\right)=\sum_{l=1}^d a_l \lambda_{l}^2\E\left(\frac{\Upsilon_{l}(I)}{|I|}\frac{\Upsilon_{l}(J)}{|J|}\right)+o\left(\left|\left|\LL\right|\right|^2\right).\nonumber
\end{eqnarray}
In particular, we have:
\begin{eqnarray}
         \E\left(\ln\left(\frac{M\left(I\right)}{|I|}\right)\ln\left(\frac{M\left(I\right)}{|I|}\right)\right)=\sum_{l=1}^d a_l \lambda_{l}^2\E\left(\frac{\Upsilon_{l}(I)}{|I|}\frac{\Upsilon_{l}(I)}{|I|}\right)+o\left(\left|\left|\LL\right|\right|^2\right),\nonumber
\end{eqnarray}
which leads to the desired result by substracting the two previous equalities.\\
    \item 
Given two arbitrary sub-intervals $I$ and $J$ of $K$, we have
\begin{eqnarray}
    \Sigma\left(I\right)\Sigma\left(J\right)=\sum_{1\leq l,s \leq d} b_l^2 b_s^2 M^l\left(I\right)M^s\left(J\right). \nonumber
\end{eqnarray}

For any $(l,s)\in \llbracket 1,d \rrbracket^2$, we have:

\begin{eqnarray}
\E \left( \frac{M^l(I)}{|I|}\frac{M^s(J)}{|J|} \right) = \int_{I \times J}\frac{dxdy}{|I||J|} \E \left( e^{\omega^l_x+\omega^s_y}\right)  . \nonumber
\end{eqnarray}

We have for any $(x,y)\in I\times I$:
\begin{eqnarray}
