\end{eqnarray}

where:
\begin{eqnarray}
    \rho_{i,j}\left(\tau\right)=
    \begin{cases*}
        \frac{1}{(H_i+H_j)(1-H_i-H_j)}\left(1-\left(\frac{\tau}{T}\right)^{H_i+H_j}\right) & \mbox{if}  i=j  \\
        0 & \mbox{otherwise} 
    \end{cases*}.\nonumber
\end{eqnarray}

Which gives after some algebra:
\begin{eqnarray}
    \E\left(e^{w_{H_{l},T}(x)+w_{H_{s},T}(y)}\right) = e^{\lambda_{l }\lambda_{s}\rho_{l, s}(|x-y|)}. \nonumber
\end{eqnarray}
By denoting the functional:
  $$\psi:\left(\lambda_{l},\lambda_{s}\right) \mapsto e^{\lambda_{l }\lambda_{s}\rho_{l ,s}(|x-y|)},  $$
we perform a first order Taylor expansion:
 \[\psi\left(\lambda_{l},\lambda_{s}\right)=\psi(0_{\R^2})+\left<\nabla_{\bm{\lambda}_d=0_{\R^2}}\psi,\bm{\lambda}\right>+\frac{1}{2}\left<Hess\left(\psi\right)|_{\bm{\lambda}=0_{\R^2}}\bm{\lambda},\bm{\lambda}\right>+ o\left(\left|\left|\bm{\lambda} \right|\right|^2\right),\]
Where 
$$ \bm{\lambda}= \begin{pmatrix}
\lambda_l \\
\lambda_s 
\end{pmatrix}
$$
We get:

 \[\psi\left(\lambda_{l},\lambda_{s}\right)=1+\lambda_{l}\lambda_{s}\rho_{l,s}(|x-y|)+ o\left(\left|\left|\bm{\lambda} \right|\right|^2\right).\]
Thus, we conclude that:

\begin{eqnarray}
    \E\left(\frac{M^l\left(I\right)}{|I|}\frac{M^s\left(J\right)}{|J|}\right)=
    \begin{cases*}
        1+ o\left(\left|\left|\bm{\lambda} \right|\right|^2\right)   \hspace{1.45cm} if \hspace{0.5mm} l \neq s \\
         1+\lambda_{l}^2\E\left(\frac{\Upsilon_{l}(I)}{|I|}\frac{\Upsilon_{l}(J)}{|J|}\right)+ o\left(\left|\left|\bm{\lambda} \right|\right|^2\right) \hspace{3mm} if \hspace{0.5mm}  l = s
    \end{cases*}.
    \nonumber
\end{eqnarray}

As a result, we obtain:
\begin{eqnarray}
          \E\left(\frac{\Sigma\left(I\right)}{|I|}\frac{\Sigma\left(J\right)}{|J|}\right)=\sum_{l=1}^d b_l^4 \left(1+\lambda_{l}^2\E\left(\frac{\Upsilon_{l}(I)}{|I|}\frac{\Upsilon_{l}(J)}{|J|}\right) \right)+\sum_{\substack{1 \leq l\neq s \leq d }}b_l^2b_s^2 +o\left(\left|\left|\LL \right|\right|^2\right) ,\nonumber
     \end{eqnarray}

which can be rewritten as:
\begin{eqnarray}
          \E\left(\frac{\Sigma\left(I\right)}{|I|}\frac{\Sigma\left(J\right)}{|J|}\right)=\sum_{l=1}^d b_l^4 \lambda_{l}^2\E\left(\frac{\Upsilon_{l}(I)}{|I|}\frac{\Upsilon_{l}(J)}{|J|}\right) +\left(\sum_{l=1}^d b_l^2\right)^2 +o\left(\left|\left|\LL\right|\right|^2\right).\nonumber
\end{eqnarray}
Thus, we obtain:
\begin{eqnarray}
         \E\left(\left(\frac{\Sigma\left(I\right)}{|I|}-1\right)\left(\frac{\Sigma\left(J\right)}{|J|}-1\right)\right)=\sum_{l=1}^d b_l^4 \lambda_{l}^2\E\left(\frac{\Upsilon_{l}(I)}{|I|}\frac{\Upsilon_{l}(J)}{|J|}\right)+\left(\sum_{l=1}^d b_l^2\right)^2 -2\sum_{l=1}^db_l^2 \nonumber \\
         +1 +o\left(\left|\left|\LL\right|\right|^2\right).\nonumber
\end{eqnarray}
Using the Proposition C.1 in \cite{bacry2008log}, we have:
\begin{eqnarray}
         \E\left(\ln\left(\frac{\Sigma\left(I\right)}{|I|}\right)\ln\left(\frac{\Sigma\left(J\right)}{|J|}\right)\right)=\sum_{l=1}^d b_l^4 \lambda_{l}^2\E\left(\frac{\Upsilon_{l}(I)}{|I|}\frac{\Upsilon_{l}(J)}{|J|}\right)+\left(\sum_{l=1}^d b_l^2\right)^2 -2\sum_{l=1}^db_l^2 \nonumber \\
         +1 +o\left(\left|\left|\LL\right|\right|^2\right).\nonumber
\end{eqnarray}
In particular, we have:
