\section{Proof of Proposition \ref{prop:qvfactorintermsofqvassets}}
\label{app:proofqvfactorintermsofqvassets}
Let us define the increment operator $\delta_\tau$ acting on an arbitrary stochastic process $x_t$ as follows:
\begin{eqnarray}
    \forall (\tau,t)\in K^2, \tab \delta_{\tau} x_t:=x_{t+\tau}-x_t. \nonumber
\end{eqnarray}
Starting from the N-SfFM in  Eq.~\eqref{eq:NFM_definition}, we have for any $\tau\in K$:
\begin{equation}
\forall i\in \llbracket 1,N_< \rrbracket,\quad
   \delta_{\tau} x^{i}_t=\beta_i\delta_{\tau} f_t+\delta_{\tau} e^{i}_t,
    \nonumber
\end{equation}
where:
\begin{eqnarray}
    \begin{cases*}
        \delta_{\tau} x^{i}_t=\int_t^{t+\tau}{\rm d}x^i_s\\
        \delta_{\tau} f_t =\int_t^{t+\tau}e^{\frac{\Omega_{s}}{2}}{\rm d}W_s\\
        \delta_{\tau} e^{i}_t =\int_t^{t+\tau}e^{\frac{\gamma_i\Omega_{s}+\omega^i_{s}}{2}}{\rm d}B^{i}_s
    \end{cases*}.
    \nonumber
\end{eqnarray}
We consider the two optimal least square solutions:
\begin{eqnarray}
\label{eq:olsfactorincrement}
\forall t\in K,\quad
\begin{cases}
    \widehat{\delta_{\tau}f}_{t}:=\underset{f\in \R}\argmin  \left|\left|\delta_{\tau} X_t-\beta  f\right|\right|\\
    \widehat{f}_{t}:=\underset{f\in \R}\argmin  \left|\left| X_t-\beta f\right|\right|
\end{cases},
\end{eqnarray}
where $\left|\left| .\right|\right|$ is the $\mathcal{L}^2$ norm in $\R^{N_<}$.\\\\
It is straightforward to see that the ordinary least squares solutions of Eq.~\eqref{eq:olsfactor} are linked as follows.
\begin{eqnarray}
\label{eq:lemhatfactor}
        \widehat{\delta_{\tau}f}_{t}=\delta_{\tau}\widehat{f}_{t}.
    \end{eqnarray}
We have timewise the following ordinary least square solution:
    \begin{eqnarray}
        \forall t\in K, \tab \quad\widehat{\delta_{\tau}f}_t = \frac{\sum_{i=1}^N\beta_i\delta_{\tau}x^i_t}{\sum_{i=1}^N\beta_i^2}. \nonumber
    \end{eqnarray}
    For the sake of simplicity, we denote: $h:=\frac{1}{\sum_{i=1}^N\beta_i^2}$.\\\\
As a result, we obtain:
\begin{eqnarray}
    \widehat{\delta_{\tau}f}_{t}^2 = h^2\sum_{k^{'},k^{''}=1}^N\beta_{k^{'}}\beta_{k^{''}} \delta_{\tau}x^{k^{'}}_t\delta_{\tau}x^{k^{''}}_t.\nonumber
\end{eqnarray}
Given that for any $ i\in \llbracket 1,N \rrbracket,\quad\delta_{\tau}x^i_t=\beta_{i}\delta_{\tau}f_t+\delta_{\tau}e^i_t$, we have:
\begin{eqnarray}
    \widehat{\delta_{\tau}f}_{t}^2 = \sum_{k^{'}=1}^N h^2\beta_{k^{'}}^2\left(\delta_{\tau}x^{k^{'}}_{t}\right)^2+\sum_{k^{'}\neq k^{''}=1}^N h^2\beta_{k^{'}}\beta_{k^{''}} \left(\beta_{k^{'}}\delta_{\tau}f_t+\delta_{\tau}e^{k^{'}}_t\right)\left(\beta_{k^{''}}\delta_{\tau}f_t+\delta_{\tau}e^{k^{''}}_t\right).\nonumber
\end{eqnarray}
We obtain:
\begin{eqnarray}
    \widehat{\delta_{\tau}f}_{t}^2 = \sum_{k^{'}=1}^Nh^2\beta_{k^{'}}^2\left(\delta_{\tau}x^{k^{'}}_{t}\right)^2+\left(\sum_{k^{'}\neq k^{''}=1}^Nh^2\left(\beta_{k^{'}}\beta_{k^{''}} \right)^2\right)\left(\delta_{\tau}f_{t}\right)^2 \nonumber \\
    \sum_{k^{'}\neq k^{''}=1}^N h^2\beta_{k^{'}}^2\beta_{k^{''}}\delta_{\tau}f_t\delta_{\tau}e^{k^{''}}_t +
    \sum_{k^{'}\neq k^{''}=1}^N h^2\beta_{k^{'}}\beta_{k^{''}}^2\delta_{\tau}f_t\delta_{\tau}e^{k^{'}}_t+\sum_{k^{'}\neq k^{''}=1}^N h^2\beta_{k^{'}}\beta_{k^{''}}\delta_{\tau}e^{k^{'}}_t\delta_{\tau}e^{k^{''}}_t .\nonumber
\end{eqnarray}

As the previous equality is valid for any $t$ and $\tau$, considering a subdivision $\left(t_k\right)_{k\in \llbracket 1,n \rrbracket}$ with time step $\theta:=\frac{t_n-t_0}{n}$ of an arbitrary sub interval $I\subset K$.\\\\
By definition, we have:
\begin{eqnarray}
\forall (i,j)\in \llbracket 1,N \rrbracket^2,
    \begin{cases}
         \sum_{l=1}^n \left(\delta_{t_l}x^i_{t_{l-1}}\right)^2 \xrightarrow[\theta\rightarrow 0]{\Prob} \left<x^i\right>_I\\
         \sum_{l=1}^n \left(\delta_{t_l}f_{t_{l-1}}\right)^2 \xrightarrow[\theta\rightarrow 0]{\Prob} \left<f\right>_I\\
         \sum_{l=1}^n \delta_{t_l}f_{t_{l-1}}\delta_{t_l}e^i_{t_{l-1}}\xrightarrow[\theta\rightarrow 0]{\Prob} \left<f,e^i\right>_I \\
         \sum_{l=1}^n \delta_{t_l}e^i_{t_{l-1}}\delta_{t_l}e^j_{t_{l-1}}\xrightarrow[\theta\rightarrow 0]{\Prob} \left<e^i,e^j\right>_I 
    \end{cases}.
    \nonumber
\end{eqnarray}

Given that $B$ and $B^j$ are independent from $B^i$ for any $i\neq j\in \llbracket 1,N \rrbracket^2$, we have that:
\begin{eqnarray}
    \forall i\neq j\in \llbracket 1,N \rrbracket,\quad\tab  \left<f,e^i\right>_I=0,\tab \left<e^i,e^j\right>_I=0 .\nonumber
\end{eqnarray}
This means that the right hand side of the previous equation converges in probability as $\theta \rightarrow 0$ to: $\sum_{k^{'}=1}^Nh^2\beta_{k^{'}}^2\left<x^{k^{'}}\right>_I+\left(\sum_{k^{'}\neq k^{''}=1}^Nh^2\left(\beta_{k^{'}}\beta_{k^{''}} \right)^2\right)\left<f\right>_I $.\\\\
On the other hand, we have using Eq.~\eqref{eq:lemhatfactor}: 
\begin{eqnarray}
    \sum_{l=1}^n \left(\widehat{\delta_{t_l} f}_{t_{l-1}}\right)^2 \xrightarrow[\theta\rightarrow 0]{\Prob} \left<\hat{f}\right>_I ,\nonumber
\end{eqnarray}
and by the almost sure uniqueness of the limit in probability, we conclude that:

\begin{eqnarray}
\label{refequationqv}
    \left<\widehat{f}\right>_I= \sum_{k^{'}=1}^Nh^2\beta_{k^{'}}^2\left<x^{k^{'}}\right>_I+\left(\sum_{k^{'}\neq k^{''}=1}^Nh^2\left(\beta_{k^{'}}\beta_{k^{''}} \right)^2\right)\left<f\right>_I .
\end{eqnarray}
On the other hand, starting from this identity:
\begin{eqnarray}
    \forall (t,\tau)\in \R_{+}^2 ,   \quad\widehat{\delta_{\tau}f}_t = \delta_{\tau}f_t+\sum_{i=1}^Np_i\delta_{\tau}e^i_t.\nonumber
    \end{eqnarray}
Using the same convergence in probability arguments, we end up with:
\begin{eqnarray}
       \left<\hat{f}\right>_I = \left<f\right>_I+\sum_{i=1}^Np_i^2\left<e^i\right>_I, \tab a.s.\nonumber
    \end{eqnarray}
Using the strong law of large numbers, we have that:
\begin{eqnarray}
       \left<\hat{f}\right>_I = \left<f\right>_I+\underset{N\rightarrow \infty} o\left(1\right), a.s.\nonumber
    \end{eqnarray}


By injecting the latter in Eq.~\eqref{refequationqv}, we obtain after some algebra that:
\begin{eqnarray}
    \left<\hat{f}\right>_I \underset{N\rightarrow\infty}\sim  \frac{1}{h^{-2}-\left(\sum_{k^{'}\neq k^{''}=1}^N\left(\beta_{k^{'}}\beta_{k^{''}} \right)^2\right)}\sum_{k^{'}=1}^N\beta_{k^{'}}^2\left<x^{k^{'}}\right>_I, \tab a.s, \nonumber
\end{eqnarray}
from which the claimed result derives.
\\
