\subsection{The method}\label{subsec: The method}
In this subsection, we present a detailed description of the proposed \texttt{IRMGL+\(\Psi\)} method~\eqref{main iterative schrme}.

\noindent Let us begin by introducing the step size $\alpha_k^\delta$ and the weighted parameter $\beta_k^\delta$ to promote rapid convergence of the method~\eqref{main iterative schrme}. It is natural to select $\alpha_k^\delta$ and $\beta_k^\delta$ adaptively at each iteration in such a way that the iterates remain close to a solution of~(\ref{Model eqn}). Accordingly, we define the parameters 
\begin{equation}\label{alpha}
   0 < \eta \leq  \alpha_k^\delta = \begin{cases}
        \min \left\{ \frac{\eta
    _0\|Au_k^\delta - v^\delta\|^2}{\|A^* (Au_k^\delta -v^\delta)\|^2}, \eta_1 \right\}, & \text{if } \|A^* (Au_k^\delta -v^\delta)\| \neq 0\\ 
     0, &\text{if } \|A^* (Au_k^\delta -v^\delta)\| = 0
   \end{cases}
\end{equation}
\begin{equation}\label{beta}
   \beta_k^\delta =  \begin{cases}
      \min \left\{ \frac{\nu_0 \|A u_k^\delta - v^\delta\|^2}{\|\Delta_{u_k^\delta} u_k^\delta\|}, \frac{\nu_1}{\|\Delta_{u_k^\delta} u_k^\delta\|}, \nu_2 \right\} , & \text{if } \|\Delta_{u_k^\delta} u_k^\delta\| \neq 0\\ 
      0, &\text{if } \|\Delta_{u_k^\delta} u_k^\delta\| = 0,
    \end{cases} 
\end{equation}
where \(\eta_0, \eta_1, \nu_0, \nu_1\) and \(\nu_2\) are some fixed positive constants. 
The pseudo code of the iterative scheme~\eqref{main iterative schrme} is outlined in \Cref{alg:buildtree}.
\begin{remark}
    At each \((k+1)\)-th iteration of the Algorithm~\ref{alg:buildtree}, a new graph Laplacian \(\Delta_{u_k^\delta}\) is constructed based on the previous approximate solution \(u_k^\delta\), for any given initial reconstructor \(\Psi\). In other words, the regularization term is adaptively updated at each iteration.
\end{remark}
% It is assumed that \( \|\Delta_{u_k^\delta} u_k^\delta\| \neq 0 \) to ensure the well-posedness of the expression.



\begin{algorithm}
\caption{\texttt{IRMGL+\(\Psi\)} with early stopping}
\label{alg:buildtree}
\begin{algorithmic}
\STATE{Given: $A, v^\delta, \delta, \Psi, \sigma, R.$}
\STATE{Initialize: $u_0^\delta=\Psi(v^\delta)$}
\WHILE{$\|Au_k^\delta - v^\delta\|> \tau \delta$}
\STATE{Given $u_{k}^\delta, R, \sigma,$ compute $\Delta_{u_k^\delta}$ as defined in Section \ref{sec:prem}.}
\STATE{Update $u_{k+1}^\delta = u_k^\delta - \alpha_k^\delta A^*(Au_k^\delta - v^\delta) - \beta_k^\delta \Delta_{u_k^\delta}u_k^\delta,$}
\STATE{where $\alpha_k^\delta$ and $\beta_k^\delta$ are defined in \eqref{alpha} and \eqref{beta}, respectively.}
\ENDWHILE
\RETURN $u_{k_\delta}^\delta.$
\end{algorithmic}
\end{algorithm}
\begin{lemma}\label{Lemma: Monotonicity}
    Let \Cref{hypo: bounded} and $\ref{hypo: soln existence}$ hold. Consider \Cref{alg:buildtree} and let $n \leq k_\delta$  be an integer, where $k_\delta$ is the stopping index as defined in $(\ref{eqn: discrepancy})$. Let
    \begin{equation}\label{assum: On C}
       C:= \eta- \frac{\eta_1}{\tau} -\nu_0(\wp + \nu_1) - \eta_0\eta_1 > 0.
         \end{equation}
    Then the following hold: 
    \begin{enumerate}
        \item [(i)] The monotone behavior of the iterates of \texttt{IRMGL+\(\Psi\)} $(\ref{main iterative schrme})$ for $0 \leq k < n$, i.e.,
        $$\|u_{k+1}^\delta - u^\dagger\| \leq  \|u_{k}^\delta - u^\dagger\|.$$
        \item [(ii)] The iterates $u_k^\delta \in \mathcal{B}(u^\dagger, \wp)$ for all $0 \leq k \leq n$ and  
        \[\sum_{k=0}^{n}  \|Au_k^\delta - v^\delta\|^2 \leq  \frac{1}{2C} \|u_{0}^\delta - u^\dagger\|^2.\] 
        \end{enumerate}
%     Moreover assume that there exist $C_\beta^\delta>0$ such that 
%    \begin{align}
%     \beta_k^\delta &\leq C_\beta^\delta \|A u_k^\delta - v^\delta\|, \label{Assum: on beta} \\
%     \|\Delta_{u_k^\delta} u_k^\delta\| &\leq \gamma \|A u_k^\delta - v^\delta\|. \label{Assum: On Delta}
% \end{align}
%     Then $u_{k+1}^\delta \in \mathcal{B}(u^\dagger, \wp)$ and 
\end{lemma}
\begin{proof}
By \Cref{hypo: soln existence}, we have $u_0 \in \mathcal{B}(u^\dagger, \wp)$. Suppose further that $u_k^\delta \in \mathcal{B}(u^\dagger, \wp)$ for some iteration $k$. This implies that $u_k^\delta \in \mathcal{B}(u_0, 2\wp)$. We define
\[
x_k^\delta := u_k^\delta - u^\dagger \quad \text{and} \quad d_k^\delta := \alpha_k^\delta A^*(Au_k^\delta - v^\delta) + \beta_k^\delta \Delta_{u_k^\delta}u_k^\delta.
\]
With these definitions and in view of the update rule given in (\ref{main iterative schrme}), we obtain
\begin{equation}\label{split eqn}
    \|x_{k+1}^\delta\|^2 - \|x_k^\delta\|^2 = \|d_k^\delta\|^2 - 2\langle x_k^\delta, d_k^\delta \rangle.
\end{equation}
We now proceed to analyze each term on the right-hand side of the \eqref{split eqn}  individually. To begin, we consider the second term and estimate it as
\begin{align}\label{ek, dk}
 \nonumber  - \langle x_k^\delta, d_k^\delta \rangle &= \alpha_k^\delta \langle A(u^\dagger - u_k^\delta), Au_k^\delta - v^\delta \rangle + \beta_k^\delta \langle u^\dagger - u_k^\delta, \Delta_{u_k^\delta}u_k^\delta \rangle \\ \nonumber
   & = - \alpha_k^\delta \|Au_k^\delta - v^\delta\|^2 + \alpha_k^\delta\langle v - v^\delta, Au_k^\delta - v^\delta \rangle +  \beta_k^\delta \langle u^\dagger - u_k^\delta, \Delta_{u_k^\delta}u_k^\delta \rangle \\ \nonumber
   & \leq  - \alpha_k^\delta \|Au_k^\delta - v^\delta\|^2 + \alpha_k^\delta\delta\|Au_k^\delta - v^\delta\| + \beta_k^\delta\wp \| \Delta_{u_k^\delta}u_k^\delta\| \\ 
   & \leq - \left(\eta - \frac{\eta_1}{\tau}\right)\|Au_k^\delta - v^\delta\|^2 + \wp\nu_0 \|Au_k^\delta - v^\delta\|^2,
\end{align}
where we have used (\ref{eqn: delta}), (\ref{eqn: discrepancy}) and \eqref{alpha} in deriving \eqref{ek, dk}. 
Similarly, by using the definitions of $\alpha_k^\delta$ and $ \beta_k^\delta$ with the inequality $(a_1 + a_2)^2 \leq 2(a_1^2 + a_2^2)$ for $a_1, a_2 \in \mathbb{R}$, we can estimate the first term of (\ref{split eqn}) as
\begin{align}\label{dk}
 \nonumber   \|d_k^\delta\|^2 &= \| \alpha_k^\delta A^*(Au_k^\delta - v^\delta) + \beta_k^\delta \Delta_{u_k^\delta}u_k^\delta\|^2 \\ \nonumber
    & \leq 2 \eta_0\eta_1 \|Au_k^\delta - v^\delta\|^2 + 2\nu_0 \nu_1\|Au_k^\delta - v^\delta\|^2 \\ 
    & \leq 2(\eta_0\eta_1+ \nu_0 \nu_1)\|Au_k^\delta - v^\delta\|^2. 
\end{align}
 Further, by using (\ref{ek, dk}) and (\ref{dk}) in (\ref{split eqn}), we get
\begin{equation}\label{Concluding eqn of first Lemma}
     \|x_{k+1}^\delta\|^2 - \|x_k^\delta\|^2 \leq -2\left( \eta- \frac{\eta_1}{\tau} -\nu_0(\wp + \nu_1) - \eta_0\eta_1\right)\|Au_k^\delta - v^\delta\|^2.
\end{equation}
Finally, by substituting (\ref{assum: On C}) in (\ref{Concluding eqn of first Lemma}), we obtain the required monotonicity for $0 \leq k <n$.
Next, we discuss the proof of assertion $(ii)$. The inequality (\ref{Concluding eqn of first Lemma}) guarantees that
\[
\|u_{k+1}^\delta - u^\dagger\| \leq \|u_{k}^\delta - u^\dagger\| \leq \wp,
\]
which implies that $u_{k+1}^\delta \in \mathcal{B}(u^\dagger, \wp)$. By summing the inequality (\ref{Concluding eqn of first Lemma}) from $k = 0$ to $k = n$, we obtain
\begin{equation}\label{Concluding eqn of first Lemma in C}
   \sum_{k=0}^{n} \left[\|x_{k+1}^\delta\|^2 - \|x_k^\delta\|^2\right] \leq -2C  \sum_{k=0}^{n}\|Au_k^\delta - v^\delta\|^2.
\end{equation}
Finally, it follows from the last inequality that
\begin{equation*}
 \sum_{k=0}^{n}\|Au_k^\delta - v^\delta\|^2 \leq \frac{1}{2C} \|x_{0}^\delta\|^2 = \frac{1}{2C}\|u_0^\delta - u^\dagger\|^2.
\end{equation*}
This establishes the desired result.
\end{proof}

\noindent In the following result, we show that \texttt{IRMGL+\(\Psi\)} method terminates in a finite number of steps, i.e., Algorithm \ref{alg:buildtree} is well defined. The proof leverages Lemma~\ref{Lemma: Monotonicity} to substantiate this conclusion.

\begin{theorem}
    Let all the assumptions of \Cref{Lemma: Monotonicity} be satisfied. Let \Cref{alg:buildtree} be initiated with given $u_0^\delta$. Then the algorithm must terminates in finitely many steps, i.e., there exist a finite integer $k_\delta$ such that 
    \begin{equation*}
        \|Au_{k_\delta}^\delta - v^\delta\| \leq \tau \delta < \|Au_k^\delta - v^\delta\|, \quad 0 \leq k < k_\delta.
    \end{equation*}
\end{theorem}
\begin{proof}
Suppose \( n \geq 0 \) is an integer such that \( \|A u_k^\delta - v^\delta\| > \tau \delta \) holds for all \( k = 0, 1, \dots, n \). Then, be engaging \eqref{Concluding eqn of first Lemma in C}, we obtain
% We sum the inequality (\ref{Concluding eqn of first Lemma}) from $0$ to $k_\delta$, that is
\begin{align*}
     2C\sum_{k=0}^{k=n}  \|Au_k^\delta - v^\delta\|^2 &\leq \sum_{k=0}^{k = n}\left[\|x_{k}^\delta\|^2 - \|x_{k+1}^\delta\|^2\right],\\
     & = \|x_0^\delta\|^2 - \|x_{n+1}^\delta\|^2 \leq \|x_0^\delta\|^2.
\end{align*}
% \begin{equation*}
%     \|x_{0}^\delta\|^2 - \|x_{k_\delta}^\delta\|^2 \geq 2C  \sum_{k=0}^{k_\delta-1}\|Au_k^\delta - v^\delta\|^2.
% \end{equation*}
By virtue of \eqref{eqn: discrepancy}, we deduce that
\begin{equation}\label{eqn: thm 3.5 conclusion}
  2(n+1)C\tau^2\delta^2\leq  2C\sum_{k=0}^{k=n}  \|Au_k^\delta - v^\delta\|^2 \leq \|x_0^\delta\|^2 < \infty.
\end{equation}
% Using the fact that $\|x_{0}^\delta\|^2 \geq \|x_{0}^\delta\|^2 - \|x_{k_\delta}^\delta\|^2$ and (\ref{Assum: discrepacy}), from the above inequality it is straightforward to obtain
% \begin{equation*}
%     \infty > \|x_0^\delta\| \geq 2Ck_\delta (\tau\delta)^2,
% \end{equation*}
If there exists no finite integer \( k_\delta \) such that condition (\ref{eqn: discrepancy}) is satisfied, then by taking the limit as \( n \to \infty \) in \eqref{eqn: thm 3.5 conclusion}, we get a contradiction. Therefore,  Algorithm \ref{alg:buildtree} is guaranteed to terminate after a finite number of iterations.
\end{proof}
\subsection{Convergence for exact data}\label{Subsec: Convergence for exact data}
In this subsection, we investigate the counterpart of Algorithm~\ref{alg:buildtree} in the form of \Cref{alg:exactdata} that employs the exact data \( v \) instead of $v^\delta$.
\begin{algorithm}
\caption{\texttt{IRMGL+\(\Psi\)} with exact data}
\label{alg:exactdata}
\begin{algorithmic}
\STATE{Given: $A, v, \Psi, \sigma, R.$}
\STATE{Initialize: $u_0=\Psi(v)$}
\WHILE{$k \geq0$}
\STATE{Given $u_{k}, R, \sigma,$ compute $\Delta_{u_k}$ as defined in Section \ref{sec:prem}.}
\STATE{Update $u_{k+1} = u_k - \alpha_k A^*(Au_k - v) - \beta_k \Delta_{u_k}u_k,$}
\STATE{where $\alpha_k$ and $\beta_k$ are defined as  \begin{equation*}
     \alpha_k = \min \left\{ \frac{\eta
    _0\|Au_k - v\|^2}{\|A^* (Au_k -v)\|^2}, \eta_1 \right\} \quad \text{when } Au_k \neq v,
\end{equation*}
\begin{equation*}
   \beta_k =  \begin{cases}
      \min \left\{ \frac{\nu_0 \|A u_k - v\|^2}{\|\Delta_{u_k} u_k\|}, \frac{\nu_1}{\|\Delta_{u_k} u_k\|}, \nu_2 \right\} , & \text{if } \|\Delta_{u_k} u_k\| \neq 0\\ 
      0, &\text{if } \|\Delta_{u_k} u_k\| = 0
    \end{cases} 
\end{equation*}}
\ENDWHILE
% \RETURN $u_{k_\delta}^\delta.$
\end{algorithmic}
\end{algorithm}
To establish the convergence of our method for exact data, we demonstrate that the sequence \(\{u_k\}_{k \geq 0} \) generated by Algorithm~\ref{alg:exactdata} forms a Cauchy sequence. 
We begin by presenting a preliminary result for the sequence \( \{u_k\}_{k \geq 0} \).

\begin{lemma}\label{lemma: monotonicity for exact data}
    Let \Cref{hypo: bounded} and  \Cref{hypo: soln existence} hold. Let $\{u_k\}_{k \geq 0}$ be the sequence of iterates generated by the \Cref{alg:exactdata}. Then $u_k \in \mathcal{B}(u^\dagger, \wp)$ for all integers $k \geq 0$ and for the solution $u^\dagger$ of $(\ref{Model eqn})$, there holds
 \begin{equation}
     \|u_{k+1} - u^\dagger\|^2 - \|u_k - u^\dagger\|^2 \leq -2C_0 \|Au_k - v\|^2 \quad \forall k \geq0,
 \end{equation}
 where $$C_0: = \eta  -\nu_0(\wp + \nu_1) - \eta_0\eta_1 > 0.$$ Also, the sequence $\{\|u_k - u^\dagger\|\}_{k \geq 0}$ is monotonically decreasing and 
 \begin{equation}\label{sum for non noisy case}
     \sum_{k=0} ^\infty \|Au_k - v\|^2 \leq \frac{1}{2C_0} \|u_0 - u^\dagger\|^2 < \infty.
 \end{equation}
 This means that $\|Au_k - v\| \to 0$ as $k \to \infty$ i.e.,  the residual norm converges to zero. 
\end{lemma}
\begin{proof}
   The result follows directly by analogy with the proof of Lemma \ref{Lemma: Monotonicity}.
\end{proof}
  \noindent To this end,we are ready to  to present the convergence result in the case of $\delta=0$.
\begin{theorem}\label{Convergence for exact data}
   Under the assumptions of \Cref{lemma: monotonicity for exact data}, the iterates $\{u_k\}_{k \geq 0}$ generated by \Cref{alg:exactdata} converges to $u^\dagger$, which is a solution of $(\ref{Model eqn})$.
\end{theorem}
\begin{proof}
    For $\delta =0,$ we define $x_k:= u_k - u^\dagger$ and $r_k:=Au_k -v$. Given $l \geq k$, we choose an integer $m$ with $l \geq m \geq k$ such that
    \begin{equation}\label{rn rp ineq}
        \|r_m\| \leq \| r_n\|, \quad \forall \hspace{1mm} k \leq n \leq l.
    \end{equation}
    By triangular inequality, we observe that 
\begin{equation}\label{xk triangular}
    \|x_l - x_k\| \leq \|x_l - x_m\| + \|x_m - x_k\|,
\end{equation}    
where 
\begin{align}
    \|x_l - x_m\|^2 &= 2\langle x_m - x_l, x_m \rangle + \|x_l\|^2 - \|x_m\|^2, \label{xl_xn} \\
    \|x_m - x_k\|^2 &= 2\langle x_k - x_m, x_m \rangle + \|x_m\|^2 - \|x_k\|^2. \label{xn_xm}
\end{align}
 From Lemma \ref{lemma: monotonicity for exact data} it is clear that $\{\|x_k\|\}_{k \geq 0}$ is a monotonically decreasing sequence bounded below by $0.$ Consequently, we suppose that \(\lim_{k \to \infty}\|x_k\| = \theta \geq 0.\) Hence, as a result, we write
\begin{align}
     \lim_{k \to \infty }\|x_l - x_m\|^2 &= 2 \lim_{k \to \infty }\langle x_m - x_l, x_m \rangle + \theta^2 - \theta^2, \label{xl xm limit}\\
     \lim_{k \to \infty }\|x_m - x_k\|^2 &= 2 \lim_{k \to \infty }\langle x_k - x_m, x_m \rangle + \theta^2 - \theta^2.\label{xm xk limit}
\end{align} 
Our aim is to demonstrate that $\{x_k\}_{k \geq 0}$ is a Cauchy sequence. To this end, we claim that $\langle x_m - x_l, x_m \rangle \to 0$ as $k \to \infty$. For proving the claim, it can be observe that  
\begin{align}
 \nonumber   |\langle x_m - x_l, x_m\rangle| &= |\langle u_m - u_l, x_m\rangle| \\ \nonumber
    & \leq \left| \left\langle \sum_{j=m}^{l-1} \alpha_j A^*(Au_j - v) + \beta_j \Delta_{u_j}u_j, u_m - u^\dagger \right\rangle \right| \\ \nonumber
     & \leq \sum_{j=m}^{l-1}\left| \left\langle  \alpha_j A^*(Au_j- v), u_m - u^\dagger \right\rangle \right| + \sum_{j=m}^{l-1}\left| \left\langle \beta_j \Delta_{u_j}u_j, u_m - u^\dagger \right\rangle \right| \\ \nonumber
     & \leq \eta_1 \sum_{j=m}^{l-1}\left| \left\langle   Au_j- v, Au_m - v \right\rangle \right| + \sum_{j=m}^{l-1}\beta_j \left| \left\langle  \Delta_{u_j}u_j, u_m - u^\dagger \right\rangle \right|, 
\end{align}
where, we have utilized the bound on $\alpha_j$ and the relation $Au^\dagger =v$ in deriving the last inequality.
Furthermore, by incorporating the definition of $\beta_k$ together with inequality~(\ref{rn rp ineq}), and using the fact that $u_k \in \mathcal{B}(u^\dagger, \wp)$ for all $k \geq 0$, the above inequality can be reformulated as 
\begin{align}\label{x_n x_l in terms of residual}
   \nonumber   |\langle x_m - x_l, x_m\rangle| & \leq \eta_1 \sum_{j=m}^{l-1}\|Au_j - v\|^2 + \wp \nu_0 \sum_{j=m}^{l-1}\|Au_j - v\|^2 \\ 
   &  \leq (\eta_1 + \wp\nu_0)\sum_{j=m}^{l-1}\|Au_j - v\|^2.
\end{align}
Reasoning in the same way for $|\langle x_k - x_m, x_m \rangle|$, we may write
\begin{equation}
 |\langle x_k - x_m, x_m \rangle| \leq    (\eta_1 + \wp \nu_0)\sum_{j=k}^{l-1}\|Au_j - v\|^2.
\end{equation}
From these estimates, it follows that \( |\langle x_m - x_l, x_m \rangle| \) and \( |\langle x_k - x_m, x_m \rangle| \) tend to zero as \( k \to \infty \), owing to \eqref{sum for non noisy case}. Consequently, from (\ref{xl xm limit}) and \eqref{xm xk limit} it follows that
\begin{align*}
     \lim_{k \to \infty }\|x_l - x_m\|^2 &= 2 \lim_{k \to \infty }\langle x_m - x_l, x_m \rangle =0, \\
     \lim_{k \to \infty }\|x_m - x_k\|^2 &= 2 \lim_{k \to \infty }\langle x_k - x_m, x_m \rangle =0.
\end{align*}
Hence, from \eqref{xk triangular}, \eqref{xl_xn} and \eqref{xn_xm}, it follows that the sequence \( \{x_k\}_{k \geq 0} \) is Cauchy. By the definition of \( x_k \), this immediately implies that the sequence \( \{u_k\}_{k \geq 0} \) is also Cauchy and therefore converges to some limit \( \hat{u} \). Furthermore, since the residuals \( Au_k - v \) tend to zero as \( k \to \infty \), the limit \( \hat{u} \) satisfies \eqref{Model eqn}, which concludes that $\hat{u} = u^\dagger$. Consequently, the iterates  converge to a solution of \eqref{Model eqn}.
\end{proof}
\subsection{Stability analysis}\label{subsec: stability}
In this subsection, we establish the stability of the \texttt{IRMGL+\(\Psi\)} method. For that, we require the following assumption. 
% we consider the choice of step sizes and weighted parameters, that satisfies
%  \[\alpha_k^\delta \to \alpha_k \quad \text{and} \quad \beta_k^\delta \to \beta_k \quad \text{as} \quad \delta \to 0, \quad \forall k \geq 0.\]
% Additionally, to establish the stability result for the proposed method
 \begin{assumption}\label{hypothesis stability}
     Let $v^\delta
     $ be the sequence of noisy data such that \(v^\delta \to v\) as \(\delta \to 0\). Then the reconstructor $\Psi$ satisfies
     \begin{equation*}
         \|\Psi(v^\delta) - \Psi(v)\| \to 0 \quad \text{as} \quad \delta \to 0.
     \end{equation*}
 \end{assumption}
It is worth noting that the above assumption is relatively mild and is satisfied by a broad class of reconstruction operators. A straightforward example is to consider \( \Psi \) as a (locally) Lipchitz continuous operator. That is, if \( \Psi \) satisfies
\[
\|\Psi(v^\delta) - \Psi(v)\| \leq K \|v^\delta - v\|,
\]
for some constant \( K > 0 \), then the assumption is clearly fulfilled. The following remark presents another example that satisfies \Cref{hypothesis stability}.
\begin{remark}
    A standard Tikhonov regularization method may also serve as a viable choice for the initial reconstructor \(\Psi\). Specifically, one may define 
    \begin{equation}\label{eqn: tikhonov}
          \Psi(v^\delta) = (A^T A + \gamma I)^{-1} A^T v^\delta,
    \end{equation}
    where \(\gamma > 0\) is the regularization parameter.
\end{remark}
\noindent
The main difficulty in establishing stability results stems from the regularization term \( \mathcal{R}(u, v^\delta) \), which explicitly depends on the observed data \( v^\delta \).
Consequently, conventional analytical techniques cannot be applied in a straightforward manner and hence we propose a lemma that plays a crucial role in the stability analysis. It is worth noting that a similar result was established in \cite{bianchi2025data} for the variational setting, however, the analysis presented here is fundamentally different from that work.


\begin{lemma}\label{lemma: contraction of Delta}
  For the iterates \(u_k^\delta\) and $u_k$ generated by \Cref{alg:buildtree} and \Cref{alg:exactdata} respectively, it holds that 
  \begin{equation*}
      \|\Delta_{u_k^\delta}u_k - \Delta_{u_k}u_k\|_2 \leq \mathcal{H} \|u_k\|_2\|u_k^\delta - u_k\|_2,
  \end{equation*}
    where the constant \[\mathcal{H} =2 L_h \left( \max_{a,b}{g(a, b)}\sqrt{|S|}  +  \max_{a}\max_{b}{g(a, b)}\right),\] with \(g(a,b)\) the edge weight function specified in \eqref{eqn: edge weight fun}.
\end{lemma}
\begin{proof}
% Since \( u_k^\delta, u_k\) are the iterates generated by Algorithm 1 corresponding to noisy and non-noisy case.
From triangular inequality and submultiplicativity of the operator norm, we have 
\[\|\Delta_{u_k^\delta}u_k - \Delta_{u_k}u_k\|_2 \leq \|\Delta_{u_k^\delta} - \Delta_{u_k}\|_s \|u_k\|_2,\]
where $\|\cdot\|_s$ denotes the spectral norm (i.e., matrix operator norm induced by the Euclidean vector norm). We recall that, for any vector $u$, the graph Laplacian is given by 
\[
\Delta_{u} = D_{u} - W_{u},
\]
where the weight matrix \( W_{u} \) and the diagonal degree matrix \(D_{u}\) are same as defined in subsection~\ref{subsec: Graph Theory}. Using this result, it can be noted that
\begin{equation}\label{eqn: delta split in D and W}
  \| \Delta_{u_k^\delta} - \Delta_{u_k} \|_s \leq \| D_{u_k^\delta} - D_{u_k} \|_s + \| W_{u_k^\delta} - W_{u_k} \|_s.  
\end{equation}
\noindent
Next, we individually estimate both the terms of right hand side of the above inequality, starting with the second term. For that, the entry-wise difference is 
\[
|w_{u_k}(a, b) - w_{u_k^\delta}(a, b)|= g(a, b)|h_{u_k}(a, b)-h_{u_k^\delta}(a, b) |,
\]
where \( h_{u} \) is a Lipchitz continuous Gaussian kernel function for any vector $u$ with Lipchitz constant $L_h$. Hence, we have that
\begin{align*}
    |w_{u_k}(a, b) - w_{u_k^\delta}(a, b)| &= g(a, b)L_h \left||u_k(a) -u_k(b)| - |{u_k^\delta}(a) -  {u_k^\delta}(b)| \right| \\
    & \leq g(a, b)L_h  \left|(u_k(a) -u_k(b)) - ({u_k^\delta}(a) -  {u_k^\delta}(b))\right| \\
    & \leq g(a, b)L_h  \left|(u_k(a) -u_k^\delta(a)) - (u_k(b) -  {u_k^\delta}(b))\right|\\
    &\leq g(a, b)L_h  \left(\left|u_k(a) -u_k^\delta(a)\right| + \left|u_k(b) -  {u_k^\delta}(b)\right|\right).
\end{align*}
Thus, we arrive at
\[\| W_{u_k^\delta} - W_{u_k} \|_F^2 \leq (\max_{a,b}{g(a, b)}L_h)^2 \sum_{a,b \in S} \left(|u_k(a) -u_k^\delta(a)| + |u_k(b) -  {u_k^\delta}(b)|\right)^2,\] 
where $\|\cdot\|_F$ denotes the Frobenius norm and $S$ denotes the set associated with the edge-weight function $g(a, b).$
After solving the above estimate and using the fact that \(\|\cdot\|_s \leq \|\cdot\|_F\), we get
\begin{equation}\label{eqn: Wuk estimate}
\| W_{u_k^\delta} - W_{u_k} \|_s \leq  \| W_{u_k^\delta} - W_{u_k} \|_F  \leq 2 \max_{a,b}{g(a, b)}L_h\sqrt{|S|} \|u_k^\delta - u_k^\delta\|_2.
\end{equation}
Similarly, we estimate the first term of \eqref{eqn: delta split in D and W} in which each diagonal entry satisfies
\begin{align*}
 |d_{u_k}(a)-d_{u_k^\delta}(a)| &= \left| \sum_{b \in S} (w_{u_k}(a, b) - w_{u_k^\delta}(a, b)) \right| \leq \sum_{b \in S} |w_{u_k}(a, b) - w_{u_k^\delta}(a, b)| \\
 &\leq \max_{b}{g(a, b)}L_h \sum_{b \in S}  \left(|u_k(a) -u_k^\delta(a)| + |u_k(b) -  {u_k^\delta}(b)| \right) \\
 & \leq 2 \max_{b}{g(a, b)}L_h   \|u_k -u_k^\delta\|_2.
\end{align*}
This yields that
\begin{equation}\label{eqn: Duk estimate}
    \| D_{u_k^\delta} - D_{u_k} \|_s = \max_{a} |d_{u_k}(a)-d_{u_k^\delta}(a)| \leq 2 \max_{a}\max_{b}{g(a, b)}L_h  
    \|u_k -u_k^\delta\|_2. 
\end{equation}
Plugging (\ref{eqn: Wuk estimate}) and (\ref{eqn: Duk estimate}) in (\ref{eqn: delta split in D and W}) to arrive at
\[
\|  \Delta_{u_k^\delta} - \Delta_{u_k} \|_s \leq \mathcal{H}  \|u_k^\delta - u_k\|_2,
\]
where $\mathcal{H}$ is the same constant as defined in the statement. Thus, the result holds.
\end{proof}
\noindent
Next, we show that  the Lemma~\ref{lemma: contraction of Delta}, in conjunction with \Cref{hypothesis stability}, establishes the stability required to link Algorithm~\ref{alg:buildtree} with Algorithm~\ref{alg:exactdata}. This is formalized in the following result.


 \begin{lemma}\label{lemma: stability}
 Let Assumptions~$\ref{hypo: bounded}, \ref{hypo: soln existence}$ and $\ref{hypothesis stability}$ hold. Then for each fixed integer $k \geq 0$, there holds 
 \begin{equation}
    u_k^\delta \to u_k \quad \text{as} \quad \delta \to 0,
 \end{equation} 
 where $u_k^\delta$ and $u_k$ are same as in \Cref{alg:buildtree} and \Cref{alg:exactdata}.
 \end{lemma}
\begin{proof}
   We establish the result by induction. For the base case \( k = 0 \), note that \( u_0^\delta = \Psi(v^\delta) \) and \( u_0 = \Psi(v) \). Therefore, the claim holds trivially by \Cref{hypothesis stability}. Next, let us assume that the statement holds for all \( 0 \leq j \leq k \). We aim to show that it also holds for \( j = k+1 \), i.e., \( u_{k+1}^\delta \to u_{k+1} \) as \( \delta \to 0 \). 
    From (\ref{main iterative schrme}), we have 
    \begin{align}\label{x_k+1 to x_k}
    \nonumber u_{k+1}^\delta - u_{k+1} &= (u_k^\delta - u_k) -  \left( \alpha_k^\delta A^*(Au_k^\delta - v^\delta) - \alpha_k A^*(Au_k - v) \right)\\
     & \quad -(\beta_k^\delta \Delta_{u_k^\delta}u_k^\delta - \beta_k \Delta_{u_k}u_k).
    \end{align}
We begin by establishing that  
\[
\alpha_k^\delta A^*(Au_k^\delta - v^\delta) \to \alpha_k A^*(Au_k - v) \quad \text{as } \delta \to 0.
\]
To this end, we utilize that \( u_k^\delta \to u_k \) and \( v^\delta \to v \) as \( \delta \to 0 \) to establish that
\[
\alpha_k^\delta = \min \left\{ \frac{\eta_0 \|Au_k^\delta - v^\delta\|^2}{\|A^*(Au_k^\delta - v^\delta)\|^2}, \eta_1 \right\}
\to
\min \left\{ \frac{\eta_0 \|Au_k - v\|^2}{\|A^*(Au_k - v)\|^2}, \eta_1 \right\} = \alpha_k,
\]
where we have assumed \( \|A^*(Au_k^\delta - v^\delta)\| \neq 0 \), the case when this norm vanishes is trivial. Consequently, we obtain
\begin{align}\label{Eqn: (3.26)}
\left\| \alpha_k^\delta A^*(Au_k^\delta - v^\delta) - \alpha_k A^*(Au_k - v) \right\|
& \leq \alpha_k^\delta \left\| A^*(Au_k^\delta - v^\delta) - A^*(Au_k - v) \right\| \nonumber \\
& \quad + \left| \alpha_k^\delta - \alpha_k \right| \left\| A^*(Au_k - v) \right\| \to 0 \text{ as }  \delta \to 0.
\end{align}
In a similar vein, assume that \( \|\Delta_{u_k^\delta} u_k^\delta\| \neq 0 \). Then, by the definitions of \( \beta_k^\delta \) and \( \beta_k \), we obtain
\[
\beta_k^\delta = 
\min \left\{ \frac{\nu_0 \|A u_k^\delta - v^\delta\|^2}{\|\Delta_{u_k^\delta} u_k^\delta\|}, \nu_1 \right\} \to 
\min \left\{ \frac{\nu_0 \|A u_k - v\|^2}{\|\Delta_{u_k} u_k\|}, \nu_1 \right\} = \beta_k
\quad \text{as } \delta \to 0.
\]
This convergence follows from the induction hypothesis and Lemma~\ref{lemma: contraction of Delta}, which ensures that\( \|\Delta_{u_k^\delta} u_k^\delta\| \to \|\Delta_{u_k} u_k\| \) as \( \delta \to 0 \). Thus, we have
\begin{align} \label{eqn: (3.27)}
  \|\beta_k^\delta \Delta_{u_k^\delta}u_k^\delta &- \beta_k \Delta_{u_k}u_k\| \leq  \|\beta_k^\delta \Delta_{u_k^\delta}u_k^\delta - \beta_k^\delta \Delta_{u_k^\delta}u_k\| + \|\beta_k^\delta \Delta_{u_k^\delta}u_k - \beta_k \Delta_{u_k}u_k\| \nonumber \\ 
&\quad \leq  \|\beta_k^\delta \Delta_{u_k^\delta}(u_k^\delta - u_k)\| +\left(|\beta_k^\delta - \beta_k|\| \Delta_{u_k^\delta}\| +  \beta_k \|\Delta_{u_k^\delta} - \Delta_{u_k}\|\right)\|u_k\|  \nonumber \\ 
&\quad \leq  \|\beta_k^\delta \Delta_{u_k^\delta}\|\|u_k^\delta - u_k\| +\left(|\beta_k^\delta - \beta_k|\| \Delta_{u_k^\delta}\| +  \beta_k \|\Delta_{u_k^\delta} - \Delta_{u_k}\|\right)\|u_k\|.
\end{align} 
Therefore, by applying Lemma~\ref{lemma: contraction of Delta} to the above expression along with the induction hypothesis, we conclude that 
\[
\beta_k^\delta \Delta_{u_k^\delta} u_k^\delta \to \beta_k \Delta_{u_k} u_k \quad \text{as } \delta \to 0.
\]
Consequently, it follows from \eqref{x_k+1 to x_k}, \eqref{Eqn: (3.26)}, \eqref{eqn: (3.27)} and the induction hypothesis that
\(
u_{k+1}^\delta \to u_{k+1} \text{ as } \delta \to 0.
\) This completes the proof.
\end{proof}
\subsection{Convergence for noisy data}\label{subsec: nonnoisy} In this subsection, our goal is to establish the regularization property of \texttt{IRMGL+\(\Psi\)} method. It is worth emphasizing that, in general, convergence of the method with noisy data cannot be guaranteed, as the perturbed data \( v^\delta \) may not belong to the range of the operator \( A \), i.e., \( v^\delta \notin \mathcal{R}(A) \). 
\begin{theorem}\label{thm: non noisy}
   Under the assumptions of \Cref{lemma: stability}, if $k_\delta$ is the stopping index as defined in \eqref{eqn: discrepancy} for the method defined in  \Cref{alg:buildtree}, then there exist a solution $u^\dagger$ of $(\ref{Model eqn})$ such that 
    \[\lim_{\delta \to 0} \|u_{k_\delta}^\delta - u^\dagger\| = 0.\]
    \begin{proof}
        Let $u^\dagger$ be the solution of (\ref{Model eqn}) determined in Theorem \ref{Convergence for exact data} such that \(\|u_k - u^\dagger\| \to 0\) as \(\delta \to 0\), where $\{u_k\}_{k \geq 0}$ denotes the sequence of iterates determined by the Algorithm~\ref{alg:exactdata} using the exact data. We assume that there is a sequence $\{\delta_n\}$ such that $\delta_n \to 0$ as $n \to \infty,$ and let $v^{\delta_n}$ be the associated noisy data sequence. The corresponding stopping index for each pair $(\delta_n, v^{\delta_n}),$ as established by (\ref{eqn: discrepancy}), is represented by $k_n:=k_{\delta_n}$.
      We shall examine two scenarios in order to demonstrate the desired outcome.

      \textit{Case-I:} Consider that for some finite integer $\Bar{k}$, $k_n \to \Bar{k}$ as $n \to \infty$. Then, for all large $n$, we may assume that $k_n = \Bar{k}$. Consequently, using the definition of $k_n$, we obtain
      \begin{equation}\label{discrepancy in last result}
       \|Au_{\Bar{k}}^{\delta_n} - v^{\delta_n}\| \leq \tau \delta_n.   
      \end{equation}
       Taking the limit as \( n \to \infty \) in \eqref{discrepancy in last result} and applying Lemma \ref{lemma: stability}, we obtain \( A u_{\bar{k}} = v \). Then, by invoking Theorem \ref{Convergence for exact data}, it follows that \( u_{\bar{k}} = u^\dagger \). Consequently, we conclude that \( u_{k_n}^{\delta_n} \to u^\dagger \) as \( n \to \infty \).

    \textit{Case-II:} Next, assume that there exist a sequence $\{\delta_n\}$ with  $\delta_n \to 0$ such that $k_n:= \hat{k}_{\delta_n} \to \infty$ as $n \to \infty$, and let $v^{\delta_n}$ be the corresponding sequence of noisy data. Let $k$ be sufficiently large fixed integer. 
        From Lemma~\ref{lemma: monotonicity for exact data}, it follows that there exist an $\varepsilon >0$ such that $\|u_k - \hat{u}\| \leq \frac{\varepsilon}{2}$. Since for fixed $k,$ using Lemma~\ref{lemma: stability}, there is a $n=(k, \varepsilon)$ such that $\|u_k^{\delta_n} - u_k\|\leq \frac{\varepsilon}{2}$ for all $n > n(k, \varepsilon).$
        Then, for sufficiently large $n$, such that $k_n > k$, we conclude from Lemma~\ref{Lemma: Monotonicity} that 
        \begin{align*}
            \|u_{k_n}^{\delta_n}-\hat{u}\| &\leq \|u_{k_n -1}^{\delta_n} - \hat{u}\| \leq \cdots \leq \|u_k^{\delta_n} - \hat{u}\|\\
            & \leq \|u_{k}^{\delta_n} - u_k\| + \|u_k - \hat{u}\| \leq \varepsilon.
        \end{align*}
      Consequently, the outcome follows.
    \end{proof}
\end{theorem}
\section{Numerical experiments and discussion}
\label{sec: numerical}
In this section, we present the numerical simulations for two-dimensional (2D) computed tomography (CT) and image deblurring applications. We describe the experimental setup, problem setting, and a number of numerical tests that were performed to assess the effectiveness of the \texttt{IRMGL+\(\Psi\)} method. Furthermore, we provide a comparative analysis with existing methods to demonstrate the efficiency, and robustness of our approach.

% The computational results demonstrate that our \texttt{IRMGL+\(\Psi\)} method with a posteriori stopping is effective to reconstruct CT images from noisy sinograms.
\subsection{X-ray Computed Tomography (CT)}
It is a widely used medical imaging technique that plays a crucial role in diagnosing various conditions such as internal injuries, tumors, hemorrhages, and bone fractures. A typical CT system consists of an X-ray source that rotates around the subject, emitting beams from a fixed number of angles along a circular or arc-shaped trajectory. As these X-ray beams pass through the internal structures of the body, different tissues absorb varying amounts of radiation depending on their density. The attenuated rays are then captured by a detector. See \cite{natterer2001mathematics} for the nice details.

\noindent The set of all such measurements, acquired at multiple projection angles, is referred to as a \emph{sinogram}. In the discrete setting, this process can be modeled by a linear system
\[
A \in \mathbb{R}^{m \times n}, \quad u \in \mathcal{U} := \mathbb{R}^n, \quad v^\delta \in \mathcal{V} := \mathbb{R}^m,
\]
where \( A \) denotes the discretized Radon transform (or forward operator), \( u \) represents the unknown 2D image vectorized into \( n \) pixels (or voxels), and \( v^\delta \) is the vectorized sinogram obtained from noisy measurement data.

\subsubsection{Experimental setup}\label{experimental setup}
The vectorization of the 2D image is typically performed using a lexicographic (1D) ordering of the pixels \( a = (i,j) \), following either column-major or row-major convention. For an image of size \( E \times F \), the total number of pixels is \( n = E \cdot F \), and the image is reshaped into a vector in \( \mathbb{R}^n \).

\noindent In \cite{jonasadler20181442734}, the Operator Discretization Library (ODL), a Python-based framework, is introduced for modeling X-ray computed tomography (CT) measurements and reconstruction. In our experiments, we utilize the function \texttt{odl.uniform\_discr} to define the image domain as a uniformly discretized square grid of size \( E \times F \) over the region \([-128, 128]^2 \subset \mathbb{R}^2\), represented with single-precision floating point values.

\noindent For the numerical simulation, we employ the Shepp–Logan phantom image provided by \texttt{skimage.data}. The acquisition setup is based on a parallel-beam geometry with \( m_\theta = 60 \) uniformly distributed projection angles over the interval \( [0, 2\pi) \), constructed using the \texttt{odl.tomo.parallel\_beam\_geometry} routine. The forward operator \( A \in \mathbb{R}^{m \times n} \), which approximates the discrete Radon transform, is implemented via \texttt{odl.tomo.RayTransform}. Here, \( m = m_\theta \cdot d \), where \( d \) denotes the number of detector elements, which is automatically determined by ODL to ensure full coverage of the image domain. Specifically, for \( E = F = 128 \), we have \( d = \lceil \sqrt{2} \cdot 128 \rceil = 363 \), and hence \( m = 60 \cdot 363 = 21780 \), while the number of image pixels is \( n = 128 \cdot 128 = 16384 \) leading to an ill-conditioned linear system. For the parameter selection in the edge-weight function~\eqref{eqn: edge weight fun}, we set \(R = 5\) and \(\sigma = 0.01\) based on empirical considerations.

\noindent In order to replicate real-world circumstances, we introduce Gaussian noise $\xi$ into the sinogram at an intensity level of $\delta$. In particular, we compute $v^\delta$ as
\[v^\delta = v +\delta_{rel} \| v \| \frac{\xi}{\| \xi\|},\]
where $\delta_{rel} = \|v - v^\delta\| / \|v\|$ is the relative noise level and $\delta = \delta_{rel}\|v\|$ is the noise level.

\subsubsection{Reconstruction results}\label{subsec: reconstrution}
The primary objective of this subsection is to evaluate the reconstruction accuracy under varying noise levels using the discrepancy principle~\eqref{eqn: discrepancy} as the stopping criterion. Similar to the investigation in \cite{bianchi2025data} on various reconstruction operators $\Psi$ for variational regularization, our iterative method also leverages a selection of initializers (excluding the NETT approach \cite{evangelista2023rising, ronneberger2015u}). Additionally, we introduce $A^*$ (the adjoint operator) as an initializer. This choice is particularly relevant as $A^*$ inherently satisfies \Cref{hypothesis stability}, providing a fundamental, yet non-regularizing, starting point for the reconstruction.
