\left| \mathbf{E} \left[{W}_n^{\mathbf{B}_{1}, \mathbf{B}_{2} , \mathbf{A}_{1}, \mathbf{A}_{2}}(t, u) \right] \right| = \notag \\
&\hspace{-3.7cm}
\frac{D}{\pi} \times
\sqrt{\frac{1}{\left| b_1 b_2 \left( \zeta_{\mathbf{B}_{1},\mathbf{B}_{2}} - 2 \right) + \mu_{\mathbf{A}_{1},\mathbf{A}_{2}} \left( \overline{a}_1 \overline{b}_2 - \overline{a}_2 \overline{b}_1 \right) \right|}}
