\title{Automatic Rank Determination for Low-Rank Adaptation via Submodular Function Maximization
}

\author{Yihang Gao\thanks{Department of Mathematics, National University of Singapore. Email: gaoyh@nus.edu.sg}\and Vincent Y. F.  Tan\thanks{Department of Mathematics and Department of Electrical and Computer Engineering, National University of Singapore. Email: vtan@nus.edu.sg}}

