\section{Analysis of the Plancherel weight}
Let $G$ be a locally compact group. In this section, we denote $\lambda=\lambda_\ell^G$ and $\rho=\lambda_r^G$ when there is no risk of confusion. Moreover, given $G$ and a closed subgroup $H$, we consider arbitrarily fixed left Haar measures $\mu_G$ on $G$ and $\mu_H$ on $H$, and denote $L^2(G)=L^2(G,\mu_G),L^2(H)=L^2(H,\mu_H)$. First, we recall the following classical result due to \cite{TakesakiTatsuuma1971} (see the proof of \cite[Theorem 6]{TakesakiTatsuuma1971}). Since we need the explicit form of the $*$-isomorphism $\Phi\colon L(H)\to \lambda_\ell^G(H)''\subseteq L(G)$, we provide an outline of the proof. We also refer to \cite[Proposition 3.4.4]{KaniuthLaubookMR3821506} for details.

\begin{proposition} \label{subisom}
    For a locally compact group $G$ and the closed subgroup $H$ of $G$, we have 
    $$L(H) \cong \{\lambda_\ell^G(h) : h \in H\}'' \subseteq \B (L^2 (G, \mu_G)).$$
\end{proposition}
\begin{proof}
    Let $\tilde{\rho}_h \,\,(h\in H)$ be the right regular representation of $H$. Denote $\mathcal{F}(G,\tilde{\rho})$ as the set of all continuous mappings $\xi\colon G\to L^2(H)$ with the following properties; 
    \begin{itemize}
        \item $\xi$ has a compact support modulo $H$.
        \item $\xi(xy)=\Delta_G(y)^{-1/2}\Delta_H(x)^{1/2}\tilde{\rho}_{y^{-1}}\xi(x)$ for all $x \in G, y \in H$.
    \end{itemize}
    Note that $\mathcal{F}(G,\tilde{\rho})$ is dense in $\mathcal{H}(\text{Ind}_H^G\tilde{\rho})$. Define an intertwiner operator $U\colon L^2(G)\to \mathcal{H}(\text{Ind}_H^G\tilde{\rho})$ by $$(Uf)(x)(h)=\Delta_G(x)^{-1/2}f(hx^{-1})\,\, (f\in C_c(G)).$$ In this case, we obtain $U^*\colon \mathcal{H}(\text{Ind}_H^G\tilde{\rho})\to L^2(G)$ by
    $$(U^*\xi)(x)=\Delta_G(x)^{-1/2}\xi(x^{-1})(e) \,\, (\xi\in \mathcal{F}(G,\tilde{\rho})).$$
    In addition, define $\widehat{\cdot}\colon \B(L^2(H))\to \B(\mathcal{H}(\text{Ind}_H^G\tilde{\rho}))$ by $$(\widehat{T}\xi)(x)=T\xi(x) \,\, (\xi\in \mathcal{H}(\text{Ind}_H^G\tilde{\rho}), x\in G).$$ It can be shown that $\Phi\colon L(H) \to \B(L^2(G));T \mapsto U^*\widehat{T}U$ gives a desired $*$-isomorphism can be shown using \cite{Blattner1962}. Moreover, $\Phi(\lambda_\ell^H(h))=\lambda_\ell^G(h)\,\,(h\in H)$ holds.
\end{proof}

We give the definition of the canonical weight of $L(G)$.

\begin{definition}
    For $\xi \in \B(L^2(G))$, we say that $\xi$ is left bounded if there is a bounded operator $\pi_{l}(\xi) \in\B(L^2(G))$ such that $\pi_{l}(\xi)f=\xi * f$ for all $f \in C_c(G)$. Similarly, $\xi$ is right bounded if there is a bounded operator $\pi_{r}(\xi) \in\B(L^2(G))$ such that $\pi_{r}(\xi)f=f*\xi$ for all $f \in C_c(G)$.
\end{definition}

\begin{definition}\label{defofplweight}
    For a locally compact group $G$, define the weight $\varphi_{G}$ on $L(G)_+$ as \begin{equation*}
        \varphi_{G}(x)=
        \begin{cases}
            \|\xi\|_2^2 & x=\pi_{l}(\xi)^*\pi_{l}(\xi) \,\,\text{for some left bounded}\,\, \xi \in L^2(G) \\
            \infty & \text{otherwise}.
        \end{cases}
    \end{equation*}
    It is known to be a normal faithful semifinite weight. We call it the Plancherel weight of $L(G)$. Note that $\varphi_G$ depends on the left Haar measure $\mu_G$ on $G$ up to a constant.
\end{definition}

It is also known that $G$ is unimodular if and only if its Plancherel weight is tracial. The following lemmas are well known. We include the proof for completeness.  

\begin{lemma}
    Any $f\in C_c(G)$ is both left and right bounded.
\end{lemma}
\begin{proof}
    The left boundness follows from the inequality $$\|f*\xi\|_2 \le \|f\|_1\|\xi\|_2\,\, \text{for all} \,\, \xi \in L^2(G).$$
    Thus, we have $\pi_{l}(f)\xi=f*\xi$ for all $\xi \in L^2(G)$. For the right boundness, fix $\xi \in L^2(G)$. Then, $$\xi*f(x)=\int\xi(y)f(y^{-1}x)\,dy = \int\xi(xy)f(y^{-1})\,dy = \int\Delta_G(y)^{-1/2}\rho_y\xi(x)f(y^{-1})\,dy.$$
    Hence, $$\xi*f=\int\Delta_G(y)^{-1/2}f(y^{-1})\rho_y\xi(\cdot)\,dy.$$
    By Minkowski’s inequality for integrals, we obtain 
    \begin{align*}
        \|\xi*f\|_2 \le \int\|\Delta_G(y)^{-1/2}f(y^{-1})\rho_y\xi\|_2\,dy & =  \int |\Delta_G(y)^{-1/2}f(y^{-1})|\|\rho_y\xi\|_2\,dy \\ & = \|\xi\|_2\int |\Delta_G(y)^{-1/2}f(y^{-1})|\,dy \le C\|\xi\|_2
    \end{align*}
    for some $C > 0$. This shows that $f$ is right bounded and $\pi_r(f)\xi=\xi*f$ for all $\xi \in L^2(G)$.
\end{proof}

Now, we introduce some notation. For any complex function $f$ on $G$, we put  $$f^{\#}(x)= \Delta_G(x)^{-1}\overline{f}(x^{-1}),\,\,\, f^*(x)= \Delta_G(x)^{-1/2}\overline{f}(x^{-1}), \,\,\, f^{\flat}(x)=\overline{f}(x^{-1}).$$ 
$\#$, * and $\flat$ are involutions of the convolution algebra $C_c(G)$. Moreover, * is 
an isometry on $L^2(G)$. $\#$ makes $C_c(G)$ into the left Hilbert algebra and $\flat$ makes $C_c(G)$ into the right Hilbert algebra with $L^2$ inner product. 

\begin{lemma}\label{sumprodadj}
    For $f,g \in C_c(G)$, $$\pi_l(f+g)=\pi_l(f)+\pi_l(g),\,\,\, \pi_l(f^{\#}*g)=\pi_l(f)^*\pi_l(g),\,\,\, \pi_l(f^{\#})=\pi_l(f)^*.$$
\end{lemma}
\begin{proof}
    Fix $f,g \in C_c(G)$. It is obvious that $f+g, f^{\#},f^{\#}*g\in C_c(G)$. Then, for each $\xi.\eta \in C_c(G)$, $$(\pi_l(f)+\pi_l(g))\xi=\pi_l(f)\xi+\pi_l(g)\xi=f*\xi+g*\xi=(f+g)*\xi,$$
    $$\nai{\pi_l(f)^*\pi_l(g)\xi}{\eta}_2=\nai{\pi_l(g)\xi}{\pi_l(f)\eta}_2=\nai{g*\xi}{f*\xi}_2=\nai{f^{\#}*g*\xi}{\eta}_2
    =\nai{(f^{\#}*g)*\xi}{\eta}_2,$$ $$\nai{\pi_l(f)^*\xi}{\eta}_2=\nai{\xi}{\pi_l(f)\eta}_2=\nai{\xi}{f*\eta}_2=\nai{f^{\#}*\xi}{\eta}_2.$$ These calculations implies desired formulas.
\end{proof}

\begin{lemma}\label{rbddimp*lbdd}
    If $g \in L^2(G)$ is right bounded, then $g^*$ is left bounded.
\end{lemma}
\begin{proof}
    For $f \in C_c(G)$, 
    $$\|g^**f\|_2= \|(g^**f)^*\|_2 = \|f^**g\|_2 \le \|f^*\|_2\|\pi_r(g)\|= \|f\|\|\pi_r(g)\|.$$
    Hence, there is a bounded operator $\pi_l(g^*) \in \B(L^2(G))$ such that $\pi_l(g^*)f= g^**f$ for all $f \in C_c(G)$. This shows that $g^*$ is left bounded.
\end{proof}

In fact, the formula $\pi_l(f^{\#}*g)=\pi_l(f)^*\pi_l(g)$ holds for left bounded $L^2$ functions $f,g$ (c.f. \cite[Lemma 2.8]{Haagerupdualweight}).
In addition, we define $$ P (G) =\text{the set of all continuous functions of positive type on G.}$$
Following \cite[P 126]{Haagerupdualweight}, we write $\varphi\ll K\cdot \delta$ for $\varphi\in P(G)$ and $K>0$, if there exists a $K>0$ such that $\int\varphi(x)(f^{\#}*f)(x)\, dx \le K(f^{\#}*f)(e)$ for all $f \in C_c(G)$.

\begin{lemma}\label{rbddlesskdelta}
    For any right bounded $f\in L^2(G) \cap P(G)$,  $f \ll K \cdot \delta$ holds, where $K=\|\pi_r(f)\|$.
\end{lemma}
\begin{proof}
    Fix $\xi \in C_c(G)$, then
    \begin{align*}
       0\le \int f(x)(\xi^{\#}*\xi)(x)\, dx &= \nai{f}{\overline{\xi^{\#}*\xi}}_2 =\nai{f}{\overline{\xi}^{\#}*\overline{\xi}}_2 = \nai{f}{\pi_l(\overline{\xi})^*\overline{\xi}}_2 = \nai{\pi_l(\overline{\xi})f}{\overline{\xi}}_2 = \nai{\overline{\xi}*f}{\overline{\xi}}_2 \\ &= \nai{\pi_r(f)\overline{\xi}}{\overline{\xi}}_2 \le \|\pi_r(f)\|\|\overline{\xi}\|_2^2 = \|\pi_r(f)\|\|\xi\|_2^2 = \|\pi_r(f)\|(\xi^{\#}*\xi)(e).
    \end{align*}
    We use the equation $\pi_l(\xi^{\#})=\pi_l(\xi)^*$ for $\xi \in C_c(G)$. 
\end{proof}

\begin{lemma}\label{convresol}
    Suppose $\varphi \in P(G)$ and $\varphi \ll K \cdot \delta$ for some $K>0$. Then, there exists a right bounded $g \in L^2(G)$ such that $\varphi=g*g^{\flat}$.
\end{lemma}
\begin{proof}
    We apply the proof of \cite[Proposition 2.9]{Haagerupdualweight}.
    Let $(\pi_{\varphi}, \mathcal{H}_{\varphi}, \xi_{\varphi})$ be the cyclic representation induced by $\varphi$. For $f \in C_c(G)$, 
    \begin{align*}
        \|\pi_{\varphi}(f)\xi_{\varphi}\|^2 = \nai{\pi_{\varphi}(f^{\#}*f)\xi_{\varphi}}{\xi_{\varphi}} &= \int (f^{\#}*f)(x)\nai{\pi_{\varphi}(x)\xi_{\varphi}}{\xi_{\varphi}}\, dx \\ &=\int (f^{\#}*f)(x) \varphi(x)\, dx \le K(f^{\#}*f)(e) = K\|f\|_2^2 .\end{align*}
    Hence, there exists a bounded operator $T\colon L^2(G) \to \mathcal{H}_{\varphi}$ such that $Tf=\pi_{\varphi}(f)\xi_{\varphi}$ for all $f \in C_c(G)$. A simple calculation shows that $T\lambda(f)=\pi_{\varphi}(f)T \,\, ( f \in C_c(G))$. Indeed, since $\lambda(f)=\pi_l(f)$ for all $f \in C_c(G)$, for $g \in C_c(G)$, 
    $$T\lambda(f)g=T(f*g)=\pi_{\varphi}(f*g)\xi_{\varphi} = \pi_{\varphi}(f)\pi_{\varphi}(g)\xi_{\varphi} = \pi_{\varphi}(f)Tg.$$
    Let $T=U|T|$ be the polar decomposition. It follows that $U\lambda(f)=\pi_{\varphi}(f)U$ and $UU^*=P_{\overline{\text{ran}}(T)}=P_{\mathcal{}{H}_{\varphi}}=1$ since $\xi_{\varphi}$ is cyclic. In particular, $U\lambda_x=\pi_{\varphi}(x)U \,\,( x \in G)$. Put $\xi=U^*\xi_{\varphi} \in L^2(G)$ and $g=\overline{\xi}$. For $x \in G$, 
    \begin{align*}
        \varphi(x) & = \nai{\pi_{\varphi}(x)\xi_{\varphi}}{\xi_{\varphi}} = \nai{\pi_{\varphi}(x)UU^*\xi_{\varphi}}{\xi_{\varphi}} =\nai{U\lambda_xU^*\xi_{\varphi}}{\xi_{\varphi}} = \nai{\lambda_x\xi}{\xi}_2 \\ &= \int \xi(x^{-1}y)\overline{\xi}(y)\, dy = \int \overline{\xi}^{\flat}(y^{-1}x) \overline{\xi}(y) \, dy = (g*g^{\flat})(x). 
    \end{align*}
    It remains to show that $g$ is right bounded. It suffices to show the right boundness of $\xi$. For $f \in C_c(G)$, 
    \begin{align*}
        \|f*\xi\|_2^2=\nai{f*\xi}{f*\xi}_2
        & =\nai{f^{\#}*f*\xi}{\xi}_2 = \nai{\lambda(f^{\#}*f)\xi}{\xi}_2 \\ & = \int (f^{\#}*f)(x)\nai{\lambda_x\xi}{\xi}_2\, dx = \int (f^{\#}*f)(x)\varphi(x) \, dx \le K\|f\|_2^2
    \end{align*}
    Hence, there exists $\pi_r(\xi)\in \B(L^2(G))$ such that $\pi_r(\xi)f = f* \xi $ for all $f \in C_c(G)$.
\end{proof}

Now, we shall show that $\varphi_G|L(H)=C\cdot\varphi_H$ for some constant $C >0$ if and only if $H$ is open. 
Before we prove the theorem, we give a necessary and sufficient condition for the semifiniteness of the restriction of the Plancherel weight. 
\par
We recall a strongly quasi-invariant Radon measure on $G/H$ and a rho-function for the pair $(G,H)$. We refer to \cite[Section 2.6]{Folland} for the details. Let $G$ be a locally compact group and $H$ be a closed subgroup of $G$. Then, there exists a continuous function $\rho\colon G \to (0,\infty)$ such that 
$$\rho(xh)=\frac{\Delta_H(h)}{\Delta_G(h)}\rho(x)\,\,(g\in G, h\in H).$$ This function is called a rho-function. Moreover, suppose $\mu$ is a Radon measure on $G/H$. For $x \in G$, we define the translate $\mu_x$ of $\mu$ by $\mu_x(E)=\mu(xE)$, where $E$ is a Borel subset of $G/H$. $\mu$ is said to be strongly quasi-invariant if there is a continuous function $\lambda\colon G \times G/H \to(0,\infty)$ such that $d\mu_x(p)=\lambda(x,p)d\mu(p)$ for all $x\in G, p\in G/H$. A rho-function $\rho$ produces a strongly quasi-invariant measure $\mu$ on $G/H$ which satisfies 
$$\int_Gf(x)\rho(x)\,d\mu_G(x)=\int_{G/H}\int_H f(xh)\,d\mu_H(h)d\mu(xH)\,\,(f\in C_c(G)).$$ 
\par
Now we give a characterization of openness of $H$. This is likely to be known, but we include the proof for completeness.

\begin{proposition}\label{openiffmuposi}
    For a locally compact group $G$, a closed subgroup $H$ of $G$ and $\mu$ is a strongly quasi-invariant Radon measure on $G/H$ obtained by a rho-function $\rho$, the following conditions are equivalent.
    \begin{enumerate}
        \item[(i)] $H$ is open.
        \item[(ii)] $\mu(\{H\}) >0$.
    \end{enumerate}
\end{proposition}
\begin{proof}
