\end{proof}

\begin{lemma}\label{openimpmodcondi}
    For a locally compact group $G$ and an open subgroup $H$, $\Delta_G|H=\Delta_H$ holds.
\end{lemma}
\begin{proof}
    Take an arbitrary rho-function $\rho$. There is a strongly quasi-invariant measure $\mu$ obtained by $\rho$. By Proposition \ref{openiffmuposi}, $\mu(\{H\})>0$ holds. Moreover, by the proof of $\text{(ii)}\implies \text{(i)}$, it follows that $\rho$ is constant on each coset $xH\,\,(x\in G)$. Thus, for $x\in G, h\in H$, we have $\rho(x)=\rho(xh)=\frac{\Delta_H(h)}{\Delta_G(h)}\rho(x)$. Since $0 < \rho$, we conclude that $\Delta_H(h)=\Delta_G(h)$ for all $h \in H$.
\end{proof}

We provide a sufficient condition for the semifiniteness of the restriction of the Plancherel weight. Note that under the assumption $\Delta_G|H=\Delta_H$, the rho-function $\rho$ can be taken as $\rho \equiv 1$. In this case, the strongly quasi-invariant Radon measure $\mu$ is actually the $G$-invariant Radon measure. 

\begin{proposition}\label{sfofrest}
    Let $G$ be a locally compact group and $H$ be an open subgroup of $G$. Then $\varphi_G|L(H)$ is semifinite.
\end{proposition}
\begin{proof}
     Note that $C_c(G)_H=\{f\in C_c(G) : {\rm supp}\,f \subseteq H\} \ne \{0\}$ since $H$ is open. Let $\mu$ be the $G$-invariant Radon measure on $G/H$ obtained by the rho-function $\rho \equiv 1$. Also, we set $C=\mu(\{H\})$ and $\mathcal{N}_H=\{\lambda_h:h\in H\}$. It follows that $C>0$ by Proposition \ref{openiffmuposi}. Since $L(H) \cong \mathcal{N}_H''$, we shall show that $\varphi_G|\mathcal{N}_H''$ is semifinite. We now prove $\Phi(\pi_l(C_c(H)))=\pi_l(C_c(G)_H)$ where $\Phi$ is the isomorphism as in Proposition \ref{subisom}. Note that $\int_G f(x)\, d\mu_G(x) = \mu(\{H\})\int_H f(x)\, d\mu_H(x)$ for all $f\in C_c(G)_H$. Take $f \in C_c(H)$. Fix $\xi \in C_c(G), x\in G$, then
    \begin{align*}
        \Phi(\pi_l(f))(\xi)(x) &= (U^*\widehat{\pi_l(f)}U\xi)(x) \\ &= \Delta_G(x)^{-1/2}(\widehat{\pi_l(f)}U\xi)(x^{-1})(e) \\ &= \Delta_G(x)^{-1/2}(\pi_l(f)(U\xi)(x^{-1}))(e) \\ &= \Delta_G(x)^{-1/2}(f*(U\xi)(x^{-1}))(e) \\ &= \Delta_G(x)^{-1/2}\int_H f(y)(U\xi)(x^{-1})(y^{-1})\, d\mu_H(y) \\ &=\Delta_G(x)^{-1/2} \int_H f(y)\Delta_G(x)^{1/2} \xi(y^{-1}x) \, d\mu_H(y) \\ &= \int_H f(y) \xi(y^{-1}x) \, d\mu_H(y).
    \end{align*}
    If we denote $\tilde{f} \in C_c(G)_H$ for the zero extension of $f$, then we obtain
    \begin{align*}
        \Phi(\pi_l(f))(\xi)(x)=\int_H f(y) \xi(y^{-1}x) \, d\mu_H(y) &= \int_H\tilde{f}(y)  \xi(y^{-1}x) \, d\mu_H(y) \\ &= C^{-1}\int_G \tilde{f}(y)\xi(y^{-1}x) \, d\mu_G(y) \\&=(\pi_l(C^{-1}\tilde{f})\xi)(x).
    \end{align*}
    This shows that $\Phi(\pi_l(f))=\pi_l(C^{-1}\tilde{f})$. It is clear that $C_c(H)\ni f \mapsto C^{-1}\tilde{f}\in C_c(G)_H$ is bijective. Therefore, we conclude that $\Phi(\pi_l(C_c(H)))=\pi_l(C_c(G)_H)$. Next, we show $\pi_l(C_c(G)_H) \subseteq \mathfrak{n}_{\varphi_G|\mathcal{N}_H''}=\mathfrak{n}_{\varphi_G}\cap \mathcal{N}_H''$. It is clear that $\pi_l(C_c(G)_H) \subseteq \mathfrak{n}_{\varphi_G}$. Take $f\in C_c(G)_H$. For each $T\in \mathcal{N}_H'$, we have 
    \begin{align*}
        T\pi_l(f) &= T\int_G f(x)\lambda_x\, d\mu_G(x) = T\int_H f(x)\lambda_x\, d\mu_G(x) \\ &= \int_H f(x)T\lambda_x\, d\mu_G(x) = \int_H f(x)\lambda_xT\, d\mu_G(x) = \pi_l(f)T.
    \end{align*}
    Thus, $\pi_l(f)\in \mathcal{N}_H''$. To show the semifiniteness of $\varphi_G|\mathcal{N}_H''$, it suffices to show that $\pi_l(C_c(G)_H)''=\mathcal{N}_H''$. Since $\Phi$ is an isomorphism between von Neumann algebras $L(H)$ and $\mathcal{N}_H''$, and hence is normal, we have  
    \begin{align*}
        \pi_l(C_c(G)_H)''&= \Phi(\pi_l(C_c(H)))''=\Phi(\pi_l(C_c(H))'')=\Phi(L(H))\\&=\Phi(\{\lambda_\ell^H(h):h\in H\}'')=\Phi(\{\lambda_\ell^H(h):h\in H\})''=\mathcal{N}_H''.
    \end{align*}
\end{proof}


