Now, we provide a necessary condition for the semifiniteness of the restriction of the Plancherel weight. We recall the support of an element of the group von Neumann algebra. We set $$A(G)=\{\xi*\eta^{\flat}:\xi,\eta\in L^2(G)\}.$$ 
$A(G)$ is called the Fourier algebra of $G$. It is well known that $A(G)$ is a dense $*$-subalgebra of the abelian $C^*$-algebra $C_0(G)$ of all continuous functions on $G$ vanishing at infinity, with $\|\cdot\|_\infty$-norm (see, e.g. \cite[Chapter VII, Lemma 3.7]{TakesakiOA2}). As a Banach space, $A(G)$ is isomorphic to the predual $L(G)_*$ of $L(G)$. The duality paring is given by $\nai{x}{\phi}=\nai{x\xi}{\eta}_2$ for all $x\in L(G),\phi=\xi*\eta^{\flat} \in A(G)$. We see that $\nai{\lambda_x}{\phi}=\phi(x)\,\, (x\in G)$. Now, we define the multipliers on $L(G)$. For $\phi \in A(G)$, a normal completely bounded map $m_\phi\colon  L(G) \to L(G)$ is defined by the formula $$\nai{m_\phi(x)}{\psi}=\nai{x}{\psi\phi}\,\,(x\in L(G),\psi \in A(G)).$$ In this setting, $m_\phi(\lambda_x)=\phi(x)\lambda_x\,\,(x\in G)$ holds. 
% Additionally, using the form $\pi_l(f)=\int_G f(x)\lambda_x\,d\mu_G(x)$ for $f\in C_c(G)$, it follows that
% \begin{align*}
% m_\phi(\pi_l(f))=m_\phi(\int_G f(x)\lambda_x\,d\mu_G(x))&=\int_G f(x)m_\phi(\lambda_x)\,d\mu_G(x)\\&=\int_Gf(x)\phi(x)\lambda_xd\mu_G(x)=\pi_l(\phi f).
% \end{align*}
% Thus, we obtain $m_\phi(\pi_l(f))=\pi_l(\phi f)$ for all left bounded $f \in L^2(G)$.
We define the support of $x\in L(G)$. For $x\in L(G)$, set
$${\rm supp}(x)=\{g\in G: m_\phi(x)\ne0\,\, \text{for all}\,\,\phi\in A(G)\,\, \text{such that}\,\, \phi(g) \ne 0 \}.$$ It is known that the support is closed in $G$. We refer to \cite[Chapter 4]{Eymard1964}, \cite{TakesakiTatsuuma1972} and \cite[Section 2.6, Section 3.1]{BoutonnetBrothier2016} for details.
We provide the following lemmas. In fact, they were shown in \cite[Proposition 3.2, Theorem 5.2]{BoutonnetBrothier2016}. But, we give an outline of the proof in the simple case for completeness.

\begin{lemma}[{\cite[Proposition 3.2]{BoutonnetBrothier2016}}]\label{suppinc1}
    Let $G$ be a locally compact group, $x\in L(G)$ and $g \in G$. If  $1_{gU}x1_U \ne 0$ for any open neighborhood $U$ of $e$, then $g \in {\rm supp}(x)$ holds.
\end{lemma}
\begin{proof}
    Let $\phi \in A(G)$ such that $\phi(g) \ne 0$. We shall show that $m_\phi(x) \ne 0$. Let $\mathcal{I}(\phi)$ be the closed ideal generated by $\phi$. Since $\psi_\lambda \to \psi$ in $A(G)$ implies $\nai{y}{\psi_\lambda-\psi} \to 0\,\,(y\in L(G))$, if $\psi_\lambda \to \psi$ in $A(G)$, then $m_{\psi_\lambda}(y) \to m_\psi(y)$ $\sigma$-weakly for all $y\in L(G)$ holds. Note that $\mathcal{I}(\phi)$ is the closure of the set ${\{\phi\psi:\psi\in A(G)\}}$ and $m_\phi(x)=0$ implies $m_{\phi\psi}(x)=0$ for all $\psi \in A(G)$. We conclude that if $m_\phi(x)=0$, then we have $m_\psi(x)=0$ for all $\psi \in \mathcal{I}(\phi)$. Therefore, to show $m_\phi(x) \ne 0$, it suffices to find $\psi \in \mathcal{I}(\phi)$ such that $m_\psi(x) \ne 0$. Set $$F=\{g\in G: \phi(g) =0\},\,\,h(\mathcal{I}(\phi))=\{g\in G: \psi(g)=0\,\,\text{for all}\,\,\psi \in \mathcal{I}(\phi)\}.$$ In fact, since the spectrum of the commutative Banach algebra $A(G)$ is known to be $G$, $h(\mathcal{I}(\phi))$ is the hull of $\mathcal{I}(\phi)$ in the sense of \cite[Definition 4.1.1]{Kaniuth2009}. Moreover, it can be shown that $F= h(\mathcal{I}(\phi))$. Take some compact neighborhood $V$ of $g$ such that $\phi \ne 0$ on $V$. Noting that the identification map between the spectrum of $A(G)$ and $G$ is the identity map (see \cite[Theorem 2.9.4]{Kaniuth2009}), by \cite[Theorem 4.2.8]{Kaniuth2009} (or \cite[Lemma 25C]{Loomis1953}), there exists $\psi \in \mathcal{I}(\phi)$ which satisfies $\psi =1$ on $V$. Take an open neighborhood $U$ of $e$ such that $gU\cdot U^{-1} \subseteq V$. We shall show that $$1_{gU}m_\psi(y)1_U=1_{gU}y 1_U\,\,(y\in L(G)).$$ If $h\in V$, then since $m_\psi(\lambda_h)=\psi(h)\lambda_h=\lambda_h$, the equation is obvious. Let $h \notin V$. For $\xi \in C_c(G)$ and $s\in G$, we have $$(1_{gU}m_\psi(\lambda_h)1_U\xi)(s)=\psi(h)1_{gU}(s)1_U(h^{-1}s)\xi(h^{-1}s)=\psi(h)(1_{gU}\lambda_h1_U\xi)(s).$$ By construction, the value of the above equation is zero. Therefore, we see that $1_{gU}m_\psi(y)1_U=1_{gU}y 1_U$ for all $y\in L(G)$ since $\{\lambda_h:h\in G\}''=L(G)$. We conclude that $1_{gU}m_\psi(x)1_U=1_{gU}x 1_U\ne 0$ and hence $m_\psi(x)\ne 0$.
\end{proof} 

\begin{lemma}[{\cite[Theorem 5.2]{BoutonnetBrothier2016}}]\label{sptinc}
    Let $f$ be a continuous, left bounded function in $L^2(G)$. Then the inclusion ${\rm supp}(f)\subseteq {\rm supp}(\pi_l(f))$ holds.
\end{lemma}
\begin{proof}
    Let $g\in {\rm supp}(f)$. By Lemma \ref{suppinc1}, we shall show that $1_{gU}\pi_l(f)1_U \ne 0$ for any open neighborhood $U$ of $e$. Fix an open neighborhood $U$ of $e$. For $\xi \in C_c(G)_U=\{f\in C_c(G) : {\rm supp}\,f \subseteq U\}$, it follows that $1_{gU}\pi_l(f)1_U \xi=1_{gU}\pi_l(f)\xi=1_{gU}\pi_r(\xi)f$. Since $f$ is continuous, $gU \cap \{h\in G: f(h)\ne 0\}$ is a non-empty open set. Thus, $1_{gU}f\ne0$ holds. Put $C=\|1_{gU}f\|_2>0$. For $\xi \in C_c(G)$, we denote $\check{\xi}$ for the function $h\mapsto \xi(h^{-1})$. Let $\xi \in C_c(G)_+$ such that $\int_G \xi \,d\mu_G =1$. We calculate
    \begin{align*}
        \|\pi_r(\check{\xi})f-f\|_2^2&=\int_G|\pi_r(\check{\xi})f(h)-f(h)|^2\,dh
        \\&= \int_G|\int_G\xi(s)(f(hs)-f(h))\,ds|^2dh
        \\&\le \int_G(\int_G\xi(s)|f(hs)-f(h)|\,ds)^2dh
        \\&= \int_{G \times G \times G}\xi(s)\xi(t)|f(hs)-f(h)||f(ht)-f(h)|\,ds\,dt\,dh
        \\&= \int_{G \times G \times G}\xi(s)\xi(t)|\Delta_G(s)^{-1/2}\rho_sf(h)-f(h)||\Delta_G(t)^{-1/2}\rho_tf(h)-f(h)|\,ds\,dt\,dh
        \\&\le \int_{G\times G} \xi(s)\xi(t)\|\Delta_G(s)^{-1/2}\rho_sf-f\|_2\|\Delta_G(t)^{-1/2}\rho_tf-f\|_2\,ds\,dt 
        \\&= (\int_G \xi(s)\|\Delta_G(s)^{-1/2}\rho_sf-f\|_2\,ds)^2.
    \end{align*}
    Since the map $s \mapsto \|\Delta_G(s)^{-1/2}\rho_sf-f\|_2$ is continuous and the value at $e$ is zero, if we take the support of $\xi$ sufficiently small, then $\|\pi_r(\check{\xi})f-f\|_2 \le \int_G \xi(s)\|\Delta_G(s)^{-1/2}\rho_sf-f\|_2\,ds < \frac{C}{2}$ holds. Noting that $$\|1_{gU}f\|_2-\|1_{gU}\pi_r(\check{\xi})f\|_2 \le\|1_{gU}f-1_{gU}\pi_r(\check{\xi})f\|_2 \le \|f-\pi_r(\check{\xi})f\|_2,$$ we conclude that $$\|1_{gU}\pi_r(\check{\xi})f\|_2\ge \|1_{gU}f\|_2- \|f-\pi_r(\check{\xi})f\|_2 >\frac{C}{2}>0$$ for some $\xi \in C_c(G)_U$.
    That is, $1_{gU}\pi_l(f)1_U \check{\xi}=1_{gU}\pi_r(\check{\xi})f\ne0$ and hence $1_{gU}\pi_l(f)1_U \ne0$ holds.
\end{proof}

\begin{proposition}\label{sfimpopen}
    For a locally compact group $G$ and a closed subgroup $H$ of $G$, if $\varphi_G|L(H)$ is semifinite, then $H$ is open.
\end{proposition}
\begin{proof}
    We identify $L(H)$ with $\mathcal{N}_H''$. Since $\varphi_G|\mathcal{N}_H''$ is semifinite, there is a non-zero $x\in \mathfrak{m}_{\varphi_G}^+ \cap \mathcal{N}_H''$. Then, by \cite[Proposition 2.9 (2)]{Haagerupdualweight}, $x=\pi_l(f)$ for some continuous left bounded $f\in L^2(G)$. Lemma \ref{sptinc} implies that ${\rm supp}(f) \subseteq {\rm supp}(\pi_l(f))$. Moreover, by \cite[Theorem 3]{TakesakiTatsuuma1972}, ${\rm supp}(\pi_l(f)) = {\rm supp}(x)\subseteq H$ holds. Since $f$ is continuous, non-zero and ${\rm supp}(f) \subseteq H$, it follows that $H$ is open. 
\end{proof}

