Now, we obtain the following theorem.
\begin{theorem}\label{openiffsf}
    For a locally compact group $G$ and a closed subgroup $H$, the following conditions are equivalent.
    \begin{enumerate}
        \item[(i)] $H$ is open.
        \item[(ii)] $\varphi_G|L(H)$ is semifinite.
     \end{enumerate}
\end{theorem}
\begin{proof}
    Proposition \ref{sfofrest} and Proposition \ref{sfimpopen} imply the desired equivalence.
\end{proof}

\begin{corollary}
    For a locally compact group $G$ and a closed subgroup $H$, there exists a $\varphi_G$-preserving conditional expectation from $L(G)$ onto $L(H)$ if and only if $H$ is open.
\end{corollary}
\begin{proof}
    Since $L(H)$ is globally $\sigma^{\varphi_G}$-invariant, the theorem follows from \cite{Takesaki72MR303307} and Theorem \ref{openiffsf}.
\end{proof}

As another corollary, we also recover a part of Guinto--Nelson's theorem.
\begin{corollary}[{\cite[Theorem 2.1]{guinto2025unimodulargroups}}]
    For a locally compact group $G$, the Plancherel weight of $G$ is strictly-semifinite if and only if $G_1$ is open in $G$, where $G_1$ is the kernel of $\Delta_G$.
\end{corollary}
\begin{proof}
    Note that $\varphi_G$ is strictly-semifinite if and only if $\varphi_G|L(G)^{\varphi_G}$ is semifinite. It is known that $L(G)^{\varphi_G} \cong L(G_1)$ (see \cite[Theorem 6.1]{Sutherland1973}). Thus, Theorem \ref{openiffsf} implies the desired equivalence.
\end{proof}
We remark that in \cite[Theorem 2.1]{guinto2025unimodulargroups}, the strict semifiniteness of $\varphi_G$ is also shown to be equivalent to its almost periodicity. In $\S 4$, We will use the almost periodicity of $\varphi_G$ to characterize the factoriality of $L(G)$ for almost unimodular groups. We also remark that any totally disconnected locally compact group, we abbreviate it tdlc group, is almost unimodular \cite[Example 2.4(4)]{guinto2025unimodulargroups}.
% It had been shown that the strictly semifiniteness of the Plancherel weight is equivalent to the almost periodicity of it in \cite[Theorem 2.1]{guinto2025unimodulargroups}. We will use the almost periodicity in $\S4$. A tdlc group $G$ always admits strictly semifinite almost periodic Plancherel weight. The following lemma is well known (see, e.g. \cite[Example 2.4 (4)]{guinto2025unimodulargroups}). We provide the proof for completeness.

In the rest of this section, we show that $\varphi_G|L(H)=C\cdot\varphi_H$ for some constant $C >0$ if $\varphi_G|L(H)$ is semifinite. 
%First, we provide the if part. 
The proof is due to following Pedersen-Takesaki theorem (see also \cite[Chapter IIX, Theorem 3.15]{TakesakiOA2}). 

\begin{theorem}[{\cite[Proposition 5.9]{PedersenTakesaki1973}}]\label{TakTats}
    Let $M$ be a von Neumann algebra. Let $\varphi$ be a normal semifinite faithful weight on $M$. If $\psi$ is a normal semifinite weight on $M$ commuting with $\varphi$, that is, $\psi=\psi \circ \sigma_t^{\varphi} \,\, ( t \in \R)$, and if there exists a $\sigma$-weakly dense *-subalgebra $\mathfrak{m}_0$ of $\mathfrak{m}_{\varphi}$ such that $\sigma_t^{\varphi}(\mathfrak{m}_0)=\mathfrak{m}_0\,\, ( t \in \R)$ and $\varphi(x)= \psi(x)$ for every $x \in \mathfrak{m}_0$, then $\varphi=\psi$.
\end{theorem}

We provide the proof. Note that, when $H$ is an open subgroup of $G$, the pair $(G,H)$ admits the rho-function $\rho\equiv 1$ by Lemma \ref{openimpmodcondi}.

\begin{theorem}\label{restofplweight}
    Let $G$ be a locally compact group and $H$ be an open subgroup of $G$. Then $\varphi_G|L(H)=C^{-1}\cdot\varphi_H$. Here, $C=\mu(\{H\})$ where $\mu$ is the $G$-invariant Radon measure obtained by the rho-function $\rho \equiv 1$.
\end{theorem}
\begin{proof}
    Put $\psi = \varphi_G|L(H)$. By Proposition \ref{sfofrest}, $\psi$ is semifinite. Note that $\Delta_G|H=\Delta_H$ holds by Lemma \ref{openimpmodcondi}. Since $\sigma_t^{\varphi_G}(L(H))=L(H)$, we have $$\sigma_t^{\psi}(\lambda_h)=\sigma_t^{\varphi_G}(\lambda_h)=\Delta_G(h)^{it}\lambda_h=\Delta_H(h)^{it}\lambda_h=\sigma_t^{\varphi_H}(\lambda_h)=\sigma_t^{C^{-1}\cdot\varphi_H}(\lambda_h)$$
    for all $h \in H$. Thus, $\sigma_t^{\psi}(x)=\sigma_t^{C^{-1}\cdot\varphi_H}(x)$ for all $x \in L(H)$ and then $\psi \circ \sigma_t^{C^{-1}\cdot\varphi_H}=\psi\circ\sigma_t^{\psi} = \psi$. \par
    Now, put $A=\text{span}\{f*g\,|\,f,g\in C_c(H)\} \subseteq C_c(H)$ and we will show that $\pi_l(A)$ satisfies conditions of Theorem \ref{TakTats} for $\mathfrak{m}_0$.\par
    First, we show $\pi_l(A)$ is a $\sigma$-weakly dense *-subalgebra of $\mathfrak{m}_{\varphi_H}$ because $\mathfrak{m}_{\varphi_H}=\mathfrak{m}_{C^{-1}\cdot\varphi_H}$. Lemma \ref{sumprodadj} ensures that $\pi_l(A)$ is a *-subalgebra of $\B(L^2(H))$. Indeed, $\pi_l(f)\pi_l(g)=\pi_l(f^{\#})^*\pi_l(g)=\pi_l((f^{\#})^{\#}*g)=\pi_l(f*g)\in \pi_l(A) \,\,( f,g \in C_c(H))$.
    Moreover, for $a=\sum_{i=1}^{n}f_i*g_i \in A$, $$\pi_l(a)=\sum_{i=1}^{n}\pi_l(f_i*g_i)=\sum_{i=1}^{n}\pi_l(f_i^{\#})^*\pi_l(g_i)\in \mathfrak{n}_{\varphi_H}^*\mathfrak{n}_{\varphi_H}=\mathfrak{m}_{\varphi_H}$$ because $\pi_l(f) \in \mathfrak{n}_{\varphi_H}$ for all left bounded functions $f \in L^2(G)$. It follows that $\pi_l(A)$ is a *-subalgebra of $\mathfrak{m}_{\varphi_H}$. We show that for each $x \in \mathfrak{m}_{\varphi_H}$, there exists a net $(f_i)_{i\in I} \subseteq A$ such that $\pi_l(f_i) \to x$ strongly. Since $L(H)=\pi_l(C_c(H))''$ and $\text{span}(\pi_l(C_c(H))) \subseteq \pi_l(C_c(H))$, there exists a net $(g_{\lambda})_{\lambda\in \Lambda} \subseteq C_c(H)$ such that $\pi_l(g_\lambda) \to x$ strongly. Let $(h_\gamma)_{\gamma\in \Gamma}\subseteq C_c(H)$ be an approximate identity. Define $g_{\lambda,\gamma}=h_\gamma *g_\lambda$ for each $\lambda \in \Lambda,\gamma\in\Gamma$. Then, for all $\lambda \in \Lambda$, it follows that $(g_{\lambda,\gamma})_{\gamma\in\Gamma} \subseteq A$ is a net such that $\|g_{\lambda,\gamma}-g_{\lambda}\|_1 \to 0$. Set $$I:=\{(\lambda,\gamma,\varepsilon):\lambda\in\Lambda,\gamma\in\Gamma,\varepsilon>0,\|g_{\lambda,\gamma}-g_\lambda\|_1<\varepsilon\}$$
    and define $(\lambda_1,\gamma_1,\varepsilon_1)\le (\lambda_2,\gamma_2,\varepsilon_2)$ if $\lambda_1\le\lambda_2,\gamma_1\le\gamma_2
    $ and $\varepsilon_1\ge \varepsilon_2$. We shall now confirm that $I$ is a directed set. For all $(\lambda_1,\gamma_1,\varepsilon_1),(\lambda_2,\gamma_2,\varepsilon_2)\in I$, there exists $0<\varepsilon_3<\text{min}\{\varepsilon_1,\varepsilon_2\}$ and $\lambda_3\ge\lambda_1,\lambda_2$. Moreover, we can choose $\gamma_3\in\Gamma$ such that $\|g_{\lambda_3,\gamma_3}-g_{\lambda_3}\|_1<\varepsilon_3$ and $\gamma_3 \ge \gamma_1,\gamma_2$. Therefore, $(\lambda_3,\gamma_3,\varepsilon_3)\in I$ and $(\lambda_3,\gamma_3,\varepsilon_3) \ge (\lambda_1,\gamma_1,\varepsilon_1),(\lambda_2,\gamma_2,\varepsilon_2)$ holds. Define $p_\Lambda\colon I\to\Lambda;(\lambda,\gamma,\varepsilon)\mapsto\lambda$ and $p_\Gamma\colon I\to\Gamma;(\lambda,\gamma,\varepsilon)\mapsto\gamma$, we shall now check that $p\colon I\to \Lambda\times\Gamma;(\lambda,\gamma,\varepsilon)\mapsto(\lambda,\gamma)$ defines a subnet of $\Lambda\times\Gamma$ as a double index net. For each  $(\lambda_0,\gamma_0)\in\Lambda\times\Gamma$, there exists a $\varepsilon_0>0$ such that $\|g_{\lambda_0,\gamma_0}-g_{\lambda_0}\|_1<\varepsilon_0$. Define $i_0=(\lambda_0,\gamma_0,\varepsilon_0)\in I$. For each $i\ge i_0$, we obtain $p(i)\ge p(i_0)=(\lambda_0,\gamma_0)$. This shows $(g_{p(i)})_{i\in I}$ is a subnet of $(g_{\lambda,\gamma})_{(\lambda,\gamma)\in \Lambda\times\Gamma}\subseteq A$. Similarly, it follows that $p_\Lambda$ defines a subnet of $\Lambda$. Now, it can be shown that $\|g_{p(i)}-g_{p_\Lambda(i)}\|_1 \to 0$. For each $\varepsilon>0$, there exists $(\lambda_0.\gamma_0)\in\Lambda\times\Gamma$ such that $\|g_{\lambda_0,\gamma_0}-g_{\lambda_0}\|_1<\varepsilon$. Set $i_0=(\lambda_0,\gamma_0,\varepsilon)\in I$. For all $i\ge i_0$, we obtain $\|g_{p(i)}-g_{p_\Lambda(i)}\|_1<\varepsilon$. Hence, we conclude that $\|g_{p(i)}-g_{p_\Lambda(i)}\|_1 \to 0$. Finally, we will show $(\pi_l(f_i))_{i\in I}$ converges $x$ strongly where $f_i:=g_{p(i)}\,\,(i\in I)$. For each $\xi\in L^2(H)$,
    \begin{align*}
        \|x\xi-\pi_l(f_i)\xi\|_2 & \le \|x\xi- \pi_l(g_{p_\Lambda(i)})\xi\|_2 + \|\pi_l(g_{p_\Lambda(i)})\xi-\pi_l(f_i)\xi\|_2 \\ &= \|x\xi- \pi_l(g_{p_\Lambda(i)})\xi\|_2 + \|g_{p_\Lambda(i)}*\xi-f_i*\xi\|_2 \\ & \le \|x\xi- \pi_l(g_{p_\Lambda(i)})\xi\|_2 + \|g_{p_\Lambda(i)}-f_i\|_1\|\xi\|_2 \to 0 .
    \end{align*}
    Therefore, $(f_i)_{i\in I}$ is desired one. We conclude that $\pi_l(A)$ is a $\sigma$-weakly dense *-subalgebra of $\mathfrak{m}_{C^{-1}\cdot\varphi_H}$. \par
    Next, we show $\sigma_t^{C^{-1}\cdot\varphi_H}(\pi_l(A))=\pi_l(A)\,\,( t \in \R)$. It suffices to show that $\sigma_t^{\varphi_H}(\pi_l(A)) \subseteq \pi_l(A)\,\,( t \in \R)$ since $\sigma_t^{C^{-1}\cdot\varphi_H}=\sigma_t^{\varphi_H}\,\,( t\in\R)$. We use the form $\pi_l(f)=\int f(x)\lambda_x\, dx$ for $f \in C_c(H)$. Then, for $t\in \R$,  $$\sigma_t^{\varphi_H}(\pi_l(f))=\sigma_t^{\varphi_H}(\int f(x)\lambda_x\, dx) = \int f(x)\sigma_t^{\varphi_H}(\lambda_x) \, dx = \int f(x)\Delta_H(x)^{it}\lambda_x\, dx =\pi_l(f^{(t)})$$ where $f^{(t)}(x)=f(x)\Delta_H(x)^{it} \in C_c(H)$. 
    Moreover, \begin{align*}
         (f*g)^{(t)}(x) =\Delta_H(x)^{it}(f*g)(x)&=\Delta_H(x)^{it}\int f(y)g(y^{-1}x) \, dy \\ &=\int \Delta_H(y)^{it}f(y)\Delta_H(y)^{-it}\Delta_H(x)^{it}g(y^{-1}x)\, dy  \\ &= \int f^{(t)}(y)g^{(t)}(y^{-1}x)\, dy = f^{(t)}*g^{(t)}(x). 
    \end{align*}
    Thus, for $a=\sum_{i=1}^{n}f_i*g_i \in A$, $$\sigma_t^{\varphi_H}(\pi_l(a))=\sum_{i=1}^{n}\sigma_t^{\varphi_H}(\pi_l(f_i*g_i))=\sum_{i=1}^{n}\pi_l(f_i^{(t)}*g_i^{(t)})=\pi_l(\sum_{i=1}^{n}f_i^{(t)}*g_i^{(t)}) \in \pi_l(A).$$
    Therefore, we obtain $\sigma_t^{C^{-1}\cdot\varphi_H}(\pi_l(A)) \subseteq \pi_l(A)\,\,( t \in \R)$. \par
    Finally, we show that $\psi(x)=C^{-1}\cdot\varphi_H(x)$ for all $x \in \pi_l(A)$. It is known that $A \subseteq C_c(H) \cap P(H)$ \cite[Proposition 3.33]{Folland}. Fix $f,g \in C_c(H)$. Since $*$-operation is an involution of $C_c(H)$, we have $(f*g)^*=g^**f^*\in A \subseteq C_c(H) \cap P(H)$. Then, Lemma \ref{rbddlesskdelta} and Lemma \ref{convresol} implies $(f*g)^*=h_0*h_0^{\flat}$ for some right bounded function $h \in L^2(H)$. Hence, $$f*g=((f*g)^*)^*=(h_0*h_0^{\flat})^*=(h_0^{\flat})^**h_0^*=(h_0^*)^{\#}*h_0^*$$
    and $h=h_0^*$ is left bounded by Lemma \ref{rbddimp*lbdd}. We obtain $$\varphi_H(\pi_l(f*g))=\varphi_H(\pi_l(h^{\#}*h))=\varphi_H(\pi_l(h)^*\pi_l(h))=\|h\|_2^2=(h^{\#}*h)(e)=(f*g)(e).$$ Therefore, $\varphi_H(\pi_l(a))=a(e)\,\,( a \in A)$ holds. To complete the proof, we have to show $\psi(\pi_l(a))=C^{-1}\cdot a(e) \,\,( a\in A)$. Note that we identify $L(H)$ with $\{\lambda_h:h\in H\}'' \subseteq L(G)$ via Proposition \ref{subisom}. Let $\Phi$ be the isomorphism i.e. $\Phi(x)=U^*\widehat{x}U$ for $x \in L(H)$. We know that $\Phi(\pi_l(f))=\pi_l(C^{-1}\cdot \tilde{f})$ for $f \in C_c(H)$ as in Proposition \ref{sfofrest}. Fix $f,g\in C_c(H)$, $$\widetilde{f*g}(h)=\int_Hf(y)g(y^{-1}h)\, d\mu_H(y)=C^{-1}\int_H \tilde{f}(y)\tilde{g}(y^{-1}h)\,d\mu_G(y)=C^{-1}(\tilde{f}*\tilde{g})(h) \,\,(h\in H).$$
    Thus, we obtain $\Phi(\pi_l(f*g))=\pi_l(C^{-1}\cdot\widetilde{f*g})=\pi_l(C^{-2}\cdot\tilde{f}*\tilde{g})$. Therefore, it follows that 
    \begin{align*}        \psi(\Phi(\pi_l(f*g)))&=\psi(\pi_l(C^{-2}\cdot\tilde{f}*\tilde{g}))=\varphi_G(\pi_l(C^{-2}\cdot \tilde{f}*\tilde{g}))\\&=C^{-2}(\tilde{f}*\tilde{g})(e)=C^{-1}(\widetilde{f*g})(e)=C^{-1}(f*g)(e).
    \end{align*}
    We use the formula $\varphi_G(\pi_l(f*g))=(f*g)(e)$ for all $f,g\in C_c(G)$.
    Hence, we conclude that $\psi(\pi_l(a))=C^{-1}\cdot a(e) \,\,( a\in A)$. 
\end{proof}

