\section{Twisted crossed products}
Throughout $\S3$ and $\S4$, von Neumann algebras are assumed to have separable preduals, locally compact groups are assumed to be second countable. In this section, we study twisted crossed products of von Neumann algebras. We recall the definition. 

\begin{definition}
    For locally compact groups $G,H$, a cocycle action $(\alpha,c)\colon H \curvearrowright G$ is a pair of maps $\alpha\colon H \to \text{Aut}(G)$ and $c\colon H \times H \to G$ satisfying the relations
    $$\alpha_s\alpha_t=\text{Ad(c(s,t))}\alpha_{st},\,\, c(s,t)c(st,r)=\alpha_s (c(t,r))c(s,tr),\,\,c(s,e_H)=c(e_H,s)=e_G $$
    where $s,t,r \in H$. We say the cocycle action is continuous if the maps $H \times G \ni (s,x)\mapsto \alpha_s(x) \in G$ and $H \times H \ni (s,t) \mapsto c(s,t) \in G$ are continuous where the products are equipped with the product topology.
\end{definition}

\begin{definition}\label{twistcrossprodgrp}
    For locally compact groups $G,H$ and a continuous cocycle action $(\alpha,c)\colon H \curvearrowright G$, we define twisted crossed product as a topological group, denoted by $G \rtimes_{\alpha,c}H$, consisting of $G\times H$ equipped with the product topology and the following group operations
    $$(x,s)(y,t)=(x\alpha_s(y)c(s,t),st),\,\,\,\,(x,s)^{-1}=(\alpha_s^{-1}(x^{-1}c(s,s^{-1})^{-1}),s^{-1})$$
    where $x,y \in G, s,t \in H$. Also, the unit is $(e_G,e_H)$.
\end{definition}

\begin{definition}\label{defofcocycle}
    For a von Neumann algebra $M$ and a locally compact group $G$, a cocycle action $(\alpha,u)\colon G \curvearrowright M$ is a pair of maps $\alpha\colon G \to \text{Aut}(M)$ and $u\colon G \times G \to M^{U}$ satisfying the relations $$\alpha_s\alpha_t=\text{Ad(}u(s,t))\alpha_{st},\,\,u(s,t)u(st,r)=\alpha_s(u(t,r))u(s,tr),\,\,u(s,e_G)=u(e_G,s)=1_M$$ where $s,t,r\in G$. Additionally, we demand that $\alpha$ and $u$ are Borel. That is, $G \ni g \mapsto \alpha_g\in \text{Aut}(M)$ and $u$ are Borel measurable, where a Borel structure on $\text{Aut}(M)$ is generated by the u-topology (equivalent to the topology of pointwise norm convergence against $M_*$) and on $M^U$ is generated by the strong $*$-topology on $M^{U}$.
\end{definition}

\begin{definition}\label{defoftwistvN}
    For a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact group $G$ and a cocycle action $(\alpha,u)\colon G \curvearrowright M$, we define the left twisted crossed product of $M$ by $G$ is the von Neumann algebra on $L^2(G,\mathcal{H})$ (with fixed left Haar measure) generated by the operators 
    \begin{equation*}
    \begin{cases}
        (I^{\alpha}_\ell(x)\xi)(g)=\alpha_{g^{-1}}(x)\xi(g), \\
        (\lambda_\ell^{u}(h)\xi)(g)=u(g^{-1},h)\xi(h^{-1}g)
    \end{cases}
    \end{equation*}
    where $x \in M, g,h\in G, \xi \in L^2(G, \mathcal{H})$. We denote $M \rtimes_{\alpha,u}^{\ell}G$. Also, we define the right twisted crossed product of $M$ by $G$ is the von Neumann algebra on $L^2(G,\mathcal{H})$ (with fixed right Haar measure) generated by the operators  
    \begin{equation*}
    \begin{cases}
        (I_r^{\alpha}(x)\xi)(g)=\alpha_g(x)\xi(g), \\
        (\lambda_r^{u}(h)\xi)(g)=u(g,h)\xi(gh)
    \end{cases}
    \end{equation*}
    where $x \in M, g,h\in G, \xi \in L^2(G, \mathcal{H})$. We denote $M \rtimes_{\alpha,u}^{r}G$.
\end{definition}

\begin{remark}
    Note that the right twisted crossed product is used in \cite{NakagamiSutherland1979}. Moreover, let $M$ be a von Neumann algebra acting on a Hilbert space $\mathcal{H}$. Let $G$ be a locally compact group and $(\alpha,u)\colon G \curvearrowright M$ be a cocycle action $(\alpha,u)\colon G \curvearrowright M$ as described above. Fix a left Haar measure $\mu_G$ on $G$. Then, the right Haar measure on $G$ associated with $\mu_G$ is defined by $\rho_G(E)=\mu_G(E^{-1})$ for each Borel set $E \subseteq G$. In this case, we define the unitary $U\colon L^2(G, \mathcal{H},\mu_G) \to L^2(G, \mathcal{H},\rho_G)$ given by 
    $$(U\xi)(g)=\Delta_G(g)^{-1/2}\xi(g^{-1})\,\,(\xi\in L^2(G, \mathcal{H},\mu_G),g\in G).$$
    It can be shown that this unitary gives the spatial isomorphism $M\rtimes_{\alpha,u}^\ell G \cong M \rtimes_{\alpha,u}^r G$.
\end{remark}

\begin{remark}
    With the same notation as above, it follows that $I_\ell^\alpha$ and $\lambda_\ell^u$ satisfy the covariant relation. That is, for $x\in M, s\in G$, 
    \begin{align*}(\lambda_\ell^u(s)I_\ell^\alpha(x)\lambda_\ell^u(s)^*\xi)(t) &=u(t^{-1},s)(I_\ell^\alpha(x)\lambda_\ell^u(s)^*\xi)(s^{-1}t)
    \\&= u(t^{-1},s)\alpha_{t^{-1}s}(x)(\lambda_\ell^u(s)^*\xi)(s^{-1}t)
    \\&= u(t^{-1},s)\alpha_{t^{-1}s}(x)u(t^{-1},s)^*\xi(t)
    \\&= \text{Ad}(u(t^{-1},s))\alpha_{t^{-1}s}(x)\xi(t)
    \\&=\alpha_t^{-1}(\alpha_s(x))\xi(t)
    \\&=(I_\ell^{\alpha}(\alpha_s(x))\xi)(t)\,\,(\xi\in L^2(G,\mathcal{H})).
    \end{align*}
    Therefore, we obtain    $$\lambda_\ell^u(s)I_\ell^\alpha(x)\lambda_\ell^u(s)^*=I_\ell^{\alpha}(\alpha_s(x))$$
    for all $x\in M, s \in G$.
\end{remark}

Now, we study actions and dual actions. For a moment, we assume that $G$ has a right Haar measure. Throughout the rest of this paper, an action of $G$ on $M$ means a pointwise $\sigma$-weakly continuous action unless explicitly stated otherwise.\par
First, we note that we can identify an action of $G$ on $M$ with an isomorphism of $M$ into $M \overline{\otimes} L^\infty(G)$. We refer to \cite{Nakagami1977} for details.
That is, fix an action $\alpha$ of a locally compact group $G$ on a von Neumann algebra $M$, $\pi_\alpha\colon M\to M \overline{\otimes}L^\infty(G)$ is defined by $$\pi_\alpha(x)(g)=\alpha_g(x)\,\,(g\in G)$$ where we identify $M \overline{\otimes} L^\infty(G)$ with $L^\infty(G,M)$ of all essentially bounded $M$-valued $\sigma$-weakly measurable functions on G. In \cite[Theorem 2.1]{Nakagami1977}, it was shown that a mapping $\alpha$ of $M$ into $M \overline{\otimes}L^{\infty}(G)$ be induced an action $\sigma$ with $(\alpha(x)\xi)(g)=\sigma_g(x)\xi(g)$ if and only if $\alpha$ is an injective homomorphism which satisfies $$(\alpha\otimes \iota)\circ\alpha=(\iota\otimes\delta)\circ\alpha$$ where 
$$\delta\colon L^{\infty}(G)\to L^{\infty}(G)\overline{\otimes}L^{\infty}(G);(\delta f)(s,t)=f(st)$$ and $\iota$ means identity map on $L^{\infty}(G)$ (Here, we identify $L^{\infty}(G)\overline{\otimes}L^{\infty}(G)$ with $L^{\infty}(G\times G)$). In this view point, we define the dual action of $G$ as an isomorphism of $M$ into $M\vNtensor R(G)$ where $R(G)$ denotes the von Neumann algebra generated by the right regular representation on $L^2(G, \rho_G)$, $\rho_G$ stands for the right Haar measure on $G$.

\begin{definition}[{\cite[Definition 2.2]{Nakagami1977}}]
    For a von Neumann algebra $N$ acting on a Hilbert space $\mathcal{K}$ and a locally compact group $G$, a dual action of $G$ on $N$ is an isomorphism of $N$ into $N \vNtensor R(G)$ satisfying $$(\beta\otimes\iota)\circ\beta=(\iota\otimes\gamma)\circ\beta$$
    where $\gamma$ is a normal unital injective homomorphism characterized by $$\gamma\colon R(G)\to R(G) \vNtensor R(G); \gamma(\rho_g)=\rho_g \otimes\rho_g.$$
    We also define crossed dual product $N\rtimes_\beta^{d}G$ be the von Neumann algebra generated by the operators $\beta(N)$ and $1\otimes L^{\infty}(G)$. 
\end{definition}

\begin{remark}
    In the above definition, we note that dual action is not an action in usual sense. 
\end{remark}

Now, we analyze the case where $G$ is abelian. Thus, in the rest of this section, $G$ is assumed to be abelian and admits a fixed (left and right) invariant Haar measure. First, we define the action of $\hat{G}$. Fix a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact abelian group $G$ and a cocycle action $(\alpha,u)\colon G\curvearrowright M$. Following \cite[II, P150]{Sutherland1980}, we define for $p\in \hat{G}$ a unitary $\mu(p)$ on $L^2(G, \mathcal{H})$ by $$(\mu(p)\xi)(g)=\overline{\nai{g}{p}}\xi(g)\,\,\,(\xi\in L^2(G, \mathcal{H}),g\in G).$$
Here, for $x\in M$, on $M \rtimes_{\alpha,u}^{\ell}G$
\begin{align*}
    (\mu(p)I_\ell^{\alpha}(x)\mu(p)^{*}\xi)(g) &= \overline{\nai{g}{p}}(I_\ell^{\alpha}(x)\mu(p)^*\xi)(g) \\&= \overline{\nai{g}{p}}\alpha_{g^{-1}}(x)(\mu(p)^*\xi)(g) \\&= \overline{\nai{g}{p}}\alpha_{g^{-1}}(x)\nai{g}{p}\xi(g) \\&=\alpha_{g^{-1}}(x)\xi(g)\\&= (I_\ell^{\alpha}(x)\xi)(g).
\end{align*}
Also, for $h\in G$, 
\begin{align*}
    (\mu(p)\lambda_\ell^{u}(h)\mu(p)^{*}\xi)(g) &= \overline{\nai{g}{p}}(\lambda_\ell^{u}(h)\mu(p)^*\xi)(g) \\&= \overline{\nai{g}{p}}u(g^{-1},h)(\mu(p)^*\xi)(h^{-1}g) \\&= \overline{\nai{g}{p}}u(g^{-1},h)\nai{h^{-1}g}{p}\xi(h^{-1}g) \\&=\overline{\nai{h}{p}}u(g^{-1},h)\xi(h^{-1}g)\\&= (\overline{\nai{h}{p}}\lambda^u_\ell(h)\xi)(g).
\end{align*}
Thus, $\hat{\alpha}_p=\text{Ad}\mu(p)$ defines a continuous action of $\hat{G}$ on $M \rtimes_{\alpha,u}^{\ell}G$ satisfying 
\begin{align*}
    \begin{cases}        \hat{\alpha}_p(I_\ell^\alpha(x))=I_\ell^\alpha(x),\quad (x\in M) \\
    \hat{\alpha}_p(\lambda_\ell^u(h))=\overline{\nai{h}{p}}\lambda_\ell^u(h) \quad (h\in G)
    \end{cases}
\end{align*}
for all $p \in \hat{G}$.

\begin{definition}
    We say that the continuous action of $\hat{G}$ defined as above is the action of $\hat{G}$ dual to $(\alpha,u)$. We denote $\hat{\alpha}$. 
\end{definition}

%We also define the unitaries $U,V,V'$ and $W$ on $L^2(G) \otimes L^2(G)$ by 
%$$(U\xi)(s,t)=\xi(t,s),(V\xi)(s,t)=\xi(st,t),(V'\xi)(s,t)=\xi(t^{-1}s,t),$$ and $W=UVU$, so $(W\xi)(s,t)=\xi(s,ts)$. \par 
Now, we show the duality for the action dual to a cocycle action.

\begin{lemma}[{\cite[Lemma 1]{NakagamiSutherland1979}}]\label{dualaction}
    For a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact abelian group $G$ and a cocycle action $(\alpha,u)\colon G\curvearrowright M$, if $\beta$ is defined on $M\rtimes_{\alpha,u}^{r}G$ by $$\beta(y)=\text{Ad}(1\otimes W^*)(y\otimes 1_G) \in \B(\mathcal{H})\vNtensor\B(L^2(G))\vNtensor\B(L^2(G)),$$ then $\beta$ is a dual action of $G$ on $M\rtimes_{\alpha,u}^{r}G$. Note that $y\in M\rtimes_{\alpha,u}^{r}G \subseteq \B(L^2(G,\mathcal{H})) \cong \B(\mathcal{H}\otimes L^2(G))=\B(\mathcal{H})\vNtensor\B(L^2(G))$. Here, the unitary $W$ on $L^2(G) \otimes L^2(G)$ is defined by $$(W\xi)(s,t)=\xi(s,ts)\,\,(\xi\in L^2(G) \otimes L^2(G)).$$ 
\end{lemma}

We provide the following lemmas. The first lemma is a minor variation of Tietze's extension theorem (e.g., \cite[4.34]{FollandrealanalysisMR1681462}). We include the proof for completeness.

\begin{lemma}\label{TietzeforLCH}
    For a locally compact Hausdorff space $X$, compact subset $K \subseteq X$ and open subset $K \subseteq U \subseteq X$, if $f\in C(K)$, then there exists $F \in C_c(X)$ such that $F|K=f$ and ${\rm supp}\,F \subseteq U$ hold. Moreover, we may arrange $F$ to satisfy $\|F\|_\infty \le 2$ if $\|f\|_\infty \le 1$.  
\end{lemma}
\begin{proof}
    First, we consider the case $f\in C(K,[0,1])$. By the regularity of $X$, there exists a relatively compact open subset $V \subseteq X$ such that $K \subseteq V \subseteq \overline{V} \subseteq U$. We obtain $\tilde{f} \in C(\overline{V},[0,1])$ such that $\tilde{f}|K=f$ by Tietze extension theorem. If $V=\overline{V}$, then the zero extension of $\tilde{f}$, we denote $F_0$, satisfies the desired properties. If $V \subsetneq \overline{V}$, then there exists $g\in C(X,[0,1])$ such that $g|K=1$ and $g|\overline{V}\backslash V =0$ by Urysohn's lemma. In this case, $F_0\cdot g$ satisfies the desired properties. Next, we consider the case where $f$ is real valued. Since $K$ is compact, there exist $a,b\in \R$ such that $f\in C(K,[a,b])$. Then, using the homeomorphism $[0,1]\ni t \mapsto (b-a)t+a \in[a,b]$, we may find $F\in C_c(X,[a,b])$ with the desired properties. Finally, if $f$ is complex valued, then we obtain $F_1,F_2\in C_c(X,\R)$ that satisfies $F_1|K=\text{Re}f,F_2|K=\text{Im}f$ and ${\rm supp}\,F_i \subseteq U\,\,(i=1,2)$. In this case, $F=F_1+iF_2$ satisfies the desired properties. Moreover, if $\|f\|_\infty \le 1$, then $\|\text{Re}f\|_\infty,\|\text{Im}f\|_\infty \le 1$ hold. The previous argument implies that $\|F_1\|_\infty,\|F_2\|_\infty \le 1$. Therefore, $\|F\|_\infty \le \|F_1\|_\infty +  \|F_2\|_\infty\le 2$ holds.
\end{proof}

\begin{lemma}\label{dualgrpdensity}
    Let $G$ be a locally compact abelian group. We have $m(\hat{G})''=m(L^\infty(G)) \subseteq \B(L^2(G))$, where $m(f)$ denotes the multiplication operator.
\end{lemma}
\begin{proof}
    First, we show that $m(C_0(G))''=m(L^\infty(G))$. Since $m(L^\infty(G))$ is a von Neumann algebra, it is clear that $m(C_0(G))'' \subseteq m(L^\infty(G))$. To show the converse inclusion, we shall show that $m(f)$ is in SOT-closure of the set $\{m(g):g\in C_c(G)\}$. Take $f \in L^\infty(G)$. Fix an arbitrary SOT-neighborhood of $m(f)$, that is, fix $\varepsilon>0,\xi_1,\cdots,\xi_n\in L^2(G)$ and consider the set $$\mathcal{N}(m(f);\xi_1,\cdots ,\xi_n,\varepsilon)=\{T\in \B(L^2(G)): \|m(f)\xi_i-T\xi_i\|_2<\varepsilon\,\,(i=1,\cdots,n)\}.$$ It suffices to show that there exists $g\in C_c(G)$ such that $m(g) \in \mathcal{N}(m(f);\xi_1,\cdots ,\xi_n,\varepsilon)$. We may assume that $\|f\|_\infty=1$. Since $\mu_G$ is a Radon measure, $d\nu_i=|\xi_i|^2d\mu_G\,\,(i=1,\cdots,n)$ is a finite Radon measure on $G$ (see, e.g. \cite[P220, Exercise 7.8]{FollandrealanalysisMR1681462}). Then, by the inner regularity, for each $i=1,\cdots,n$, there exists a compact set $K_i$ such that $\nu_i(G\backslash K_i) < \varepsilon^2/50$. Let $K=\bigcup_{i=1}^nK_i$. We see that $K$ is compact. Since $\mu_G|K$ is a finite Radon measure on $K$, $C_c(K)$ is dense in $L^1(K,\mu_G|K)$. Therefore, since $f|K \in L^1(K,\mu_G|K)$, there exists a sequence  $(g_m)_{m\in \N} \subseteq C_c(K)$ such that $\int_K|g_m-f|\,d\mu_G \to 0$ as $m\to \infty$ and $|g_m(x)|\le2|f(x)|$ for all $m\in\N$ and $\mu_G$-a.e. $x\in K$. Then, by passing to a subsequence, we may assume $|g_m(x)|\to|f(x)|$ as $m\to\infty$ $\mu_G$-a.e. $x\in K$. For each $i=1,\cdots,n$, we have $|g_m(x)-f(x)|^2 |\xi_i(x)|^2\le 9|\xi_i(x)|^2 $ and $|\xi_i|^2\in L^1(K,\mu_G|K)$. Therefore, by Lebesgue dominated convergence theorem, we have 
    $$\int_K|g_m-f|^2|\xi_i|^2\,d\mu_G \to 0\,\, \text{as}\,\, m \to\infty\,\, (i=1,\cdots,n). $$ It follows that there exists $N\in \N$ such that $\int_K|g_N-f|^2|\xi_i|^2\,d\mu_G < \varepsilon^2/2$ for all $i=1,\cdots,n$. By Lemma \ref{TietzeforLCH}, we obtain $g\in C_c(G)$ such that $g|K=g_N$. Since $\|g_N\|_\infty \le2$, the proof of Lemma \ref{TietzeforLCH} implies that $\|g\|_\infty \le4$. For $i=1,\cdots,n$, we have 
    $$\int_{G\backslash K}|g-f|^2|\xi_i|^2\,d\mu_G \le 25 \int_{G \backslash K}|\xi_i|^2\,d\mu_G < \varepsilon^2/2.$$
    Thus, we obtain 
    \begin{align*}
        \|m(g)\xi_i-m(f)\xi_i\|_2^2&=\int_G|g-f|^2|\xi_i|^2 \,d\mu_G \\&=\int_K|g-f|^2|\xi_i|^2\,d\mu_G+\int_{G\backslash K}|g-f|^2|\xi_i|^2\,d\mu_G
        \\&< \frac{\varepsilon^2}{2} + \frac{\varepsilon^2}{2} =\varepsilon^2\,\,(i=1,\cdots,n).
    \end{align*}
    We conclude that $m(g) \in \mathcal{N}(m(f);\xi_1,\cdots ,\xi_n,\varepsilon)$ and hence $m(f) \in m(C_c(G))''\subseteq m(C_0(G))''$. \par
    Next, we shall show that $m(\hat{G})''=m(L^\infty(G))$, in particular $m(L^\infty(G))\subseteq m(\hat{G})''$. We identify $G$ with the dual group of $\hat{G}$, let $\hat{\mathcal{F}}\colon L^1(\hat{G})\to C_0(G)$ be the Fourier transform given by $$(\hat{\mathcal{F}}f)(x)=\int_{\hat{G}} \nai{x}{p}f(p)\,d\mu_{\hat{G}}(p)\,\,(f\in L^1(\hat{G})).$$ Then, it follows that $\hat{\mathcal{F}}(L^1(\hat{G}))$ is norm dense in $C_0(G)$ and hence $m(C_0(G))'' = m(\hat{\mathcal{F}}(L^1(\hat{G})))''$. We see that $$m(\hat{\mathcal{F}}f)=\int_{\hat{G}}f(p)m(p)\,d\mu_{\hat{G}}(p)\in m(\hat{G})''\,\,(f\in L^1(\hat{G})).$$ Thus, we conclude that $$m(L^\infty(G))=m(C_0(G))'' = m(\hat{\mathcal{F}}(L^1(\hat{G})))''\subseteq m(\hat{G})''.$$
\end{proof}

\begin{proposition}\label{cocycleduality}
    For a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact abelian group $G$ and a cocycle action $(\alpha,u)\colon G\curvearrowright M$, we have $$M\rtimes_{\alpha,u}^{\ell}G\rtimes_{\hat{\alpha}}\hat{G}\cong M \vNtensor \B(L^2(G)).$$
\end{proposition}
\begin{proof}
    Let $\beta$ be a dual action of $G$ defined in Lemma \ref{dualaction}. Since $M\rtimes_{\alpha,u}^{r}G\rtimes_\beta^{d}G\cong M \vNtensor\B(L^2(G))$ by \cite[Theorem 2]{NakagamiSutherland1979}, we shall show $M\rtimes_{\alpha,u}^{\ell}G\rtimes_{\hat{\alpha}}\hat{G}\cong M\rtimes_{\alpha,u}^{r}G\rtimes_\beta^{d}G$. Let $\mathcal{F}\colon L^2(G)\to L^2(\hat{G)}$ be the Fourier transform defined by $$(\mathcal{F}\xi)(p)=\int_{G}\overline{\nai{s}{p}}\xi(s)\,d\mu_G(s)\,\,(\xi\in L^2(G)).$$ Put $\hat{\mathcal{F}}=\mathcal{F}^*$ be the Fourier inverse transform. We also define unitary $S\colon L^2(G)\to L^2(G)$ by $(S\xi)(g)=\xi(g^{-1})$. Set $\Phi\colon \B(\mathcal{H})\vNtensor\B(L^2(G))\vNtensor\B(L^2(\hat{G}))\to \B(\mathcal{H})\vNtensor\B(L^2(G))\vNtensor\B(L^2(G))$ by $\Phi=\text{Ad}(1\otimes S \otimes \hat{\mathcal{F}})$. Note that $M\rtimes_{\alpha,u}^{\ell}G\rtimes_{\hat{\alpha}}\hat{G}$ is generated by operators $\pi_{\hat{\alpha}}(x), \lambda_{\hat{\alpha}}(p) (x\in M\rtimes_{\alpha,u}^{\ell}G,p\in \hat{G})$ defined by $$(\pi_{\hat{\alpha}}(x)\xi)(g,p)=((\hat{\alpha}_p^{-1}(x)\otimes1_{\hat{G}})\xi)(g,p),(\lambda_{\hat{\alpha}}(q)\xi)(g,p)=\xi(g,p-q)$$ where $\xi\in\mathcal{H}\otimes L^2(G) \otimes L^2(\hat{G}),g\in G, p,q \in \hat{G}$. Then, we can calculate, for $x\in M$, 
    \begin{align*}
        (\Phi(\pi_{\hat{\alpha}}(I_\ell^{\alpha}(x)))\xi)(s,t)&=((1\otimes S \otimes \hat{\mathcal{F}})(\pi_{\hat{\alpha}}(I_\ell^{\alpha}(x)))(1\otimes S^*\otimes \mathcal{F})\xi)(s,t) \\&=\int_{\hat{G}}\nai{t}{p}(\pi_{\hat{\alpha}}(I_\ell^{\alpha}(x))(1\otimes S^*\otimes \mathcal{F})\xi)(s^{-1},p) \,d\mu_{\hat{G}}(p) \\&= \int_{\hat{G}}\nai{t}{p}((\hat{\alpha}_p^{-1}(I_\ell^{\alpha}(x))\otimes1_{\hat{G}})(1\otimes S^* \otimes\mathcal{F})\xi)(s^{-1},p)\, d\mu_{\hat{G}}(p) \\&= \int_{\hat{G}}\nai{t}{p}((I_\ell^{\alpha}(x)\otimes 1_{\hat{G}})(1\otimes S^* \otimes\mathcal{F})\xi)(s^{-1},p)\, d\mu_{\hat{G}}(p) \\&= \int_{\hat{G}}\nai{t}{p}\alpha_{s}(x)((1\otimes S^* \otimes\mathcal{F})\xi)(s^{-1},p)\, d\mu_{\hat{G}}(p) \\&= \alpha_{s}(x)\int_{\hat{G}}\nai{t}{p}((1\otimes S^* \otimes\mathcal{F})\xi)(s^{-1},p)\, d\mu_{\hat{G}}(p) \\&= \alpha_{s}(x)((1\otimes S\otimes \hat{\mathcal{F}})(1\otimes S^* \otimes\mathcal{F})\xi)(s,t) \\&= \alpha_s(x)\xi(s,t)\\&= ((I_r^{\alpha}(x)\otimes 1_{G})\xi)(s,t).  
    \end{align*}
    For $g \in G$, 
    \begin{align*}
         (\Phi(\pi_{\hat{\alpha}}(\lambda_\ell^u(g)))\xi)(s,t) 
         &= \int_{\hat{G}} \nai{t}{p}(\pi_{\hat{\alpha}}(\lambda_\ell^u(g))(1\otimes S^*\otimes \mathcal{F})\xi)(s^{-1},p)\,d\mu_{\hat{G}}(p) 
         \\&= \int_{\hat{G}} \nai{t}{p}((\hat{\alpha}_p^{-1}(\lambda_\ell^u(g))\otimes1_{\hat{G}})(1\otimes S^*\otimes \mathcal{F})\xi)(s^{-1},p)\,d\mu_{\hat{G}}(p) 
         \\&= \int_{\hat{G}}\nai{t}{p}\nai{g}{p}u(s,g)((1\otimes S^* \otimes \mathcal{F})\xi)(g^{-1}s^{-1},p)\,d\mu_{\hat{G}}(p) 
         \\&= u(s,g) \int_{\hat{G}}\nai{tg}{p}((1\otimes S^* \otimes \mathcal{F})\xi)(g^{-1}s^{-1},p)\,d\mu_{\hat{G}}(p) 
         \\&= u(s,g)((1\otimes S \otimes \hat{\mathcal{F}})(1\otimes S^* \otimes \mathcal{F})\xi)(sg,tg)
         \\&=u(s,g)\xi(sg,tg)
         \\&=((\lambda_r^u(g)\otimes \lambda_r(g))\xi)(s,t),
    \end{align*}
    where $\lambda_r$ stands for the right regular representation. Furthermore, for $q\in \hat{G}$, 
    \begin{align*}
        (\Phi(\lambda_{\hat{\alpha}}(q))\xi)(s,t) 
        &= \int_{\hat{G}} \nai{t}{p}(\lambda_{\hat{\alpha}}(q)(1\otimes S^*\otimes \mathcal{F})\xi)(s^{-1},p)\,d\mu_{\hat{G}}(p)
        \\&= \int_{\hat{G}} \nai{t}{p}((1\otimes S^*\otimes \mathcal{F})\xi)(s^{-1},p-q)\,d\mu_{\hat{G}}(p)
        \\&=\int_{\hat{G}} \nai{t}{p+q}((1\otimes S^*\otimes \mathcal{F})\xi)(s^{-1},p)\,d\mu_{\hat{G}}(p) 
        \\&= \nai{t}{q}\int_{\hat{G}} \nai{t}{p}((1\otimes S^*\otimes \mathcal{F})\xi)(s^{-1},p)\,d\mu_{\hat{G}}(p) 
        \\&= \nai{t}{q} ((1\otimes S\otimes \hat{\mathcal{F}})(1\otimes S^*\otimes \mathcal{F})\xi)(s,t) 
        \\&=\nai{t}{q}\xi(s,t)
        \\&=((1\otimes 1_G \otimes m(q))\xi)(s,t),
    \end{align*}
    where $m\colon L^{\infty}(G)\to \B(L^2(G));(m(f)\xi)(t)=f(t)\xi(t)$. Therefore, we conclude 
    \begin{align*}
        \begin{cases}
            \Phi(\pi_{\hat{\alpha}}(I_\ell^{\alpha}(x)))=I_r^{\alpha}(x)\otimes1_G \\
            \Phi(\pi_{\hat{\alpha}}(\lambda_\ell^{u}(g)))=\lambda_r^u(g)\otimes \lambda_r(g) \\
            \Phi(\lambda_{\hat{\alpha}}(q))=1\otimes1_G\otimes m(q),
        \end{cases}
    \end{align*}
    where $x \in M, g\in G, q\in \hat{G}$. By \cite[Lemma 1]{NakagamiSutherland1979}, we see that 
    \begin{align*}
        \begin{cases}
            \beta(I_r^{\alpha}(x))=I_r^{\alpha}(x) \otimes 1_G\\
            \beta(\lambda_r^{u}(g))=\lambda_r^{u}(g)\otimes\lambda_r(g),
        \end{cases}
    \end{align*}
    where $x\in M, g \in G$. By Lemma \ref{dualgrpdensity}, we conclude that $\Phi(M\rtimes_{\alpha,u}^\ell G \rtimes_{\hat{\alpha}}\hat{G})$ generates $M \rtimes_{\alpha,u}^rG \rtimes_\beta^dG$. Hence, we have $$M\rtimes_{\alpha,u}^\ell G \rtimes_{\hat{\alpha}}\hat{G}\cong M \rtimes_{\alpha,u}^rG \rtimes_\beta^d G \cong M \vNtensor\B(L^2(G)).$$
    In particular, $M\rtimes_{\alpha,u}^\ell G \rtimes_{\hat{\alpha}}\hat{G}$ and $M \rtimes_{\alpha,u}^rG \rtimes_\beta^dG$ are spatially isomorphic.
\end{proof}

\begin{remark}\label{remark1}
    Proposition \ref{cocycleduality} might be known to experts, but for the clarity of the presentation we included a detailed proof. Moreover, $\hat{\alpha}$ of Proposition \ref{cocycleduality} is employed as the point modular extension within \cite[Theorem 5.1]{guinto2025unimodulargroups} (see also Proposition \ref{fullspectrum}).   
\end{remark}

 We introduce the action $\tilde{\alpha}$ of $G$ on $M \vNtensor \B(L^2(G))$. Let $\tilde{\lambda^u}(t)$ be the unitary on $\mathcal{H}\otimes L^2(G)$ defined by $$(\tilde{\lambda^u}(t)\xi)(s)=u(t,t^{-1}s)^*\xi(t^{-1}s)$$ where $\xi\in \mathcal{H}\otimes L^2(G),t,g\in G$. Then, we see that $$(\tilde{\lambda^u}(t)^*\xi)(s)=u(t,s)\xi(ts).$$ Now, we define the action $\tilde{\alpha}$ by $$\tilde{\alpha}_t=\text{Ad}\tilde{\lambda^u}(t)\circ(\alpha_t \otimes \iota)\,\, (t\in G).$$
We can check $\tilde{\alpha}$ is a well defined action, i.e. $\tilde{\alpha}_s\tilde{\alpha}_t=\tilde{\alpha}_{st}$ for all $s,t\in G$. We refer to \cite[Corollary 3]{NakagamiSutherland1979} and \cite[Theorem 2.1]{Nakagami1977} for details.

%\begin{lemma}
%    With the same notation in Proposition\ref{cocycleduality}, we have $$M\rtimes _{\alpha,u}^\ell G \cong (M \vNtensor \B(L^2(G)))^{\tilde{\alpha}}.$$ 
%\end{lemma}
%\begin{proof}
%    We can check that $\text{Ad}(1\otimes S)$ induces a unitarily equivalence\todo{spatial isomorphism} $M \rtimes_{\alpha,u}^\ell G \cong M \rtimes_{\alpha,u}^r G$ where $S$ is the unitary operator defined in the proof of Proposition \ref{cocycleduality}. Therefore, by \cite[Corollary4]{NakagamiSutherland1979}, we obtain $$M \rtimes_{\alpha,u}^\ell G \cong M \rtimes_{\alpha,u}^r G=(M \vNtensor \B(L^2(G)))^{\tilde{\alpha}}.$$
%\end{proof}

Now, we introduce the subgroup of $\hat{G}$ defined by the cocycle action. 

\begin{definition}\label{defoftwistspctrm}
    For a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact abelian group $G$ and a cocycle action $(\alpha,u)\colon G\curvearrowright M$, $\Gamma(\alpha,u)$ is defined as the kernel of the restriction of the action $\hat{\alpha}$ of $\hat{G}$ dual to $(\alpha,u)$ to the center $Z(M\rtimes_{\alpha,u}^\ell G)$ of the twisted crossed product $M\rtimes_{\alpha,u}^\ell G$. That is, 
    $$\Gamma(\alpha,u)=\{p\in \hat{G}: \hat{\alpha}_p(n)=n \,\,(n\in Z(M\rtimes_{\alpha,u}^\ell G))\}$$
\end{definition}

We give some definitions for the factority results of twisted crossed products.

\begin{definition}
    For a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact abelian group $G$ and a cocycle action $(\alpha,u)\colon G\curvearrowright M$, the fixed point algebra $M^{(\alpha,u)}$ is defined by $$M^{(\alpha,u)}=\{x\in M : \alpha_t(x)=x\,(t\in G)\}.$$ The equation $\alpha_s\alpha_t=\text{Ad}(u(s,t))\alpha_{st}$ implies that $$\text{Ad}(u(s,t))(x)=x\,\,(s,t\in G)$$ for all $x \in M^{(\alpha,u)}$ automatically. Clearly, $M^{(\alpha,u)}$ is a von Neumann subalgebra of $M$.
\end{definition}

Since $\alpha_t\in \text{Aut}(M)$ for all $t\in G$, we have $\alpha_t(Z(M))=Z(M) \,\, (t\in G)$. Thus, we can define central ergodicity of a cocycle action. 

\begin{definition}
    For a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact abelian group $G$ and a cocycle action $(\alpha,u)\colon G\curvearrowright M$, we say the cocycle action is centrally ergodic if $$Z(M)^{\alpha}=\{x\in Z(M):\alpha_t(x)=x\,\,(t\in G)\}=\C1_M.$$
\end{definition}

Before proving the factoriality characterization. We recall elementary facts about an isomorphism between von Neumann algebras. Let $M,N$ be von Neumann algebras and $\Phi\colon M\to N$ be an isomorphism. Then it is straightforward to see $\Phi(Z(M))=Z(N)$. Next, if some locally compact group $G$ acts on $M$ continuously by $\alpha\colon G\to \text{Aut}(M)$, then $G\ni g\mapsto \Phi\circ\alpha_g\circ\Phi^{-1}\in \text{Aut}(N)$ defines a continuous action of $G$ on $N$. Moreover, we see that $\Phi (M^{\alpha})=N^{\Phi\circ\alpha\circ\Phi^{-1}}$. 

\begin{theorem}\label{twistConnesfactority}
    For a von Neumann algebra $M$ acting on a Hilbert space $\mathcal{H}$, a locally compact abelian group $G$ and a cocycle action $(\alpha,u)\colon G\curvearrowright M$, the following two conditions are equivalent.
    \begin{enumerate}
        \item[(i)] $\Gamma(\alpha,u)=\hat{G}$ and $(\alpha,u)\colon G\curvearrowright M$ is centrally ergodic.
        \item[(ii)] $M\rtimes_{\alpha,u}^\ell G$ is a factor.
    \end{enumerate}
\end{theorem}
\begin{proof}
    $\text{(i)}\implies \text{(ii)}.$ Let $N=M\rtimes_{\alpha,u}^\ell G$. By assumption, we obtain $Z(N) \subseteq N^{\hat{\alpha}}$. Indeed, for each $n\in Z(N)$, it follows that $\hat{\alpha}_p(n)=n$ for all $p \in \hat{G}$. Since, for each $n \in Z(N)$, $(\pi_{\hat{\alpha}}(n)\xi)(p)=n\xi(p)$ for all $\xi \in L^2(\hat{G},\mathcal{K}),p\in \hat{G}$ where $\mathcal{K}=\mathcal{H}\otimes L^2(G)$, we see that $$\pi_{\hat{\alpha}}(n)\pi_{\hat{\alpha}}(x)=\pi_{\hat{\alpha}}(x)\pi_{\hat{\alpha}}(n), \pi_{\hat{\alpha}}(n)\lambda_{\hat{\alpha}}(q)=\lambda_{\hat{\alpha}}(q)\pi_{\hat{\alpha}}(n)\,\,(x\in N,q\in\hat{G}).$$ Hence, $\pi_{\hat{\alpha}}(Z(N))$ is contained in the center of $N \rtimes_{\hat{\alpha}}\hat{G}$. Put $N_r=M \rtimes_{\alpha,u}^r G \subseteq M \vNtensor \B(L^2(G))$. 
    Let $\Psi\colon M \vNtensor\B(L^2(G)) \to N \rtimes_{\hat{\alpha}}\hat{G}$ be the isomorphism obtained by Proposition \ref{cocycleduality}. In fact, $\Psi=\Phi^{-1}\circ \Theta$ where $\Phi\colon N\rtimes_{\hat{\alpha}}\hat{G}\to  N_r\rtimes_\beta^d G$ is a $*$-isomorphism defined in Proposition \ref{cocycleduality} and $\Theta \colon  M\vNtensor \B(L^2(G)) \to N_r \rtimes_\beta^d G$ is a $*$-isomorphism defined in \cite[Theorem 2]{NakagamiSutherland1979}. We see that 
    \begin{align*}
        \begin{cases}
         \Theta(I_r^\alpha(x))=I_r^\alpha(x)\otimes1_G, \quad (x\in M) \\
         \Theta(\lambda_r^u(g))=\lambda_r^u(g)\otimes\lambda_r(g), \quad(g\in G).
        \end{cases}
    \end{align*}
    Therefore, we obtain $\Psi(N_r)=\pi_{\hat{\alpha}}(N)$ by the calculation in Proposition \ref{cocycleduality}. Furthermore, since $\pi_{\hat{\alpha}}$ is an isomorphism of $N$ onto image, we have $\Psi(Z(N_r))=Z(\Psi(N_r))=Z(\pi_{\hat{\alpha}}(N))\subseteq \pi_{\hat{\alpha}}(Z(N))$.
    %we shall show that $\Psi(Z(N_r)) \subseteq\pi_{\hat{\alpha}}(Z(N))$. It is clear that $\Psi(Z(N_r))=Z(\Psi(N_r))=Z(\pi_{\hat{\alpha}}(N))$. Hence, for $x\in Z(\pi_{\hat{\alpha}}(N))$, take $y\in N$ such that $x=\pi_{\hat{\alpha}}(y) \in \pi_{\hat{\alpha}}(N)'$, we shall show that $y \in Z(N)$. Take arbitrary $z\in N$, we have $$\pi_{\hat{\alpha}}(yz)=\pi_{\hat{\alpha}}(y) \pi_{\hat{\alpha}}(z)=\pi_{\hat{\alpha}}(z) \pi_{\hat{\alpha}}(y)=\pi_{\hat{\alpha}}(zy).$$ 
    %Since $N\ni z \mapsto \pi_{\hat{\alpha}}(z)\in N \rtimes_{\hat{\alpha}}\hat{G}$ is an injective isomorphism, we conclude that $yz=zy$. Therefore, $\Psi(Z(N_r))=Z(\pi_{\hat{\alpha}}(N)) \subseteq \pi_{\hat{\alpha}}(Z(N))$ holds.
    Noting that $N_r=(M \vNtensor \B(L^2(G)))^{\tilde{\alpha}}\subseteq M \vNtensor L^2(G)$ by \cite[Corollary 4]{NakagamiSutherland1979}, it follows that 
    \begin{align*}
        \Psi(Z(N_r))&=\Psi(Z(N_r)^{\tilde{\alpha}})= \Psi(Z(N_r))^{\Psi\circ\tilde{\alpha}\circ \Psi^{-1}} \subseteq \pi_{\hat{\alpha}}(Z(N))^{\Psi\circ\tilde{\alpha}\circ \Psi^{-1}} \subseteq Z(N\rtimes_{\hat{\alpha}}\hat{G})^{\Psi\circ\tilde{\alpha}\circ \Psi^{-1}} \\
        &= \Psi(Z(M \vNtensor \B(L^2(G))))^{\Psi\circ\tilde{\alpha}\circ \Psi^{-1}}=\Psi(Z(M\vNtensor\B
        (L^2(G)))^{\tilde{\alpha}}).
    \end{align*}
    We shall show $Z(M\vNtensor\B
    (L^2(G)))^{\tilde{\alpha}}=\C$. Since $Z(M\vNtensor \B(L^2(G)))=Z(M)\vNtensor \C$, for $x \otimes 1_G \in Z(M) \vNtensor \C
    $, we calculate 
    \begin{align*}
        (\tilde{\alpha}_t(x\otimes 1_G)\xi)(s) &=(\tilde{\lambda}^u(t)(\alpha_t\otimes\iota
        )(x\otimes 1_G)\tilde{\lambda}^u(t)^*\xi)(s) 
        \\&= u(t,t^{-1}s)^*((\alpha_t(x)\otimes 1_G)\tilde{\lambda}^u(t)^*\xi)(t^{-1}s) 
        \\&= u(t,t^{-1}s)^*\alpha_t(x)(\tilde{\lambda}^u(t)^*\xi)(t^{-1}s)
        \\&= u(t,t^{-1}s)^*\alpha_t(x)u(t,t^{-1}s)\xi(s)
        \\&= \alpha_t(x)\xi(s)
        \\&= ((\alpha_t(x)\otimes1_G)\xi)(s)            
    \end{align*}
    for all $\xi \in \mathcal{H} \otimes L^2(G), s,t\in G$. Thus, we conclude that $\tilde{\alpha}_t(x\otimes 1_G)=\alpha_t(x)\otimes1_G\,(t\in G)$. Hence, if $\tilde{\alpha}_t(x\otimes 1_G)=x\otimes1_G$ for all $t\in G$, then $\alpha_t(x)=x\, (t\in G)$ holds. Central ergodicity of the cocycle action implies $Z(M\vNtensor \B(L^2(G)))^{\tilde{\alpha}}=Z(M)^\alpha \vNtensor\C=\C$. We obtain $Z(N)\cong Z(N_r) \cong \Psi(Z(N_r)) = \C$. That is, $N$ is a factor. \\
    $\text{(ii)}\implies\text{(i)}.$ If $N=M \rtimes_{\alpha,u}^\ell G$ is a factor, then the kernel of the restriction of the action $\hat{\alpha}$ to $Z(N)=\C$ must be the entire $\hat{G}$. It remains to show the central ergodicity of the cocycle action. For, $x,y \in M, s\in G$, we see that 
    \begin{align*}
        \begin{cases}
            I_\ell^\alpha(x)I_\ell^{\alpha}(y)=I_\ell^\alpha(xy),\\
            \lambda_\ell^u(s)I_\ell^\alpha(x)\lambda_\ell^u(s)^*=I_\ell^\alpha(\alpha_s(x)).
        \end{cases}
    \end{align*}
    Now, suppose that $(\alpha,u)$ is not centrally ergodic. Then, there exists $x \in Z(M)^\alpha$ such that $x \notin \C 1_M$. For $y\in M$, since $x \in Z(M)$, $$I_\ell^\alpha(x)I_\ell^{\alpha}(y)=I_\ell^\alpha(xy)=I_\ell^\alpha(yx)=I_\ell^\alpha(y)I_\ell^{\alpha}(x).$$
    Moreover, by the covariant relation, for $s\in G$, $$\lambda_\ell^u(s)I_\ell^\alpha(x)\lambda_\ell^u(s)^*=I_\ell^\alpha(\alpha_s(x))=I_\ell^\alpha(x),$$
    that is $\lambda_\ell^u(s)I_\ell^\alpha(x)=I_\ell^\alpha(x)\lambda_\ell^u(s)$. It follows that $I_\ell^\alpha(x)$ is a non trivial central element of $M\rtimes_{\alpha,u}^\ell G$, which is a contradiction.
\end{proof}


\section{Application to totally disconnected groups}
In this section, we apply Theorem \ref{twistConnesfactority} to group von Neumann algebras of tdlc (totally disconnected locally compact) groups. We use the following proposition. We provide a proof for later use. 

\begin{proposition}
[{\cite[II, Proposition 3.1.7]{Sutherland1980}}]\label{cocycleresol}
    For a locally compact group $G$, a discrete group $K$ and an open normal subgroup $H$ of $G$, if $G/H \cong K$ as topological groups and $H$ is unimodular, then there exists a cocycle action $(\alpha,u)$ of $K$ on $L(H)$ such that $L(G) \cong L(H) \rtimes_{\alpha,u}^\ell K$ holds.
\end{proposition}
\begin{proof}
    Fix representatives $(g_i)_{i\in I}\subseteq G$ for the $H$ cosets. That is, $(g_i)_{i\in I}$ satisfies $G=\bigsqcup_{i\in I}g_i H$. We can take as $e_G\in (g_i)_{i\in I}$. By assumption, there exists an injective map $\sigma\colon K\to G$ such that $q\circ \sigma\colon K\to G/H$ is a group isomorphism, where $q\colon G\to G/H$ is the canonical quotient map. One can normalize this map as $\sigma(e_K)=e_G$. Moreover, we can take this map as a continuous map since $K$ is discrete. Set $\alpha^K\colon K\to \text{Aut}(H)$ as $\alpha_k^K(h)=\sigma(k)h\sigma(k)^{-1}$ and $c^K\colon K\times K \to H$ as $c^K(k_1,k_2)=\sigma(k_1)\sigma(k_2)\sigma(k_1k_2)^{-1}$. Then by a straightforward calculations, one can see that $(\alpha^K,c^K)$ is a continuous cocycle action of $K$ on $H$. Furthermore, it can be shown that $G\ni g=h\sigma(k)\mapsto (h,k)\in H\rtimes_{\alpha^K,c^K}K$ is a topological group isomorphism.\par
    We define $\beta_k\in \text{Aut}(H)$ by $\beta_k(h)=\sigma(k^{-1})^{-1}h\sigma(k^{-1})$ for each $k\in K$ and $c(k_1,k_2) \in H$ by $c(k_1,k_2)=\sigma(k_1^{-1})^{-1}\sigma(k_2^{-1})^{-1}\sigma(k_2^{-1}k_1^{-1})$ for each $k_1,k_2\in K$. Furthermore, we define the unitary $v_k$ on $L^2(H)$ by $$(v_k\xi)(h)=\delta(k)^{1/2}\xi(\beta_k^{-1}(h))$$
    for each $k \in K$ where $\xi \in L^2(H)$ and $\delta(k) \in (0,\infty)$ is a constant which satisfies $\int_H\xi(h)\,d\mu_H(h)=\delta(k)\int_H\xi(\beta_k^{-1}(h))\,d\mu_{H}(h)$ for all $\xi \in L^1(H)$. Note that $\delta\colon K\to (0,\infty)$ is a homomorphism since $H$ is unimodular. We need unimodularity because $\beta_{k_1}^{-1}\beta_{k_2}^{-1}=\beta_{k_2k_1}^{-1}\circ\text{Ad}(c(k_2,k_1))^{-1}$ for all $k_1,k_2 \in K$. For $k\in K$, since $\alpha_k(\lambda_\ell^{H}(h))=\lambda_\ell^{H}(\beta_k(h))\,\,(h\in H)$, it follows that $L(H) \ni x\mapsto v_kxv_k^* \in \B(L^2(H))$ is an automorphism on $L(H)$. Now, if we define $\alpha_k\colon L(H)\ni x\mapsto v_kxv_k^* \in L(H)$ and $u(k_1,k_2)=\lambda_\ell^H(c(k_1,k_2))$, then it follows that $(\alpha,u)\colon K\curvearrowright L(H)$ is a cocycle action. By calculation, we obtain the cocycle equations. That is, they satisfy the following equations: 
    $$\alpha_{k_1}\alpha_{k_2}=\text{Ad}(u(k_1,k_2))\alpha_{k_1 k_2}, u(k_1,k_2)u(k_1k_2,k_3)=\alpha_{k_1}(u(k_2,k_3))u(k_1,k_2k_3)$$
    for all $k_1,k_2,k_3 \in K$. Moreover, $u(k,e)=u(e,k)=1_{L(H)}\,\,(k\in K)$ holds. Since $K$ is discrete, Borel requirement is satisfied. \par 
    Finally, we shall show that $L(G) \cong L(H) \rtimes_{\alpha,u}^\ell K$. Note that $L(G) \cong L(H\rtimes_{\alpha^K,c^K}K)$. We identify $L^2(H) \otimes L^2(K)$ with $L^2(H \times K)$. Under this identification, $L(H) \rtimes_{\alpha,u}^\ell K$ is generated by the operators $I_{\ell}^{\alpha}(\lambda_{\ell}^H(h_0))\,(h_0\in H)$ and $\lambda_{\ell}^u(k_0)\,(k_0\in K)$ given by 
    \begin{align*}
        \begin{cases}
            (I_\ell^{\alpha}(\lambda_\ell^H(h_0))\xi)(h,k)=((\alpha_{k^{-1}}(\lambda_\ell^H(h_0))\otimes1_K)\xi)(h,k)=\xi(\beta_{k^{-1}}(h_0)^{-1}h,k), \\
            (\lambda_\ell^u(k_0)\xi)(h,k)=((u(k^{-1},k_0)\otimes1_K)\xi)(h,k_0^{-1}k)=\xi(c(k^{-1},k_0)^{-1}h,k_0^{-1}k)
        \end{cases}
    \end{align*} 
    where $\xi \in L^2(H \times K),h,h_0\in H,k,k_0\in K$. Let $U$ be the unitary on $L^2(H\times K)$ defined by $$(U\xi)(h,k)=((v_{k^{-1}}^*\otimes1_K)\xi)(h,k)=\delta(k)^{1/2}\xi(\beta_{k^{-1}}(h),k).$$ 
     We see that $$(U^*\xi)(h,k)=\delta(k)^{-1/2}\xi(\beta_{k^{-1}}^{-1}(h),k).$$
    We calculate, for $h_0 \in H$,
    \begin{align*}
        (U(I_\ell^{\alpha}(\lambda_\ell^H(h_0))U^*\xi)(h,k)&= \delta(k)^{1/2}(I_\ell^{\alpha}((\lambda_\ell^H(h_0))U^*\xi)(\beta_{k^{-1}}(h),k) \\
        &= \delta(k)^{1/2}(U^*\xi)(\beta_{k^{-1}}(h_0)^{-1}\beta_{k^{-1}}(h),k) \\
        &= \xi(h_0^{-1}h,k).
    \end{align*}
    Also, for $k_0 \in K$,
    \begin{align*}
        (U\lambda_\ell^u(k_0)U^*\xi)(h,k) &=\delta(k)^{1/2}(\lambda_\ell^u(k_0)U^*\xi)(\beta_{k^{-1}}(h),k) \\
        &= \delta(k)^{1/2}(U^*\xi)(c(k^{-1},k_0)^{-1}\beta_{k^{-1}}(h),k_0^{-1}k) \\
        &= \delta(k_0)^{1/2}\xi(\beta_{k^{-1}k_0}^{-1}(c(k^{-1},k_0)^{-1}\beta_{k^{-1}}(h)),k_0^{-1}k).
    \end{align*}
    On the other hand, with the identification $G \cong H\rtimes_{\alpha^K,c^K}K$, for $h_0 \in H$, 
    \begin{align*}
        (\lambda_\ell^{G}(h_0,e_K)\xi)(h,k) &=\xi((h_0,e_K)^{-1}(h,k)) \\
        &=\xi((h_0^{-1},e_K)(h,k)) \\
        &=\xi(h_0^{-1}h,k).
    \end{align*}
    Also, for $k_0\in K$, let $\sigma(k_0^{-1})^{-1}=h'\sigma(k_0) \in G$, then
    \begin{align*}
        (\lambda_\ell^{G}(h',k_0)\xi)(h,k)
        &= \xi((h',k_0)^{-1}(h,k)) \\
        &= \xi(((\alpha_{k_0}^K)^{-1}(h'^{-1}c^K(k_0,k_0^{-1})^{-1}),k_0^{-1})(h,k)) \\
        &= \xi((\alpha^K_{k_0})^{-1}(h'^{-1}c^K(k_0,k_0^{-1})^{-1})\alpha^K_{k_0^{-1}}(h)c^K(k_0^{-1},k),k_0^{-1}k)
    \end{align*}
    Furthermore, 
    \begin{align*}
        \beta_{k^{-1}k_0}^{-1}(c(k^{-1},k_0)^{-1}\beta_{k^{-1}}(h))
        &=\sigma(k_0^{-1}k)c(k^{-1},k_0)^{-1}\beta_{k^{-1}}(h)\sigma(k_0^{-1}k)^{-1} \\
        &= \sigma(k_0^{-1}k)\sigma(k_0^{-1}k)^{-1}\sigma(k_0^{-1})\sigma(k)\sigma(k)^{-1}h\sigma(k)\sigma(k_0^{-1}k)^{-1} \\
        &=\sigma(k_0^{-1})h\sigma(k)\sigma(k_0^{-1}k)^{-1},
    \end{align*}
    \begin{multline*}
         (\alpha^K_{k_0})^{-1}(h'^{-1}c^K(k_0,k_0^{-1})^{-1})\alpha^K_{k_0^{-1}}(h)c^K(k_0^{-1},k) \\
        = \sigma(k_0)^{-1}h'^{-1}c^K(k_0,k_0^{-1})^{-1}\sigma(k_0)\sigma(k_0^{-1})h\sigma(k_0^{-1})^{-1}\sigma(k_0^{-1})\sigma(k)\sigma(k_0^{-1}k)^{-1} \\=\sigma(k_0^{-1})\sigma(k_0^{-1})^{-1}\sigma(k_0)^{-1}\sigma(k_0)\sigma(k_0^{-1})h\sigma(k)\sigma(k_0^{-1}k)^{-1} =\sigma(k_0^{-1})h\sigma(k)\sigma(k_0^{-1}k)^{-1}.
    \end{multline*}
    Therefore, we conclude that 
    \begin{align*}
        \begin{cases}
            (U(I_\ell^{\alpha}(\lambda_\ell^H(h_0))U^*\xi)(h,k)=(\lambda_\ell^{G}(h_0,e_K)\xi)(h,k),\\
            (U\lambda_\ell^u(k_0)U^*\xi)(h,k)=\delta(k_0)^{1/2}(\lambda_\ell^{G}(\sigma(k_0^{-1})^{-1}\sigma(k_0)^{-1},k_0)\xi)(h,k)
        \end{cases}
    \end{align*}
    for all $h,h_0\in H, k,k_0\in K$. Therefore, we conclude that $$U(L(H)\rtimes_{\alpha,u}^\ell K)U^*=L(H\rtimes_{\alpha^K,c^K} K)\cong L(G).$$    
\end{proof}

For a tdlc group $G$, since $G_1=\text{ker}\Delta_G$ is an open normal subgroup of $G$ which is unimodular, we obtain $G/G_1 \cong \Delta_G(G)$ as topological groups, where $\Delta_G(G)$ is equipped with discrete topology. Therefore, we obtain the following corollary.

\begin{corollary}
    For a tdlc group $G$, there is a cocycle action $(\alpha,u)\colon \Delta_G(G) \curvearrowright L(G_1)$ such that $$L(G) \cong L(G_1)\rtimes_{\alpha,u}^\ell\Delta_G(G).$$ 
\end{corollary}

\begin{remark}\label{remark2}
    To apply the above corollary, it suffices to assume that $G_1$ is open. Although this fact is used in \cite[Example 3.8, Theorem 5.1]{guinto2025unimodulargroups}, we need a slight modification to the construction of the cocycle action. We denote $\Delta_G(G)=K$. In \cite[Example 3.8, Theorem 5.1]{guinto2025unimodulargroups}, the twisted crossed product decomposition of $G$ is obtained by above $(\alpha^K,c^K)$. But, the group operation is different from Definition \ref{twistcrossprodgrp}. Also, the twisted crossed product decomposition of $L(G)$ is given by $\check{\alpha}_{k_1}(\lambda_\ell^{G_1}(s))=\lambda_\ell^{G_1}(\alpha^K_{k_1}(s)), \check{c}(k_1,k_2)=\lambda_\ell^{G_1}(c^K(k_1,k_2))\,\,(s\in G_1, k_1,k_2 \in K)$ in \cite{guinto2025unimodulargroups}.
    However, in Proposition \ref{cocycleresol}, we have to construct two cocycle actions of $K$ on $G_1$. It can be observed in the proof that $(\alpha^K,c^K)$ is used for the topological group decomposition $G \cong G_1 \rtimes_{\alpha^K,c^K}K$ and $(\alpha,u)$ is used for the von Neumann algebra decomposition $L(G) \cong L(G_1)\rtimes _{\alpha,u}^\ell K$.
\end{remark}


Since $\Delta_G(G) \le \R^*$ is an abelian group, we can apply Theorem \ref{twistConnesfactority}. In fact, central ergodicity of the cocycle action is equivalent to the factoriality of $L(G)$. We shall show it. \par 
In \cite[Theorem 2.1]{guinto2025unimodulargroups}, it was shown that $\varphi_G$ is an almost periodic weight if $G$ is a tdlc group (it suffices to assume that $G_1$ is open, that is, $G$ is an almost unimodular group defined in \cite[Definition 2.2]{guinto2025unimodulargroups}). Therefore, fix a tdlc group $G$, then there exists a continuous action $\tilde{\sigma}\colon \widehat{\Delta_G(G)} \curvearrowright L(G)$ called the point modular extension of $\sigma^{\varphi_G}\colon \R \curvearrowright L(G)$ (see \cite[Proposition 1.1]{Connes1974},\cite[Section 1.3]{Dykema1995} and \cite[Section 1.4]{GuintoNelson2024}). Here, $\text{Aut}(L(G))$ is equipped with the u-topology.  Let $\iota\colon \Delta_G(G) \to \R_+$ be the inclusion map. We obtain a continuous group homomorphism which is the transpose of the inclusion map $\hat{\iota}\colon \R \to \widehat{\Delta_G(G)}$ defined by dual pairings as 
$$\nai{k}{\hat{\iota}(t)}=\nai{\iota(k)}{t}=k^{it}\,\,(k\in \Delta_G(G),t\in\R).$$
Here, we identify $\R \cong \hat{\R}_+$. Injectivity of inclusion implies the density of $\hat{\iota}(\R)$ in $\widehat{\Delta_G(G)}$. In this setting, $\tilde{\sigma}_{\hat{\iota}(t)}=\sigma^{\varphi_G}_t\,\,(t\in \R)$ holds. We have the following proposition.

\begin{proposition}\label{fullspectrum}
    For a tdlc group $G$, let $(\alpha,u)\colon \Delta_G(G) \curvearrowright L(G_1)$ be the cocycle action obtained by Proposition \ref{cocycleresol}, then $\Gamma(\alpha,u)=\widehat{\Delta_G(G)}$ holds.
\end{proposition}
\begin{proof}
    We denote $K=\Delta_G(G)$. We identify $G \cong G_1 \rtimes_{\alpha^K,c^K} K$. Let $U$ be the unitary defined in the proof of Proposition \ref{cocycleresol} and $\Phi\colon L(G_1)\rtimes_{\alpha,u}^\ell K \to L(G_1 \rtimes_{\alpha^K,c^K} K)$ be the isomorphism defined by the adjoint of $U$. We calculate $\Phi\circ\hat{\alpha}\circ\Phi^{-1}$. Fix $p \in \hat{K}$. For $s\in G_1$, 
    \begin{align*}
        \Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(\lambda^G_\ell(s,1))&=\Phi\circ\hat{\alpha}_p(I_\ell^\alpha(\lambda_\ell^{G_1}(s))) =\Phi(I_\ell^\alpha(\lambda_\ell^{G_1}(s)))=\lambda^G_\ell(s,1).
    \end{align*}
    Also, for $k\in K$, let $(s_0,k)\in G_1 \rtimes_{\alpha^K,c^K} K$ be the element which satisfies $\sigma(k^{-1})^{-1}=s_0\sigma(k) \in G$, then 
    \begin{align*}
        \Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(\lambda^G_\ell(s_0,k))&=\Phi\circ\hat{\alpha}_p(\delta(k)^{-1/2}\lambda_\ell^u(k))\\&=\Phi(\delta(k)^{-1/2}\overline{\nai{k}{p}}\lambda_\ell^u(k))
        = \overline{\nai{k}{p}}\lambda^G_\ell(s_0,k).
    \end{align*}
    Now, for each $(s,k)\in G_1 \rtimes_{\alpha^K,c^K} K$, there exists $s_0 \in G_1$ which satisfies $\sigma(k^{-1})^{-1}=s_0\sigma(k) \in G$ and $(s,k)=(ss_0^{-1},1)(s_0,k)$. Therefore, 
    \begin{align*}
        \Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(\lambda^G_\ell(s,k)) &= \Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(\lambda^G_\ell(ss_0^{-1},1))\cdot\Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(\lambda^G_\ell(s_0,k))
        \\&= \lambda^G_\ell(ss_0^{-1},1)\cdot \overline{\nai{k}{p}}\lambda^G_\ell(s_0,k)
        \\&= \overline{\nai{k}{p}}\lambda^G_\ell(ss_0^{-1},1)\lambda^G_\ell(s_0,k)
        \\&= \overline{\nai{k}{p}} \lambda_\ell^{G}(s,k).
    \end{align*}
    It follows that $\Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(\lambda^G_\ell(s,k))=\overline{\nai{k}{p}} \lambda_\ell^{G}(s,k)$ for all $p\in \hat{K},s\in G_1, k\in K$. Next, we calculate $\tilde{\sigma}$. Note that $\Delta_G(s\sigma(k))=k$, whence $\Delta_{G}(s,k)=k$. For $(s,k)\in G_1 \rtimes_{\alpha^K,c^K} K$, we have
    \begin{align*}
        \tilde{\sigma}_{\hat{\iota}(t)}(\lambda_\ell^G(s,k))&=\sigma^{\varphi_G}_t(\lambda_\ell^G(s,k))=\Delta_G((s,k))^{it}\lambda_\ell^G(s,k)\\&=k^{it}\lambda_\ell^G(s,k)=\nai{\iota(k)}{t}\lambda_\ell^G(s,k)=\nai{k}{\hat{\iota}(t)}\lambda_\ell^G(s,k)\,\,(t\in\R).
    \end{align*}
    Hence, density of $\hat{\iota}(\R) \subseteq \hat{K}$ and continuity $\hat{K} \ni p \mapsto \tilde{\sigma}_p \in \text{Aut}(L(G))$ implies 
    $$\tilde{\sigma}_p(\lambda_\ell^G(s,k))=\nai{k}{p}\lambda_\ell^G(s,k),$$
    for all $p\in \hat{K},s\in G_1, k\in K$. Therefore, we obtain $$\Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(\lambda^G_\ell(g))=\tilde{\sigma}_{-p}(\lambda_\ell^G(g)),$$
    for all $p\in \hat{K},g\in G$. It follows that $$\Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(x)=\tilde{\sigma}_{-p}(x),$$
    for all $p\in \hat{K}, x\in L(G)$. Take $x\in Z(L(G))$, since $Z(L(G)) \subseteq L(G)^{\varphi_G}$, we have 
    $$\tilde{\sigma}_{\hat{\iota}(t)}(x)=\sigma_t^{\varphi_G}(x)=x\,\, (t\in \R).$$
    Thus, $\tilde{\sigma}_p(x)=x$ for all $p\in \hat{K}$ holds. We conclude that $\Phi\circ\hat{\alpha}_p\circ\Phi^{-1}(x)=x$ for all $x\in Z(L(G)),p\in\hat{K}$. Since $\Phi^{-1}(Z(L(G)))=Z(L(G_1)\rtimes_{\alpha,u}^\ell K)$, it follows that $\hat{\alpha}_p(x)=x$ for all $p \in \hat{K}, x\in Z(L(G_1)\rtimes_{\alpha,u}^\ell K)$. That is, $\Gamma(\alpha,u)=\hat{K}$ holds.
\end{proof}

Combining Theorem \ref{twistConnesfactority} and Proposition \ref{fullspectrum}, the following theorem holds.

\begin{theorem}\label{tdlcfactority}
    For a tdlc group $G$, let $(\alpha,u)\colon \Delta_G(G) \curvearrowright L(G_1)$ be the cocycle action obtained by Proposition \ref{cocycleresol}, then the following two conditions are equivalent.
    \begin{enumerate}
        \item[(i)] $(\alpha,u)\colon \Delta_G(G) \curvearrowright L(G_1)$ is centrally ergodic.
        \item[(ii)] $L(G)$ is a factor.
    \end{enumerate}  
\end{theorem}

\begin{remark}
    If $G$ is unimodular, then Theorem \ref{tdlcfactority} is a trivial result because $\Delta_G(G)=\{1\}$ and hence $(\alpha,u)$ becomes a trivial action. Also, in non-unimodular case, if $L(G_1)$ is a factor, then $L(G)$ is a factor because $L(G_1) \cong L(G)^{\varphi_G}$. In this case, the cocycle action $(\alpha,u)\colon \Delta_G(G) \curvearrowright L(G_1)$ must be centrally ergodic.
\end{remark}

 Theorem \ref{tdlcfactority} is still useful when $L(G_1)$ is not a factor because there exists a tdlc group $G$ which satisfies that $L(G)$ is a factor and $L(G_1)$ is not a factor. For example, let $\Q_p$ be a $p$-adic numbers as an additive group, also $\Q_p^*$ be a multiplicative group. Then $G=\Q_p \rtimes \Q_p^*$ is a desired one. It is well known that $L(G)$ is a $\rm{I}_\infty$ factor (see \cite[Section 3]{Blackadar1977}). In this case, $G_1=\Q_p \rtimes \Z_p^*=\{(a,b)\in G:|b|_p=1\}$ and it follows that  $\int_{\Z_p}\lambda^{G_1}(a,1)\,d\mu_{\Q_p}(a)\in L(G_1)$ is a non-trivial central element (see, e.g.  \cite[Example 5.3 (1)]{guinto2025unimodulargroups}). Thus, there is a centrally ergodic cocycle action even if $L(G_1)$ is not a factor. 
In fact, we can directly verify that $(\alpha,u)\colon \Delta_G(G) \curvearrowright L(G_1)$ is centrally ergodic when $G=\Q_p \rtimes \Q_p^*,G_1=\Q_p \rtimes \Z_p^*$.

\begin{example}\label{afineex}
    Let $G=\Q_p \rtimes \Q_p^*,G_1=\text{ker}\Delta_G=\Q_p \rtimes \Z_p^*$. Since $\Delta_G(a,b)=|b|_p^{-1}$, we can take $\sigma \colon \Delta_G(G) \to G$ as a homomorphism $p^n \mapsto (0,p^{-n})$. In this case, the cocycle action $(\alpha,u)$ is an action $\alpha$ given by $$\alpha_{p^n}(\lambda(a,b))=\lambda(p^{-n}a,b)\,\,(n\in \Z).$$ Here, $\Q_p \rtimes \Z_p^*$ is obtained by the action $\gamma\colon \Z_p^* \curvearrowright \Q_p$ defined by $\gamma_s(x)=sx\,\,(s\in\Z_p^*, x\in\Q_p)$. It follows that $$L(\Q_p \rtimes \Z_p^*) \cong L(\Q_p) \rtimes_{\overline{\gamma}}\Z_p^*\cong L^\infty(\hat{\Q}_p)\rtimes_{\tilde{\gamma}}\Z_p^* \cong L^\infty(\Q_p) \rtimes_{\dot{\gamma}}\Z_p^*,$$
    where $\dot{\gamma}\colon \Z_p^* \curvearrowright L^\infty(\Q_p)$ is induced by the isomorphism $\Phi\colon L(\Q_p) \to L^\infty(\Q_p)$. We can check that $\dot{\gamma}_s=\beta_{s^{-1}}$ where $\beta\colon \Z_p^*\curvearrowright L^\infty(\Q_p)$ is obtained by $\gamma\colon \Z_p^* \curvearrowright \Q_p$ as a group measure space construction. That is, 
    $$(\dot{\gamma}_s(m(f))\xi)(x)=f(sx)\xi(x)\,\,(f\in L^\infty(\Q_p),\xi\in L^2(\Q_p),s\in \Z_p^*,x\in\Q_p).$$ Put $\Psi\colon L(\Q_p \rtimes \Z_p^*) \to L^\infty(\Q_p) \rtimes_{\dot{\gamma}}\Z_p^*$ be the isomorphism. By calculation, we have $\Psi(\lambda_\ell^{G_1}(x,1))=\pi_{\dot{\gamma}}(m(\theta(-x)))$ where $\theta\colon \Q_p\to\hat{\Q}_p$ is an isomorphism between topological groups. Hence, for $x\in \Q_p$, 
    $$\Psi\circ\alpha_{p^n}\circ\Psi^{-1}(\pi_{\dot{\gamma}}(m(\theta(x))))=\pi_{\dot{\gamma}}(m(\theta(p^{-n}x))).$$
    Note that $\nai{y}{\theta(x)}=\nai{xy}{\theta(1)}$ for all $y\in \Q_p$, we see that $\theta(p^{-n}x)=\theta(x)_{p^{-n}}$ where $\theta(x)_{p^{-n}}(y)=\theta(x)(p^{-n}y)$. By Lemma \ref{dualgrpdensity}, we conclude that 
    $$\Psi\circ\alpha_{p^n}\circ\Psi^{-1}(\pi_{\dot{\gamma}}(m(f)))=\pi_{\dot{\gamma}}(m(f_{p^{-n}}))$$ for all $f\in L^\infty(\Q
    _p)$. Since $\dot{\gamma}$ is a free action in the sense of \cite[Definition 2.1]{Sauvageot1977}, we also see that $Z(L^\infty(\Q_p) \rtimes_{\dot{\gamma}}\Z_p^*)=\pi_{\dot{\gamma}}(m(L^\infty(\Q_p))^{\dot{\gamma}})$ by \cite[Corollary 2.2]{Sauvageot1977}. Thus,
    \begin{align*}
        \Psi(Z(L(\Q_p \rtimes \Z_p^*))^{\alpha})=Z(L^\infty(\Q_p) \rtimes_{\dot{\gamma}}\Z_p^*)^{\Psi\circ\alpha\circ\Psi^{-1}} = \pi_{\dot{\gamma}}(m(L^\infty(\Q_p))^{\dot{\gamma}})^{\Psi\circ\alpha\circ\Psi^{-1}}.
    \end{align*}
    Take $f\in L^\infty(\Q_p)$ such that $\pi_{\dot{\gamma}}(m(f))$ is in the right hand side of the above equation. Then, $f$ satisfies $$f(sx)=f(x)\,\,(s\in \Z_p^*),\quad f(p^{n}x)=f(x)\,\,(n\in \Z)$$
    for all $x\in \Q_p$. Since for each $x\in \Q_p$ can be factorized as $x=p^ns$ where $n\in\Z,s\in \Z_p^*$, we conclude that $f(x)=f(1)$ for all $x\in \Q_p$. That is, $f=c\cdot1_{\Q_p}$ for some constant $c \in \C$. Therefore, $Z(L(\Q_p \rtimes \Z_p^*))^{\alpha}=\Psi^{-1}(\C)=\C$ holds. That is, the action is centrally ergodic. 
\end{example}

In this case, $L(G)$ admits a crossed product decomposition because of the construction of $G$, that is, $L(G)=L(\Q_p \rtimes \Q_p^*) \cong L(\Q_p) \rtimes \Q_p^*$ (see, e.g. \cite[Proposition 2.2]{Sutherland1978}). But, we use another decomposition $L(G) \cong L(G_1) \rtimes \Delta_G(G)$ in Example \ref{afineex}. Thus, our theorem also covers groups which do not admit genuine crossed product decompositions. 

