	\simplifcationlemma*

	\begin{proof}
		Given a mechanism $(V_g,V_b,M,P)$, we will construct another mechanism $(\tilde{V}_b,\tilde{V}_b,\tilde{M},P)$ with the desired properties stated above.

		First, we define $\tilde{M}(\theta)=\theta$. If $\Lambda(M(\theta))=0$, we define $$\tilde{V}_b(\theta)=V_b(\theta)$$ Conversely, if $\Lambda(M(\theta))>0$, we define
		\begin{equation}\label{eq:V'}
			\tilde{V}_b(\theta)=\frac{1-\Lambda(M(\theta))}{\Lambda(M(\theta))}V_g(\theta)\
		\end{equation}

		Let $\tilde{\Lambda}$ be the quality associated with mechanism $(V_g,\tilde{V}_b,\tilde{M},P)$. Observe that, by construction, 
		\begin{equation}\label{eq:mu'}
			\tilde{\Lambda}(\tilde{M}(\theta))=\Lambda(M(\theta))\qquad \text{ for all $\theta\in\Theta$.}
		\end{equation}

		so
		$$\theta A(\tilde{\Lambda}(\tilde{M}(\theta')))V_g(\theta') - P(\theta')=\theta A(\Lambda(M(\theta')))V_g(\theta') - P(\theta') \qquad \text{ for all } \theta,\theta' \in \Theta.$$
		In words, good providers of all values have the same payoff as the original mechanism (whether they report truthfully or misreport) and consequently $(V_g,\tilde{V}_b,\tilde{M},P)$ is incentive compatible and individually rational because the original mechanism $(V_g,V_b,M,P)$ is both.

		Take an $m$ in the image of $M$. If $\Lambda(m)=0$, then 
		$$\bbE[V_b(\theta)|M(\theta)=m]=\bbE[\tilde{V}_b(\theta)|M(\theta)=m]$$
		since $V_b$ and $\tilde{V}_b$ are defined to be equal for such $\theta$. When $\Lambda(m)>0$, \eqref{eq:V'} and \eqref{eq:mu'} together imply that
		\begin{align*}
			\bbE[V_b(\theta)|M(\theta)=m]  =\frac{1-\Lambda(m)}{\Lambda(m)}\bbE[V_g(\theta)|M(\theta)=m] & =\bbE\left[\frac{1-\tilde{\Lambda}(\tilde{M}(\theta))}{\tilde{\Lambda}(\tilde{M}(\theta))}V_g(\theta)\bigg|M(\theta)=m\right]\\
			& = \bbE[\tilde{V}_b(\theta)|M(\theta)=m].
		\end{align*}

		Consequently,
		$$\int_{\Theta} \left[ A(\Lambda(M(\theta)))V_b(\theta) - \gamma V_b(\theta) \right]f(\theta)d\theta=\int_{\Theta} \left[ A(\tilde{\Lambda}(\tilde{M}(\theta)))\tilde{V}_b(\theta) - \gamma \tilde{V}_b(\theta) \right]f(\theta)d\theta$$
		and so the platform makes the identical profit from $(V_g,V_b,M,P)$ and $(V_g,\tilde{V}_b,\tilde{M},P)$ as required.
	\end{proof}

	\singleone*

	\begin{proof}
		Since $\phi(\overline{\theta})=\overline{\theta}> \gamma$, observe that the optimal number of views $V^{s,1}_g(\theta)=c'^{-1}\left(\max\{\phi(\theta)-\gamma,0\}\right)$ for $\lambda=1$ is such that
		$$\int_0^{\overline{\theta}}  \left[ \left(\phi(\theta)-\gamma\right)V^{s,1}_g(\theta) - c(V^{s,1}_g(\theta)) \right]  f(\theta) d\theta>0.$$
