		Therefore, for any $\gamma'>\gamma$, we must have
		\begin{align*}
			& \gamma'\left(\frac{1}{\lambda}-\frac{1}{\Lambda^*_{\gamma}(\theta)} \right) > \left(\phi(\theta)+\frac{1-\lambda}{\lambda}\right)A(\lambda) - \left(\phi(\theta)+\frac{1-\Lambda^*_{\gamma}(\theta)}{\Lambda^*_{\gamma}(\theta)}\right)A(\Lambda^*_{\gamma}(\theta)) \\
			\iff & \left(\phi(\theta)+\frac{1-\Lambda^*_{\gamma}(\theta)}{\Lambda^*_{\gamma}(\theta)}\right)A(\Lambda^*_{\gamma}(\theta))-\frac{\gamma'}{\Lambda^*_{\gamma}(\theta)} > \left(\phi(\theta)+\frac{1-\lambda}{\lambda}\right)A(\lambda)-\frac{\gamma'}{\lambda}
		\end{align*}
		for all $\lambda\in(0,\Lambda^*_{\gamma}(\theta))$. Therefore, we must have $\Lambda^*_{\gamma'}(\theta)\geq \Lambda^*_{\gamma}(\theta)$ as required.
	\end{proof}

	\compstaticskappa*
	\begin{proof}
		The first statement follows immediately from Proposition \ref{prop:opt_mech} since the cost $\kappa c(\cdot)$ does not enter the expression for $\Lambda^*$.

		From Proposition \ref{prop:opt_mech}, $V^*_g(\theta)$ solves
		$$V^*_g(\theta)=c^{-1}\left(\frac{1}{\kappa}\max\left\{\left[\phi(\theta)+\frac{1-\Lambda^*(\theta)}{\Lambda^*(\theta)}\right]A(\Lambda^*(\theta))-\frac{\gamma}{\Lambda^*(\theta)},0\right\}\right).$$
		The second and third statements follow immediately from this equation and properties of $c$. Note that $V^*_g(\theta)>0$ whenever the right hand side of the above equation is greater than 0 and the sign of right hand side does not depend on $\kappa$. Clearly the term in the round brackets is nonincreasing in $\kappa$ so  $V^*_g(\theta)$ must be nonincreasing in $\kappa$.
	\end{proof}

	\renewcommand{\theproposition}{\Alph{section}.1}

	The remaining comparative statics use the following result.

	\mattnote[inline]{The proof seems to only require the final condition when $\lambda<1$, i.e. the interior part.}

	\begin{proposition}\label{prop:1proof}
		Consider a family of attention functions $A(\hat{\lambda};\hat{\alpha})$ parametrized by some $\hat{\alpha}\in (\underline{\alpha},\overline{\alpha})\subset \mathbb{R}_+$ and denote the optimal mechanism for a given $\hat{\alpha}$ as $(V^*_{g,\hat{\alpha}},\Lambda^*_{\hat{\alpha}})$. Assume that $A(\hat{\lambda};\hat{\alpha})$ is (i) twice continuously differentiable, (ii) strictly decreasing in $\hat{\alpha}$ and that (iii) $\frac{1}{A(\hat{\lambda};\hat{\alpha})}\frac{\partial A(\hat{\lambda};\hat{\alpha})}{\partial \hat{\alpha}}$ is strictly increasing in $\hat{\lambda}$ whenever $\hat \lambda<1$. 

		Then for every $\theta\in\Theta$ and every $\alpha,\alpha'\in (\underline{\alpha},\overline{\alpha})$ with $\alpha'<\alpha$  and $V^*_{g,\alpha}(\theta)>0$, we have $V^*_{g,\alpha'}(\theta)>0$ and $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$.
	\end{proposition}

	\begin{proof}
		Recall that $\Lambda^*_{\alpha}(\theta)$ is defined to be the greatest $\lambda$ that maximizes of $R_{\alpha}(\theta,\lambda)$ (like the mechanism, this notation makes the dependence on $\alpha$ explicit). Since $R_{\alpha}(\theta,\lambda)$ is continuous in $\lambda$ and in $\alpha$ (by assumption), the set of $\lambda$s that  maximize $R_{\alpha}(\theta,\lambda)$ is an upper semi-continuous correspondence in $\alpha$ for each $\theta\in\Theta$. Thus, $\Lambda^*_{\alpha}(\theta)$ is an upper semi-continuous function in $\alpha$ because it is the maximum of an upper semi-continuous correspondence.

		In the proof, we employ the shorthand notation
		\begin{equation}\label{eq:g_function}
			g(\hat{\alpha},\hat{\lambda}):=\left(\phi(\theta)+\frac{1-\hat{\lambda}}{\hat{\lambda}}\right)A(\hat{\lambda};\hat{\alpha}).
		\end{equation}
		Observe that
		$$\frac{\partial g(\hat{\alpha},\hat{\lambda})}{\partial \hat{\alpha}}=\frac{g(\hat{\alpha},\hat{\lambda})}{A(\hat{\lambda};\hat{\alpha})}\frac{\partial A(\hat{\lambda};\hat{\alpha})}{\partial \hat{\alpha}}.$$

		Consider a $\theta$ and an $\alpha$ such that $V^*_{g,\alpha}(\theta)>0$. For all $\alpha'<\alpha$, we have
		$$0<g(\alpha,\Lambda^*_{\alpha}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha}(\theta)}\leq g(\alpha',\Lambda^*_{\alpha}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha}(\theta)}\leq \max_{\lambda\in[0,1]} \left\{g(\alpha',\lambda)-\frac{\gamma}{\lambda}\right\}=g(\alpha',\Lambda^*_{\alpha'}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}$$
		where the first inequality follows from the fact that $V^*_{g,\alpha}(\theta)>0$ and the second inequality from the fact that $g(\hat{\alpha},\hat{\lambda})$ is decreasing in $\hat{\alpha}$. Therefore, $V^*_{g,\alpha'}(\theta)>0$.

		Once again, consider a $\theta$ and an $\alpha$ such that $V^*_{g,\alpha}(\theta)>0$. We will argue that, there exists an $\varepsilon>0$ such that $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha-\varepsilon,\alpha)$ and $\Lambda^*_{\alpha}(\theta)\leq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha,\alpha+\varepsilon)$. This suffices to establish that $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$ for all $\alpha' < \alpha$ (because $V^*_{g,\hat{\alpha}}(\theta)>0$ for all $\hat{\alpha}\in[\alpha',\alpha]$) and therefore the result.

%		Consider $\theta$ and an $\alpha$ such that $V^*_{g,\alpha}(\theta)>0$. We will argue that, there exists an $\varepsilon>0$ such that $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha-\varepsilon,\alpha)$ and $\Lambda^*_{\alpha}(\theta)\leq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha,\alpha+\varepsilon)$. This suffices to establish that $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$ for all $\alpha > \alpha'$. Moreover, since $g(\hat{\alpha},\hat{\lambda})$ is decreasing in $\hat{\alpha}$, we have
%		$$g(\alpha,\Lambda^*_{\alpha}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha}(\theta)}\leq g(\alpha',\Lambda^*_{\alpha}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha}(\theta)}\leq g(\alpha',\Lambda^*_{\alpha'}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}$$
%		for $\alpha'<\alpha$. $V^*_{g,\alpha}(\theta)>0$ implies that the leftmost term is positive; the above inequality in turn implies the rightmost term is also positive and therefore $V^*_{g,\alpha'}(\theta)>0$.

		The proof proceeds in two steps each of which has two sub-cases.

		\noindent \textit{Step 1:} We first argue that there exists an $\varepsilon>0$ such that $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha-\varepsilon,\alpha)$. Obviously, this is true if $\Lambda^*_{\alpha}(\theta)=1$ so we only need to consider the case $\Lambda^*_{\alpha}(\theta)<1$. 

		We define the sequence
		$$\lambda_n=\sup\left\{\Lambda^*_{\alpha'}(\theta)\; \bigg|\; \alpha\left(1-\frac1n\right)\le \alpha'\le \alpha\right\}$$
		for $n=\underline{n},\underline{n}+1,\dots$ where $\underline{n}>\frac{\alpha}{\alpha-\underline{\alpha}}$ is chosen to be sufficiently large so that $\alpha\left(1-\frac1n\right)>\underline{\alpha}$. Observe that this sequence is nonincreasing and bounded so it has a limit. Observe also that, by definition,  $\lambda_n\geq \Lambda^*_{\alpha}(\theta)$ for all $n$ since the supremum is taken to include $\alpha$.

		We split the argument into the two possible cases.

		\noindent Case 1.1: $\lim_{n\to\infty} \lambda_n > \Lambda^*_{\alpha}(\theta)$.

		Take a quality value $\tilde{\lambda}$ satisfying $\Lambda^*_{\alpha}(\theta)<\tilde{\lambda}<\lim_{n\to\infty} \lambda_n$. For every $\varepsilon\in(0,1)$, there exists an $n>\frac{\alpha}{\varepsilon}$ such that $\lambda_n>\hat{\lambda}$. From the definition of $\lambda_n$, this implies that there exists an $\alpha'\in \left[\alpha\left(1-\frac1n\right),\alpha\right]\subseteq (\alpha-\varepsilon,\alpha]$ such that $\Lambda_{\alpha'}>\tilde{\lambda}$. This violates the upper semi-continuity of the optimal quality $\Lambda^*_{\alpha}(\theta)$ at $\alpha$. Thus, this case cannot arise.

		\noindent Case 1.2: $\lim_{n\to\infty} \lambda_n = \Lambda^*_{\alpha}(\theta)$.

		If there exists an $n$ such that $\lambda_n = \Lambda^*_{\alpha}(\theta)$, then, for any $0<\varepsilon<\frac{\alpha}{n}$ we have $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha-\varepsilon,\alpha)$ as required. Thus, for the remainder of the argument of this case, we assume that $\lambda_n>\Lambda^*_{\alpha}$ for all $n$.

		Take an $n\ge \underline{n}$ for which $\lambda_n<1$ and note that such an $n$ exists because $\lim_{n\to\infty} \lambda_n = \Lambda^*_{\alpha}(\theta)<1$. The cross partial at $(\alpha,\Lambda^*_{\alpha}(\theta))$ satisfies
		\begin{align*}
			\frac{\partial^2 g(\alpha,\Lambda^*_{\alpha}(\theta))}{\partial \hat{\lambda} \partial \hat{\alpha}} =&  g(\alpha,\Lambda^*_{\alpha}(\theta)) \frac{\partial}{\partial \hat{\lambda}}\left(\frac{1}{A(\Lambda^*_{\alpha}(\theta);\alpha)}\frac{\partial A(\Lambda^*_{\alpha}(\theta);\alpha)}{\partial \hat{\alpha}}\right) \\& + \frac{\partial g(\alpha,\Lambda^*_{\alpha}(\theta))}{\partial \hat{\lambda}} \left(\frac{1}{A(\Lambda^*_{\alpha}(\theta);\alpha)}\frac{\partial A(\Lambda^*_{\alpha}(\theta);\alpha)}{\partial \hat{\alpha}}\right) >0.
		\end{align*}
		The inequality follows from the facts that (i) $\frac{1}{A(\hat{\lambda};\hat{\alpha})}\frac{\partial A(\hat{\lambda};\hat{\alpha})}{\partial \hat{\alpha}}$ is strictly negative and increasing in $\hat{\lambda}$ (by assumption), (ii) $g(\alpha,\Lambda^*_{\alpha}(\theta))>0$ because $V^*_{g,\alpha}(\theta)>0$ and (iii) $\frac{\partial g(\alpha,\Lambda^*_{\alpha}(\theta))}{\partial \hat{\lambda}}<0$ because $\Lambda^*_{\alpha}(\theta)<1$ (as $\lambda_n<1$) and therefore satisfies the first-order condition
		$$ \frac{\partial g(\alpha,\Lambda^*_{\alpha}(\theta)) }{\partial \hat{\lambda}} + \frac{\gamma}{\Lambda^*_{\alpha}(\theta)^2}=0.$$ 
		Consequently, because the cross partial is continuous (by assumption), there exists an $\varepsilon>0$ such that for all $(\alpha'',\lambda'')$ in an $\varepsilon$-ball $||(\alpha'',\lambda'')-(\alpha,\Lambda^*_{\alpha}(\theta))||<\varepsilon$ around $(\alpha,\Lambda^*_{\alpha}(\theta))$, the cross-partial also satisfies $\frac{\partial^2 g(\alpha'',\lambda'')}{\partial \hat{\lambda} \partial \hat{\alpha}}>0$.

		Now take an $\alpha'<\alpha$ such that $||(\alpha',\Lambda^*_{\alpha'}(\theta))-(\alpha,\Lambda^*_{\alpha}(\theta))||<\varepsilon$ and $\Lambda^*_{\alpha'}(\theta)>\Lambda^*_{\alpha}(\theta)$. Such an $\alpha'$ exists because $\lim_{n\to\infty} \lambda_n = \Lambda^*_{\alpha}$ and $\lambda_n > \Lambda^*_{\alpha}$ for all $n$. For this $\alpha'$, the optimality of $\Lambda^*_{\alpha'}(\theta)$ implies that
		\begin{align*}
			& g(\alpha',\Lambda^*_{\alpha'}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} \ge g(\alpha',\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \\
			\implies & g(\alpha',\Lambda^*_{\alpha'}(\theta))+ \int^{\alpha}_{\alpha'}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} \ge  g(\alpha',\Lambda^*_{\alpha}(\theta))  + \int^{\alpha}_{\alpha'}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha}- \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \\
			\implies & g(\alpha',\Lambda^*_{\alpha'}(\theta))+ \int^{\alpha}_{\alpha'}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}> g(\alpha',\Lambda^*_{\alpha}(\theta)) + \int^{\alpha}_{\alpha'}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \\
			\implies & g(\alpha,\Lambda^*_{\alpha'}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} > g(\alpha,\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)}.
		\end{align*}
		The third inequality is a consequence of the fact that $\frac{\partial g(\alpha'',\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}}>\frac{\partial g(\alpha'',\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}}$ for all $\alpha''\in[\alpha',\alpha]$ because $\frac{\partial^2 g(\alpha'',\lambda'')}{\partial \hat{\lambda} \partial \hat{\alpha}}>0$ for all $\alpha''\in[\alpha',\alpha]$ and $\lambda''\in [\Lambda^*_{\alpha}(\theta),\Lambda^*_{\alpha'}(\theta)]$ since these values of $(\alpha'',\lambda'')$ lie in the $\varepsilon$-ball around $(\alpha,\Lambda^*_{\alpha}(\theta))$.

		This contradicts $\Lambda^*_{\alpha}(\theta)$ being optimal at $\alpha$ and therefore it is not possible to have $\lambda_n>\Lambda^*_{\alpha}(\theta)$ for all $n$. Taken together, we have thus shown that there is an $\varepsilon>0$ such that $\Lambda^*_{\alpha}(\theta)\geq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha-\varepsilon,\alpha)$.

		\noindent \textit{Step 2:} We now argue that, there exists an $\varepsilon>0$ such that $\Lambda^*_{\alpha}(\theta)\leq \Lambda^*_{\alpha'}(\theta)$ for $\alpha'\in(\alpha,\alpha+\varepsilon)$. To do so, we employ a similar argument to the first step for the case where the optimum varies continuously, but the case where the function jumps at $\alpha$ requires an additional argument.

		First suppose $\Lambda^*_{\alpha}(\theta)=1$. By the optimality of $\Lambda^*_{\alpha}(\theta)=1$ for $\alpha$, we have
		$$g(\alpha,\Lambda^*_{\alpha}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha}(\theta)}=\phi(\theta)-\gamma\geq g(\alpha,\Lambda^*_{\alpha'}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}$$
		for all $\alpha'>\alpha$. Suppose, for contradiction, that $\Lambda^*_{\alpha'}(\theta)<1$ for some $\alpha'>\alpha$.

		Now $V^*_{g,\alpha}(\theta)>0$ implies that $\phi(\theta)-\gamma>0$ which, in turn, implies that $\phi(\theta)>0$. By assumption, $A(\Lambda^*_{\alpha'}(\theta);\alpha)>A(\Lambda^*_{\alpha'}(\theta);\alpha')$  and this combined with the fact that  $\phi(\theta)>0$ implies $g(\alpha,\Lambda^*_{\alpha'}(\theta))> g(\alpha',\Lambda^*_{\alpha'}(\theta))$. Consequently,
		$$\phi(\theta)-\gamma\geq g(\alpha,\Lambda^*_{\alpha'}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}\implies \phi(\theta)-\gamma> g(\alpha',\Lambda^*_{\alpha'}(\theta))-\frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}$$
		violating the optimality of $\Lambda^*_{\alpha'}(\theta)$. To summarize, if $\Lambda^*_{\alpha}(\theta)=1$, then we must have $\Lambda^*_{\alpha'}(\theta)=1$ for all $\alpha'>\alpha$ as required.

		In what follows, we consider the case of $\Lambda^*_{\alpha}(\theta)<1$. We define the sequence 
		%$$\alpha_n = \alpha\left(1-\frac1n\right)$$ for $n=1,2,\dots$ and
		$$\lambda_n=\inf\left\{\Lambda^*_{\alpha'}(\theta)\; \bigg|\; \alpha\le \alpha'\le \alpha\left(1+\frac1n\right)\right\}$$ for $n=\underline{n},\underline{n}+1,\dots$ where $\underline{n}>\frac{\alpha}{\overline{\alpha}-\alpha}$ is chosen to be sufficiently large so that $\alpha\left(1+\frac1n\right)<\overline{\alpha}$. Observe that this sequence is nondecreasing and bounded so it has a limit. Observe also that, by definition, $\lambda_n\leq \Lambda^*_{\alpha}(\theta)$ for all $n$.

		As with the previous step, we break the argument into the two possible cases.

		\noindent Case 2.1: $\lim_{n\to\infty} \lambda_n = \Lambda^*_{\alpha}(\theta)$.

		If there exists an $n$ such that $\lambda_n = \Lambda^*_{\alpha}(\theta)$, then, for any $0<\varepsilon<\frac{\alpha}{n}$ we have $\Lambda^*_{\alpha'}(\theta)\geq \Lambda^*_{\alpha}(\theta)$ for $\alpha'\in(\alpha,\alpha+\varepsilon)$ as required. Thus, for the remainder of the argument of this case, we assume that $\lambda_n<\Lambda^*_{\alpha}(\theta)$ for all $n$.

		As we argued in Case 1.2, when $\Lambda^*_{\alpha}(\theta)<1$, the cross partial at $(\alpha,\Lambda^*_{\alpha}(\theta))$ satisfies $\frac{\partial^2 g(\alpha,\Lambda^*_{\alpha}(\theta))}{\partial \hat{\lambda} \partial \hat{\alpha}}  >0.$ Consequently, because the cross partial is continuous (by assumption), there exists an $\varepsilon>0$ such that for all $(\alpha',\lambda')$ in an $\varepsilon$-ball $||(\alpha',\lambda')-(\alpha,\Lambda^*_{\alpha}(\theta))||<\varepsilon$ around $(\alpha,\Lambda^*_{\alpha}(\theta))$, the cross-partial also satisfies $\frac{\partial^2 g(\alpha',\lambda')}{\partial \hat{\lambda} \partial \hat{\alpha}}>0$.

		Now take an $\alpha'>\alpha$ such that $||(\alpha',\Lambda^*_{\alpha'}(\theta))-(\alpha,\Lambda^*_{\alpha}(\theta))||<\varepsilon$ and $\Lambda^*_{\alpha'}(\theta)<\Lambda^*_{\alpha}(\theta)$. Such an $\alpha'$ exists because $\lim_{n\to\infty} \lambda_n = \Lambda^*_{\alpha}(\theta)$ and $\lambda_n > \Lambda^*_{\alpha}(\theta)$ for all $n$. For this $\alpha'$, the optimality of $\Lambda^*_{\alpha'}(\theta)$ implies that
		\begin{align*}
			& g(\alpha',\Lambda^*_{\alpha'}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} \ge g(\alpha',\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \\
			\implies & g(\alpha',\Lambda^*_{\alpha'}(\theta))- \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} \ge  g(\alpha',\Lambda^*_{\alpha}(\theta))  - \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha}- \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \\
			\implies & g(\alpha',\Lambda^*_{\alpha'}(\theta))- \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}> g(\alpha',\Lambda^*_{\alpha}(\theta)) - \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \\
			\implies & g(\alpha,\Lambda^*_{\alpha'}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} > g(\alpha,\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)}.
		\end{align*}
		The third inequality is a consequence of the fact that $\frac{\partial g(\alpha'',\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}}<\frac{\partial g(\alpha'',\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}}$ for all $\alpha''\in[\alpha',\alpha]$ because $\frac{\partial^2 g(\alpha'',\lambda'')}{\partial \hat{\lambda} \partial \hat{\alpha}}>0$ for all $\alpha''\in[\alpha,\alpha']$ and $\lambda''\in [\Lambda^*_{\alpha}(\theta),\Lambda^*_{\alpha'}(\theta)]$ since these values of $(\alpha'',\lambda'')$ lie in the $\varepsilon$-ball around $(\alpha,\Lambda^*_{\alpha}(\theta))$.

		This contradicts $\Lambda^*_{\alpha}(\theta)$ being optimal at $\alpha$ and thus it is not possible to have $\lim_{n\to\infty} \lambda_n = \Lambda^*_{\alpha}(\theta)$ and $\lambda_n<\Lambda^*_{\alpha}(\theta)$ for all $n$. This completes the argument for this case.

		\noindent Case 2.2: $\lim_{n\to\infty} \lambda_n < \Lambda^*_{\alpha}(\theta)$.

		Let $\tilde{\lambda}=\lim_{n\to\infty} \lambda_n < \Lambda^*_{\alpha}(\theta)$. First observe that this implies
		$$g(\alpha,\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} = g(\alpha,\tilde{\lambda})- \frac{\gamma}{\tilde{\lambda}} \implies g(\alpha,\Lambda^*_{\alpha}(\theta))  < g(\alpha,\tilde{\lambda}).$$
		The inequality follows from the fact that  $\frac{\gamma}{\tilde{\lambda}}>\frac{\gamma}{\Lambda^*_{\alpha}(\theta)}$. The equality follows from the following argument. Suppose $g(\alpha,\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} > g(\alpha,\tilde{\lambda})- \frac{\gamma}{\tilde{\lambda}}$ then, by the continuity of $g(\cdot,\cdot)$, there exists an $\varepsilon>0$ such that $g(\alpha',\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} > g(\alpha',\lambda')- \frac{\gamma}{\lambda'}$ for all $(\alpha',\lambda')$ in $||(\alpha',\lambda')-(\alpha,\tilde{\lambda})||<\varepsilon$. But this contradicts $\tilde{\lambda}=\lim_{n\to\infty} \lambda_n$.

		Moreover, $V^*_{g,\alpha}(\theta)>0$ implies that $g(\alpha,\Lambda^*_{\alpha}(\theta)) > 0$. Taken together, we get
		\begin{align*}
			\frac{\partial g(\alpha,\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}}&=\frac{1}{A(\Lambda^*_{\alpha}(\theta);\alpha)}\frac{\partial A(\Lambda^*_{\alpha}(\theta);\alpha)}{\partial \hat{\alpha}} g(\alpha,\Lambda^*_{\alpha}(\theta))> \frac{1}{A(\tilde{\lambda};\alpha)}\frac{\partial A(\tilde{\lambda};\alpha)}{\partial \hat{\alpha}} g(\alpha,\tilde{\lambda})=\frac{\partial g(\alpha,\tilde{\lambda})}{\partial \hat{\alpha}}
		\end{align*}
		because $0>\frac{1}{A(\Lambda^*_{\alpha}(\theta);\alpha)}\frac{\partial A(\Lambda^*_{\alpha}(\theta);\alpha)}{\partial \hat{\alpha}}>\frac{1}{A(\tilde{\lambda};\alpha)}\frac{\partial A(\tilde{\lambda};\alpha)}{\partial \hat{\alpha}}$ by assumption.

		Now, since $\frac{\partial g(\cdot,\cdot)}{\partial \hat{\alpha}}$ is continuous (by assumption), there is an $\varepsilon>0$ such that
		$$\frac{\partial g(\alpha'',\lambda'')}{\partial \hat{\alpha}}>\frac{\partial g(\alpha',\lambda')}{\partial \hat{\alpha}}$$
		for all $||(\alpha'',\lambda'')-(\alpha,\Lambda^*_{\alpha}(\theta))||<\varepsilon$ and all $||(\alpha',\lambda')-(\alpha,\tilde{\lambda})||<\varepsilon$.

		So take an $\alpha'>\alpha$ such that  $||(\alpha',\Lambda^*_{\alpha'}(\theta)))-(\alpha,\tilde{\lambda})||<\varepsilon$. Such an $\alpha'$ must exist since  $\tilde{\lambda}=\lim_{n\to\infty} \lambda_n$. Note that, for this $\alpha'$, we also have $||(\alpha',\Lambda^*_{\alpha}(\theta))-(\alpha,\Lambda^*_{\alpha}(\theta))||<\varepsilon$. Therefore,
		$$\frac{\partial g(\alpha',\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}}>\frac{\partial g(\alpha',\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}}$$
		and consequently for all $\alpha''\in(\alpha,\alpha')$, we also have  
		$$\frac{\partial g(\alpha'',\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}}>\frac{\partial g(\alpha'',\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}}.$$
		This inequality combined with the optimality of $\Lambda^*_{\alpha}(\theta)$ for $\alpha$ implies that
		\begin{align*}
			& g(\alpha,\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \ge g(\alpha,\Lambda^*_{\alpha'}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} \\
			\implies & g(\alpha,\Lambda^*_{\alpha}(\theta)) + \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} \ge  g(\alpha,\Lambda^*_{\alpha'}(\theta)) + \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha}- \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} \\
			\implies & g(\alpha,\Lambda^*_{\alpha}(\theta)) + \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)}> g(\alpha,\Lambda^*_{\alpha'}(\theta)) + \int^{\alpha'}_{\alpha}\frac{\partial g(\hat{\alpha},\Lambda^*_{\alpha'}(\theta))}{\partial \hat{\alpha}} d\hat{\alpha} - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)} \\
			\implies & g(\alpha',\Lambda^*_{\alpha}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha}(\theta)} > g(\alpha',\Lambda^*_{\alpha'}(\theta)) - \frac{\gamma}{\Lambda^*_{\alpha'}(\theta)}.
		\end{align*} 	
		This violates the optimality of $\Lambda^*_{\alpha'}(\theta)$ for $\alpha'$ and therefore  $\lim_{n\to\infty} \lambda_n < \Lambda^*_{\alpha}(\theta)$ cannot arise. This completes the proof of the result.
	\end{proof}



	\convexity*
	\begin{proof}
		Observe that
		$$A(\hat{\lambda};\hat{\alpha})=A(\hat{\lambda})^{\hat{\alpha}} \implies \frac{\partial A(\hat{\lambda};\hat{\alpha})}{\partial \hat{\alpha}}=\ln(A(\hat{\lambda}))A(\hat{\lambda})^{\hat{\alpha}} \implies \frac{1}{A(\hat{\lambda};\hat{\alpha})}\frac{\partial A(\hat{\lambda};\hat{\alpha})}{\partial \hat{\alpha}}=\ln(A(\hat{\lambda})).$$
		This implies that the result is an immediate consequence of Proposition \ref{prop:1proof} because $A(\hat{\lambda};\hat{\alpha})$ is strictly decreasing in $\hat{\alpha}$ and $\frac{1}{A(\hat{\lambda};\hat{\alpha})}\frac{\partial A(\hat{\lambda};\hat{\alpha})}{\partial \hat{\alpha}}$ is increasing in $\hat{\lambda}$.
	\end{proof}

	\welfaresummary*
	\begin{proof}

		An exhaustive list of possibilities is Cases 1 and 2 in the statement of the Proposition plus the following two cases.

		\noindent Case 3: $\Lambda^{*}(\theta)=1$ for all $\theta$ such that $\phi(\theta)\ge\gamma$ and $V_{g}^{*}(\theta)>0$ for some $\theta$ such that  $\phi(\theta)\le\gamma$.

		\noindent Case 4:  $\Lambda^{*}(\theta)<1$ for some $\theta$ such that $\phi(\theta)>\gamma$ and $V_{g}^{*}(\theta)=0$ for all $\theta$ such that  $\phi(\theta)<\gamma$.

		We show that Cases 3 and 4 cannot occur. Denote the contribution to profits by the type $\theta$ under the optimal mechanism by $\pi(\theta)=R(\phi(\theta),\Lambda^*(\theta))V_{g}^{*}(\theta)-c(V_{g}^{*}(\theta))$. Similarly denote the analogous contribution to profits under perfect certification by $\pi^{s,1}(\theta)=R(\phi(\theta),1)V_{g}^{s,1}(\theta) -c(V_{g}^{s,1}(\theta) )$. These are both continuous by the theorem of the maximum. They are increasing since $R(\phi(\theta),\lambda)$ is increasing in $\theta$.

		Suppose Case 3 could arise. This requires that $\Lambda^{*}(\theta)=1$ for all $\theta$ with $\phi(\theta) \ge \gamma$, so $\pi(\theta)=\pi^{s,1}(\theta)=0$ for $\phi(\theta)=\gamma$, and therefore $\pi(\theta)=V_{g}^{*}(\theta)=0$ for $\phi(\theta)  \le \gamma$. This contradicts $V_{g}^{*}(\theta)>0$ for some $\theta$ such that  $\phi(\theta)\le\gamma$ as required in Case 3.

		Finally, suppose Case 4 could arise. This requires $\pi(\theta)=0$ for $\theta$ such that $\phi(\theta) <\gamma$, so $\pi(\theta)=0$ for $\theta$ such that $\phi(\theta)=\gamma$ by continuity. Case 4 requires further that $\lim_{\theta \downarrow \phi^{-1}(\gamma)} \Lambda^*(\theta) <1$  and $\lim_{\theta \downarrow \phi^{-1}(\gamma)} R(\phi(\theta),\Lambda^*(\theta)) =0$. To see the latter, note that, if $\lim_{\theta \downarrow \phi^{-1}(\gamma)} R(\phi(\theta),\Lambda^*(\theta)) >0$, this implies that $\lim_{\theta \downarrow \phi^{-1}(\gamma)} \pi(\theta) >0$ which violates the continuity of $\pi$. But $R(\phi^{-1}(\gamma),1)=0$ and therefore we must have $\Lambda^*(\phi^{-1}(\gamma))=1$. This provides the requisite contradiction since $\lim_{\theta \downarrow \phi^{-1}(\gamma)} \Lambda^*(\theta) <1$ and $\Lambda^*(\theta)$ is nondecreasing.
	\end{proof}

	\polynomial*

	\begin{proof}
		For clarity in the proof, we denote the optimal mechanism as $(V^*_{g,\gamma},\Lambda^*_{\gamma})$ and the true effective virtual value as $R_{\gamma}$ to make the dependence on $\gamma$ explicit.

		We first argue that $\lim_{\gamma\downarrow 0}\Lambda^{*}_{\gamma}(\theta)=0$ for all $\theta\in\Theta$. For contradiction, suppose there exists a $\theta\in\Theta$ and a $\lambda_l>0$ such that for every $\varepsilon>0$, there exists a $\gamma\in(0,\varepsilon)$ for which $\Lambda^{*}_{\gamma}(\theta)\geq\lambda_l$. For such a $\gamma$, observe that
		$$R_{\gamma}(\phi(\theta),\Lambda^{*}_{\gamma}(\theta))= \max_{\lambda\in [\lambda_l,1]} \left\{\left(\phi(\theta)+\frac{1-\lambda}{\lambda}\right)A(\lambda)-\frac{\gamma}{\lambda}\right\}  < \max_{\lambda\in [\lambda_l,1]} \left\{\left(\phi(\theta)+\frac{1-\lambda}{\lambda}\right)A(\lambda)\right\}$$
		and so the value of $R(\phi(\theta),\Lambda^{*}_{\gamma}(\theta))$ is bounded from above by the right term (that does not depend on $\gamma$).

		But suppose, instead of the optimal quality $\Lambda^*_{\gamma}$, the platform chooses quality $\lambda=\gamma$. Then, 
		$$R_{\gamma}(\phi(\theta),\gamma)=(\phi(\theta)-1)\gamma^{\alpha}+\gamma^{\alpha-1}-1.$$
		Now since $\alpha\in(0,1)$ and $\gamma<\varepsilon$, if we take $\varepsilon$ sufficiently small, then $$R_{\gamma}(\phi(\theta),\gamma)>\max_{\lambda\in [\lambda_l,1]} \left\{\left(\phi(\theta)+\frac{1-\lambda}{\lambda}\right)A(\lambda)\right\}>R_{\gamma}(\phi(\theta),\Lambda^{*}_{\gamma}(\theta))$$ because $R_{\gamma}(\phi(\theta),\Lambda^{*}_{\gamma}(\theta))$ is bounded and $\gamma^{\alpha}\to 0$, $\gamma^{\alpha-1}\to\infty$, and so $R_{\gamma}(\phi(\theta),\gamma)\to\infty$ as $\gamma\downarrow 0$. This provides the requisite contradiction and implies that $\lim_{\gamma\downarrow 0}\Lambda^{*}_{\gamma}(\theta)=0$ for all $\theta\in\Theta$.

		Now we derive the limit of the engagement $A(\Lambda^{*}_{\gamma}(\theta))V^*_{g,\gamma}(\theta)$ from the optimal mechanism as $\gamma\downarrow 0$. First observe that, for every $\theta\in\Theta$, the above argument implies that $R_{\gamma}(\phi(\theta),\Lambda^{*}_{\gamma}(\theta))>0$ for sufficiently small $\gamma>0$. Thus, for sufficiently small $\gamma$, the views $V^*_{g,\gamma}(\theta)>0$ and are given by the equation
		$$c'(V^*_{g,\gamma}(\theta))=R_{\gamma}(\phi(\theta),\Lambda^{*}_{\gamma}(\theta))\iff V^*_{g,\gamma}(\theta)=\left(\left(\phi(\theta)+\frac{1-\Lambda^{*}_{\gamma}(\theta)}{\Lambda^{*}_{\gamma}(\theta)}\right)\Lambda^{*}_{\gamma}(\theta)^{\alpha}-\frac{\gamma}{\Lambda^{*}_{\gamma}(\theta)}\right)^{\frac{1}{\sigma-1}}.$$
		Thus, engagement from the optimal mechanism is given by
		$$A(\Lambda^{*}_{\gamma}(\theta))V^*_{g,\gamma}(\theta)=\Lambda^{*}_{\gamma}(\theta)^{\alpha}\left(\left(\phi(\theta)+\frac{1-\Lambda^{*}_{\gamma}(\theta)}{\Lambda^{*}_{\gamma}(\theta)}\right)\Lambda^{*}_{\gamma}(\theta)^{\alpha}-\frac{\gamma}{\Lambda^{*}_{\gamma}(\theta)}\right)^{\frac{1}{\sigma-1}}.$$

		Since $\lim_{\gamma\downarrow 0}\Lambda^{*}_{\gamma}(\theta)=0$, the optimal quality $\Lambda^{*}_{\gamma}(\theta)$ must be less than 1 for sufficiently small $\gamma>0$. Thus, for such small values of $\gamma$, it must satisfy the first-order condition
		$$\alpha(\phi(\theta)-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha-1}+(\alpha-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha-2}+\frac{\gamma}{\Lambda^{*}_{\gamma}(\theta)^{2}}=0.$$
		This can be rewritten as
		$$\alpha(\phi(\theta)-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha}+(\alpha-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha-1}=-\frac{\gamma}{\Lambda^{*}_{\gamma}(\theta)}.$$
		We use this equation to replace the term $-\frac{\gamma}{\Lambda^{*}_{\gamma}(\theta)}$ in the expression for the engagement $A(\Lambda^{*}_{\gamma}(\theta))V^*_{g,\gamma}(\theta)$ to get
		\begin{align*}
			A(\Lambda^{*}_{\gamma}(\theta))V^*_{g,\gamma}(\theta) & =\Lambda^{*}_{\gamma}(\theta)^{\alpha}\left(\left(\phi(\theta)+\frac{1-\Lambda^{*}_{\gamma}(\theta)}{\Lambda^{*}_{\gamma}(\theta)}\right)\Lambda^{*}_{\gamma}(\theta)^{\alpha}+\alpha(\phi(\theta)-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha}+(\alpha-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha-1}\right)^{\frac{1}{\sigma-1}}\\
			& =\Lambda^{*}_{\gamma}(\theta)^{\alpha}\left((\phi(\theta)-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha}+\Lambda^{*}_{\gamma}(\theta)^{\alpha-1}+\alpha(\phi(\theta)-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha}+(\alpha-1)\Lambda^{*}_{\gamma}(\theta)^{\alpha-1}\right)^{\frac{1}{\sigma-1}}\\
			& =\Lambda^{*}_{\gamma}(\theta)^{\alpha}\left((\phi(\theta)-1)(1+\alpha)\Lambda^{*}_{\gamma}(\theta)^{\alpha}+\alpha\Lambda^{*}_{\gamma}(\theta)^{\alpha-1}\right)^{\frac{1}{\sigma-1}}\\
			& =\left((\phi(\theta)-1)(1+\alpha)\Lambda^{*}_{\gamma}(\theta)^{\sigma\alpha}+\alpha\Lambda^{*}_{\gamma}(\theta)^{\sigma\alpha-1}\right)^{\frac{1}{\sigma-1}}.
		\end{align*}
		As $\gamma\downarrow 0$, the optimal quality $\Lambda^{*}_{\gamma}(\theta)\to 0$ and therefore, the first term goes to zero, since $\alpha\sigma>0$. The second term goes to zero if $\alpha>\frac{1}{\sigma}$, to infinity	if $\alpha<\frac{1}{\sigma}$, and to $\alpha$ if $\alpha=\frac{1}{\sigma}$. This completes the proof.
	\end{proof}

