	\section{The relationship between engagement and consumer welfare}\label{sec:appendixwelfare}

	Here we substantiate the claim in Sections \ref{sec:planner} and \ref{subsec:compare_to_perfect} that maximizing engagement is equivalent to maximizing consumer welfare.


	\setcounter{proposition}{0}
	\renewcommand{\theproposition}{\Alph{section}.\arabic{proposition}}

	\begin{proposition}
		Suppose $A(\lambda)=\lambda^\alpha$. Then, the consumer welfare from $v_g$ good content views assigned a certificate of quality $\lambda$ is proportional to $A(\lambda)v_g$.
	\end{proposition}

	\begin{proof}
		We calculate the consumer welfare from $v_g$ good content views when the content is marked with a certificate of quality $\lambda$. This, of course, implies that there are $v_b=\frac{1-\lambda}{\lambda}v_g$ bad content views assigned to the same certificate.

		Recall that consumers pay a cost $q$ drawn from a distribution $A$ of reading content. If content is read, the consumer receives a payoff of 1 if the content is good and 0 if it is bad. Thus, only consumers with cost $q\leq \lambda$ read the content and thus consumer welfare is given by
		\[
		v_{g}\int_{0}^{\lambda}\left(1-q\right)dA(q)-v_{b}\int_{0}^{\lambda}qdA(q).
		\]
		This expression can be rewritten as
		\begin{align*}
			v_{g}\int_{0}^{\lambda}\left(1-q\right)dA(q)-v_{b}\int_{0}^{\lambda}qdA(q) & =v_{g}\int_{0}^{\lambda}\left(\left(1-q\right)-\frac{(1-\lambda)}{\lambda}q\right)dA(q)\\
			& =v_{g}\int_{0}^{\lambda}\left(1-\frac{1}{\lambda}q\right)dA(q)\\
			& =v_{g}\left(A(\lambda)-\frac{1}{\lambda}\int_{0}^{\lambda}qdA(q)\right).
		\end{align*}
		For $A(\lambda)=\lambda^{\alpha}$, this simplifies to $\frac{1}{\alpha+1}v_{g}A(\lambda)$; that is, welfare is proportional to engagement as required.
	\end{proof}


	\section{Two certificates analysis}\label{sec:appendixtwocert}
	In this section, we provide a full characterization of the platform's optimal mechanism when restricted to two certificates.

	\setcounter{proposition}{0}

	\begin{proposition}\label{prop:twocert}
		Consider the version of the platform's problem \eqref{eq:prin_prob_simple} where $\Lambda:\Theta\to \{\umu,\omu\}$ and $V_g:\Theta\to \mathbb{R}_+$.

		There is an optimal mechanism $(V^{bin}_g,\Lambda^{bin})$ given by
		\begin{align*}
			& \hat{\theta}=\left\{\begin{array}{cl}
				\min\left\{\theta\in\Theta \;\bigg|\; \left(\phi(\theta)+\frac{1-\omu}{\omu}\right)A(\omu)-\frac{\gamma}{\omu}\geq \left(\phi(\theta)+\frac{1-\umu}{\umu}\right)A(\umu)-\frac{\gamma}{\umu}\right\} & \text{ if the set is non-empty,} \\
				\overline{\theta} & \text{ otherwise,} 
			\end{array}\right.\\
			& \Lambda^{bin}(\theta)=\left\{\begin{array}{cl} \omu\;\; \text{ if }\theta> \hat{\theta}\; \text{ or }\; \theta=\hat{\theta}<\overline{\theta}, \\ \umu\;\; \text{ if }\theta< \hat{\theta}\; \text{ or }\; \theta= \hat{\theta}=\overline{\theta}, \end{array}\right.\qquad \text{ and }\\
			& V^{bin}_g(\theta)=c'^{-1}\left(\max\left\{\left[\phi(\theta)+\frac{1-\Lambda^{bin}(\theta)}{\Lambda^{bin}(\theta)}\right]A(\Lambda^{bin}(\theta))-\frac{\gamma}{\Lambda^{bin}(\theta)},0\right\}\right).
		\end{align*}
	\end{proposition}
	\begin{proof}
		We maximize the objective function pointwise and show that the mechanism we obtain satisfies the necessary monotonicity properties to satisfy the incentive compatibility constraints.

		First, observe that, if
		\begin{equation}\label{eq:mu_ineq}
			\left(\phi(\theta)+\frac{1-\omu}{\omu}\right)A(\omu)-\frac{\gamma}{\omu} \geq \left(\phi(\theta)+\frac{1-\underline{\lambda}}{\underline{\lambda}}\right)A(\underline{\lambda})-\frac{\gamma}{\underline{\lambda}}
		\end{equation}
		then, for any $V_g(\theta)\in\mathbb{R}_+$, the value of the objective function satisfies
		$$\left[\left(\phi(\theta)+\frac{1-\omu}{\omu}\right) A(\omu)-\frac{\gamma}{\omu}\right]V_g(\theta) - c(V_g(\theta))\geq \left[\left(\phi(\theta)+\frac{1-\underline{\lambda}}{\underline{\lambda}}\right) A(\underline{\lambda})-\frac{\gamma}{\underline{\lambda}}\right]V_g(\theta) - c(V_g(\theta))$$
		and vice versa when inequality \eqref{eq:mu_ineq} is reversed.

		Consequently, there is a pointwise optimum that satisfies
		$$\Lambda^{bin}(\theta)\in\argmax_{\lambda\in\{\underline{\lambda},\omu\}}\left\{ \left(\phi(\theta)+\frac{1-\lambda}{\lambda}\right) A(\lambda) - \frac{\gamma}{\lambda}\right\}.$$
		For any $\theta\in \Theta$ at which both $\underline{\lambda}$ and $\omu$ are maximizers, we set $\Lambda^{bin}(\theta)=\omu$.

		Now note that, if \eqref{eq:mu_ineq} holds for some $\theta$, it also holds for all $\theta'>\theta$. This is because $A(\omu)>A(\underline{\lambda})$ and $\phi(\cdot)$ is nondecreasing. Consequently, $\Lambda^{bin}$ must take the cutoff form
		$$\Lambda^{bin}(\theta)=\left\{\begin{array}{cl} \omu & \text{ when } \theta> \hat{\theta},\\ \underline{\lambda} & \text{ when } \theta< \hat{\theta}.
		\end{array}\right.$$
		as in the statement of the proposition and thus $\Lambda^{bin}$ is nondecreasing.

		The function $V^{bin}_g$ as defined in the statement of the proposition is the solution to
		\begin{equation}\label{eq:Vbin}
			V^{bin}_g(\theta)=\argmax_{v_g\in \mathbb{R}_+}\left\{\left[\left(\phi(\theta)+\frac{1-\Lambda^{bin}(\theta)}{\Lambda^{bin}(\theta)}\right)A(\Lambda^{bin}(\theta))-\frac{\gamma}{\Lambda^{bin}(\theta)}\right]v_g - c(v_g)\right\}
		\end{equation}
		and the exact expression is obtained from the first-order condition.

		Now observe that, because $\phi$ is nondecreasing, the function
		$$\left(\phi(\theta)+\frac{1-\Lambda^{bin}(\theta)}{\Lambda^{bin}(\theta)}\right)A(\Lambda^{bin}(\theta))-\frac{\gamma}{\Lambda^{bin}(\theta)}=\max_{\lambda\in\{\underline{\lambda},\omu\}}\left\{ \left(\phi(\theta)+\frac{1-\lambda}{\lambda}\right) A(\lambda) - \frac{\gamma}{\lambda}\right\}$$
		is nondecreasing because it is the maximum of two nondecreasing functions. This, in turn, implies from \eqref{eq:Vbin}, that $V^{bin}$ is nondecreasing. Therefore $A(\Lambda^{bin}(\cdot))V^{bin}_g(\cdot)$ is nondecreasing and consequently the pointwise solution is incentive compatible as required. This completes the proof.
	\end{proof}



