\title[]
{$\pi_1$-injective bounding \\ and application to 3- and 4-manifolds}

\author{Jianfeng Lin}
\address{Department of Mathematics Science, Tsinghua University, Beijing, 100080, CHINA}
\email{linjian5477@mail.tsinghua.edu.cn}

\author{Zhongzi Wang}
