\subsection{Complexity of 4-manifolds with given boundaries}
%{Finite index bounding and   achirality of 3-manifolds} 

Started from Hausmann-Weinberger \cite{HW},
some  3-manifold invariants are derived from related 4-manifolds, see \cite{SW1}  for more details. Given  Theorems \ref{main} and \ref{main3}, it is natural to consider the following new  invariant for bounding $n$-manifolds $Y$,  the minimal bounding index,  derived  from $(n+1)$-manifolds it bounds:
\[ 
\begin{split}
O_b(Y)=\min \{|\pi_1(W):\pi_{1}(Y)|\, \mid\, W \text{ is $\pi_1$-injectively bounded by }Y\}
\in \ZZ_+\cup\{\infty\}.    \end{split}\]
In particular $O_b(Y)$ is defined for each closed 3-manifold. 
%Intuitively, $O_{b}(Y)$ describes the minimal size  of a group that contains $\pi_{1}(Y)$ as the boundary subgroup. 
We say $Y$ is finite index bounding if $O_b(Y)< \infty$. %And we say $Y$ is index two bounding if $O_b(Y)=2$. 
%Clearly for each bounding $n$-manifold $Y$, $O_b(Y)$ can be defined,  
Clearly  $|\pi_1(Y)|<\infty$ implies  $O_b(Y)< \infty$ by Theorems 
\ref{main} and \ref{main3}.  

%We say that a 3-manifold $M$ {\it virtually} has a certain property if a finite cover of $M$ has this property. %which is based on Wise's machinery (\cite{Wise}). 
%The general philosophy is: a $3$-manifold has a lot of finite covers, so it should have a finite cover that satisfies any given reasonable property. 
 %see  a survey \cite{LS}.  We will address another two virtual properies of 3-manifolds: Virtually achiral and virtually bounds surface bundles over surfaces.


A closed orientable manifold is called {\em achiral},  if it admits an orientation reversing homeomorphism, and is called virtually achiral if it has an achiral finite cover.  The study of various virtual properties of $3$-manifolds became an active  topic on $3$-manifolds after Agol's solution (\cite{Ag}) of Thurston's virtual Haken conjecture \cite{Thu}.
%Virtually achirality of 3-manifolds is also discussed in a recent work \cite{TWWY}
%Both achirality  and virtual properties (such as virtually Haken and virtually special \cite{Ag}, \cite{PWi}) are  important topics in 3-manifolds and in geometric group theory.
The following results reveal some relations between  finite index bounding and virtual achirality and geometries of 3-manifolds:

\begin{theorem}\label{thm: O(Y)=2 or finite} Let $Y$ be a closed, orientable 3-manifold.

{\rm (1)}  If $Y$ is aspherical, then $O_{b}(Y)<\infty$ implies that  $Y$ is virtually achiral.

{\rm (2)}     If $Y$ admits an orientation reversing free involution, then $O_{b}(Y)=2$. The reverse is also true if $Y$ is hyperbolic. 

{\rm (3)}   Suppose $Y$ $\pi_1$-injectively bounds a compact orientable $4$-manifold $W$. Then for any integer $d>0$, $Y$ $\pi_1$-injectively bounds a compact orientable $4$-manifold $W_d$ such that $|\pi_1(W_d): \pi_1(Y)|=d|\pi_1(W): \pi_1(Y)|$.
\end{theorem}


%The next result claims that all odd primes are realized by len spaces

\begin{theorem}\label{O(Y)=3}
For each prime $p\ge 5$, $O_b(L(p,q))=\min\{d\ge 3|\, d|p-1\}.$ %Thus every odd prime is realized by $O_b(Y)$.
\end{theorem}



\begin{remark}\label{finite index} It is known that  {\rm (i)} each  $\mathcal G$ $3$-manifold is aspherical unless $ \mathcal  G$ is $S^2\times E^1$ or  $S^3$;
