\section{Atiyah's generalization of Thom's Theorem and a surgery theorem}
\subsection{Results in dim $\ge 3$ for proving $\pi_1$-injective bounding results}

We use $H_n(X)$ to denote  $H_n(X, \ZZ)$ in the whole paper.

\begin{theorem}\label{Atiyah} Let $X$ be a CW-complex with $\tilde H_*(X)=0$. Let $M$ be 
a closed oriented $n$-manifold which is trivial in $\Omega_n$.
Then for any map $f: M\to X$, there is a compact oriented $(n+1)$-manifold $W$ such that  $\partial W=M$
and the map $ f: M\to X$ extends to a map $\tilde f: W\to X$.
\end{theorem}



\begin{proof}
The proof based on Atiyah's generalization of Thom's Theorem.

Recall that Atiyah defined the bordism homology group  $\{\MSO_k(X), k\ge 0\}$ and proved it is a generalized homology theory in \cite{Ati}. Let $R_k(X)=\MSO_k(X)$.
Let $c:X\to \{\text{point}\}$ be a constant map. It induces a map between Atiyah-Hirzebruch Spectral Sequence
$$c_*^2: E^2_{s, t}(X)\to E^2_{s,t}(\text{point})$$
where $E^2_{s, t}(X)=H_s(X, R_t(\text{point}))$ and $E^2_{s, t}(\text{point})=H_s(\text{point}, R_t(\text{point}))$. Since $\tilde H_*(X)=0$,
by universal coefficient theorem, $c_*^2$ is an isomorphism for all $s, t$.
Note that $$H_s(X, R_t(\text{point}))=H_s(\text{point}, R_t(\text{point}))=0$$ for all $s\ge 1, t\ge 0$. So 
$$ E^2_{s, t}(X)\to E^2_{s,t}(\text{point})=0$$
for all $s\ge 1, t\ge 0$. So the Atiyah-Hirzebruch Spectral Sequence collapses in $E^2$-page, so it collapses on $E^n$-page
for all $n\ge 2$. The Atiyah-Hirzebruch Spectral Sequence converges to bordism groups, it follows that the induced map $$c_* :    R_k(X)=\MSO_k(X)\to  R_k(\text{point})=\MSO_k(\text{point})$$
are isomorphism for all $k\ge 0$.

Reall each element in  $\MSO_k(X)$ is represented
by a map $f: M\to X$ where $M$ is a closed oriented $k$-manifold.
Then for any map $f:M\to X$ for a closed oriented $n$-manifold, consider the bordism class $[f: M\to X]$. Let 
$c_*[f: M\to X]=[c\circ f: M\to X]$ be the image in $\MSO_k(\text{point})$. Then it is represented by a map $c\circ f: M\to \{\text{point}\}$,
which is a constant map. Since $[M]=0\in \Omega_n$, there is a compact oriented $(n+1)$-manifold $W'$ such that  $\partial W'=M$.
Then $c\circ f$ extends to $W'$, that is,  there is a map $g:W'\to \text{point} $ with  $g|M=f$. 
It follows that $c_*[f: M\to X]$ is trivial in $\MSO_k(\text{point})$. Since $c_* :    \MSO_n(X)\to  \MSO_n(\text{point})$ is an isomorphism, we 
have that $ [f: M\to X]$ is trivial in $\MSO_n(X)$, that is there is a compact oriented $(n+1)$-manifold $W$ such that  $\partial W=M$
together with a map $\tilde f: W \to X$ which extends $f$.
\end{proof}


\begin{proposition}\label{surgery}
Suppose $\Gamma$ is a finitely presented group. Suppose $M$ is a closed oriented $n$-manifold, $n\ge 3$, and  $f: M\to K(\Gamma, 1)$ is a $\pi_1$-injective map. If $f$ extends to $\tilde f: W\to K(\Gamma, 1)$ for some  compact oriented $(n+1)$-manifold $W$
with $\partial W=M$, then we can choose $W$ so that $\tilde f$ is an $\pi_1$-isomorphism.
\end{proposition}

\begin{lemma}\label{finite generated} Let $\phi: G\to \Gamma$ be a surjection from a finitely generated group to a finitely presented group.
Then the kernel of $\phi$ is finitely normally generated.
\end{lemma}

\begin{proof}
Let $\phi: G\to \Gamma$ be a surjection from a finitely generated group to a finitely presented group.
Since $G$ is finitely generated, there is a surjection $\psi: F_n\to G$ from free group of rank $n$ for some $n$, therefore a surjection $\phi\circ \psi: F_n\to G \to \Gamma$.
Let $y_1, ... , y_n\in \Gamma$ be the images of the free generators $\{x_1, ... x_n\}$ of $F_n$ under $\phi\circ \psi$, then $y_1, ... , y_n$ is set of generators of $\Gamma$.
Since $\Gamma$ is finitely presented, and the property to be finitely presented is independent of the set of generators,
and we have a presentation
$$\Gamma=\langle y_1, ... , y_n\ \, | \, r_1(y_1, ..., y_n), ... , r_m(y_1, ..., y_n) \rangle,$$
which implies that the kernel of   $\phi\circ \psi$ is normally generated by 
$$\{r_1(x_1, ..., x_n), ... , r_m(x_1, ..., x_n) \}.$$
Then one can see directly  that the kernel of   $\phi$ is normally generated by 
$$\{\psi(r_1(x_1, ..., x_n)), ... , \psi(r_m(x_1, ..., x_n)) \}.$$
\end{proof}

\begin{proof}[Proof of Proposition \ref{surgery}]
Suppose $\tilde f: W\to K(\Gamma, 1)$ is an extension $f: M\to K(\Gamma, 1)$.
Let $k$ be the rank $\Gamma$.
Let $W_1=W\# (\#_k S^{n-1}\times S^1)$ be  the connected sums of $W$ and $k$ copies of $S^{n-1}\times S^1$.
Let $$\tilde f_1: W_1=W\# (\#_k S^{n-1}\times S^1) \to W\vee (\vee_k  S^1) \to K(\Gamma, 1)$$
be the composition of two maps: the first one pinch each $S^{n-1}\times S^1$ to $S^1$, and second one maps $W$ to $K(\Gamma, 1)$ via $\tilde f$, and maps those $k$
circles to the $k$ generators of $K(\Gamma, 1)$.
Clearly  $\tilde f_{1*}$ is  surjective
on $\pi_1$. 

Since $\tilde f_{1*}$ is a surjection between two finitely presented groups, by Lemma \ref{finite generated} the kernel of $\tilde f_{1*}$
is  normal generated by finitely many elements in $\pi_1(W_1)$. Let $c_1, ..., c_k$ be disjoint simple closed circles
in the interior of $W_1$ which represent the free homotopy classes of those generators.
Let $N(c_1), ... , N(c_k)$ be the disjoint regular neighborhood of $c_1, ... , c_k$ respectively. Then each 
$$N(c_i)\cong c_i\times D^n\cong S^1\times D^n.$$

Let $$W_2=W_1\setminus  (\cup_i c_i\times D^n)$$ and 
$$W_3=W_2\cup (\cup_i D^2_i\times S^{n-1}),$$
where each component $c_i\times S^{n-1}$ of $\partial W_2$ is identified with $\partial (D^2\times S^{n-1})=S^1\times S^{n-1}$ canonically.
Since $K(\Gamma, 1)$  has no homotopy groups of dimension $>1$, the restriction $\tilde f_1|: W_2 \to K(\Gamma, 1)$ extends to $\tilde f_3: W_3\to K(\Gamma, 1)$,
From Van Kampen theorem, it is easy to verify that $\tilde f_{3*}$ is an isomorphism on $\pi_1$.

Note during the surgery from $(\tilde f, W)$ to $(\tilde f_3, W_3)$, we do not touch $(f, M)$, we have a required extension $\tilde f_3: W_3\to K(\Gamma, 1)$.

\subsection{Results in dim $=3$ for further  applications} %In the text below, we often use $Y$ to denote closed oriented 3-manifolds

\begin{theorem}\label{pro: key proposition} Let $Y$ be a connected closed oriented $3$-manifold and let $\phi: \pi_{1}(Y)\to \Gamma$ be a group homomorphhism to a finitely presented group $\Gamma$. Let $f_{\phi}: Y\to K(\Gamma,1)$ be the map induced by $\phi$. Then the following two conditions are equivalent:

\begin{enumerate}
    \item There exists a smooth 4-manifold $X$ bounded by $Y$, and an isomorphism $\pi_{1}(X)\cong \Gamma$ under which $\phi$ is exactly the map induced by the inclusion $Y\to X$.
    \item The map 
       $f_{\phi,*}: H_{3}(Y;\mathbb{Z})\to H_{3}(K(\Gamma,1);\mathbb{Z})$
    is trivial. 
\end{enumerate}
\end{theorem}

%Our  proof of the main result, Theorem \ref{main}, relies the following Theorems \ref{Thom Atiyah} and \ref{virtual torsion} which will be proved in this section, as well as Propsositions \ref{fiber torsion}, \ref{H1=0} and \ref{surgery} which will be proved in next section.






\begin{theorem}\label{Thom Atiyah}%\cite{Ati}
 Suppose $X$ is a compact topological space,  $Y_1,...,Y_k$ are closed oriented 3-manifolds, and  $f_i:Y_i\rightarrow X$ are maps, $i=1,..., k$. If
$$\sum_{i=1}^{n}{(f_i)_*[Y_i]}=0,$$ Then there exists a $4$-manifold such that $\partial W=\cup_{i=1}^k Y_i$, and $f: W\rightarrow X$ such that $f|_{Y_i}=f_i$.
\end{theorem}

\begin{proof} We use the bordism homology groups $\MSO_k(X)$ \cite{Ati}. Consider the map $\psi_k: \MSO_k(X)\rightarrow H_k(X;\mathbb{Z})$ which sends $[Y,f]$ to $f_*[Y]$. It is known that $\MSO_*$ is a generalized homology theory.  (recall $\Omega_q=\MSO_q(\text{point})$) Thus there exists an Atiyah-Hirzebruch Spectral sequence whose $E^2$-page is $\{H_p(X,\Omega_q)\}$ and converges to $\{\MSO_k(X)\}$.  

Since $\Omega_q=0$ for $1\le q\le 3$, the spectral sequence collapses on $E_2$-page in the region $p+q\le 3$. Since $\Omega_0=\mathbb{Z}$, we have $E^2_{p,0}(X)=H_p(X, \mathbb{Z})$. So $E^\infty_{k,0}(X)=H_k(X,\mathbb{Z})$ for $k\le 3$.
Since $\Omega_q=0$ for $1\le q\le 3$, $E^\infty_{p,q}=0$ for $1\le q\le 3$. So we have $\MSO_k(X)\cong H_k(X,\mathbb{Z})$ when $k\le 3$.

We have the map $\psi_k: \MSO_k(X)\rightarrow H_k(X;\mathbb{Z})$ is an isomorphism when $k\le 3$.

Now consider the element $\xi=\sum_{i=1}^n [Y_i, f_i]\in \MSO_3(X)$. Then $\psi_3(\xi)=\sum_{i=1}^{n}{(f_i)_*[Y_i]}=0$. Since $\psi_3$ is an isomorphism, $\xi$ is trivial in $\MSO_3(X)$. It follows that there exists a $4$-manifold such that $\partial W=\cup_{i=1}^k Y_i$, and $f: W\rightarrow X$ such that $f|_{Y_i}=f_i$.
\end{proof}






\begin{proof}[Proof of Theorem  \ref{pro: key proposition}] (1) $\Longrightarrow$ (2):
Let $X\to K(\Gamma, 1)$ be the map which induces the identity on $\pi_1$. The the composition map $Y\to X\to K(\Gamma, 1)$
induces $\phi: \pi_1(Y)\to \Gamma$ on $\pi_1$, and the map  $f_{\phi,*}: H_{3}(Y;\mathbb{Z})\to H_{3}(K(\Gamma,1);\mathbb{Z})$
is trivial since the first map is trivial.

(2) $\Longrightarrow$ (1): Let $i=1$ and $Y=Y_1$,  by Theorem \ref{Thom Atiyah}, there exists a compact orientable 4-manifold $W$ such that 
$\partial W=Y$ and $\tilde f :W \to K(\Gamma, 1)$ such that $\tilde f|Y= f_{\phi}$. By Proposition \ref{surgery}, we can choose $W$
such that $\tilde f :W \to K(\Gamma, 1)$ is a $\pi_1$-isomorphism. So we have the commutative diagram


$$
\CD
Y     @>>>    W \\
@\vert @VV{\tilde f}V \\
Y   @>f_{\phi}>>K(\Gamma,1)
\endCD
$$
which induces commutative diagram on $\pi_1$
$$
\CD
\pi_1(Y) @>>> \pi_1(W) \\
@\vert @VV{\tilde f_*}V \\
\pi_1(Y) @>\phi>> \Gamma.
\endCD
$$

So under the isomorphism $\tilde f_*: \pi_1(W)\to \Gamma$, $\phi$ is exactly induced by the inclusion $Y\to W$.
\end{proof}

