Consider the sequence (\ref{eq: sequence Xn}). For $n>m$, we define the map  
$$\tau_{m, n}= e_{n-1}\circ ... \circ e_m: X_m\to...  \to X_{n-1}\to X_n.$$
Then we have the following property of $\tau_{m,n}$ on homology groups.

\begin{lemma} The following are equivalent:

{\rm (1)} For any integers $d>0$, and $N>0$, there exists an $n>N$ such that $\tau_{N, n}: X_N\to X_n$ induces trivial maps on $H_i$ for $1\le i \le d$.

{\rm (2)} $\tilde H_i(X_\infty)=0$.
\end{lemma}

 \begin{proof}
 Suppose (1) holds. For any $k$-cycle $c\in X_\infty$, $c\subset X_N$ for some $N$. Then for some $n>N$, $c=\partial D$ for some
 $D\subset X_n \subset X_\infty$. Hence $c$ is zero in $H_*(X_\infty)$, i.e. $\tilde H_i(X_\infty)=0$.

 Suppose (2) holds. For each $i\in \{1, ... ,  d\}$, fix a finite generating set of $H_i(X_N)$. For  any element $c$ in this basis, since $\tilde H_i(X_\infty)=0$, $c=\partial D$ for some finite chain $D\subset X_\infty$.
 Since $D$ is compact, $D\subset  X_{n_c}$. 
 Since there are only finitely many elements in this set, there exists an $n_i>N$ such that each element in this set bounds in $X_{n_i}$. Then the image of $H_i(X_N)$ vanishes in $H_i(X_{n_i})$.
 Let $n=\text{max}\{n_i, i=1, ..., d\}$, we have
 that $\tau_{N, n}: X_N\to X_n$ is trivial in $H_i$ for $1\le i \le d$.
 \end{proof}

 So to prove (2), we need only to prove (1), and to prove (1), we need only to prove the following

 \begin{proposition}\label{1}
$X\to \sigma^{3^{n-1}}(X)=X_{3^{n-1}}$ induces trivial maps on $H_i$ for $1\le i\le n$.
\end{proposition}

We will prove Proposition \ref{1} by induction based on the following

 \begin{proposition}\label{2}
Suppose we have a composition  
$$A_1\overset {f_1}  \longrightarrow A_2\overset {f_2}  \longrightarrow  A_3 \to \sigma (A_3).$$
If $f_1$ and $f_2$ induce  trivial maps  on $H_i$ for  $1\le i\le n-1$, then the composition $A_1\to \sigma(A_3)$ induces  trivial maps in $H_i$ for  $1\le i\le n$.
\end{proposition}

To start the induction, we need 

\begin{lemma}\label{3}
$X\to \sigma(X)$ induces trivial map on $H_1$.
\end{lemma}

\begin{proof} Recall  $$i_1: X\to X\times X, \, i_2:  X\to X\times X, \, \Delta : X\to X\times X$$
 be the embedding of $X$ to the first factor, the second factor,
and diagonal map respectively, and  
$$q: X\times X \to \sigma(X)$$
be the quotient map.
Since in  construction of $\sigma(X)$, the first factor $X$ and the diagonal are identified canonically,  we have
$$q\circ\Delta=q\circ i_1  $$
and the embedding $e: X\to \sigma (X)$ is given by 
$$e=q\circ i_2.$$
Applying Kunneth formular \cite[Theorem 3B.6.]{Ha1} to $H_1(X\times X)$, since $\textrm{Tor} (H_0(X), H_0(X))=\textrm{Tor}(\mathbb{Z},\mathbb{Z})=0$,
we have $$H_1(X\times X)=H_1(X)\otimes \mathbb{Z} \oplus \mathbb{Z}\otimes  H_1(X\times X).$$

Then one can derived that

$$i_{1*}+i_{2*}=\Delta_*.$$
So we have 
$$e_*=q_*\circ i_{2*}= q_*\circ (\Delta_*-i_{1*})= q_*\circ \Delta_*- q_*\circ i_{1*}=(q\circ \Delta)_*-( q\circ i_1)_*=0,$$
that is,  the embedding induces trivial map on $H_1$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{1}] By Lemma \ref{3}, Proposition \ref{1} hold for $k=1$.

Suppose Proposition \ref{1} hold for $k=n-1$.
Consider the embedding sequence
$$X\to \sigma^{3^{n-1}}(X)\to  \sigma^{ 3^{n-1}}(\sigma^{3^{n-1}}(X))=\sigma^{2\times 3^{n-1}}(X)$$
$$\to \sigma(\sigma^{2\times 3^{n-1}}(X))= \sigma^{2\times 3^{n-1}+1}(X)
\to \sigma^{3^{n}}(X).$$
By the induction hypothesis on $n-1$, the first two maps induce trivial maps on $H_i$ for $1\le i\le n$.
By Proposition \ref{2}, the embedding 
$$X\to \sigma(\sigma^{2\times 3^{n-1}}(X))= \sigma^{2\times 3^{n-1}+1}(X)$$ induces trivial maps on $H_i$ for $1\le i\le n+1$, therefore 
the embedding 
$$X\to \sigma^{3^{n}}(X)$$ induces trivial maps on $H_i$ for $1\le i\le n$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{2}]
 We will prove that for the sequence
$$A_1\overset {f_1}  \longrightarrow A_2\overset {f_2}  \longrightarrow  A_3 \overset {e}  \longrightarrow\sigma (A_3).$$
if$f_1$ and $f_2$ induce  trivial maps  on $H_i$ for  $1\le i\le n-1$,  then composition $A_1\to \sigma(A_3)$ are trivial in $H_i$ for  $1\le i\le n$.

\end{proof}

We start from the following commutative diagram

$$\begin{CD}
			A_1 @>  f_1 >> A_2 @>  f_2 >> A_3   \\
		         @VV \Delta_1 V   @VV \Delta_2 V   @ VV \Delta_3V\\
			A_1\times A_1@> f_1\times f_1 >> A_2\times A_2@> f_2\times f_2 >>A_3\times A_3.
		\end{CD} \qquad (1)  $$

		Then we have the  following commutative diagram in $H_n$

		$$\begin{CD}
			H_n(A_1) @>  f_1 >> H_n(A_2) @>  f_2 >> H_n(A_3)   \\
		         @VV \Delta_1 V   @VV \Delta_2 V   @ VV \Delta_3V\\
			H_n(A_1\times A_1)@> f_1\times f_1 >> H_n(A_2\times A_2)@> f_2\times f_2 >>H_n(A_3\times A_3).
		\end{CD} \qquad (2)  $$


		Apply Kunneth formula \cite[Theorem 3B.6.]{Ha1} to the second low of (1), we have the following commutative diagram

		$$\begin{CD}
			0 @>  >>\overset\bigoplus {_{k+l=n}} H_k(A_1)\otimes H_l(A_1) @>  j_1 >> H_n(A_1\times A_1) @>  p_1 >> \overset\bigoplus {_{k+l=n-1}} \text{Tor}( H_k(A_1), H_l(A_1))   \\
			@ VV V@VV  f_1\otimes f_1 V   @VV f_1\times f_1 V   @VV  V   \\
			0 @>  >>\overset\bigoplus {_{k+l=n}} H_k(A_2)\otimes H_l(A_2)@>  j_2 >> H_n(A_2\times A_2) @>  p_2 >> \overset\bigoplus {_{k+l=n-1}} \text{Tor}( H_k(A_2), H_l(A_2))\\
			@ VV V@VV f_2\otimes f_2 V  @VV  f_2\times f_2  V   @VV  V   \\
			0 @>  >>\overset\bigoplus {_{k+l=n}} H_k(A_3)\otimes H_l(A_3)@>  j_3 >> H_n(A_3\times A_3) @>  p_3 >>\overset\bigoplus {_{k+l=n-1}} \text{Tor}( H_k(A_3), H_l(A_1)).
		\end{CD}   \qquad(3)$$ 

		For each $\alpha \in H_n(A_1)$, we are going to prove $e \circ f_2 \circ f_1(\alpha)=0.$

		 Set $\alpha_2=f_1(\alpha)$ and $\alpha_3=f_1(\alpha_2)$. 

		 Now we explain the roles of $f_1$ and $f_2$ in Proposition \ref{2}: $f_1$ is to ensure $\Delta_2(f_1(\alpha))$ projects to $0\in \oplus_{i+j=n-1}{\Tor}(H_i(A_2),H_j(A_2))$, therefore  it is an image of an element  $\tilde \alpha_2\in  \oplus_{i+j=n}H_i(A_2)\otimes H_j(A_2)$; $f_2$ is to ensure the image of $\tilde \alpha_2$ in $\oplus_{i+j=n}H_i(A_3)\otimes H_j(A_3)$ has only  component
		 with $i=0$ or $j=0$. 


		By conditions posed on $f_1$, the right-up vertical homomorphism  in the above diagram is trivial.
		Then by using the commutativity of the right-up square of (3), we have $p_2\circ (f_1\times f_2)=0$.
		So we have 
		$$0=p_2\circ (f_1\times f_2) \circ \Delta_1(\alpha)=p_2 \circ \Delta_2  \circ f_1(\alpha)=p_2 \circ \Delta_2(\alpha_1)$$
where the second $"="$ comes from the 	the commutativity of the left square of (2). So $\Delta_2(\alpha_1)\in ker (p_2)$.
By the exactness of second low of (3), we have $j_2(\tilde \alpha_2)=\Delta_2(\alpha_1)$ for some 
\[\tilde \alpha_2\in \overset\bigoplus {_{k+l=n}} H_k(A_2)\otimes H_l(A_2).\]
Let $\tilde \alpha_3=f_2\otimes f_2(\tilde \alpha_2)$. By conditions posed on $f_2$, we have
$$\tilde \alpha_3=\alpha_{n,0}+ \alpha_{0,n},$$
where $\alpha_{n,0}\in    H_n(A_2)\otimes H_0(A_2),\,    \alpha_{0,n}\in  H_0(A_2)\otimes H_n(A_2)$.

From the definition (or construction) of $j_3$, we have
$$j_3(\tilde \alpha_3)=j_3( \alpha_{n, 0})+ j_3( \alpha_{0,n})=i_1(\beta_1)+i_2(\beta_2),$$
where $\beta_1, \beta_2\in H_n (A_3)$. Then we have 


$$\Delta_3(\alpha_3)=j_3(\tilde \alpha_3)=i_1(\beta_1)+i_2(\beta_2),$$
where the first $"="$ follows from the commutativity of both the right square of (2) and middle-down square of (3).
Let $$p_1: A_3\times A_3\to A_3$$ be the projection  to its the first factor, we have
$$p_1\circ i_1=id_{A_3}, \, p_1\circ \Delta=id_{A_3}, \, p_1\circ i_2=0.$$

So 
$$\alpha_3=(p_1\circ \Delta)(\alpha_3)=p_{1}\circ (i_1(\beta_1)+i_2(\beta_2))=p_{1}\circ i_1(\beta_1)+p_{1}\circ i_2(\beta_2)=\beta_1.$$
Similar arguments show that $\alpha_3=\beta_2$. So we have



$$\Delta_3(\alpha_3)=i_1(\alpha_3)+i_2(\alpha_3).$$


Now consider the quotient map $q_3: A_3 \times A_3\to \sigma(A_3)$. As we see in the proof of Lemma \ref{3},
$q_3\circ  \Delta_3(\alpha_3)=q_3\circ  i_1(\alpha_3)$, so we have 
$$0=q_3\circ  i_2(\alpha_3)=q_3\circ  i_2 \circ  f_2\circ f_1(\alpha)=e \circ  f_2\circ f_1(\alpha).$$
This finishes the proof.
\end{proof}






\subsection{Manifolds with  finite $\pi_1$ bound manifolds with  finite $\pi_1$} In this section, we prove Theorem \ref{main}. We start with a 
algebraic lemma.

\begin{lemma}\label{Reduction Thm}
Suppose $G$ is a finitely-generated residually-finite group and $H$ is a finite group and $\phi:H\to G$ is an injective homomorphism.
Then there exists a finite group $G_1$ and a homomorphism $\psi:G\to G_1$ such that the composite map
$$\psi\circ\phi:H\to G\to G_1$$
is injective.
\end{lemma}
\begin{proof}
Note that $\phi(H)\subset G$ is a finite subgroup. Since $G$ is residually-finite, for any $h\in H$, $h\ne e$, there exists a finite-index normal subgroup $N(h)\subset G$ such that $h\notin N(h)$.
Write $H=\{h_1=e,h_2,...,h_m\}$ where $m=|H|$. Then for any $2\le i\le m$, there exists a finite-index normal subgroup $N_i\subset G$ such that $h_i\notin N_i$.
Let $N=\cap_{i=2}^mN_i$. Then $N\subset G$ is a finite-index normal subgroup.
Note that for any $2\le i\le m$, we have $h_i\notin N_i$. So $h_i\notin N$. Therefore $H\cap N=\{e\}$.
 Let $G_1=G/N$ and $\psi:G\to G_1$ be the quotient map.
Then
$$ker(\psi)\cap \phi(H)=N\cap \phi(H)=\{e\}.$$
Therefore we get an  injective composite map
$$\psi\circ\phi:H\to G\to G_1.$$
\end{proof}

Now we restate Theorem \ref{main} as Theorem \ref{main2}.  Theorem \ref{main2} (1) is known  \cite{Hau}, we reprove it in our route,
then use it to prove  Theorem \ref{main2} (2) and (3), that is our Theorem \ref{main}.
\begin{theorem}\label{main2}
Suppose $M$ is a closed oriented bounding $n$-manifold. Then 
\begin{enumerate}
    \item $M$ $\pi_1$-injectively bounds a compact oriented $(n+1)$-manifold.
    \item $M$ $\pi_1$-injectively bounds a compact oriented $(n+1)$-manifold
with residually finite $\pi_1$ if $\pi_1(M)$ is residually finite.
\item $M$ $\pi_1$-injectively bounds a compact oriented $(n+1)$-manifold with finite $\pi_1$ if $\pi_1(M)$ is finite. 
\end{enumerate}
 \end{theorem}

\begin{proof}[Proof of Theorem \ref{main2}]
(1) Let $X_0=M$ be a closed oriented $n$-manifold.  Then we have  the  sequence of embeddings and its mapping telescope
$$\tau: X=X_0\to X_1\to X_2\to ...  \to X_{n-1} \to X_n\to ...\to  X_\infty.$$

By Proposition \ref{zero1}, we have $H_*(X_\infty)=H_*(\text{point})$. Since $M=0\in \Omega_n$,
by Theorem \ref{Atiyah}, the map $\tau: M\to X_\infty$ extends to a map $\tilde \tau: W\to X_\infty$ for a compact $(n+1)$-manifold
$W$ such that $\partial W=M$, more precisely
$$\tilde \tau \circ i =\tau : M\to X_\infty,$$
where $i: M\to W$ is the inclusion.
Since $W$ is compact, $\tilde \tau(W)\subset X_n$ for some $n$. 
By Proposition \ref{surgery}, we may assume the inclusion map $\tilde\tau_n: W\to X_n$ is $\pi_1$-isomorphic.
Then we have 
$$\tilde \tau_n \circ i =\tau_n : M\to X_n.$$

By Proposition \ref{tech3} (1), $\tau_n: M\to X_n$ is $\pi_1$-injective. 
Since $\tilde \tau_n$ is $\pi_1$-isomorphism, it concludes that $i: M\to W$ is $\pi_1$-injective.








(2) If $\pi_1(M)$ is residually-finite, then by Proposition \ref{tech3} (2), $\pi_1(X_n)$ is residually-finite. Since $\pi_1(W)\cong\pi_1(X_n)$, we get that $\pi_1(W)$ is residually-finite. 

(3) Suppose $\pi_1(M)$ is finite. Then it is residually-finite. By (2), $M$ $\pi_1$-injectively bounds 
a compact oriented $(n+1)$-manifold $W_0$ with residually-finite $\pi_1$.


Let $i_0:M\to W_0$ be the inclusion map. Then we have an injective map
$$\phi=(i_0)_*:H=\pi_1(M)\to\pi_1(W_0)=G.$$
%Then $H$ is a finite group and $\phi:H\to G$ is injective.
Now apply Lemma \ref{Reduction Thm}, there is a finite group $G_1$ and a homomorphism $\psi:G\to G_1$ such that the composite map
$$\psi\circ\phi:H\to G\to G_1$$
is injective.
There exists a map
$$F:W_0\to K(G_1,1)$$
such that $F_*=\psi:\pi_1(W_0)\to G_1.$
Let $$f=F|_M=F\circ i_0:M\to W_0 \to K(G_1,1).$$
Clearly $f$ extends to $W_0$ and $f_*=\psi\circ\phi:\pi_1(M)\to G_1$ is injective.
By Proposition \ref{surgery}, there exists another compact oriented $(n+1)$-manifold $W$ with $\partial W=M$ such that $f$ can be extended to $F':W\to K(G_1,1)$
such that the induced map
$$F'_*:\pi_1(W)\to K(G_1,1)$$ is an isomorphism. 
Let $i:M=\partial W\to W$ be the inclusion map. Since $$f=F'|_M=F\circ i:M\to W\to K(G_1,1),$$ and $f$ is $\pi_1$-injective, we get the inclusion map $i:M\to W$ is $\pi_1$-injective. Note that $\pi_1(W)\cong G_1$ is finite. 
\end{proof}

