\section{Minimal bounding index $O_b(Y)$}
\subsection{Finite index bounding and  virtual achirality of aspherical 3-manifolds} 


Now we state a more comprehensive version of Theorem \ref{thm: O(Y)=2 or finite}.


\begin{theorem}\label{O(Y)=2 or finite} Let $Y$ be a closed, orientable 3-manifold.
\begin{enumerate}
 \item If $Y$ is aspherical, then $O_{b}(Y)<\infty$ implies that  $Y$ is virtually achiral.
    \item  If $Y$ admits an orientation reversing free involution, then $O_{b}(Y)=2$. The reverse is also true if $Y$ is hyperbolic. 

 \item    Suppose $Y$ $\pi_1$-injectively bounds a compact orientable 4-manifold $W$. Then for any integer $d>0$, $Y$ $\pi_1$-injectively bounds a compact orientable 4-manifold $W_d$ such that \[|\pi_1(W_d): \pi_1(Y)|=d|\pi_1(W): \pi_1(Y)|.\]
 \end{enumerate}  
\end{theorem}


We start with some technical lemmas. 

\begin{lemma}\label{lem: Haken cover}
Let $Y$ be an aspherical 3-manifold. Suppose $G$ contains $\pi_{1}(Y)$ as a finite-index subgroup. Then there exists a finite-sheeted covering map $p:\widetilde{Y}\to Y$ such that $\widetilde{Y}$ is Haken and $p_{*}(\pi_{1}(\widetilde{Y}))$ is a normal subgroup of $G$.
\end{lemma}
\begin{proof}
 Since $Y$ is aspherical, there exists a finite cover $p_{1}:Y_{1}\to Y$ such that $Y_{1}$ is Haken \cite{Ag}. Let \[H_{1}=p_{1,*}(\pi_{1}(Y_{1}))\subset \pi_{1}(Y)\subset G.\] Consider the group
\[
H_{2}:=\bigcap\limits_{\gamma\in G} \gamma\cdot H_{1}\cdot \gamma^{-1}.
\]
Then $H_{2}$ is a finite-index normal subgroup of both $H_{1}$ and $G$. Let $p_{2}: Y_{2} \to Y_{1}$ be the covering space that corresponds to  $H_{2}$.  Then $Y_{2}$ is also Haken. The proof is finished by setting $\widetilde{Y}=Y_{2}$ and $p=p_{1}\circ p_{2}$.   \end{proof}

\begin{lemma}\label{lem: orientation reversing deck transformation}
Let $i:J\to G$ be the inclusion of a finite-index normal subgroup. Suppose that $H_{3}(J)=\mathbb{Z}$ and that the map 
\[
i_{*} : H_{3}(J)\to H_{3}(G)
\]
is trivial. Then there exists $\gamma\in G\setminus J$ such that $\phi_{\gamma,*}=-\operatorname{Id}$. Here  
\[\phi_{\gamma,*}: H_{3}(J)\to H_{3}(J)\] is the map induced by automorphism \[\phi_{\gamma}:J\to J,\quad g\mapsto \gamma g\gamma^{-1}.\]
\end{lemma}
\begin{proof} We let $K=K(G,1)$ and let $p:\widetilde{K}\to K$ be the normal covering space that corresponds to $J$. Then \[p_{*}: \mathbb{Z}\cong H_{3}(\widetilde{K})\to H_{3}(K)\]
is trivial because it equals  $i_{*}$. Since $H_{3}(J)=\mathbb{Z}$, each $\phi_{\gamma,*}=\pm \operatorname{Id}$. Suppose $\phi_{\gamma,*}\neq -\operatorname{Id}$ for all $\gamma$. Then the group of deck transformations on $\widetilde{K}$ acts trivially on $H_{3}(\widetilde{K})$. By the universal coefficient theorem, the group of deck transformations also acts trivially on $H^{3}(\widetilde{K};\mathbb{Q})$. Therefore, 
\[p^{*}: H^{3}(K;\mathbb{Q})\to H^{3}(\widetilde{K};\mathbb{Q})\]
is an injection (see \cite[Proposition 3G1]{Ha1}). This is a contradiction.
\end{proof}

\begin{lemma}\label{lem: embedding to Iso(H)}
Let $J$ be  a discrete subgroup of $\operatorname{Iso}(H^3)$ with finite covolume. Suppose $J$ is an index-2 subgroup of $G$ and the inclusion $J\to G$ has no left inverse. Then there exists an embedding $\psi:G\to \operatorname{Iso}(H^3)$ such that $\psi$ sends every element of $J$ to itself and $\psi(G)$ is a finite covolume discrete subgroup of  $\operatorname{Iso}(H^3)$.\end{lemma}
\begin{proof}
Take any $g\in G\setminus J$. Consider the automorphism 
\[
\phi_{g}: J\to J\quad h\mapsto g h g^{-1}.
\]
By Mostow Rigidity, there is a $\gamma \in \operatorname{Iso}(H^3)$ such that $\phi_{g}(h)=\gamma h \gamma^{-1}$ for all $h\in J$. Then we have 
$$g^2hg^{-2}=\phi_{g}^2(h)=\gamma^2h\gamma^{-2}$$ 
for any $h\in J$. That means $\gamma^{2}g^{-2}\in \operatorname{Iso}(H^3)$ commutes with all elements in $J$. Since $J$ is a non-elementary Kleinian group, which implies that 
$\gamma^2=g^2$ \cite[Lemma 1.2.4]{MR}. Consider the 
coset decomposition 
$G=J\sqcup gJ$. We define a map 
$\psi: G\to \operatorname{Iso}(H^3)$
\[
\psi(h)=\begin{cases} h &\text{ if } h\in J,\\
\gamma g^{-1}h &\text{ if } h\notin J.
\end{cases}
\]
Then $\psi$ is a group homomorphism. Since $\psi$ restricts to the identity map on $J$, we have the commutative diagram 
\[
\xymatrix{
J\ar@{=}[d]\ar@{^{(}->}[r] & G\ar@{->>}[d]^{\psi}\ar@{->>}[r] & G/J\cong \mathbb{Z}/2\ar@{->>}[d]^{\psi/J}\\
\psi(J)\ar@{^{(}->}[r]& \psi(G)\ar@{->>}[r] &\psi(G)/\psi(J).
}
\]
Since the inclusion $J\hookrightarrow G$ has no left inverse, $\psi(G)$ must be strictly larger then $\psi(J)$. Hence the group $\psi(G)/\psi(J)$ is nontrivial and the surjective map $\psi/J$ must also be injective. This implies $\psi$ is injective as well.
\end{proof}

