\subsection{Minimal bounding indices  for lens spaces} 
Let $$d(p)=\min\{d\ge 3|\, d|p-1\}.$$ We restate %the first half of 
Theorem \ref{O(Y)=3} as 

\begin{theorem}\label{O_b(Y)=3}
For each prime $p\ge 5$, $O_b(L(p,q))=d(p).$ 
\end{theorem}

We start with some known facts and  technical lemmas. 

\begin{lemma}\label{22}

{\rm (1)} $H_{2l}(\ZZ_p)=0$,  $H_{2l-1}(\ZZ_p)=\ZZ_p$.


{\rm (2)} $H_{l}(\ZZ_p, \mathbb F_p)=\mathbb F_p$,  $H^{l}(\ZZ_p, \mathbb F_p)=\mathbb F_p$;

