\section{Notations} \label{notation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Throughout this paper, we use the notation $\Lambda \in \mathbb{R}^+$ to denote the frequency label for the $\kappa\gamma$ plane wave modes. The operator ${\cal A}_{\Lambda, \kappa, \gamma}$ represents the annihilation operator associated with such a mode. On the other hand, $\Omega \in \mathbb{R}$ denotes the frequency parameter used for $\kappa$-Rindler modes, following the convention introduced in \cite{Azizi2023}. The corresponding annihilation operators for the $\kappa$-Rindler modes are denoted by ${\cal B}_{\Omega, \kappa}$.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Gamma Integrals} \label{app.gamma}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


We use the standard Gamma function identity
%%%%%
\begin{align}
\int_0^\infty u^{s-1} e^{-bu} \, \mathrm{d}u = b^{-s} \Gamma(s),
\end{align}
%%%%%
which holds for $b, s \in \mathbb{C}$ with $\Re(b) > 0$. Therefore, the regulated integrals evaluate to
%%%%%
\begin{align}
\int_{-\infty}^{+\infty} \mathrm{d} u \, \theta(u) u^{i\Omega - 1} e^{+i\Lambda u} 
&= \int_{0}^{\infty} u^{i\Omega - 1} e^{+i\Lambda u} \, \mathrm{d}u 
= \Lambda^{-i\Omega} e^{-\frac{\pi \Omega}{2}} \Gamma(i\Omega), \nn\\
%%%%%
\int_{-\infty}^{+\infty} \mathrm{d} u \, \theta(u) u^{i\Omega - 1} e^{-i\Lambda u}
&= \int_{0}^{\infty} u^{i\Omega - 1} e^{-i\Lambda u} \, \mathrm{d}u 
= \Lambda^{-i\Omega} e^{+\frac{\pi \Omega}{2}} \Gamma(i\Omega),
\end{align}
%%%%%
where we assume $\Lambda > 0$. Identical results hold for the integrals over $\theta(-u)$.




%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Derivation: \texorpdfstring{$\kappa\gamma$}{kappa-gamma}-Plane Wave in terms of \texorpdfstring{$\kappa'$}{kappa'}-Rindler Operators} \label{app:derivation_kg_in_kr}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

This appendix provides a detailed derivation of the Bogoliubov transformation that expresses the $\kappa\gamma$ plane wave operators (${\cal A}_{\Lambda, \kappa, \gamma}$) in terms of the $\kappa'$-Rindler operators (${\cal B}_{\Omega, \kappa'}$).

Our strategy is as follows:
\begin{enumerate}
    \item Start with the identity $\Phi(u) = \Phi(u)$, where the field is expanded in the $\kappa\gamma$-plane wave basis on one side and the $\kappa'$-Rindler basis on the other.
    \item Apply the Fourier transforms $\int du \, e^{\pm i\Lambda_0 u}$ to this identity to create a system of two algebraic equations.
    \item Solve this system for the operator ${\cal A}_{\Lambda_0, \kappa, \gamma}$.
\end{enumerate}

\subsection{Fourier Projection of the Field Expansions}

First, we project the $\kappa\gamma$ plane wave expansion. Applying the Fourier transform to the field $\Phi(u)$ for a fixed frequency $\Lambda_0 > 0$ yields a direct relationship for its operators:
%%%%%
\begin{align}
\int_{-\infty}^{+\infty} du \, e^{i\Lambda_0 u} \Phi(u) &= \frac{2\pi}{\sqrt{{\cal N}_{\Lambda_0,\kappa}}} \Bigg\{ e^{\frac{\pi\Lambda_0}{2\kappa} + i\gamma} {\cal A}_{\Lambda_0,\kappa,\gamma} + e^{-\frac{\pi\Lambda_0}{2\kappa} + i\gamma} {\cal A}^\dagger_{\mathbf{\Lambda_0},\kappa,\gamma} \Bigg\}, \label{eq:fourier_kg_1} \\
\int_{-\infty}^{+\infty} du \, e^{-i\Lambda_0 u} \Phi(u) &= \frac{2\pi}{\sqrt{{\cal N}_{\Lambda_0,\kappa}}} \Bigg\{ e^{-\frac{\pi\Lambda_0}{2\kappa} - i\gamma} {\cal A}_{\Lambda_0,\kappa,\gamma} + e^{\frac{\pi\Lambda_0}{2\kappa} - i\gamma} {\cal A}^\dagger_{\Lambda_0,\kappa,\gamma} \Bigg\}. \label{eq:fourier_kg_2}
\end{align}
%%%%%
Note: In Eq. \eqref{eq:fourier_kg_1}, we have corrected a likely typo from the original draft, changing ${\cal A}^\dagger_{-\Lambda_0,\kappa,\gamma}$ to ${\cal A}^\dagger_{\Lambda_0,\kappa,\gamma}$ to match the positive frequency expansion.

Next, we apply the same Fourier transforms to the $\kappa'$-Rindler expansion of $\Phi(u)$. This is more involved, requiring the Gamma function integrals detailed in Appendix \ref{app.gamma}. Let's define the result of this projection as $\mathcal{M}_{\Lambda_0}$:
%%%%%
\begin{align}
\mathcal{M}_{\Lambda_0} \equiv \int_{-\infty}^{+\infty} du\, e^{i\Lambda_0 u} \, \Phi(u) \bigg|_{\text{Rindler basis}}
\end{align}
%%%%%
Explicitly,
%%%%%
\begin{align}
\mathcal{M}_{\Lambda_0} =&
\int_{-\infty}^{+\infty} \frac{d\Omega \; i}{\sqrt{{\cal N}_{\Omega,\kappa'}}}
\Bigg\{
\left(
- \, e^{\frac{\pi \Omega}{2}} e^{\frac{\pi \Omega}{2\kappa'}}
+ e^{-\frac{\pi \Omega}{2}}\, e^{-\frac{\pi \Omega}{2\kappa'}}
\right) \Lambda_0^{-(1+i\Omega)} 
\Gamma(1+i\Omega)\, \mathcal{B}_{\Omega,\kappa'}\nn\\
%%%%%%%%%
&\phantom{\int_{-\infty}^{+\infty} \frac{d\Omega \; i}{\sqrt{{\cal N}_{\Omega,\kappa'}}}
\Bigg\{}
+ \left(-  e^{-\frac{\pi \Omega}{2}}\, e^{\frac{\pi \Omega}{2\kappa'}}
-  e^{\frac{\pi \Omega}{2}}\, e^{-\frac{\pi \Omega}{2\kappa'}}
\right) \Lambda_0^{-(1-i\Omega)}
\Gamma(1-i\Omega)\, \mathcal{B}^\dagger_{\Omega,\kappa'}
\Bigg\}.
\end{align}
%%%%%
The projection with $e^{-i\Lambda_0 u}$ simply yields the conjugate, $\mathcal{M}^{\dagger}_{\Lambda_0}$.

\subsection{System of Equations and Solution}

By equating the results from projecting both bases, we obtain a system of two linear equations relating the operators of the two frames:
%%%%%
\begin{align}
\frac{2\pi}{\sqrt{{\cal N}_{\Lambda_0,\kappa}}} \Bigg\{ e^{\frac{\pi\Lambda_0}{2\kappa} + i\gamma} {\cal A}_{\Lambda_0,\kappa,\gamma} + e^{-\frac{\pi\Lambda_0}{2\kappa} + i\gamma} {\cal A}^\dagger_{\Lambda_0,\kappa,\gamma} \Bigg\} &= \mathcal{M}_{\Lambda_0}, \\
\frac{2\pi}{\sqrt{{\cal N}_{\Lambda_0,\kappa}}} \Bigg\{ e^{-\frac{\pi\Lambda_0}{2\kappa} - i\gamma} {\cal A}_{\Lambda_0,\kappa,\gamma} + e^{\frac{\pi\Lambda_0}{2\kappa} - i\gamma} {\cal A}^\dagger_{\Lambda_0,\kappa,\gamma} \Bigg\} &= \mathcal{M}^{\dagger}_{\Lambda_0}.
\end{align}
%%%%%
This can be conveniently written in matrix form:
%%%%%
\begin{align}
\begin{pmatrix}
e^{\frac{\pi\Lambda_0}{2\kappa}}e^{i\gamma} & e^{-\frac{\pi\Lambda_0}{2\kappa}}e^{i\gamma} \\ 
e^{-\frac{\pi\Lambda_0}{2\kappa}}e^{-i\gamma} & e^{\frac{\pi\Lambda_0}{2\kappa}}e^{-i\gamma}
\end{pmatrix}
\begin{pmatrix}
{\cal A}_{\Lambda_0, \kappa, \gamma} \\
{\cal A}^\dagger_{\Lambda_0, \kappa, \gamma}
\end{pmatrix}
= \frac{\sqrt{{\cal N}_{\Lambda_0,\kappa}}}{2\pi}
\begin{pmatrix}
\mathcal{M}_{\Lambda_0} \\
\mathcal{M}^{\dagger}_{\Lambda_0}
\end{pmatrix}
\end{align}
%%%%%
The determinant of the matrix on the left is $2\sinh(\frac{\pi\Lambda_0}{\kappa})$. We can now solve for ${\cal A}_{\Lambda_0, \kappa, \gamma}$ by inverting the matrix:
%%%%%
\begin{align}
\begin{pmatrix}
{\cal A}_{\Lambda_0, \kappa, \gamma} \\
{\cal A}^\dagger_{\Lambda_0, \kappa, \gamma}
\end{pmatrix}
=
\frac{1}{2\sinh\left(\frac{\pi\Lambda_0}{\kappa}\right)}
\begin{pmatrix}
e^{\frac{\pi\Lambda_0}{2\kappa}}e^{-i\gamma} 
& -e^{-\frac{\pi\Lambda_0}{2\kappa}}e^{i\gamma} \\
-e^{-\frac{\pi\Lambda_0}{2\kappa}}e^{-i\gamma}
& e^{\frac{\pi\Lambda_0}{2\kappa}}e^{i\gamma}
\end{pmatrix}
\frac{\sqrt{{\cal N}_{\Lambda_0,\kappa}}}{2\pi}
\begin{pmatrix}
\mathcal{M}_{\Lambda_0} \\
\mathcal{M}^{\dagger}_{\Lambda_0}
\end{pmatrix}.
\end{align}
%%%%%
Focusing on the top row gives the expression for the annihilation operator:
%%%%%
\begin{align}
{\cal A}_{\Lambda_0,\kappa,\gamma} = \frac{\sqrt{{\cal N}_{\Lambda_0,\kappa}}}{4\pi\sinh(\frac{\pi\Lambda_0}{\kappa})} \left( e^{\frac{\pi\Lambda_0}{2\kappa}} e^{-i\gamma} \mathcal{M}_{\Lambda_0} - e^{-\frac{\pi\Lambda_0}{2\kappa}} e^{i\gamma} \mathcal{M}^{\dagger}_{\Lambda_0} \right).
\end{align}
%%%%%
\subsection{Final Result}
After substituting the full integral expression for $\mathcal{M}_{\Lambda_0}$ and performing the algebraic simplification of the hyperbolic and exponential terms, we arrive at the final transformation. The result expresses the $\kappa\gamma$ plane wave annihilation operator as an integral over the $\kappa'$-Rindler operators:
%%%%%
\begin{align}
{\cal A}_{\Lambda,\kappa,\gamma} = & -\frac{\im}{2 \pi} \int_{-\infty}^{\infty} d \Omega \, \frac{1}{\sqrt{\Lambda \Omega \sinh(\frac{\pi \Lambda}{\kappa}) \sinh(\frac{\pi \Omega}{\kappa'})}} \label{KGPW-in-KR_app} \\ %%%%%
%%%%%%%
& \times \Bigg \{ \Lambda^{-\im \Omega}\, \Gamma(1+\im \Omega)
\Bigg[ e^{\frac{\pi \Lambda}{2 \kappa}-i\gamma} 
\sinh \left(\ft{\pi \Omega}{2}\big(\frac{1}{\kappa'}+1\big)\right) 
+e^{-\frac{\pi \Lambda}{2 \kappa}+i\gamma} \sinh \left(\ft{\pi \Omega}{2}
\big(\frac{1}{\kappa'}-1\big)\right) \Bigg] {\cal B}_{\Omega,\kappa'} \nn\\ %%%%%
%%%%%%%%%
& \quad \quad +
\Lambda^{\im \Omega}\, \Gamma(1-\im \Omega)
\Bigg[ e^{\frac{\pi \Lambda}{2 \kappa}-i\gamma} 
\sinh \left(\ft{\pi \Omega}{2}\big(\frac{1}{\kappa'}-1\big)\right) 
+ e^{-\frac{\pi \Lambda}{2 \kappa}+i\gamma} \sinh \left(\ft{\pi \Omega}{2}
\big(\frac{1}{\kappa'}+1\big)\right) \Bigg] {\cal B}^{\dagger}_{\Omega,\kappa'}
\Bigg \}\,. \nn
\end{align}
%%%%%
This is the first of the two ``Mother of All Bogoliubov Transformations,'' generalized to include the phase parameter $\gamma$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Derivation: \texorpdfstring{$\kappa'$}{kappa'}-Rindler in terms of \texorpdfstring{$\kappa\gamma$}{kappa-gamma}-Plane Wave Operators}
\label{app:derivation_kr_in_kg}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

This appendix details the derivation of the Bogoliubov transformation that expresses the $\kappa$-Rindler operators ${\cal B}_{\Omega, \kappa'}$ in terms of the $\kappa\gamma$ plane wave operators ${\cal A}_{\Lambda, \kappa, \gamma}$. The method involves projecting the quantum field $\Phi(u)$ onto the appropriate basis functions for each wedge and solving the resulting system of equations.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Field Expansions}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We begin by writing the massless scalar field $\Phi(u)$ in both the $\kappa\gamma$ plane wave and $\kappa'$-Rindler bases.

The $\kappa\gamma$ plane wave expansion is:
%%%%%%%%%%%%%%
\begin{align}
\Phi(u) = \int_{0}^{\infty} \frac{d\Lambda}{\sqrt{8 \pi \Lambda \sinh(\frac{\pi \Lambda}{\kappa})}} \bigg\{ & \Big(e^{\frac{\pi \Lambda}{2\kappa}} e^{i\gamma} e^{-i\Lambda u} + e^{-\frac{\pi \Lambda}{2\kappa}} e^{-i\gamma} e^{i\Lambda u}\Big) {\cal A}_{\Lambda,\kappa,\gamma} \nn \nn\\
&+ \Big(e^{\frac{\pi \Lambda}{2\kappa}} e^{-i\gamma} e^{i\Lambda u} + e^{-\frac{\pi \Lambda}{2\kappa}} e^{i\gamma} e^{-i\Lambda u}\Big) {\cal A}^{\dagger}_{\Lambda,\kappa,\gamma} \bigg\}\,.
\end{align}
%%%%%%%%%%%%%%
The $\kappa'$-Rindler expansion is defined piecewise across the right ($u<0$) and left ($u>0$) Rindler wedges:
\begin{align}
\Phi(u) = & \theta(-u) \int_{-\infty}^{\infty} \frac{d\Omega'}{\sqrt{8 \pi \Omega' \sinh(\frac{\pi \Omega'}{\kappa'})}} \Big\{(-u)^{i\Omega'} e^{\frac{\pi \Omega'}{2\kappa'}} {\cal B}_{\Omega',\kappa'} + \text{h.c.}\Big\} \nn \nn\\
&+ \theta(u) \int_{-\infty}^{\infty} \frac{d\Omega'}{\sqrt{8 \pi \Omega' \sinh(\frac{\pi \Omega'}{\kappa'})}} \Big\{ u^{i\Omega'} e^{-\frac{\pi \Omega'}{2\kappa'}} {\cal B}_{\Omega',\kappa'} + \text{h.c.}\Big\}\,.
\end{align}
Note that h.c. stands for the Hermitian conjugate of the preceding term.

\subsection{Projection onto Rindler Modes}

To isolate the $\kappa'$-Rindler operators, we project $\Phi(u)$ using weighted integrals that act as inverse Mellin transforms for each wedge. This provides a system of two equations for the two unknowns, ${\cal B}_{\Omega, \kappa'}$ and ${\cal B}^\dagger_{\Omega, \kappa'}$. We then find two distinct equations:
%%%%%%%%%%%%%%%%%
\begin{enumerate}
    \item Projection onto the Right Wedge ($u<0$)
    \begin{align}
\int_{-\infty}^0 du\, (-u)^{i\Omega-1} \Phi(u) = \frac{2\pi}{\sqrt{8\pi\Omega\sinh(\frac{\pi\Omega}{\kappa'})}} \left( e^{-\frac{\pi\Omega}{2\kappa'}}{\cal B}_{-\Omega,\kappa'} 
+ e^{\frac{\pi\Omega}{2\kappa'}} 
{\cal B}^\dagger_{\Omega,\kappa'} \right)\,.
\end{align}
\item 
Projection onto the Left Wedge ($u>0$)
%%%%%%%%%
\begin{align}
\int_0^\infty du\, u^{i\Omega-1} \Phi(u) = \frac{2\pi}{\sqrt{8\pi\Omega\sinh(\frac{\pi\Omega}{\kappa'})}} 
\left( e^{\frac{\pi\Omega}{2\kappa'}}{\cal B}_{-\Omega,\kappa'} 
+ e^{-\frac{\pi\Omega}{2\kappa'}} {\cal B}^\dagger_{-\Omega,\kappa'} \right)\,.
\end{align}
%%%%%%
\end{enumerate}





\subsection{Solving the System of Equations}

We now have a system of two linear equations. We can write the system in matrix form. Let the right-hand side of the projections onto the $\kappa\gamma$ basis be defined as $\int d\Lambda (M_{\Omega\Lambda} {\cal A}_{\Lambda,\kappa,\gamma} + N_{\Omega\Lambda} {\cal A}^\dagger_{\Lambda,\kappa,\gamma})$ and $\int d\Lambda (K_{\Omega\Lambda} {\cal A}_{\Lambda,\kappa,\gamma} + P_{\Omega\Lambda} {\cal A}^\dagger_{\Lambda,\kappa,\gamma})$ respectively.
%%%%%%%%%%%%%%%%%%
\begin{align}
\begin{pmatrix}
e^{\frac{\pi\Omega}{2\kappa'}} 
& e^{-\frac{\pi\Omega}{2\kappa'}} \\
e^{-\frac{\pi\Omega}{2\kappa'}} 
& e^{\frac{\pi\Omega}{2\kappa'}}
\end{pmatrix}
%%%%%%%%%%%%%%
\begin{pmatrix}
{\cal B}_{-\Omega,\kappa'} \\
{\cal B}^\dagger_{\Omega,\kappa'}
\end{pmatrix}
%%%%%%%%%%
= \int_0^{\infty} d\Lambda
\begin{pmatrix}
M_{\Omega\Lambda} 
& N_{\Omega\Lambda} \\
K_{-\Omega\Lambda}
& P_{-\Omega\Lambda}
\end{pmatrix}
%%%%%%%%%%%%%
\begin{pmatrix}
{\cal A}_{\Lambda,\kappa,\gamma} \\
{\cal A}^\dagger_{\Lambda,\kappa,\gamma}
\end{pmatrix}\,.
\end{align}
%%%%%%%%%%%%%%%%%%%
The determinant of the matrix on the left is $2\sinh(\frac{\pi\Omega}{\kappa'})$. Inverting this matrix to solve for ${\cal B}_{\Omega, \kappa'}$ gives:
%%%%%%%%
\begin{align}
{\cal B}_{\Omega,\kappa'} = \frac{1}{2\sinh(\frac{\pi\Omega}{\kappa'})} \int d\Lambda \bigg[ &\Big(e^{\frac{\pi\Omega}{2\kappa'}}M_{\Omega\Lambda} - e^{-\frac{\pi\Omega}{2\kappa'}}K_{-\Omega\Lambda}\Big) {\cal A}_{\Lambda,\kappa,\gamma}  \nn\\
%%%%%%%%
 &+ \Big(e^{\frac{\pi\Omega}{2\kappa'}}N_{\Omega\Lambda} - e^{-\frac{\pi\Omega}{2\kappa'}}P_{-\Omega\Lambda}\Big) {\cal A}^\dagger_{\Lambda,\kappa,\gamma} \bigg]\,. \label{eq:b_solved_app}
\end{align}
%%%%%%%%
\subsection{Evaluating the Integral Kernels and Simplifying}

The next step is to evaluate the integral kernels $M, N, K, P$ by performing the projections on the $\kappa\gamma$ plane wave expansion, using the Gamma function integral identity. After a lengthy but straightforward calculation, the expressions for the kernels are inserted into Eq. (\ref{eq:b_solved_app}). The resulting combination of terms simplifies significantly.

After combining all terms, we arrive at the final Bogoliubov transformation:
%%%%%%%%%%%%%%%%%%%%%%
\begin{align}
{\cal B}_{\Omega, \kappa'} =&\frac{\operatorname{sgn}(\Omega)}{2 \pi} \int_0^{\infty} d \Lambda \sqrt{\frac{\Omega}{
{ \sinh(\frac{\pi\Omega}{\kappa'})\Lambda \sinh(\frac{\pi\Lambda}{\kappa})}}}\Lambda^{\im \Omega} \Gamma(-\im \Omega) \nn\\
%%%%%
&\times\Bigg\{\,\left[
e^{\frac{\pi \Lambda}{2 \kappa}+i\gamma} \sinh \left(\frac{\pi \Omega}{2}\left(\frac{1}{\kappa'}+1\right)\right)+e^{-\frac{\pi \Lambda}{2 \kappa}-i\gamma} \sinh \left(\frac{\pi \Omega}{2}\left(\frac{1}{\kappa'}-1\right)\right)\right] {\cal A}_{\Lambda, \kappa, \gamma}\nn\\
%%%%
&\phantom{\times\Bigg\{}
+ \left[
e^{\frac{\pi \Lambda}{2 \kappa}-i\gamma} \sinh \left(\frac{\pi \Omega}{2}\left(\frac{1}{\kappa'}-1\right)\right)+e^{-\frac{\pi \Lambda}{2 \kappa}+i\gamma} \sinh \left(\frac{\pi \Omega}{2}\left(\frac{1}{\kappa'}+1\right)\right)\right] {\cal A}^{\dagger}_{\Lambda, \kappa, \gamma}
\Bigg\},
\end{align}
where we have used properties of the Gamma function and made a substitution to express the result over the domain $\Omega>0$.


