\title{Compound Burgers -- KdV Soliton Behaviour: Refraction, Reflection and Fusion}


\author{Darryl D. Holm$^1$, Ruiao Hu$^1$, Oliver D. Street$^{1,2}$, Hanchun Wang$^{1,3}$\footnote{Corresponding author, email: hw660@cam.ac.uk} \\ \footnotesize
(1) Department of Mathematics, Imperial College London. \\ \footnotesize
