\section{Variational derivations of Burgers, KdV and the Burgers–swept KdV system}
\label{app-derivingBurgers–swept KdV}

\subsection{Variational derivations of Burgers and KdV equations}
This appendix begins by briefly mentioning the geometric structures of the Burgers' and KdV equations. It then provides two auxialary derivations of the 
\smallskip

\paragraph{Burgers' equation in one dimension.}The Burgers' equation follows from applying Hamilton's Principle to the action corresponding to the kinetic energy Lagrangian
\begin{equation}
	\ell_{B}(u) = \int_{\mathbb{R}} \frac{u^2}{2}\,dx \,,
\end{equation}
where the variations in $u$ are taken to be \emph{Lin constrained} Euler-Poincar\'e variations given by
\begin{align*}
    \delta u = {\eta _t} + \eta u - u\eta  = \partial_t \eta - {\rm ad}_u \eta \,,
\end{align*}
for an arbitrary vector field $\eta \in \mathfrak{X}(\mathbb{R})$. In the relation above, ${\rm ad}$ denotes the standard adjoint action of the space of vector fields in itself, inherited from the group structure of the diffeomorphism group.  This variation follows from taking arbitrary variations, vanishing at the endpoints, of the flow $g_t \in {\rm Diff}(\mathbb{R})$ related to the velocity by $u = \dot{g}g^{-1}$, where concatenation has been used to denote tangent lifted group translation. The arbitrary vector field in the variation is then given by $\eta = \delta g g^{-1}$. The equation follows from Hamilton's Principle as
\begin{align*}
	0 &= \delta\int_{t_0}^{t_1} \ell_B(u)\,dt = \int_{t_0}^{t_1}\int_{\mathbb{R}} u \,\delta u \,dx\,dt
	\\
	&=  \int_{t_0}^{t_1}\int_{\mathbb{R}}  u (\partial_t \eta - {\rm ad}_u) \,dx\,dt =  \int_{t_0}^{t_1}\int_{\mathbb{R}} (\p_t u + {\rm ad}^*_uu)\,\eta\,dx\,dt \,,
\end{align*}
where ${\rm ad^*}$ is the dual operator to ${\rm ad}$ with respect to the duality pairing. Since $\eta$ is arbitrary, the fundamental lemma of the calculus of variations gives the equation
\begin{equation}
	0 = \p_tu + {\rm ad}^*_uu = \p_t u + u\p_xu + \p_x(u^2) = u_t + 3uu_x \,.
\end{equation}
\smallskip

\paragraph{The KdV equation.} The KdV equation has a noncanonical Hamiltonian structure. That is, it can be expressed in the form
\begin{equation}
	\p_t v = \mathcal{D}\frac{\delta H_{KdV}}{\delta v} \,,\quad\hbox{where}\quad \mathcal{D} = -\p_x \,,\quad\hbox{and}\quad H_{KdV} = \int_{\mathbb{R}} v^3 -  \frac{\gamma}{2} v_x^2\,dx \,.
\end{equation}
Indeed, computing the variational derivative of the Hamiltonian, this implies
\begin{equation}
	v_t = -\p_x\left( 3v^2 + \gamma v_{xx} \right) = -6vv_{x} - \gamma v_{xxx} \,,
\end{equation}
which is the well known KdV equation. Just as canonical Hamiltonian systems have a phase space variational description, this noncanonical system can be deduced from the following Lagrangian
\begin{equation}
	\ell_{KdV}(v) = \int_{\mathbb{R}} \frac12 v(\mathcal{D}^{-1}v)_t - H_{KdV}(v) \,dx =  \int_{\mathbb{R}} \frac12 v\mathcal{D}^{-1}v_t - v^3 + \frac{\gamma}{2} v_x^2 \,dx \,.
\end{equation}
Indeed, applying Hamilton's Principle, we find that
\begin{align*}
	0 &= \delta\int_{t_0}^{t_1} \ell_{KdV}(v)\,dt =  \int_{t_0}^{t_1} \frac12 \delta v\mathcal{D}^{-1}v_t + \frac12 v \mathcal{D}^{-1}\delta v_t - 3v^2\delta v + \gamma v_x\delta v_x \,dx\,dt
	\\
	&= \int_{t_0}^{t_1}\int_{\mathbb{R}} \delta v\left(\mathcal{D}^{-1}v_t - 3v^2 - \gamma v_{xx} \right) \,dx \,,
\end{align*}
and since $\delta v$ is arbitrary this implies the KdV equation.




\subsection{Variational derivation of the Burgers–swept KdV system}
\label{CoM-app}

This variational derivation of the Burgers–swept KdV system in \eqref{eq: Burgers–swept KdV} proceeds by introducing the composition of two time-dependent maps $g$ and $\phi$ in defining the following Lagrangian:
\begin{align}
\begin{split}
0 = \delta S &= \delta\!\! \int \ell(u, n, v)\,dt
= \delta \!\!\int \ell_{B}(u)+\ell_{K d V}(n, v)\,dt
\\&
=\frac12\delta\!\! \int_{\mathcal{D}} u^2 
+  \nu n_x+2 n_x^3 - \gamma n_{x x}^2 \,d x \,dt    
\label{eq: HP var appendix}
\end{split}
\end{align}
with constant $\gamma$ and Eulerian fluid variables
\begin{align}
u = \dot{g}\,g^{-1}
\,,\quad
n = \phi\,g^{-1}
\,,\quad
\nu = \phi_t\,g^{-1}
\,.   \label{eq:HP var defs appendix}
\end{align}
The variations of velocity vector field $u=\dot{g} g^{-1}$ and of 0-forms $n=\phi g^{-1}$ and $\nu= \phi_t g^{-1}$ with respect to $\eta = \delta g g^{-1}$ and $\xi = \delta \phi g^{-1}$ are calculated as follows,\\

\begin{equation*}
\begin{array}{lll}
\delta u = \delta(\dot{g} g^{-1}) & \delta n = \delta (\phi g^{-1}) & \delta \nu = \delta (\phi_t g^{-1}) \\
= (\delta g)_t g^{-1} + \dot{g} \delta g^{-1} 
& = \delta \phi g^{-1} - \phi \delta g^{-1} 
& = (\delta \phi_t) g^{-1} - \phi_t \delta g^{-1} \\
= (\delta g g^{-1})_t - \delta g (g^{-1})_t - \dot{g} g^{-1} \delta g g^{-1} 
& = \delta \phi g^{-1} - \phi g^{-1} \delta g g^{-1} 
& = (\delta \phi g^{-1})_t + \delta \phi g^{-1} g_t g^{-1} - \phi_t g^{-1} \delta g g^{-1} \\
= \eta_t + \eta u - u \eta 
& = \xi - n \eta 
& = \xi_t + \xi u - \nu \eta \\
= \eta_t - \mathcal{L}_u \eta 
& = \xi - \mathcal{L}_\eta n 
& = \xi_t + \mathcal{L}_u \xi - \mathcal{L}_\eta \nu
\end{array}
\end{equation*}

Hence, we arrive at the Euler-Poincare equations:
\begin{equation}
    \begin{aligned}
\left(\partial_t+\operatorname{ad}_u^*\right) \frac{\delta l}{\delta u} & =\frac{\delta l}{\delta n} \diamond n+\frac{\delta l}{\delta \nu} \diamond \nu 
\,,\\
\left(\partial_t+\mathcal{L}_u\right) \frac{\delta l}{\delta \nu} & =\frac{\delta l}{\delta n} 
\,,\\
\left(\partial_t+\mathcal{L}_u\right) n & =\nu
\,.\end{aligned}
\label{EP-eqns-CoM}
\end{equation}
In 1D the diamond operator is given by $\diamond=-\partial_x$, then we have the variations of the Lagrangian in \eqref{eq: HP var appendix} as: 

\begin{equation}
    \begin{aligned}
\frac{\delta l}{\delta u} & =u \mathrm{~d} x \\
\frac{\delta l}{\delta \nu} & =\frac{n_x}{2} \mathrm{~d} x=\frac{1}{2} \mathrm{~d} n \\
\frac{\delta l}{\delta n} & =-\partial_x \frac{\delta l}{\delta n_x}+\partial_{x x} \frac{\delta l}{\delta n_{x x}} =\left(-\frac{1}{2} \nu_x-6 n_x n_{x x}-\gamma n_{x x x x}\right) \mathrm{d} x \\
& =\left(-\frac{1}{2} \partial_x\left(\left(\partial_t+u \partial_x\right) n\right)-6 n_x n_{x x}-\gamma n_{x x x x}\right) \mathrm{d} x \\
&=-\frac{1}{2} \left(\partial_t+u \partial_x\right) dn-\left(6 n_x n_{x x}+\gamma n_{x x x x}\right) \mathrm{d} x
\end{aligned}
\label{BSKdV-varsCoM}
\end{equation}
The second Euler--Poincar\'e equation in \eqref{EP-eqns-CoM} and the second variational equation in \eqref{BSKdV-varsCoM} combine to yield the following:
\begin{align}
\begin{split}
    \left(\partial_t+\mathcal{L}_u\right) \frac{\delta l}{\delta \nu} &=\left(\partial_t+\mathcal{L}_u\right)\left(\frac{1}{2} \mathrm{~d} n\right)
   \\=\frac{\delta l}{\delta n}& = - \frac{1}{2}\left(\partial_t+\mathcal{L}_u\right)  dn
    -6 n_x n_{x x} \mathrm{~d} x 
    -\gamma n_{x x x x} \mathrm{~d} x 
\end{split}
\end{align}
after commuting the differential and the Lie derivative in the above equation one finds: 
\begin{equation}
    d\left[ ({{\partial _t} + {{\cal L}_u}}) n + 3{n_x}^2
    + \gamma {n_{xxx}}\right] = 0
    \,,
\end{equation}
or equivalently,
\begin{equation}
    n_{x t}+u_x n_x+u n_{x x}+6 n_x n_{x x}+\gamma n_{x x x x} = 0
\,.\end{equation}
Now defining $v=n_x$ implies the second equation in Burgers–swept KdV system:
\begin{equation}
    v_t+(uv)_x=-(6 v v_x+\gamma v_{x x x})
\,.\end{equation}
In 1D the diamond operator is given by $\diamond=-\partial_x$, then we have 
\begin{equation}
    \left(\partial_t+3 u \partial_x\right) u=-\frac{n_x}{2} \nu_x+\left(\frac{1}{2} \nu_x-6 n_x n_{x x}-n_{x x x x}\right) n_x
    \,,
\end{equation}
which is the first equation in Burgers–swept KdV system:
\begin{equation}
    u_t + 3uu_x = -v(6vv_x + \gamma v_{xxx})
    \,.
\end{equation}








