\subsection{Notations}

\begin{itemize}
	\item We fix once and for all a prime number $p > 0$. All rings and schemes in this paper are defined over $\bF_p$.
	\item We fix an algebraically closed field $k$ (of characteristic $p$).
	\item A \emph{point} denotes a closed point. We will refer to non--closed point as \emph{scheme--theoretic points}.
	\item Throughout, $A$ denotes an abelian variety over $k$ of dimension $g$, with dual abelian variety $\bighat{A}$ and normalized Poincaré bundle $\cP \in \Pic(A \times \bighat{A})$. For a point $\alpha \in \bighat{A}$, we write $\cP_\alpha \coloneqq \cP|_{A \times \alpha} \in \Pic^0(A)$. Given an integer $n \in \bZ$, multiplication by $n$ on the group law of $A$ will still be denoted $n$.
	\item A variety is a scheme $X$ which is separated and of finite type over $k$. 
	\item The symbol $F$ always denotes the absolute Frobenius of a $\bF_p$--scheme, i.e. the unique endomorphism with restrict to taking $p$--powers on affine charts.
	\item An $\bF_p$--scheme $X$ is $F$--finite if its absolute Frobenius morphism $F \colon X \to X$ is finite. 

	\item If $\pi \colon X \to S$ is a morphism, then $F_{X/S} : X \to X^{(p)}$ always denotes the relative Frobenius over $S$, i.e. the unique map fitting in the following diagram: 
	\[ \begin{tikzcd}
		X \arrow[rrrrd, "F", bend left] \arrow[rrdd, "\pi"', bend right] \arrow[rrd, "F_{X/S}", dashed] &      &                        &  &             \\
		& & X^{(p)} \arrow[rr] \arrow[d] &  & X \arrow[d, "\pi"] \\
		& & S \arrow[rr, "F"]            &  & S          
	\end{tikzcd} \] where the middle square is by definition a pullback square.
	\item Given a complex $\cA^{\bullet}$ with values in some abelian category and $i \in \bZ$, we denote by $\cH^i(\cA^{\bullet})$ its $i$--th cohomology object.
	\item Given a variety $X$, we let $D_{\coh}(X)$ denote the derived category of complex of $\cO_X$--modules $\cA^{\bullet}$ such that $\cH^i(\cA^{\bullet})$ is coherent for all $i \in \bZ$. We let $D^b_{\coh}(X) \inc D_{\coh}(X)$ denote the full subcategory of complexes $\cA^{\bullet}$ such that $\cH^i(\cA^{\bullet}) = 0$ for $\abs{i} \gg 0$.
\end{itemize}

\section{Preliminaries}

Throughout, fix a positive integer $s > 0$.

\subsection{Cartier modules and crystals}

As stated in the introduction, the main actors in positive characteristic generic vanishing theory are \emph{Cartier modules} and \emph{crystals}. Here we gather the basic definitions. We will not need any deep fact about these objects in this paper. The reader interested in further details about these objects is invited to read \cite{Blickle_Bockle_Cartier_modules_finiteness_results, Baudin_Duality_between_perverse_sheaves_and_Cartier_crystals}.

\begin{defn}
	Let $X$ be a Noetherian $\bF_p$--scheme.
	\begin{itemize}
		\item An \emph{$s$--Cartier module} is a pair ($\cM$, $\theta$) where $\cM$ is a coherent $\cO_X$--module and $\theta \colon F^s_*\cM \to \cM$ is a morphism. We call $\theta$ the \emph{structural morphism} of $\cM$. 

		\item A morphism of Cartier modules $h \colon (\cM_1, \theta_1) \to (\cM_2, \theta_2)$ is a morphism of underlying $\cO_X$--modules $h \colon \cM_1 \to \cM_2$ making the square

		\[ \begin{tikzcd}
			F^s_*\cM_1 \arrow[rr, "F^s_*h"] \arrow[d, "\theta_1"'] && F^s_*\cM_2 \arrow[d, "\theta_2"] \\
			\cM_1 \arrow[rr, "h"']                                     && \cM_2                               
		\end{tikzcd} \]
		commute. The category of $s$--Cartier modules is denoted $\Coh_X^{C^s}$.
	\end{itemize}	
\end{defn}

\begin{rem}
	Since it will not cause any confusion in this paper, we shall simply write ``Cartier module'' and omit the $s$ from the wording.
\end{rem}

Note that one can take the pushforward of a Cartier module: if $f \colon X \to Y$ is a proper morphism of Noetherian $\bF_p$--schemes and $(\cM, \theta)$ is a Cartier module on $X$, then $(f_*\cM, f_*\theta)$ defines a Cartier module on $Y$ (the properness assumption was only here to ensure that $f_*\cM$ is coherent).

\begin{example}\label{ex:Cartier_operator}
	Let us give the arguably most important example of a Cartier module (with $s = 1$): the sheaf of top differential forms. Assume that $X$ is a smooth variety, and let $\Omega_X^{\bullet}$ denote its de Rham complex. Note that although the differential $d$ is not $\cO_X$--linear, the maps $F_*d \colon F_*\Omega_X^j \to F_*\Omega_X^{j + 1}$ are $\cO_X$--linear (i.e. $d(f^ps) = f^pds$ for all $f \in \cO_X$ and $s \in \Omega_X^j$). \\

	The following important operator was defined in \cite{Cartier_une_nouvelle_operation_sur_les_formes_differentielles}:
	\begin{equation}\label{Cartier_operator}
		\begin{tikzcd}[row sep=small]
			\Omega^j_X \arrow[rr, "C^{-1}"]            && \cH^j(F_*\Omega^{\bullet}_X)                               \\
			df_1 \wedge \dots \wedge df_j \arrow[rr, mapsto] && {[f_1^{p - 1}\dots f_j^{p -1}df_1 \wedge \dots \wedge df_j]},
		\end{tikzcd}
	\end{equation}
	for $f_1, \dots, f_j \in \cO_X$. In \emph{loc.cit}, the author shows that \autoref{Cartier_operator} is an isomorphism. Hence, we define a Cartier module structure on $\omega_X \coloneqq \Omega_X^{\dim X}$ by the composition 

	\[ \begin{tikzcd}
		F_*\omega_X \arrow[rr, two heads] &  & \cH^{\dim X}(F_*\Omega_X^{\bullet}) \arrow[rr, "(C^{-1})^{-1}"] &  & \omega_X.
	\end{tikzcd} \]

	More generally, if $X$ is a normal variety, we define $\omega_X \coloneqq j_*\omega_U$, where $U$ is the smooth locus of $X$. We then obtain a Cartier structure on $\omega_X$ in this case too.
\end{example}

\begin{rem}\label{rem:def_Cartier_mod}
	\begin{enumerate}
		\item\label{itm:abuse_iterates_structure_map} Let $(\cM, \theta)$ be a Cartier module. We will abuse notations as follows: \[ \theta^e \coloneqq \theta \circ F^s_*\theta \circ \dots \circ F^{(e-1)s}_*\theta \colon F^{es}_*\cM \to \cM. \]
		\item\label{itm:notation H^0_ss} Given a proper variety $X$ and a Cartier module $(\cM, \theta)$ on $X$, we set \[ H^i_{ss, \theta}(X, \cM) \coloneqq \bigcap_{e > 0} \im\left(H^i(X, F^{es}_*\cM) \xto{\theta^e} H^i(X, \cM)\right) \inc H^i(X, \cM). \] We also write $h^i_{ss, \theta}(X, \cM) \coloneqq \dim_k H^i_{ss, \theta}(X, \cM)$, 
		and  \[ \chi_{ss, \theta}(\cM) \coloneqq \sum_i (-1)^ih^i_{ss, \theta}(X, \cM). \] Whenever the context is clear, we shall omit the $\theta$ from this notation. In order to agree with the notations from the existing literature, whenever we work with the Cartier module $\omega_X$ from \autoref{Cartier_operator}, we set \[ S^0(X, \omega_X) \coloneqq H^0_{ss}(X, \omega_X). \]
	\end{enumerate}
\end{rem}

\begin{defn}
		A Cartier module $(\cM, \theta)$ is said to be \emph{nilpotent} if $\theta^e = 0$ for some $e > 0$. These objects form a Serre subcategory of $\Coh_X^{C^s}$ (meaning that being nilpotent is stable under subobjects, quotients and extensions). The corresponding quotient category (see \stacksproj{02MS}) is denoted by $\Crys_X^{C^s}$, and the objects of this quotient category are denoted \emph{Cartier crystals}.
\end{defn}

Intuitively, working in the category of crystals allows us to forget about nilpotent phenomena. For example, a Cartier module is the zero object as a Cartier crystal if and only if it is nilpotent. More generally, a morphism $f \colon \cM \to \cN$ of Cartier modules is an isomorphism of Cartier crystals if and only if both $\ker(f)$ and $\coker(f)$ are nilpotent.

We will not need anything more about Cartier crystals in this paper. In particular, we will not need anything deep about quotient categories.

\begin{notation}\label{notation_crystals}
	If $\cM_1$ and $\cM_2$ are two Cartier modules which are isomorphic as crystals, then we shall write $\cM_1 \sim_C \cM_2$.
\end{notation}


\subsection{$V$--modules and the Fourier--Mukai transform}

Generic vanishing can be understood by how a given sheaf on an abelian variety behaves with respect to the \emph{Fourier--Mukai transform}. It turns out that the image of Cartier modules under this operation are so--called \emph{$V$--modules}. We will first start by explaining what these objects are. 

\begin{defn}[{\cite[Section 5]{Hacon_Pat_GV_Geom_Theta_Divs}}]
	The \emph{relative Verschiebung} $V_{A/k} \colon \bighat{A}^{(p)} = \bighat{A^{(p)}} \to \bighat{A}$ is by definition the dual isogeny of the relative Frobenius $F_{A/k} \colon A \to A^{(p)}$.

	Since $k$ is perfect, we can canonically identify $\bighat{A}^{(p)}$ and $\bighat{A}$ as schemes. The induced morphism $V \colon \bighat{A} \to \bighat{A}$ is called the \emph{absolute Verschiebung}. By definition, the diagram
	\[ \begin{tikzcd}
		\bighat{A} \arrow[rr, "V"] \arrow[d] &  & \bighat{A} \arrow[d] \\
		\Spec k \arrow[rr, "F^{-1}"]         &  & \Spec k             
	\end{tikzcd} \] commutes.
	\begin{itemize}
		\item A \emph{$V^s$--module} on $\bighat{A}$ is a pair $(\cN, \theta)$ where $\cN$ is a coherent sheaf on $\bighat{A}$ with a morphism $\theta \colon \cN \to V^{s, *}\cN$. A morphism of $V^s$--modules is defined as for Cartier modules: it is a morphism of underlying sheaves commuting with the $V^s$--module structures. The category of $V^s$--modules on $\bighat{A}$ is denoted $\Coh_{\bighat{A}}^{V^s}$.
		\item A $V^s$--module $(\cM, \theta)$ is nilpotent if $\theta^e = 0$ for some $e \geq 0$ (we abuse notations as in \autoref{rem:def_Cartier_mod}.\autoref{itm:abuse_iterates_structure_map}). Nilpotent modules form a Serre subcategory, whose quotient is the category of \emph{$V^s$--crystals}, denoted $\Crys_{\bighat{A}}^{V^s}$. If $\cN_1$ and $\cN_2$ are $V^s$--modules which are isomorphic as crystals, we shall write $\cN_1 \sim_V \cN_2$. 
		\item A $V^s$--module $(\cN, \theta)$ is said to be \emph{injective} if $\theta$ is injective.
	\end{itemize}
\end{defn}
\begin{rem}\label{canonical_injective_V_module}
	\begin{itemize}
		\item As for Cartier modules, we will omit the $s$ in the name ``$V^s$--module''.
		\item For any $V$--module $\cN$, there exists a canonical injective $V$--module $\cN_{\injj}$ with a surjective map $\cN \surj \cN_{\injj}$, inducing an isomorphism of crystals. Explicitly, $\cN_{\injj}$ is given by the image of $\cN \to \colim V^{es, *}\cN$.

		Note that the induced surjection $\cN \to \cN_{\injj}$ is indeed an isomorphism of $V$--crystals, since $\ker(f)$ is a nilpotent $V$--module by construction.
	\end{itemize}
\end{rem}

\begin{defn}
		Let $\phi$ denote the action of the Frobenius on $H^1(A, \cO_A)$. By \cite[Corollary p.143]{Mumford_Abelian_Varieties}, we can write \[ H^1(A, \cO_A) \cong H^1(A, \cO_A)_{ss} \oplus H^1(A, \cO_A)_{\nilp}, \] where $H^1(A, \cO_A)_{ss}$ has a basis of fixed points by $\phi$, and $H^1(A, \cO_A)_{\nilp}$ is nilpotent under the action of $\phi$. The $p$--rank of $A$ is then by definition \[ r(A) \coloneqq \dim_k H^1(A, \cO_A)_{ss} \in \{0, \dots, g\}. \]
\end{defn}

\begin{defn}
	\begin{itemize}
		\item An elliptic curve $E$ is said to be \emph{supersingular} if $r(E) = 0$.
		\item An abelian variety $A$ is \emph{supersingular} if it is isogenous to a product of supersingular elliptic curves (in particular, $r(A) = 0$, although this is not equivalent in general, see e.g. \cite[Table 4.3]{Pries_A_short_guide_to_p_torsion_of_AV_in_cgar_p}).
		\item By Poincaré's complete reducibility theorem (see e.g. \cite[Theorem 12.2]{Moonen_van_der_Geer_Abelian_varieties}), any abelian variety is isogeneous to a product of simple abelian varieties. We say that $A$ has \emph{no supersingular factor} if any of these simple pieces is not supersingular. This is equivalent to requiring that $A$ admits no surjective map to a supersingular elliptic curve. 
	\end{itemize}
\end{defn}

\begin{prop}\label{basic facts about AV}
	The following holds: 
	\begin{enumerate}
		\item\label{itm:ordinary iff Verschiebung etale} the absolute Verschiebung morphism $V$ is étale if and only if $A$ is ordinary;
		\item\label{itm:p_rank stable under isogenies} two isogeneous abelian varieties have the same $p$--rank;
		\item\label{itm:A_surjects_to_B_and_A_ord_implies_B_ord} if $f \colon A \to B$ is a surjective morphism of abelian varieties and $A$ is ordinary, then so is $B$;
		\item\label{itm:ord_no_ss_factor} An ordinary abelian variety has no supersingular factor.
	\end{enumerate}
\end{prop}
\begin{proof}
	It respectively follows from \cite[Proposition 2.3.2]{Hacon_Pat_GV_Characterization_Ordinary_AV}, \cite[p. 147]{Mumford_Abelian_Varieties}, \cite[Lemma 2.3.4]{Hacon_Pat_GV_Characterization_Ordinary_AV} and \cite[Lemma 2.3.5]{Hacon_Pat_GV_Characterization_Ordinary_AV}.
\end{proof}

We now recall the definition of the (symmetric) Fourier--Mukai transform (see \cite{Mukai_Fourier_Mukai_transform, Schnell_Fourier_Mukai_transform_made_easy}).
\begin{defn}
	\begin{itemize}
		\item The \emph{Fourier--Mukai transforms} are the functors $R\bighat{S} \colon D_{\coh}(A) \to D_{\coh}(\bighat{A})$ and $RS \colon D_{\coh}(\bighat{A}) \to D_{\coh}(A)$ defined by 
		\[ R\hat{S}(\cM^{\bullet}) \coloneqq Rp_{\bighat{A}, *}(Lp_A^*\cM^{\bullet} \otimes \cP)  \esp \mbox{ and } \esp RS(\cN^{\bullet}) \coloneqq Rp_{A, *}(Lp_{\bighat{A}}^*\cN^{\bullet} \otimes \cP), \] where $p_A \colon A \times \bighat{A} \to A$ and $p_{\bighat{A}} \colon A \times \bighat{A} \to \bighat{A}$ denote the projections.
		\item The \emph{symmetric Fourier--Mukai transforms} are the functors $\FM_A \coloneqq R\bighat{S} \circ D_A$ and $\FM_{\bighat{A}} \coloneqq RS \circ D_{\bighat{A}}$, where $D_A \coloneqq \cR\HHom(-, \omega_A[g])$ (and similarly for $D_{\bighat{A}}$).
	\end{itemize}
\end{defn}

\begin{rem}
	Although the precise definition of the (symmetric) Fourier--Mukai transforms may look technical, its properties are more important than the precise definition itself. In particular, the reader may accept \autoref{properties_Fourier_Mukai_transform} and \autoref{GV_Hacon_Pat} as black boxes, and potentially never have to work with the precise definition, even for doing research in this field.
\end{rem}

The Fourier--Mukai transform has the following important properties, which are central in generic vanishing theory.

\begin{thm}\label{properties_Fourier_Mukai_transform}
	Let $\cM$ be a coherent sheaf on $A$.
	\begin{enumerate}
		\item\label{itm:support} For all $i \notin \{-g, \dots, 0\}$, then $\cH^i(\FM_A(\cM)) = 0$ for all $i \notin \{-g, \dots 0\}$. The same holds for $\FM_{\bighat{A}}$.
		\item\label{itm:equiv_cat} The functors $\FM_A$ and $\FM_{\bighat{A}}$ are inverses of each other, and hence equivalences of categories.
		\item\label{itm:equiv_cat_unipotent} We have $\FM_A(\omega_A) = k(0)$ (i.e. the skyscraper sheaf at $0 \in \bighat{A}$). In particular, the functor $\FM_A$ induces an equivalence of categories between unipotent vector bundles (i.e. vector bundles which are consecutive extensions of $\omega_A$) and coherent modules on $\bighat{A}$ supported at the point $0$.
		\item\label{itm:Fourier_Mukai_and_translation} For any $\alpha \in \bighat{A}$, \[ \FM_{\bighat{A}} \hspace{1 mm}\circ \esp T_\alpha^* \cong \cP_{-\alpha} \otimes \FM_{\bighat{A}},\] where $T_\alpha$ denotes the translation map by $\alpha$.
		\item\label{itm:behaviour_pushforwards_and_pullbacks} Let $f \colon A \to B$ be a morphism of abelian varieties, and let $\bighat{f} \colon \bighat{B} \to \bighat{A}$ denote the dual morphism. Then we have \[ \FM_B \: \circ \: Rf_* = L\bighat{f}^* \circ \FM_A. \]
		Here are two special cases:
		\begin{itemize}
			\item if $\cM$ is a coherent sheaf on $A$, then for all $i \geq 0$, \[ H^i(A, \cM)^{\vee} \cong \Tor_i(\FM_A(\cM), k(0)). \]
			\item if $\cM$ is a Cartier module, then each $\cH^i(\FM_A(\cM))$ has an induced $V$--module structure.
		\end{itemize}
		\item\label{itm:more_gen_version} For any $\alpha \in \Pic^0(A)$, we have \[ H^i(A, \cM \otimes \cP_{\alpha})^{\vee} \cong \Tor_i(\FM_A(\cM), k(-\alpha)). \] 
		\item\label{itm:support_H0} We have that \[ \Supp \left(\cH^0\FM_A(\cM)\right) = \set{ \alpha \in \bighat{A}}{ H^0(A, \cM \otimes \cP_{-\alpha}) \neq 0}.\]
	\end{enumerate}
\end{thm}
\begin{proof}
	Part \autoref{itm:support} are the first lines in the proof of \cite[Theorem 3.1.1]{Hacon_Pat_GV_Characterization_Ordinary_AV}. Parts \autoref{itm:equiv_cat}, \autoref{itm:Fourier_Mukai_and_translation} and \autoref{itm:behaviour_pushforwards_and_pullbacks} follow respectively from \cite[Theorem 3.2, Propositions 4.1 and 5.1]{Schnell_Fourier_Mukai_transform_made_easy}. Part \autoref{itm:equiv_cat_unipotent} can be found in \cite[Example 2.9]{Mukai_Fourier_Mukai_transform} (it also follows from \cite[Corollary 1 p. 129]{Mumford_Abelian_Varieties}). Let us show \autoref{itm:more_gen_version}, so let $\alpha \in \bighat{A}$. Then we have

	\begin{align*}
		H^i(A, \cM \otimes \cP_\alpha)^{\vee} & \expl{\cong}{\autoref{itm:behaviour_pushforwards_and_pullbacks}} \Tor_i(\FM_A(\cM \otimes \cP_\alpha), k(0)) \\
		& \expl{\cong}{\autoref{itm:Fourier_Mukai_and_translation}} \Tor_i(T_{\alpha}^*\FM_A(\cM), k(0)) \\
		& \cong \Tor_i(\FM_A(\cM), k(- \alpha)). \\
	\end{align*}

	Let us finally show \autoref{itm:support_H0}. Since $\FM_A(\cM)$ is supported in non--positive degrees by \autoref{itm:support}, it follows that \[ \Tor_0(\FM_A(\cM), k(\alpha)) \cong \Tor_0(\cH^0\FM_A(\cM), k(\alpha)) = \cH^0\FM_A(\cM) \otimes k(\alpha)\] for all $\alpha$. Hence, 
	\[ \Supp(\cH^0\FM_A(\cM)) \expl{=}{Nakayama's lemma} \set{\alpha \in \bighat{A}}{\cH^0\FM_A(\cM) \otimes k(\alpha) \neq 0} \expl{=}{\autoref{itm:more_gen_version}} \set{ \alpha \in \bighat{A}}{ H^0(A, \cM \otimes \cP_{-\alpha}) \neq 0}. \]
\end{proof}

In \autoref{section_first_vanishing_thm}, we will need a few more properties of this functor. They will only be stated there because we will never need them again.

\subsection{A few commutative algebra lemmas}
Here we collect a few results from commutative algebra which will be useful later on.

\begin{lem}\label{meaning of vanishing of Tor}
	Let $(R, \fm, k)$ be a Noetherian local ring, let $M \neq 0$ be a finitely generated $R$--module and let $i \geq 0$. Then \[ \Tor_i(M, k) = 0 \iff \projdim(M) < i \iff \depth(M) > \depth(R) - i.  \]
\end{lem}
\begin{proof}
	The first equivalence holds by \cite[Lemma 1.(ii) in Chapter 19]{Matsumura_Commutative_Ring_Theory}, and the second equivalence is exactly the Auslander--Buchsbaum's formula (see e.g. \cite[Theorem 19.1]{Matsumura_Commutative_Ring_Theory}).
\end{proof}

The following is well--known to experts, but unable to find a reference, we prove it now.

\begin{cor}\label{locus of non-zero Tor is closed}
	Let $\cM$ be a coherent sheaf on a Noetherian scheme $X$. Then for all $i \geq 0$, the locus \[ \set{x \in X}{\Tor_i(\cM, k(x)) \neq 0} \] is closed.
\end{cor}
\begin{proof}
	When $i = 0$, we know by Nakayama's lemma that this locus is exactly the support of $\cM$, which is closed. Hence, assume that $i \geq 1$. By \autoref{meaning of vanishing of Tor}, we have to show that the locus \[ \set{x \in X}{\projdim(\cM_x) < i} \] is open. 

	Suppose that $l \coloneqq \projdim(\cM_x) < i$, let $U$ be an affine open around $x$, and set $U = \Spec A$, and $\cM$ correspond to the $A$--module $M$ over $U$. Furthermore, let \[  0 \to K \to P_{l - 1} \to \dots  P_0 \to M \to 0\] be an exact sequence with each $P_i$ finitely generated projective and where $K$ is the kernel of $P_l \to P_{l - 1}$. Since $\cM_x$ has projective dimension $l$, $K$ is necessarily projective at $x$, hence free. Therefore $K$ will also be free (hence projective) around $x$. Therefore the projective dimension of $\cM$ can only be smaller or equal to $l$ in a neighborhood of $x$.
\end{proof}
\begin{lem}\label{lemma Tor(V*) = 0 at x iff Tor = 0 at p(x)}
	Let $R \to S$ be a flat morphism of local rings with respective residue field $k_R$ and $k_S$, and let $M$ be a finitely generated $R$--module. Then \[ \Tor_i(M, k_R) = 0 \iff \Tor_i(M \otimes_R S, k_S) = 0. \]
\end{lem}
\begin{proof}
