\begin{proof}[Proof of \autoref{equivalence_V_crystals_and_Cartier_crystals}]
	By \autoref{properties_Fourier_Mukai_transform}.\autoref{itm:behaviour_pushforwards_and_pullbacks}, the functors $\cH^0\FM$ send Cartier modules to $V$--modules and vice--versa, and it follows from the definitions that they preserve nilpotence. Let us first show that they induce functors at the level crystals, so consider the composition \[ \begin{tikzcd}
		(\Coh_A^{C^s})^{op} \arrow[rr, "\cH^0\FM_A"] &  & \Coh_{\bighat{A}}^{V^s} \arrow[rr] &  & \Crys_{\bighat{A}}^{V^s}.
	\end{tikzcd} \]
	In order to be able to apply \stacksproj{02MS} and factor the composition above through $(\Crys_A^{C^s})^{op}$, it is then enough to show that it is exact. Hence, let \[ \begin{tikzcd}
		0 \arrow[rr] &  & \cM_1 \arrow[rr] &  & \cM_2 \arrow[rr] &  & \cM_3 \arrow[rr] &  & 0
	\end{tikzcd} \] be an exact sequence of Cartier modules.  Applying $\FM_A$ gives an exact triangle 
	\[ \begin{tikzcd}
		\FM_A(\cM_3) \arrow[rr] &  & \FM_A(\cM_2) \arrow[rr] &  & \FM_A(\cM_1) \arrow[rr, "+1"] &  & {}
	\end{tikzcd} \] By \autoref{GV_Hacon_Pat} and the induced long exact sequence in cohomology sheaves, we deduce that the sequence  \[ \begin{tikzcd}
	0 \arrow[r]  & \cH^0(\FM_A(\cM_3)) \arrow[r]  & \cH^0(\FM_A(\cM_2)) \arrow[r]   & \cH^0(\FM_A(\cM_1)) \arrow[r]  & 0
\end{tikzcd} \] is exact up to nilpotence (i.e.	exact in $\Crys_{\bighat{A}}^{V^s}$). We can then apply \stacksproj{02MS} and deduce the existence of the factorization 	\[ \begin{tikzcd}
	(\Coh_A^{C^s})^{op} \arrow[rr, "\cH^0\FM_A"] \arrow[d] &  & \Coh_{\bighat{A}}^{V^s} \arrow[d] \\
	(\Crys_A^{C^s})^{op} \arrow[rr]                        &  & \Crys_{\bighat{A}}^{V^s}.        
	\end{tikzcd} \] The proof in the other direction is identical, replacing the use of \autoref{GV_Hacon_Pat} by that of \autoref{vanishing_for_V_modules}. \\

	Now, let $\cN$ be a $V$--module, and let $\cM_0 \coloneqq \cH^0\FM_{\bighat{A}}(\cN)$. By \autoref{properties_Fourier_Mukai_transform}.\autoref{itm:support}, there is an exact triangle 
	\[ \begin{tikzcd}
		\tau_{\leq -1}\FM_{\bighat{A}}(\cN) \arrow[rr] &  & \FM_{\bighat{A}}(\cN) \arrow[rr] &  & \cM_0 \arrow[rr, "+1"] &  & {}.
	\end{tikzcd} \]

	By \autoref{vanishing_for_V_modules} and \autoref{extension_of_derived_nilp_is_nilp}, there exists $e > 0$ such that the morphism $F^{es}_*\tau_{\leq -1}\FM_{\bighat{A}}(\cN) \to \tau_{\leq -1}\FM_{\bighat{A}}(\cN)$ is zero. We can apply $\FM_A$ to the above triangle and use \autoref{properties_Fourier_Mukai_transform}.\autoref{itm:equiv_cat} to obtain \[ \begin{tikzcd}
		\FM_A(\cM_0) \arrow[rr] &  & \cN \arrow[rr] &  & \FM_A\left(\tau_{\leq -1}\FM_{\bighat{A}}(\cN)\right) \arrow[rr, "+1"] &  & {}
	\end{tikzcd} \]
	Set $\ttilde{\cN} \coloneqq \FM_A\left(\tau_{\leq -1}\FM_{\bighat{A}}(\cN)\right)$. Since the natural map $\ttilde{\cN} \to V^{es, *}\ttilde{\cN}$ is zero, we deduce that for all $j \in \bZ$, the $V$--module $\cH^j(\ttilde{\cN})$ is nilpotent. By the exact triangle above, we have a long exact sequence of $V$--modules \[ \begin{tikzcd}
		\dots \arrow[r] & \cH^{-1}(\ttilde{\cN}) \arrow[r] &  \cH^0\FM_A(\cM_0) \arrow[r] & \cN \arrow[r] & \cH^0(\ttilde{\cN}) \arrow[r] & \dots
	\end{tikzcd} \]
	Thus, the kernel and cokernel of $\cH^0\FM_A(\cM_0) \to \cM$ are nilpotent $V$--modules, so this morphism is by definition an isomorphism as $V$--crystals. In other words, we found a natural isomorphism \[ (\cH^0\FM_A \circ \: \cH^0\FM_{\bighat{A}})(\cN) \to \cN \] of $V$--crystals, which is exactly what we needed to show. 

	The proof that there is a natural isomorphism $(\cH^0\FM_{\bighat{A}} \circ \: \cH^0\FM_A)(\cM) \to \cM$ on Cartier modules $\cM$ is identical.
\end{proof}

\subsection{Cohomological support loci}

Classically, generic vanishing came as the study of some cohomology vanishing loci. We will now move towards this direction. There are two main purposes for this section:

\begin{enumerate}
	\item Slightly improve \cite[Theorem 1.1]{Hacon_Pat_GV_Geom_Theta_Divs}. A new application of this is to deduce a generic vanishing results about perverse $\bF_p$--sheaves on abelian varieties. This is done in \cite{Baudin_Duality_between_perverse_sheaves_and_Cartier_crystals}. 
	\item Simplify the proofs, using a more commutative algebraic point of view.
	\item Give examples to illustrate the theory.
\end{enumerate}

\noindent In characteristic zero, the main actors are the following closed subsets:

\begin{defn}
	Let $\cM$ be a coherent sheaf on $A$. We set \[ V^i(\cM) = \set{\alpha \in \bighat{A}}{H^i(A, F^{es}_*\cM \otimes \cP_\alpha) \neq 0} \inc \bighat{A}. \]
\end{defn}

In the context of positive characteristic geometry, we want to include Cartier module actions in the picture. The definition that arose in \cite{Hacon_Pat_GV_Geom_Theta_Divs} is the following:

\begin{defn}
	Given a Cartier module $\cM$ on $A$, we set \[ W^i_F(\cM)  = \set{\alpha \in \bighat{A}}{\varprojlim H^i(A, F^{es}_*\cM \otimes \cP_\alpha) \neq 0} \subseteq \bighat{A}. \]
\end{defn}

An immediate first remark is that by the projection formula, \[ (p^s)^{-1}W^i_F(\cM) = W^i_F(\cM).\]

\begin{rem}
	Whenever the context is clear, we will only write $V^i$ and $W^i_F$.
\end{rem}

\begin{example}
	Consider the Cartier module $F^s_*\omega_A \to \omega_A$ (see \autoref{ex:Cartier_operator}). Then note that for any non--trivial $L \in \Pic^0(A)$, we have $H^g(A, \omega_A \otimes L) = 0$ by Serre duality. Thus, if $L$ is not $p^e$--torsion for some $e$, then $L \notin W^g_F(\omega_A)$.

	On the other hand, the morphism $H^g(A, F_*\omega_A) \to H^g(A, \omega_A)$ is Serre dual to the map taking $p^s$--powers $H^0(A, \cO_A) \to H^0(A, F^s_*\cO_A)$, which is always an isomorphism. Thus, $0 \in W^g_F$, so we conclude that \[ W^g_F = \set{x \in \bighat{A}}{x \mbox{ is $p^{es}$--torsion for some $e > 0$}} = \bigcup_{e > 0} (p^{es})^{-1}\{0_{\bighat{A}}\}.\]

	This set is never closed if $A$ has positive $p$--rank, so in general the idea is to find a closed subset $W^i$ that ``approximates'' the locus $W^i_F$, in the sense that $W^i_F$ should be close to $\bigcup_e(p^{es})^{-1}W^i$. For example, we would have $W^g = \{0_{\bighat{A}}\}$ in the example above. Unfortunately, we cannot always have \[ \bigcup_{e > 0}\: (p^{es})^{-1}W^i = W^i_F, \] in general (see \autoref{first_example}, \autoref{example_euler_char}), but the difference can be somewhat ``bounded'' by some smaller--dimensional closed subset $Z^i$.
\end{example}

Let us state the theorem:
\begin{thm}\label{generic vanishing}
	Let $\cM$ be a Cartier module on $A$. Then for all $0 \leq i \leq g$, there exist closed subsets $W^i$ and $Z^i$ of $\bighat{A}$ with the following properties:
	\begin{enumerate}[topsep=1ex, itemsep=1ex]
		\item\label{itm:gv_inclusions} $W^{i + 1} \inc W^i$, $Z^{i + 1} \inc Z^i$ and $Z^i \inc W^i$ for all $i$;
		\item\label{itm:gv_codim} $\codim W^i \geq i$, $\codim{Z^i} \geq i + 1$;
		\item\label{itm:gv_p_closed} $p^s(W^i) = W^i$;
		\item\label{itm:gv_link_with_section}
		we have \[ W^0 \inc V^0 = \set{\alpha \in \bighat{A}}{H^0(A, \cM \otimes \cP_{\alpha}) \neq 0}; \]
		\item\label{van_and_non_van} there are inclusions  \[\left(\bigcup_{e \geq 0}(p^{es})^{-1}W^i\right) \setminus \ttilde{Z^i} \: \inc \: W^i_F \: \inc \: \bigcup_{e \geq 0}(p^{es})^{-1}W^i,\] where \[ \ttilde{Z^i} \coloneqq \set{\alpha \in \bighat{A}}{p^{es}(\alpha) \in Z^i \mbox{ for infinitely many }e}. \]
		In particular, if $W^i$ has a component of codimension $i$, then very general points of $\bigcup_e(p^{es})^{-1}W^i$ lie in $W^i_F$.
	\end{enumerate}
\end{thm}

\begin{rem}
	The proof explains us how to construct these $W^i$'s and $Z^i$'s explicitly. Although the explicit construction is cumbersome, it turns out that understanding $W^0$ and the codimension $i$ components of the subsets $W^i$ is more doable. We will come back to this in \autoref{properties B^i}.
\end{rem}

The condition that $p^s(W^i) = W^i$ is the positive characteristic analogue of the fact that in characteristic zero, the cohomological support loci are a finite union of torsion translates of abelian subvarieties. This analogy holds thanks to the following result:
\begin{thm}[{\cite{Pink_Roessler_Manin_Mumford_conjecture}}]\label{main thm Pink/Roessler}
	Assume that $A$ has no supersingular factor, and let $W \inc A$ be an irreducible closed subset such that $p^s(W) = W$. Then there exists $e > 0$, a point $a \in A$ of $(p^{es} - 1)$--torsion and an abelian subvariety $B \inc A$ such that \[ W = a + B. \]
%	Let $X \inc A$ be an irreducible closed subset such that $[p^s]X = X$, and let $B$ be the identity component of (the reduction of) $\Stab_A(X)$. Then there exist $e > 0$, finitely many morphisms of abelian varieties $h_{\alpha}\colon A_{\alpha} \ra A/B$ where all $A_{\alpha}$ are supersingular and have a model over a finite field, and closed subvarieties $X_{\alpha} \inc A_{\alpha}$ which satisfy $[p^{s}]X_{\alpha} = X_{\alpha}$ such that the morphism \[ h \coloneqq \sum_{\alpha}h_{\alpha}\colon \prod_{\alpha}A_\alpha \ra A/B \] has finite kernel and for some point $a \in A$, we have \[ X/B = \overline{a} + h\left(\prod_{\alpha}X_{\alpha}\right). \]
