We start by showing that $W^i_F$ can be computed in terms of $V$--modules (this can be very useful for actual computations).
\begin{lem}\label{SCSL for H^i = SCSL for Tor^i}
	Let $\cM$ be a Cartier module on $A$, and let $\cN \coloneqq \cH^0\FM_A(\cN)$ be the corresponding $V$--module.
	Then for all $i \geq 0$ and $\alpha \in \bighat{A}$, \[ \varprojlim H^i(A, F^{es}_*\cM \otimes \cP_{\alpha})  \cong \left(\colim \Tor_i(V^{es, *}\cN, k(- \alpha))\right)^{\vee}. \]
\end{lem}

\begin{proof}
	For all $e > 0$, we have a natural isomorphisms

	\[ H^i(A, F^{es}_*\cM \otimes \cP_\alpha) \expl{\cong}{\autoref{properties_Fourier_Mukai_transform}.\autoref{itm:more_gen_version}} \Tor_i(\FM_A(F^{es}_*\cM), k(-\alpha))^{\vee} \expl{\cong}{\autoref{properties_Fourier_Mukai_transform}.\autoref{itm:behaviour_pushforwards_and_pullbacks}} \Tor_i(V^{es, *}\FM_A(\cM), k(- \alpha))^{\vee}.\]

	Taking inverse limits gives \[ \lim H^i(A, F^{es}_*\cM \otimes \cP_\alpha^{\vee}) \cong \lim \Tor_i(V^{es, *}\FM_A(\cM), k(\alpha))^{\vee} \cong \left(\colim \Tor_i(V^{es, *}\FM_A(\cM), k(\alpha))\right)^\vee. \]

	Since $\cH^i\FM_A(\cM)$ is nilpotent for all $i \neq 0$ (\autoref{GV_Hacon_Pat}) and $\cN = \cH^0\FM_A(\cM)$, we have \[ \colim \Tor_i(V^{es, *}\FM_A(\cM), k(\alpha)) \cong \colim \Tor_i(V^{es, *}\cN, k(\alpha)), \] concluding the proof.
\end{proof}

As a consequence, the cohomological support loci can be completely understood in terms of commutative algebraic data of a module on $\bighat{A}$. This is the key to prove \autoref{generic vanishing}. Let us state the following natural definition.

\begin{defn}
	Let $\cN$ be a $V$--module on $\bighat{A}$, and let $i \geq 0$. Define \[ W^i_F(\cN) \coloneqq \set{\alpha \in \bighat{A}}{\varinjlim \Tor_i(V^{es, *}\cN, k(-\alpha)) \neq 0} \inc \bighat{A}. \]
\end{defn}

 An immediate consequence of \autoref{SCSL for H^i = SCSL for Tor^i} is then the following:

\begin{cor}\label{equality_of_SCSL}
	Let $\cM$ be a Cartier module on $A$, and let $\cN \coloneqq \cH^0\FM_A(\cM)$ be the associated $V$--module. Then for all $i \geq 0$, we have \[ W^i_F(\cM) = W^i_F(\cN). \]
\end{cor}

The following construction will be useful to obtain the inclusions $p^s(W^i) \inc W^i$ in \autoref{generic vanishing}.

\begin{notation}\label{notation_lambda}
	For a subset $Z \inc \bighat{A}$, define \[ \Lambda(Z) \coloneqq \set{\alpha \in \bighat{A}}{p^{es}(\alpha) \in Z \esp \forall e \gg 0}. \]
\end{notation}

\begin{rem}\label{rem_easy_lambda}
	Note that if $p^s(Z)\inc Z$, then \[ \Lambda(Z) = \bigcup_{e \geq 0}(p^{es})^{-1}Z. \]
\end{rem}


\begin{lem}\label{p-dynamic closure of a subset}
	Let $Z \inc \bighat{A}$ be a closed subset. Then there exists a canonically induced closed subset $W_Z \inc Z$ such that $p^s(W_Z) = W_Z$ and \[ \Lambda(Z) = \Lambda(W_Z). \]

	This construction satisfies the following properties:
	\begin{enumerate}
		\item\label{explicit_1} if $p^s(Z) = Z$, then $W_Z = Z$;
		\item\label{explicit_2} more generally, if $p^s(Z) \inc Z$, then $W_Z = p^{es}(Z)$ for all $e \gg 0$;
		\item\label{inclusion} if $Z' \inc Z$ is an inclusion of closed subsets, then $W_{Z'} \inc W_Z$.
	\end{enumerate}
\end{lem}

\begin{proof}
	We will first construct a canonically induced closed subset $\overline{Y_Z}$ satisfying $p^s(\overline{Y_Z}) \inc \overline{Y_Z}$, and then construct $W_Z$ out of it.

	For all $\alpha \in \Lambda(Z)$, let $e(\alpha) \geq 0$ be the minimal integer such that $p^{es}(\alpha) \in Z$ for all $e \geq e(\alpha)$, and consider \[ Y_Z \coloneqq \set{p^{es}(\alpha)}{\alpha \in \Lambda(Z), \: e \geq e(\alpha)}.\] 
	Then we immediately have:
	\begin{itemize}
		\item  $p^s(Y_Z) \inc Y_Z$;
		\item  $Y_Z \inc Z$;
		\item $\Lambda(Y_Z) = \Lambda(Z)$.
	\end{itemize}
	Since $Z$ is closed, we then obtain that $\overline{Y_Z} \inc Z$, so $\Lambda(Y_Z) \inc \Lambda(\overline{Y}) \inc \Lambda(Z)$. Since $\Lambda(Y_Z) = W(Z)$, we deduce that $W(Y_Z) = W(\overline{Y_Z})$. Furthermore, we also have that $p^s(\overline{Y_Z}) \inc \overline{Y_Z}$, since $p^s(Y_Z) \inc Y_Z$. 

	Let us now construct $W_Z$. Consider the inclusions \[ \overline{Y_Z} \cni p^s(\overline{Y_Z}) \cni p^{2s}(\overline{Y_Z}) \cni \dots. \] This descending chain of closed subsets eventually stabilizes by Noetherianity; let us define $W_Z \coloneqq p^{es}(\overline{Y_Z})$ with $e \gg 0$. It is then immediate that $\Lambda(Z) = \Lambda(X_Z)$ and $p^s(W_Z) = W_Z$. 

	The three statements \autoref{explicit_1}, \autoref{explicit_2} and \autoref{inclusion} follow directly from our construction.
\end{proof}


We now have all the ingredients to prove \autoref{generic vanishing}.

\begin{proof}[Proof of \autoref{generic vanishing}]
	By \autoref{SCSL for H^i = SCSL for Tor^i}, letting $\cN = \cH^0\FM_A(\cM)$, we have that \[ W^i_F(\cM) = W^i_F(\cN). \]

	Let $\cN_{\injj}$ be the canonical injective $V$--module nil--isomorphic to $\cN$, i.e. $\cN_{\injj}$ is the image of the map $\cN \to \colim V^{es, *}\cN$ (see \autoref{canonical_injective_V_module})

	Since the natural map $\colim V^{es, *}\cN \to \colim V^{es, *}\cN_{\injj}$ is an isomorphism by construction and $\varinjlim$ commutes with $\Tor_i$, we have \[ W^i_F(\cN) = W^i_F(\cN_{\injj}). \]
	We start with a first approximation \[ V^i_{\injj} := \set{\alpha \in \bighat{A}}{\Tor_i(\cN_{\injj}, k(-\alpha)) \neq 0} \] of $W^i_F(\cM)$. Let us list some properties of the subsets $V^i_{\injj}$:

	\begin{enumerate}
		\item $V^i_{\injj}$ is closed by \autoref{locus of non-zero Tor is closed}.
		\item $\codim V^i_{\injj} \geq i$. Indeed, for any scheme--theoretic point $\beta \in \bighat{A}$ of codimension strictly smaller than $i$ and any module $\cT$, we have \[ \Tor_i(\cT, k(\beta)) \cong \Tor_i^{\cO_{\bighat{A}, \beta}}(\cT_{\beta}, k(\beta)) = 0 \] since $\cO_{\bighat{A}, \beta}$ is regular of dimension less than $i$;
		\item $V^g_{\injj} \inc \dots \inc V^0_{\injj}$ by \autoref{meaning of vanishing of Tor}.
	\end{enumerate}

	Note that since $\cN \surj \cN_{\injj}$, we have that \[  V^0_{\injj} \expl{=}{Nakayama's lemma} -\Supp(\cN_{\injj}) \inc -\Supp(\cN) \expl{=}{\autoref{properties_Fourier_Mukai_transform}.\autoref{itm:support_H0}} V^0. \] 

	We are missing the crucial property $p^s(V^i_{\injj}) = V^i_{\injj}$, so let us make it work now (up to changing a bit the $V^i_{\injj}$). Note that given $\alpha \in \bighat{A}$, in order to have \[ \varinjlim \Tor_i(V^{es, *}\cN_{\injj}, k(-\alpha)) \neq 0, \] we must in particular have that $\Tor_i(V^{es, *}\cN_{\injj}, k(-\alpha)) \neq 0$ for all $e \gg 0$. By \autoref{Tor(V*) = 0 at x iff Tor = 0 at p(x)}, this is equivalent to the fact that $p^{es}(\alpha) \in V^i_{\injj}$ for all $e \gg 0$. In other words, \[ W^i_F \inc \Lambda(V^i_{\injj}) = \set{\alpha \in \bighat{A}}{p^{es}(\alpha) \in V^i_{\injj} \esp \forall e \gg 0}. \]
	Therefore we can apply \autoref{p-dynamic closure of a subset} to deduce the existence of closed subsets $W^i \coloneqq W_{V^i_{\injj}} \subseteq V^i_{\injj}$ such that

	\begin{itemize}
		\item $p^s(W^i) = W^i$;
		\item $W^g \inc \dots \inc W^0$ (see \autoref{p-dynamic closure of a subset}.\autoref{inclusion})
		\item $\codim W^i \geq i$;
		\item $W^i_F \inc \Lambda(V^i_{\injj}) =  \Lambda(W^i) = \bigcup_{e \geq 0}(p^{es})^{-1}W^i$ (see \autoref{rem_easy_lambda} for the last inclusion).
	\end{itemize}

	Finally, let us see how to construct the closed subsets $Z^i$. Let $\cC$ denote the cokernel of $\cN_{\injj} \inj V^{s, *}\cN_{\injj}$. Note that if $\Tor_{i + 1}(\cC, k(-\alpha)) = 0$, then we have an injection \[ \Tor_i(\cN_{\injj}, k(-\alpha)) \inj \Tor_i(V^{s, *}\cN_{\injj}, k(-\alpha)) \] by the long exact sequence if Tor-groups. Note also that the cokernel of $V^{es, *}\cN_{\injj} \ra V^{(e + 1)s, *}\cN_{\injj}$ is simply $V^{es, *}\cC$. We then define \[ Z^i \coloneqq \set{\alpha \in \bighat{A}}{\Tor_{i + 1}(\cC, k(-\alpha)) \neq 0} \cap W^i. \] As before, $Z^i$ is closed of codimension at least $i + 1$, $Z^{i + 1} \subseteq Z^i$ and $Z^i \inc W^i$. \\

	Note that at this point, we proved everything except the left inclusion in point \autoref{van_and_non_van}. Let us do that now, by first showing that \[ \set{\alpha \in \bighat{A}}{p^{es}(x) \in W^i \setminus Z^i \mbox{ for } e \gg 0} \subseteq W^i_F(\cM). \]
	Let $\alpha \in \bighat{A}$ be such that $p^{es}(\alpha) \in W^i \setminus Z^i$ for any $e \gg 0$. Then \[ \Tor_i(V^{es, *}\cN_{\injj}, k(-\alpha)) \neq 0 \] and \[ \Tor_i(V^{es, *}\cN_{\injj}, k(-\alpha)) \inj \Tor_i(V^{(e + 1)s, *}\cN_{\injj}, k(-\alpha)) \] for $e \gg 0$ by our previous discussion, implying in particular that \[ \varinjlim \Tor_i(V^{es, *}\cN_{\injj}, k(-\alpha)) \neq 0. \] In other words, this gives that $\alpha \in W^i_F$, so we obtained our sought inclusion. Finally, given that $p^s(W^i) = W^i$, we have that \[ \set{\alpha \in \bighat{A}}{p^{es}(x) \in W^i \setminus Z^i \mbox{ for } e \gg 0} = \left(\bigcup_{e \geq 0}(p^{es})^{-1}W^i\right) \setminus \ttilde{Z^i}, \] where \[ \ttilde{Z^i} \coloneqq \set{\alpha \in \bighat{A}}{p^{es}(\alpha) \in Z^i \mbox{ for infinitely many }e}. \] The proof is complete.
\end{proof}

\begin{notation}
	From now on, we will use the notations $V^i_{\injj}$ and $W^i$ as in the proof of \autoref{generic vanishing}. In other words, given a Cartier module $\cM$, we set \[ V^i_{\injj}(\cM) \coloneqq \set{\alpha \in \bighat{A}}{\Tor_i(\cN_{\injj}, k(-\alpha)) \neq 0} \] and \[ W^i(\cM) \coloneqq W_{V^i_{\injj}(\cM)}, \] (see \autoref{p-dynamic closure of a subset}), where $\cN_{\injj}$ is the canonical injective $V$--module associated to $\cM$ (i.e. $\cN_{\injj} = \cH^0(\FM_A(\cM))_{\injj}$, see \autoref{canonical_injective_V_module}). Also, if $\cC$ denoted the cokernel of $\cN_{\injj} \inj V^{s, *}\cN_{\injj}$, then \[ Z^i(\cM) \coloneqq \set{\alpha \in \bighat{A}}{\Tor_{i + 1}(\cC, k(-\alpha)) \neq 0}. \]
\end{notation}

\begin{rem}
	Note that the subsets of \cite[Theorem 1.1]{Hacon_Pat_GV_Geom_Theta_Divs} are precisely our subsets $V^i_{\injj}$. Hence, our $W^i$'s are more precise approximations of $W^i_F$. This is exactly the ``slight improvement'' we were referring to at the beginning of the section.
\end{rem}

In practice, working with the subsets $V^i_{\injj}$ can be more practical than with the subsets $W^i$. Some of their properties are listed below.


\begin{prop}\label{properties B^i}
	Let $\cM$ be a Cartier module on $A$, with associated injective $V$--module $\cN_{\injj}$. Then the following holds:

	\begin{enumerate}[itemsep=1ex]
		\item\label{inclusions} $V^g_{\injj} \subseteq \dots \subseteq V^0_{\injj}$;
		\item\label{codim} $\codim V^i_{\injj} \geq i$.
		\item\label{pB^0_is_B^0} $p^s(V^0_{\injj}) \subseteq V^0_{\injj}$, and hence $W^0 = p^{es}(V^0_{\injj})$ for $e \gg 0$;
		\item\label{non_vanishing_support} $V^0_{\injj} \inc V^0$.
		\item\label{codim_i_components} If $S^i$ denotes the union of the components of $V^i_{\injj}$ of codimension $i$, then $p^s(S^i) \subseteq S^i$. Hence, $p^{es}(S^i) \subseteq W^i$ for all $e \gg 0$, and it contains all components of $W^i$ of codimension $i$.
	\end{enumerate}
\end{prop}
\begin{proof}
	The statements \autoref{inclusions}, \autoref{codim} and \autoref{non_vanishing_support} were already shown during the proof of \autoref{generic vanishing}. The first part of \autoref{pB^0_is_B^0} is immediate, since $\cN_{\injj} \inj V^{s, *}\cN_{\injj}$ and $V^0_{\injj} = -\Supp(\cN_{\injj})$ by Nakayama's lemma. To obtain that $W^0 = p^{es}(V^0_{\injj})$, use \autoref{p-dynamic closure of a subset}.\autoref{explicit_2}.
	We now prove \autoref{codim_i_components}. Let $\alpha \in V^i_{\injj}$ be a scheme--theoretic point of codimension $i$. Then \[ \Tor_i(\cN_{\injj}, k(-\alpha)) \inj \Tor_i(V^{s, *}\cN_{\injj}, k(-\alpha))\] (there is no $\Tor_{i+ 1}$ on an $i$--dimensional regular local ring), so $\Tor_i(\cN_{\injj}, k(p^s(-\alpha)) \neq 0$ by \autoref{Tor(V*) = 0 at x iff Tor = 0 at p(x)}. In particular, $p^s(\alpha) \in V^i_{\injj}$, so we have $p^s(S^i) \subseteq S^i$. The rest follows as in the proof of \autoref{pB^0_is_B^0}.
\end{proof}

\subsection{Examples}\label{sec:examples}

Let us give a few examples, giving an idea of what these subsets are, and illustrating pathologies which can occur.

\begin{example}\label{first_example}
	Assume that $A$ is not ordinary, and let $r < g$ denote its $p$--rank. Then by definition, the Frobenius action on $H^r(A, \cO_A)$ is not nilpotent, but the action on $H^{r + 1}(A, \cO_A)$ is nilpotent. By Serre duality, we then deduce that $0 \in W^{g - r}_F(\omega_A)$ but $0 \notin W^{g - r + 1}_F(\omega_A)$. Thus, $W^{g - r}_F(\omega_A)  \not\subseteq W^{g - r + 1}_F(\omega_A)$. In particular, although we have \[ W^g \inc W^{g - 1} \inc \dots \inc W^0 \] and \[ V^g_{\injj} \inc V^{g - 1}_{\injj} \dots \inc V^0_{\injj} \] in general, this does not necessarily hold for the subsets $W^i_F$. We will nevertheless see in \autoref{inclusions_SCSL} that these inclusions ``essentially hold'' when $A$ is ordinary.

	In this example, we have the following:
	\begin{align*}
		& \cH^0(\FM_A(\omega_A))_{\injj} = \FM_A(\omega_A) = k(0); \\
		& W^i = V^i_{\injj} = \{0_{\bighat{A}}\} \mbox{ for all } 0 \leq i \leq g; \\
		& \ttilde{Z^i} = \begin{cases}
			\emptyset, \: \mbox{ if } i = g \mbox{ or } A \mbox{ is ordinary;}\\
			\bighat{A}[p^{\infty}], \: \mbox{ else;}
		\end{cases}\\
	    & W^i_F = \begin{cases}
			\emptyset, \: i \leq g - r; \\
			\bighat{A}[p^{\infty}], \: i > g - r,
		\end{cases}
	\end{align*} 
	where $\bighat{A}[p^{\infty}]$ denotes the subset of $p$--power torsion points of $\bighat{A}$. In particular, whenever $0 < r < g$, we see that both inclusions in \autoref{generic vanishing}.\autoref{van_and_non_van} can be strict.
\end{example}

\begin{example}\label{example_euler_char}
		Let $E$ be an ordinary elliptic curve, and assume for simplicity that $p \neq 2$. Although $E \cong \bighat{E}$, we will still write $E$ and $\bighat{E}$ to distinguish Cartier modules on $E$ and $V$--modules on $\bighat{E}$.

		Since we will work with divisors and the group law at the same time, we will use the following notation:

		\begin{itemize}
				\item the notation for divisors is the same as usual, i.e. we use the additive notation;
				\item the neutral element of $E$ is denoted $e$;
				\item the group law on $E$ is written multiplicatively. Recall that by definition of the group law, we have the following linear equivalence of \emph{divisors} for all $\alpha, \beta \in \bighat{E}$:
				\[ \alpha + \beta \sim \alpha\beta + e. \]
		\end{itemize}

		Consider the line bundle $L \coloneqq \cO_{\bighat{E}}(e)$. Then \[ V^{s, *}L \cong \cO_{\bighat{E}}\left(\sum_{p^s(\alpha) = e} \alpha\right) \cong \cO_{\bighat{E}}\left(\left(\prod_{p^s(\alpha) = e}\alpha\right) + pe\right) \expl{\cong}{$p \neq 2$} \cO_{\bighat{E}}(pe). \]

		Hence, let $\theta \colon L \to V^*L$ be the (injective) morphism corresponding to the section $1 \in H^0(\bighat{E}, \cO_E((p - 1)e))$. Then $\theta \otimes k(0) = 0$, so \[ \colim V^{s, *}L \otimes k(0) = 0. \] On the other hand, for any $\alpha \in \bighat{E}$ not of $p$--power torsion, each morphism $V^{es, *}\theta$ is an isomorphism at $\alpha$.

		Now, let $\cM = \cH^0\FM_{\bighat{A}}(L)$ be the Cartier module on $E$ corresponding to $L$ (\autoref{equivalence_V_crystals_and_Cartier_crystals}). Then our computation above shows that \[ W^0_F(\cM) = \bighat{E} \: \setminus \: \bigcup_{e > 0} (p^{es})^{-1}\{0_{\bighat{E}}\} = \bighat{E} \setminus \bighat{E}[p^{\infty}], \] that $W^0 = V^0_{\injj} = \bighat{E}$ ($L$ is an injective $V$--module), and $Z^0 = \{0_{\bighat{E}}\} \neq \emptyset$ (so $\ttilde{Z^0} = \bighat{E}[p^{\infty}]$). In particular, this shows that the answer to \cite[Question 1.14.(b)]{Hacon_Patakfalvi_Zhang_Bir_char_of_AVs} is negative.
\end{example}
\begin{rem}[Euler characteristics]
	It is now well--known that if $\cM$ is a GV--sheaf on an abelian variety $A$, then $\chi(A, \cM) \geq 0$: the reason is that if $\alpha \in \bighat{A}$ is general, then \[ \chi(A, \cM) = \chi(A, \cM \otimes \cP_{\alpha}) = h^0(A, \cM \otimes \cP_{\alpha}) \geq 0. \]

	With the idea that ``Cartier modules are GV--sheaves up to nilpotence'', one can wonder if the following holds: let $\cM$ be a Cartier module on an abelian variety $A$, then $\chi_{ss}(A, \cM) \geq 0$ (see \autoref{rem:def_Cartier_mod}.\autoref{itm:notation H^0_ss} for this notation).

	Unfortunately, this fails in general: if we take $r = 0$ in \autoref{first_example}, then $\chi_{ss}(A, \omega_A) = (-1)^g$, which is negative whenever $g$ is odd. The issue why the characteristic zero argument does not go through is that semistable Euler characteristic is \emph{not} invariant under twists. In \emph{loc. cit.}, we have that $\chi_{ss}(A, \omega_A \otimes \cP_{\alpha}) = 0$ if $\alpha$ is not of $p$--power torsion, so this semistable Euler characteristic can go both up or down at ``special points''. 

	This example only happens when $r = 0$, so one might hope that this pathological behaviour (the failure of invariance under twists) does not occur when $A$ is for example ordinary. Unfortunately, \autoref{example_euler_char} shows that even this is not true: with $\cM$ as in \emph{loc. cit.}, then our computations show that \[ \chi_{ss}(E, \cM \otimes \cP_\alpha) = \begin{cases}
		0 \mbox{ if $\alpha$ is $p$--power torsion;} \\
		1 \mbox{ if not.}
	\end{cases} \]

	In any case, it can be shown that $\chi_{ss}(A, \cM) \geq 0$ for any Cartier module on an ordinary abelian variety. This is explored in \cite{Baudin_On_the_Euler_characteristic_of_weakly_ordinary_varieties_of_maximal_albanese_dimension}.

\end{rem}

\section{Effectivity of $\omega_X$ for varieties of maximal Albanese dimension}

Our goal here is to show \autoref{intro_effectivity_canonical}. Although the first part of this statement (the one which does not mention ordinarity) already follows from \autoref{generic vanishing}, the second part will require some more work. \\

Let us first show what we claimed in \autoref{first_example}.

\begin{slem}\label{inclusions_SCSL}
	Assume that $A$ is ordinary, and let $\alpha \in \bighat{A}$ be a torsion point. Then for any Cartier module $\cM$ on $A$ and $i \geq 0$, then \[ \alpha \in W^{i + 1}_F(\cM) \implies \alpha \in W^i_F(\cM). \]
\end{slem}

\begin{proof}
	By \autoref{equality_of_SCSL}, it is enough to show that for any $V$--module $\cN$, then if $-\alpha \in W^{i + 1}_F(\cN)$ is a torsion point, also $-\alpha \in W^i_F(\cN)$.


	Let $\beta \coloneqq -\alpha$ be a torsion point, let $\cN$ be a $V$--module on $\bighat{A}$, and let $m \geq 0$ be the order of the point $\beta$ in the group law of $\bighat{A}$. Since $m$ divides $p^{as}(p^{bs} - 1)$ for some $a, b \geq 1$, and since $(p^s)^{-1}W^i_F(\cM) = W^i_F(\cM)$, we may replace $\beta$ by $p^{as}(\beta)$ and assume that $p^{bs}(\beta) = \beta$. Given that \[ \colim_e V^{es, *}\cN \cong \colim_e V^{ebs, *}\cN, \] we may replace $s$ by $bs$ and assume that $b = 1$. In other words, we have $p^s(\beta) = \beta$. In particular, $V^s$ induces a morphism $\cO_{\bighat{A}, \beta} \to \cO_{\bighat{A}, \beta}$. Write $N = \cN_\beta$, and let $\fm_\beta$ denote the maximal ideal of $\cO_{\bighat{A}, \beta}$. Now, let \[ 0 \to K \to P \to N \to 0 \] be a short exact sequence of $\cO_{\bighat{A}, \beta}$--modules, where $P$ is free of finite rank and $P \otimes k(\beta) \to N \otimes k(\beta)$ is an isomorphism. By freeness of $P$, there exists a $V$--module stucture $\theta_P$ on $P$ such that $P \surj N$ becomes a morphism of $V$--modules. In particular, $K$ acquires the structure of a $V$--module too, and we have a commutative diagram with exact rows as follows: \[ \begin{tikzcd}
		0 \arrow[r] & K \arrow[r] \arrow[d, "\theta_K"] & P \arrow[r] \arrow[d, "\theta_P"] & N \arrow[r] \arrow[d, "\theta_N"] & 0  \\
		0 \arrow[r] & {V^{s, *}K} \arrow[r] & {V^{s, *}P} \arrow[r] & {V^{s, *}N} \arrow[r]      & 0
	\end{tikzcd} \]
	For all $j \geq 1$, we then have isomorphisms \[ \colim \Tor_j(V^{es, *}K, k(\beta)) \cong \colim \Tor_{j + 1}(V^{es, *}N, k(\beta)). \] Since $P \to N$ is an isomorphism at $k(\beta)$, this is also the case for each map $V^{es, *}P \to V^{es, *}N$. In particular, we also have that \[ \colim V^{es, *}K \otimes k(\beta) \cong \colim \Tor_1(V^{es, *}N, k(\beta)). \]
	This shows that it is enough to prove that if $\beta \in W^1_F(\cN)$, then $\beta \in W^0_F(\cN)$ (for the other $i$'s, replace $N$ by $K$ and so on).
	We are going to show the contrapositive, so assume that $\beta \notin W^0_F$, i.e. \[ \varinjlim V^{es, *}N \otimes k(\beta) = 0. \]
	This implies that for some $e > 0$, $\theta_N^e(N) \inc \fm_\beta(V^{es, *}N)$. Since both $P \to N$ and $V^{es, *}P \to V^{es, *}N$ are isomorphisms after tensoring by $k(\beta)$, we also have that $\theta_P^e(P) \inc \fm_\beta(V^{es, *}P)$. 

	By Krull's theorem, there exists $c \geq 1$ such that $\fm_\beta^cP \cap K \inc \fm_\beta K$. Thus, 
	\begin{align*} 
		\theta_K^{ce}(K) & \inc V^{ces, *}K \cap \theta_P^{ce}(P) \\
		& \inc V^{ces, *}K \cap \fm_\beta^{c}(V^{ces, *}P) \\
		& \expl{=}{$V$ is étale by \autoref{basic facts about AV}.\autoref{itm:ordinary iff Verschiebung etale}, so $V(\fm_{\beta}^c)\cO_{\bighat{A}, \beta} = \fm_{\beta}^c$} V^{ces, *}K \cap V^{ces, *}(\fm_\beta^{c}P) \\
		& \expl{=}{\cite[Theorem 7.4.(i)]{Matsumura_Commutative_Ring_Theory}} V^{ces, *}\left(K \cap \fm_\beta^{c}P\right) \\
		& \inc V^{ces, *}(\fm_\beta K) \\
		& \expl{=}{$V$ is étale} \fm_\beta V^{ces, *}K.
	\end{align*}
	In other words, $\theta_K^{ce} \otimes k(\beta) = 0$. But then, $V^{r, *}\theta_K^{ce} \otimes k(\beta) = 0$ for all $r \geq 0$, which gives that \[ 0 = \varinjlim V^{es, *}K \otimes k(\beta) \cong \varinjlim \Tor^1(V^{es, *}N, k(\beta)).  \] We conclude that $\beta \notin W^1_F(\cN)$, completing the proof.
\end{proof}


Now let us move to the geometric consequence. We start with a useful well--known fact.

\begin{slem}\label{regular_implis_simple}
	Let $Y$ be a regular variety. Then $\omega_Y$ is simple as a Cartier module (i.e. any sub--Cartier module is either $\omega_Y$ or zero).
\end{slem}
\begin{proof}
	Since $Y$ is Gorenstein, we have to show that the test ideal $\tau(\cO_Y)$ of $Y$ is $\cO_Y$ (see \cite[Section 3]{Schwede_Tucker_A_survey_of_test_ideals}). In other words, we need to show that $Y$ is strongly $F$--regular. This holds by \cite[Theorem 3.1]{Hochster_Huneke_Tight_closure_and_strong_F_reg}.
\end{proof}

We can finally show our last main theorem.

\begin{sthm}\label{effectivity_canonical}
	Let $X$ be a normal proper variety of maximal Albanese dimension. Then $H^0(X, \omega_X) \neq 0$. If furthermore $X$ admits a generically finite morphism to an ordinary abelian variety, then $S^0(X, \omega_X) \neq 0$. 
\end{sthm}
\begin{proof}
	We will show that the conclusion of \autoref{effectivity_canonical} holds for \emph{any} Cartier submodule of $\omega_X$. Hence, let $\ttilde{\omega_X}$ be a Cartier submodule of $\omega_X$. Set also $d \coloneqq \dim(X)$. Let $a \colon X \to A$ be a generically finite morphism to an abelian variety $A$. 

	Assume first that $a \colon X \to A$ is finite. Note that by \cite[Proposition 2.4]{Patakfalvi_Zdanowicz_Ordinary_varieties_with_trivial_canonical_bundle_are_not_uniruled}, Serre duality induces an isomorphism  on $H^d(X, \omega_X) \cong H^0(X, \cO_X)^{\vee}$. Since the Frobenius action on $H^0(X, \cO_X)$ is non--nilpotent, we deduce that $H^d_{ss}(X, \omega_X) \neq 0$. Consider the short exact sequence of Cartier modules \[ 0 \to \ttilde{\omega_X} \to \omega_X \to \cC \to 0. \]
	Since $X$ is regular in codimension one, we deduce from \autoref{regular_implis_simple} that $\codim (\Supp \cC) \geq 2$. Hence, the natural morphism $H^d(X, \ttilde{\omega_X}) \to H^d(X, \omega_X)$ is an isomorphism, whence $H^d_{ss}(X, \ttilde{\omega_X}) \neq 0$. Given that $a$ is finite, we obtain that $H^d_{ss}(A, a_*\ttilde{\omega_X}) \cong H^d_{ss}(X, \ttilde{\omega_X}) \neq 0$. In other words, \[ 0 \in W^d_F(a_*\ttilde{\omega_X}) \expl{\subseteq}{\autoref{generic vanishing}.\autoref{van_and_non_van}} \bigcup_{e > 0} (p^e)^{-1}W^d, \] so $0 \in W^d$.
	Now, we have \[ W^d \expl{\inc}{\autoref{itm:gv_inclusions}} W^0 \expl{\inc}{\autoref{itm:gv_link_with_section}} \set{\alpha \in \bighat{A}}{H^0(A, a_*\ttilde{\omega_X} \otimes \cP_{\alpha}) \neq 0}, \] where both items refer to \autoref{generic vanishing}. In particular, we deduce that \[ H^0(X, \ttilde{\omega_X}) \neq 0. \] If we further assume that $A$ is ordinary, then since $0 \in W^d_F(a_*\ttilde{\omega_X})$, we directly obtain that $0 \in W^0_F(a_*\ttilde{\omega_X})$ by \autoref{inclusions_SCSL}. In other words, $H^0_{ss}(X, \ttilde{\omega_X}) \neq 0$. \\

	Now, let us prove the statement in the general case, i.e. we do not assume that $a$ is finite anymore. Let \[ \begin{tikzcd}
		X \arrow[rr, "f"] \arrow[rrrr, "a"', bend right] &  & Y \arrow[rr] &  & A.
	\end{tikzcd} \] denote the Stein factorization of $a$. Then $f_*\ttilde{\omega_X} \inc f_*\omega_X \inc \omega_Y$, so the statement for $\ttilde{\omega_X}$ on $X$ follows from the statement for $f_*\ttilde{\omega_X}$ on $Y$.
\end{proof}

