		\item\label{inj_H1} $\alb_X^* \colon H^1(\Alb(X), \cO_{\Alb(X)}) \to H^1(X, \cO_X)$ is an injection;
		\item\label{dim_Alb} $b_1(X) = 2\dim(\Alb(X))$.
