\section{Proof of Theorem \ref{main_thm}}
\label{appendix: Proof of Main Theorem}

The proof of Theorem \ref{main_thm} proceeds in several steps, leveraging the principles of duality and optimization to simplify the problem and establish the optimal policy. Below, we outline the key steps.

\subsection{Step 1: Reformulation Using Duality}
We begin by applying the perfect duality principle, as discussed in \cite{mai2021robust}, to interchange the \(\min\) and \(\max\) operations in the original problem. This reformulation reduces the optimization to:

\begin{align}
    \inf_{\widetilde{\mathbb{Q}}^+ \in \mathcal{U}^+_{n, \delta}, \, \widetilde{\mathbb{Q}}^- \in \mathcal{U}^-_{n, \delta}} \quad & \max_{\boldsymbol{\pi}} \, \int_{(\mathbb{R}^+)^2} \boldsymbol{\pi}(\epsilon^+, \epsilon^-) \, \mathbb{E}^{\widetilde{\mathbb{Q}}^+ \otimes \widetilde{\mathbb{Q}}^-} \Bigg[ A \Delta \widetilde{N}^+ - B \Delta \widetilde{N}^- \nonumber \\
    & \quad - \eta \left( C + h^{+}(\epsilon^+) \Delta \widetilde{N}^+ - h^{-}(\epsilon^-) \Delta \widetilde{N}^- \right)^2 \Bigg] \, d\epsilon^+ d\epsilon^- \nonumber \\
    & \quad - \gamma \int_{(\mathbb{R}^+)^2} \boldsymbol{\pi}(\epsilon^+, \epsilon^-) \log \boldsymbol{\pi}(\epsilon^+, \epsilon^-) \, d\epsilon^+ d\epsilon^-
\end{align}


The optimal policy for the innermost maximization problem can be obtained by applying verification theorem. Consequently, the optimal policy under measure \(\widetilde{\mathbb{Q}}^\pm\) is delineated as follows: 

\begin{align}
    \boldsymbol{\pi}(\epsilon^+, \epsilon^-) 
    &\sim 
    \frac{M(\epsilon^+, \epsilon^-)}{\int_{(\mathbb{R}^+)^2} M(\epsilon^+, \epsilon^-) \, d\epsilon^+ \, d\epsilon^-} \nonumber \\ 
    M(\epsilon^+, \epsilon^-) 
    &= 
    \exp \Bigg\{ 
        \frac{1}{\gamma} \mathbb{E}^{\widetilde{\mathbb{Q}}^+ \otimes \widetilde{\mathbb{Q}}^-} \Big[ 
            (A - 2 \eta C h^+(\epsilon^+)) \Delta \widetilde{N}^+ 
            - (B - 2 \eta C h^-(\epsilon^-)) \Delta \widetilde{N}^- \nonumber \\
    & \quad - \eta \Big( h^+(\epsilon^+) \Delta \widetilde{N}^+ 
            - h^-(\epsilon^-) \Delta \widetilde{N}^- \Big)^2 
        \Big] 
    \Bigg\} L(\epsilon^+, \epsilon^-) \nonumber \\ 
    L(\epsilon^+, \epsilon^-) 
    &= 
    \exp \Bigg\{ 
        \frac{1}{\gamma} \Big[ 
            (S + \epsilon^+) f^+(\epsilon^+) 
            - (S - \epsilon^-) f^-(\epsilon^-) 
            - \eta C^2 
        \Big] 
    \Bigg\}
\end{align}







Upon eliminating terms independent of \((\Delta \widetilde{N}^+, \Delta \widetilde{N}^-)\) and incorporating the optimal policy, the optimization problem we address is formulated as follows:
\begin{align}
     \inf_{\widetilde{\mathbb{Q}}^+ \in \mathcal{U}^+_{n, \delta}, \, \widetilde{\mathbb{Q}}^- \in \mathcal{U}^-_{n, \delta}}  \gamma \int_{(\mathbb{R}^+)^2} M(\epsilon^+, \epsilon^-) \, d\epsilon^+ \, d\epsilon^-
\end{align}
which is equivalent to 
\begin{align}
     \sup_{\widetilde{\mathbb{Q}}^+ \in \mathcal{U}^+_{n, \delta}, \, \widetilde{\mathbb{Q}}^- \in \mathcal{U}^-_{n, \delta}}  -\gamma \int_{(\mathbb{R}^+)^2} M(\epsilon^+, \epsilon^-) \, d\epsilon^+ \, d\epsilon^-
\end{align}
our subsequent objective is to define the constraint domain for the optimization problem. Since \(M(\epsilon^+, \epsilon^-)\) depends on the first and second moments of \(\Delta \widetilde{N}^\pm\), we simplify the notation as follows:
\[
\alpha^\pm = \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm} [\Delta \widetilde{N}^\pm], \quad \beta^\pm = \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm} [(\Delta \widetilde{N}^\pm)^2], \quad \text{where } \widetilde{\mathbb{Q}}^\pm \in \mathcal{U}_{n, \delta}^\pm.
\]
Under the empirical distribution \(\mathbb{\widehat{Q}}_n^\pm\), these quantities are defined as:
\[
\alpha_n^\pm = \mathbb{E}^{\mathbb{\widehat{Q}}_n^\pm} [\Delta \widetilde{N}^\pm], \quad \beta_n^\pm = \mathbb{E}^{\mathbb{\widehat{Q}}_n^\pm} [(\Delta \widetilde{N}^\pm)^2].
\]

Next, we will introduce two propositions before the proof of theorem \ref{main_thm}.

\subsection{Range of \(\alpha^\pm\)}

\begin{proposition}
\label{prop:range_alpha}
The range of \(\alpha^\pm\), where \(\widetilde{\mathbb{Q}}^\pm \in \mathcal{U}_{n, \delta}^\pm\), is given by the interval:
\[
\alpha^\pm \in \left[\alpha_n^\pm - \sqrt{\delta}, \, \alpha_n^\pm + \sqrt{\delta} \right].
\]
\end{proposition}

\begin{proof}
First, compute the upper bound of the expectation
\begin{align}
    \sup_{\widetilde{\mathbb{Q}}^\pm \in \mathcal{U}_\delta(\widehat{\mathbb{Q}}^\pm_n)} \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[\xi^\pm] &= \inf_{\lambda} \Big\{ \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[  \sup_{z} \{  z - \lambda \| z - \xi^\pm   \|^2   \}  \big]  + \lambda \delta \Big\} \nonumber \\
    & = \inf_{\lambda} \Big\{  \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[  \sup_{\Delta} \{  \Delta + \xi^\pm - \lambda \| \Delta  \|^2   \}  \big]  + \lambda \delta    \Big\} \nonumber \\
    & =  \inf_{\lambda} \Big\{  \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[ \xi^\pm  \big] + \frac{1}{4\lambda}  + \lambda \delta   \Big\} \nonumber \\
    & =  \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[ \xi^\pm  \big] + \sqrt{\delta} 
\end{align}
As for the lower bound of the expectation
\begin{align}
    \inf_{\widetilde{\mathbb{Q}}^\pm \in \mathcal{U}_\delta(\widehat{\mathbb{Q}}^\pm_n)} \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[\xi^\pm] &= -\sup_{\widetilde{\mathbb{Q}}^\pm \in \mathcal{U}_\delta(\widehat{\mathbb{Q}}^\pm_n)} \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[-\xi^\pm] \nonumber \\
    & = - \inf_{\lambda} \Big\{ \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[  \sup_{z} \{  -z - \lambda \| z - \xi^\pm  \|^2   \}  \big]  + \lambda \delta \Big\} \nonumber \\
    & = -\inf_{\lambda} \Big\{   \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[  \sup_{\Delta} \{  -\Delta - \xi^\pm - \lambda \| \Delta  \|^2   \}  \big]  + \lambda \delta    \Big\} \nonumber \\ 
    & = - \inf_{\lambda} \Big\{  \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[ -\xi^\pm  \big] + \frac{1}{4\lambda}  + \lambda \delta   \Big\} \nonumber \\
    & =   \mathbb E^{\widehat{\mathbb Q}_n^\pm}\big[\xi^\pm  \big] - \sqrt{\delta}
\end{align}
\end{proof}


\subsection{Range of $\beta^\pm$}

With this foundation established, we now turn our attention to delineating the range for \(\mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[(\Delta \widetilde{N}^\pm)^2]\), given that \(\alpha^\pm\) is confined within the interval \(\left[\alpha_n^\pm - \sqrt{\delta}, \alpha_n^\pm + \sqrt{\delta} \right]\). This forms the basis of our second claim.

\begin{proposition}
\label{prop:range_beta}
For a given expectation \(\alpha^\pm \in \left[\alpha_n^\pm - \sqrt{\delta}, \alpha_n^\pm + \sqrt{\delta} \right]\), the second moment satisfies \(\beta^\pm \in [\ell(\alpha^\pm), u(\alpha^\pm)]\), where:
\begin{align}
    u(\alpha^\pm) &= \beta_n^\pm + 2(\alpha^\pm - \alpha_n^\pm) \alpha_n^\pm + \delta + 2 \sqrt{\text{Var}^{\widehat{\mathbb{Q}}^\pm_n}(\Delta \widetilde{N}^\pm)} \sqrt{\delta - (\alpha^\pm - \alpha_n^\pm)^2}, \nonumber \\
    &= \beta_n^\pm + 2(\alpha^\pm - \alpha_n^\pm) \alpha_n^\pm + \delta + 2 \sqrt{\beta_n^\pm - (\alpha_n^\pm)^2} \sqrt{\delta - (\alpha^\pm - \alpha_n^\pm)^2}, \\
    \ell(\alpha^\pm) &= 2(\alpha^\pm - \alpha_n^\pm) \alpha_n^\pm + \delta - 2 \sqrt{\text{Var}^{\widehat{\mathbb{Q}}^\pm_n}(\Delta \widetilde{N}^\pm)} \sqrt{\delta - (\alpha^\pm - \alpha_n^\pm)^2}, \nonumber \\
    &= 2(\alpha^\pm - \alpha_n^\pm) \alpha_n^\pm + \delta - 2 \sqrt{\beta_n^\pm - (\alpha_n^\pm)^2} \sqrt{\delta - (\alpha^\pm - \alpha_n^\pm)^2}.
\end{align}
\end{proposition}

\begin{proof}
 For the upper bound, 
    \begin{align}
        u(\alpha) = \max_{\widetilde{\mathbb{Q}}^\pm \in \mathcal{U}_\delta(\widehat{\mathbb Q}^\pm_n), \  \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[\xi^\pm] = \alpha } \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[(\xi^\pm)^2]
    \end{align}
    This derivation represents a special case of propositions \(A.2\) and \(A.3\) in \cite{blanchet2022distributionally}, which can be readily deduced. \\ 
    As for the lower-bound
    \begin{align}
        \ell(\alpha) &= - \max_{\widetilde{\mathbb{Q}}^\pm \in \mathcal{U}_\delta(\widehat{\mathbb Q}^\pm_n), \  \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[\xi^\pm] = \alpha } \mathbb{E}^{\widetilde{\mathbb{Q}}^\pm}[-(\xi^\pm)^2] \nonumber \\
        & = -\inf_{\lambda_1 \geq 0, \lambda_2} \Big\{ \frac{1}{n} \sum_{i = 1}^{n} \sup_u \big[  -u^2 - \lambda_1 (u - \xi^\pm_i)^2 - \lambda_2 u  \big] + \lambda_1 \delta + \lambda_2 \alpha   \Big\} 
    \end{align}
    Here, 
    \begin{align}
         & \sup_u \big[  -u^2 - \lambda_1 (u - \xi^\pm_i)^2 - \lambda_2 u  \big] \nonumber \\
    = &\sup_u \big[  -(1 + \lambda_1) u^2 + (2\lambda_1 \xi^\pm_i - \lambda_2) u - \lambda_1 (\xi^\pm_i)^2 \big] \nonumber \\
    = &\frac{ (2\lambda_1 \xi^\pm_i - \lambda_2)^2  }{4(1 + \lambda_1)} - \lambda_1 (\xi^\pm_i)^2
    \end{align}
    Then, the lower bound becomes
    \begin{align}
        h(\alpha) =  \inf_{\lambda_1 \geq 0, \lambda_2} \Big\{ \frac{1}{n} \sum_{i = 1}^{n} \bigg[  \frac{ (2\lambda_1 \xi^\pm_i - \lambda_2)^2  }{4(1 + \lambda_1)} - \lambda_1 (\xi^\pm_i)^2 \bigg] + \lambda_1 \delta + \lambda_2 \alpha   \Big\} 
    \end{align}
    Taking the partial derivatives w.r.t $\lambda_2$, we get
    \begin{align}
        \lambda_2 &= -2(1 + \lambda_1) \alpha + 2\lambda_1 \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]  
    \end{align}

    Let $\kappa = 1 + \lambda_1$, and plugging in $\lambda_2$, we get
    \begin{align}
        &\inf_{\kappa \geq 1} \Big\{  \frac{1}{n} \sum_{i = 1}^{n} \Big[  
      \frac{ (\kappa \alpha + (\kappa - 1) \widehat{\xi}^\pm_i - (\kappa - 1) \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]    )^2 }{ \kappa} - (\kappa - 1) (\widehat{\xi}^\pm_i)^2  \Big] \nonumber \\
      +& (\kappa - 1) \delta - 2\kappa \alpha^2 + 2 (\kappa - 1) \alpha \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]   \Big\} \nonumber \\
      =& \inf_{\kappa \geq 1} \Big \{  \frac{1}{n} \sum_{i = 1}^{n} \Big[  (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])(\alpha + 2\widehat{\xi}_i - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm] ) \kappa + \frac{(\mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]  - \widehat{\xi}_i)^2}{\kappa}  \Big]   + \kappa \delta - 2\alpha^2 \kappa + 2 \alpha \kappa \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]     \Big \} \nonumber \\
      +& \frac{1}{n} \sum_{i = 1}^{n} \big[ 2 (\alpha + \widehat{\xi}_i - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]  )(\mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]  - \widehat{\xi}_i) + (\widehat{\xi}_i)^2 \big] - \delta - 2 \alpha \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm]    \nonumber \\
      =& \inf_{\kappa \geq 1} \Big\{  \big( \delta - (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2   \big) \kappa + \frac{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi)}{\kappa}    \Big\} + 2(\mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2  - \delta - 2 \alpha \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm] \nonumber \\
      =& \min \Big\{  \text{Var}^{\widehat{\mathbb Q}^\pm_n}(\xi^\pm)  + (\mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2  - \alpha^2, 2(\mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2  - \delta - 2 \alpha \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm] \nonumber \\
      +& 2 \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi^\pm)} \sqrt{ \delta - (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2 } \   \Big\}
    \end{align}
    As we notice that, in the above $\min$ bracket, 
    \begin{align}
         &\delta + 2 \alpha \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm] - 2 \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi)} \sqrt{ \delta - (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2  } - 2(\mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2 - (\alpha^2 -   \text{Var}^{\widehat{\mathbb Q}^\pm_n}(\xi^\pm)  - (\mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2 ) \nonumber \\
          = & \ \delta -  2 \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi)} \sqrt{ \delta - (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2  } + \text{Var}^{\widehat{\mathbb Q}^\pm_n}(\xi) - (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2 \nonumber \\
          = & \ \Big( \sqrt{\delta - (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2 } - \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi)}  \Big)^2 \geq 0
    \end{align}
    Therefore, the lower bound is
    \begin{align}
        \ell(\alpha) = 2(\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm]) \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm] + \delta  - 2 \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi)} \sqrt{ \delta - (\alpha - \mathbb E^{\widehat{\mathbb Q}^\pm_n} [\xi^\pm])^2  } 
    \end{align}
\end{proof}

\subsection{Proof of Theorem \ref{main_thm}}
With the proposition \ref{prop:range_alpha}, and proposition \ref{prop:range_beta}, we are now ready for the proof of the theorem \ref{main_thm}.


\begin{proof}
After plugging the $\beta^\pm$, the expression inside the exponential function becomes 
    \begin{align}
        &(A - 2 \widetilde{\eta} C h^+) \alpha^+ - (B - 2 \widetilde{\eta} C h^-) \alpha^- + 2\widetilde{\eta} h^+ h^- \alpha^+ \alpha^- - \widetilde{\eta} (h^+)^2 \beta^+ - \widetilde{\eta} (h^-)^2 \beta^- \nonumber \\
        = & (A - 2 \widetilde{\eta} C h^+) \alpha^+ - (B - 2 \widetilde{\eta} C h^-) \alpha^- - \widetilde{\eta}(h^+\alpha^+ - h^- \alpha^-)^2 \nonumber \\
        - & \widetilde{\eta} (h^+)^2 \Big( \sqrt{\text{Var}^{\widehat{\mathbb Q}^+_n} (\xi^+)} +  \sqrt{\delta - (\alpha^+ - \mathbb E^{\widehat{\mathbb Q}^+_n}[\xi^+])^2}  \Big)^2 - \widetilde{\eta} (h^-)^2 \Big( \sqrt{\text{Var}^{\widehat{\mathbb Q}^-_n} (\xi^-)} +  \sqrt{\delta - (\alpha^- - \mathbb E^{\widehat{\mathbb Q}^-_n}[\xi^\pm])^2}  \Big)^2 \nonumber 
    \end{align}
    The following function $(h^+\alpha^+ - h^- \alpha^-)^2$ has Hessian matrix 
    \begin{align}
        \begin{pmatrix}
             2(h^+)^2 & -2h^+h^- \\
             -2h^+h^- & 2(h^-)^2
        \end{pmatrix}
    \end{align}
    the Hessian matrix has determinant $0$, then by Sylvester's criterion, it is a positive semi-definite matrix, which makes $(h^+\alpha^+ - h^- \alpha^-)^2$ a convex function. 
    now, let's consider the last two terms, first define function $\phi(\alpha^\pm)$
    \begin{align}
        \phi(\alpha^\pm) = \Big( \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi^\pm)} +  \sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2}  \Big)^2
    \end{align}
    the first derivative of $\phi(\alpha^\pm)$ is 
    \begin{align}
        \frac{\partial \phi(\alpha^\pm)}{\partial \alpha^\pm} = 2 \Big( \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi^\pm)} +  \sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2}  \Big) \frac{- (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm]) }{\sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2} }
    \end{align}
    then the second derivative is 
    \begin{align}
        &\frac{\partial}{\partial \alpha^\pm} \  2 \Big( \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi^\pm)} +  \sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2}  \Big) \frac{- (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm]) }{\sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2} } \nonumber \\
        =&  2 \Big( \sqrt{\text{Var}^{\widehat{\mathbb Q}^\pm_n} (\xi)} +  \sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2}  \Big) \frac{ - \sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2} -   \frac{(\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2 }{\sqrt{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2} } }{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2} \nonumber \\
        +& \frac{2 (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2 }{\delta - (\alpha^\pm - \mathbb E^{\widehat{\mathbb Q}^\pm_n}[\xi^\pm])^2} \nonumber \\
