\begin{align}
    &\textbf{Tr} \big(\boldsymbol{\lambda}^* \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*) \nonumber \\
    =& \textbf{Tr} \left\{ \frac{1}{2n  \left( 1 - \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n \right)} \Big(   \boldsymbol{\alpha}^* - \boldsymbol{\alpha}_n + (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)\boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n  \Big) \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)  \right\} \nonumber \\
    =& \textbf{Tr} \left\{ \frac{1}{2n  \left( 1 - \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n \right)}  \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)    \Big(   \boldsymbol{\alpha}^* - \boldsymbol{\alpha}_n + (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)\boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n  \Big) \right\} \nonumber \\
    =& \frac{\boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)  (   \boldsymbol{\alpha}^* - \boldsymbol{\alpha}_n )}{2n  \left( 1 - \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n \right)} + \frac{  \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)^2  \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n  }{2n  \left( 1 - \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n \right)} \nonumber
\end{align}



Then, the robust profile becomes 
\begin{align}
     &\mathcal{R}(\boldsymbol{\alpha}^*, \boldsymbol{\Sigma}^*) \nonumber \\
    =& \frac{ (\boldsymbol{\alpha}^* - \boldsymbol{\alpha}_n)^T (\boldsymbol{\alpha}^* - \boldsymbol{\alpha}_n) }{4n  \left( 1 - \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n \right) } + \frac{\boldsymbol{\alpha}_n \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)^2 \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n   }{4n  \left( 1 - \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n \right)} + \frac{\boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)  (   \boldsymbol{\alpha}^* - \boldsymbol{\alpha}_n )}{2n  \left( 1 - \boldsymbol{\alpha}_n^T \boldsymbol{\Sigma}_n^{-1} \boldsymbol{\alpha}_n \right)} \nonumber \\ 
     +& \frac{1}{2n} \textbf{Tr}\Big( (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*) \boldsymbol{\Sigma}_n^{-1} (\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*) \Big) + \frac{1}{4n} \mathbb E^{\widehat{\mathbb{Q}}_n^+ \otimes \widehat{\mathbb{Q}}_n^-} \Big[ \boldsymbol{u}^T \boldsymbol{\Sigma}_n^{-1}(\boldsymbol{\Sigma}_n - \boldsymbol{\Sigma}^*)^2 \boldsymbol{\Sigma}_n^{-1}\boldsymbol{u} \Big]
\end{align}
\end{proof}


