\section{End matter}

\paragraph{Appendix A: Response to errors is not bounded by entropy production ---} 

The main text contains an intuitive explanation for why the bounds \eqref{eq:multitr:inequalities} are formulated in terms of the affinity rather than entropy production. This paragraph presents the example in which the ratio $\mathcal{R}^\eps\!/\sigma$ diverges more explicitly. We consider two pairs of transitions, $x$ and $y$, which connect a single state to itself. This peculiarity of having one state and two transition channels is not pivotal but simplifies the discussion; essentially the same reasoning applies to a two-dimensional discrete random walk with horizontal transitions $x$ and vertical transitions $y$. 

We assume that transitions along $y$ are not driven, i.e., $s(y) = 0$, which can be realized through equal transition rates along $y$ and $\rev{y}$. Additionally, we assume that transitions along $x$ and $\rev{x}$ are possible but rare and parametrize $p(x) = e^{s(x)} \delta, p(\rev{x}) = \delta$ for a small $\delta > 0$. The total entropy production in the system is given by
\begin{equation}
    \sigma = (p(x) - p(\rev{x})) s(x) = \delta \cdot s(x) (e^{s(x)} - 1)
,\end{equation}
thus equilibrium is attained for $\delta \to 0$. As error matrix we assume
\begin{equation}
    p_{y' \to x'} = \begin{cases}
        1 \quad y' = y, x' = x \text{ or } y' = \rev{y}, x' = \rev{x} \\
        0 \quad \text{ else }
    \end{cases}
,\end{equation}
which respects the symmetry condition \eqref{eq:symm_error}. The response $\mathcal{R}^\eps$ can be calculated via Eq. \eqref{eq:multitr:generalres}, yielding
\begin{equation}
    \mathcal{R}^\eps = 2 p(y) \left[ \cosh s(x) - 1 \right] \geq p(y) s(x)^2 = \mathcal{R}^\eps_{\text{l.r.}}
\end{equation}
independently of $\delta$. Thus, this quantity remains constant in the limit $\delta \to 0$, whereas $\sigma \to 0$, such that the ratio $\mathcal{R}^\eps\!/\sigma$ diverges.

\paragraph{Appendix B: Transition-based coarse graining---} This section briefly explains estimation of entropy production if some transitions in a network and the time at which they take place are observable, as in the set-up shown in Fig. \ref{fig:err_corr}. 

Sufficient transition statistics enable us to determine the distribution of waiting times between two subsequent transitions $I$ followed by $J$. The corresponding waiting-time distribution $\psi_{I \to J} (t)$ is normalized such that $\sum_J \int_0^\infty dt \psi_{I \to J} (t) = 1$. In the steady state the quantity
\begin{equation}
    \hat{\sigma} = \sum_{IJ} \int_0^\infty dt p(I) \psi_{I \to J} (t) \ln \frac{\psi_{I \to J} (t)}{\psi_{\rev{J} \to \rev{I}} (t)}
    \label{eq:end:sigma_tr}
\end{equation}
satisfies $\hat{\sigma} \leq \sigma$ and is therefore a consistent estimator for entropy production \cite{vdm22,haru22}. The waiting-time distribution $\psi_{I \to J} (t)$ can be viewed as the distribution of first-passage times of $J$, which can be calculated from the dynamics of the underlying microscopic model by solving a suitable initial value problem. For transitions $I = (kl), J = (mn)$ the waiting-time distribution $\psi_{I \to J} (t)$ is given by
\begin{equation}
    \psi_{I \to J} (t) = P(\gamma(t) = m|\gamma(0) = l)k_{mn}
,\end{equation}
where $k_{mn}$ denotes the transition rate from state $m$ to $n$ and $P(\gamma(t) = m|\gamma(0) = l)$ is obtained by solving the master equation subject to the initial condition $P(\gamma(0) = i) = \delta_{il}$ \cite{seki21, vdm22,haru22}. The sequence of observed transitions themselves is itself a discrete-time Markov chain with transition probabilities $\pi_{I \to J}$ given by 
\begin{equation}
     \pi_{I \to J} = \int_0^\infty dt \psi_{I \to J} (t)
.\end{equation}
If removing the observed transitions from the Markov network results in a network that is at detailed balance, e.g., one that does not contain any hidden cycles, then the estimator \eqref{eq:end:sigma_tr} is tight even when waiting times are not taken into account, i.e., the two equalities
\begin{equation}
    \hat{\sigma} = \sigma = \sum_{IJ} p(I) \pi_{I \to J} \ln \frac{\pi_{I \to J}}{\pi_{\rev{J} \to \rev{I}}}
    \label{eq:end:sigma_tr_no_wt}
\end{equation}
are satisfied \cite{vdm22}. The corresponding estimator in the presence of errors is
\begin{equation}
    \hat{\sigma}^\eps = \sum_{IJ} p^\eps(I) \pi^\eps_{I \to J} \ln \frac{\pi^\eps_{I \to J}}{\pi^\eps_{\rev{J} \to \rev{I}}}
    \label{eq:end:sigma_tr_err}
,\end{equation}
with $p^\eps(I)$ as in Eq. \eqref{eq:multitr:ep_def}. As detailed in the SM \cite{Supplement}, the probabilities $\pi^\eps_{I \to J}$ can be calculated from the two-step probabilities $p^\eps(IJ)$ to observe first $I$, then $J$ via
\begin{align}
    \pi^\eps_{I \to J} = \frac{p^\eps(IJ)}{\sum_K p^\eps(IK)} = \frac{p^\eps(IJ)}{p^\eps(I)}
    \label{eq:end:p_split_eps}
.\end{align}
In Figure \ref{fig:err_corr}\,(c), the values for $\sigma$ and $\hat{\sigma}^\eps$ were obtained by first calculating the transition probabilities $\pi_{I \to J}$ from the underlying model followed by a direct calculation using Eq. \eqref{eq:end:sigma_tr_no_wt} and Eq. \eqref{eq:end:sigma_tr_err}, respectively.

It is worth noting that in the error-free case only two of the three pairs of observed transitions are needed to recover the full entropy production rate, i.e., Eq. \eqref{eq:end:sigma_tr_no_wt} can be applied even when only two suitable pairs of transitions are observed, e.g., $K_\pm$ and either $I_\pm$ or $J_\pm$. However, the additional pair of observed transitions becomes crucial when errors are introduced, because it provides the redundant information in the coarse-grained trajectory that enables the error detection and correction mechanism, which leads to the improved estimates of entropy production. 

\paragraph{Appendix C: Decomposition of entropy production---}  
The general result Eq. \eqref{eq:sigma_diff} provides a decomposition of $\hat{\sigma}^\eps$ and $\sigma -\hat{\sigma}^\eps$ into nonnegative contributions from individual pairs of a trajectory $\gamma$ and its observation $\Gamma^\eps$. In the case of observed transitions in a Markov network as in Fig. \ref{fig:err_corr}, the microscopic path weight is known, therefore explicit results like the contribution of parts of a trajectory with $n$ subsequent errors, which scale as $\eps^n$, can be computed explicitly.

The calculation is simplified by utilizing Eq. \eqref{eq:end:sigma_tr_no_wt}, which allows us to, firstly, replace $\gamma$ by its correct coarse graining $\Gamma$ in Eq. \eqref{eq:sigma_diff} and, secondly, discard the waiting times in $\Gamma$ because only the transition statistics of $\Gamma$ contribute to $\sigma$. This leaves us with the task of comparing the irreversibility of $\Gamma^\eps$, the sequence of observed, faulty transitions, to $\Gamma$ the corresponding correct sequence. We now apply the framework of Ref. \cite{vdm23}, which allows a decomposition of the irreversibility of a steady-state trajectory $\Gamma$ of duration $T$ into trajectory snippets $\Gamma^s$ that takes the form
\begin{align}
    \frac{1}{T}\braket{\ln \frac{P[\Gamma]}{P[\widetilde{\Gamma}]}} = \sum_{\Gamma^s, I} P(I) \mathcal{P}[\Gamma^s|I] \ln \frac{\mathcal{P}[\Gamma^s|I]}{\mathcal{P}[\widetilde{\Gamma^s}|\rev{J}]}
    \label{eq:end:snippets}
.\end{align}
A snippet $\Gamma^s$ is defined as a steady-state trajectory between two observable events $I$ and $J$, which satisfy the Markov property in a specific sense. The condition under which Eq. \eqref{eq:end:snippets} applies is that $I$ and $J$ are Markovian events, meaning that, for example, observing $I$ implies that the future dynamics after $I$ is conditionally independent from its past \cite{vdm23}. This condition is satisfied on the level of $\Gamma$ for any observable transitions $I$, $J$, but to obtain the desired decomposition into trajectory snippets containing $n$ subsequent errors only correctly observed transitions are treated as valid initial and final Markovian events. Thus, in the previous equation $P(I) = (1 - \eps) p(I)$ denotes the rate at which a correctly observed transition $I$ occurs and initializes a snippet $\Gamma^s$, which by construction has correctly observed initial and final states but variable length. Schematically we denote $\Gamma^s$ and its observed counterpart, $\Gamma^{s, \eps}$ by
\begin{alignat}{3}
    \Gamma^{s} & = I_0 \to I_1 \to \cdots & & \to I_{n} && \to I_{n+1} \\
    \Gamma^{s, \eps} & = I_0 \to I_1^\eps \to \cdots & & \to I_{n}^\eps &&\to I_{n+1}
\end{alignat}
with respective path weights
\begin{align}
    \mathcal{P}[\Gamma^{s}] & = P(I_0) \mathcal{P}[\Gamma| I_0] \nonumber \\ & = (1 - \eps) p(I_0) \prod_{j = 0}^n \pi_{I_j \to I_{j+1}} \\
    \mathcal{P}[\Gamma^{s, \eps}|\Gamma^{s}] & = \eps^n \prod_{j = 1}^n p_{I_j \to I_j^\eps}
.\end{align}
To apply Eq. \eqref{eq:end:snippets}, we set $I = I_0$, $J = I_{n+1}$ and understand the sum over all possible $\Gamma^s$ as a sum over all possible $I_0, \cdots I_{n+1}$ and all $n \geq 0$. We note that the symmetry condition \eqref{eq:symm_error} is satisfied if $p_{I_j \to I_j^\eps} = p_{\rev{I_j} \to \rev{I_j^\eps}}$. Thus, substituting
\begin{align}
    \ln \frac{\mathcal{P}[\Gamma^s|I_0]}{\mathcal{P}[\widetilde{\Gamma^s}|\rev{I}_{n+1}]} & = \ln \frac{\mathcal{P}[\Gamma^s, \Gamma^{s, \eps}|I_0]}{\mathcal{P}[\widetilde{\Gamma^s}, \widetilde{\Gamma^{s, \eps}}|\rev{I}_{n+1}]} \nonumber \\ & = \ln \frac{\mathcal{P}[\Gamma^{s, \eps}|I_0]}{\mathcal{P}[\widetilde{\Gamma^{s, \eps}}|\rev{I}_{n+1}]} + \ln \frac{\mathcal{P}[\Gamma^s|\Gamma^{s, \eps}]}{\mathcal{P}[\widetilde{\Gamma^{s}}|\widetilde{\Gamma^{s, \eps}}]}
\end{align}
into \eqref{eq:end:snippets} yields the decomposition into
\begin{equation}
    \hat{\sigma}^\eps = \sum_{n \geq 0} \sum_{\substack{I_0, ..., I_{n+1} \\ I^\eps_1, ..., I^\eps_n}} \mkern-12mu P(I_0) \mathcal{P}[\Gamma^{s, \eps}, \Gamma^{s}|I_0] \ln \frac{\mathcal{P}[\Gamma^{s, \eps}|I_0]}{\mathcal{P}[\widetilde{\Gamma^{s, \eps}}|\rev{I}_{n+1}]}
    \label{eq:end:decomposition}
,\end{equation}
the visible contribution under errors, and its complement $\sigma - \hat{\sigma}^\eps$ in analogy to Eq. \eqref{eq:sigma_diff}. We can now identify $\hat{\sigma}^\eps_n$ as defined in Eq. \eqref{eq:error:decomposition} and $\sigma_n - \hat{\sigma}^\eps_n$ as the contributions due to the $n$-th term, which contain all possible snippets that contain $n$ subsequent errors surrounded by a correctly registered initial and final transition.

