\subsection{Appendix D: Thermodynamic bounds -- Calculations and proofs}

The following sections contain details about the derivations of the exact expression Eq. \eqref{eq:multitr:generalres} for the response quantity $\mathcal{R}^\eps$ defined in Eq. \eqref{eq:multitr:defR}. 

\subsubsection{First-order response in terms of probabilities}

In this section we calculate $\mathcal{R}^\eps$ in terms of $p(x)$, the steady-state rates of a transition $x$, and $p_{y \to x}$, the probability that an error in transition $y$ results in a registered transition $x$. In the following calculations, we use the shorthand $q(x) = p(\rev{x})$ and similarly $q^\eps(x) = p^\eps(\rev{x})$ to denote the steady-state rate of the reverse transition of $x$.

Starting from the expression
\begin{align}
    \braket{\sigma} - \braket{\sigma^\eps} = \frac{1}{2} \left( \sum_x (p(x) - q(x)) \ln \frac{p(x)}{q(x)} - \sum_x  (p^\eps(x) - q^\eps(x)) \ln \frac{p^\eps(x)}{q^\eps(x)} \right)
,\end{align}
we first express $p^\eps(x)$ in terms of $p(x)$ using Eq. \eqref{eq:multitr:ep_def}. We note that the following calculations remain valid for a nonvanishing diagonal $p_{y \to y} \geq 0$. Expanding the logarithm to second order in $\eps$ yields
\begin{align}
    \ln \frac{p^\eps(x)}{q^\eps(x)} & = \ln \frac{p(x) (1 - \eps) + \sum_y  \eps p(y) p_{y \to x}}{q(x) (1 - \eps) + \sum_y  \eps q(y) p_{y \to x}} 
    = \ln \frac{p(x)}{q(x)} + \ln \frac{1 - \eps + \eps \sum_y p(y) p_{y \to x}/p(x)}{1 - \eps + \eps \sum_y q(y) p_{y \to x}/q(x)} \\
    & = \ln \frac{p(x)}{q(x)} + \eps \left( \frac{\sum_y p(y) p_{y \to x}}{p(x)} - \frac{\sum_y q(y) p_{y \to x}}{q(x)} \right) + O(\eps^2)
,\end{align}
which can be substituted into the previous equation to obtain 
\begin{align}
    2 (\braket{\sigma} - \braket{\sigma^\eps}) = \, & \sum_x \left( p(x) - q(x) - (p^\eps(x) - q^\eps(x)) \right) \ln \frac{p(x)}{q(x)} \nonumber \\ & - \sum_x (p^\eps(x) - q^\eps(x)) \left( \eps \left( \frac{\sum_y p(y) p_{y \to x}}{p(x)} - \frac{\sum_y q(y) p_{y \to x}}{q(x)} \right) + O(\eps^2) \right)
.\end{align}
For the first line, we use Eq. \eqref{eq:multitr:ep_def} in the form
\begin{align}
    (p(x) - q(x)) - (p^\eps(x) - q^\eps(x)) = - \eps \left( - p(x) + q(x) + \sum _y p(y) p_{y \to x} - \sum _y q(y) p_{y \to x} \right) + O(\eps^2)
,\end{align}
whereas the second line already is of order $\eps$, so the zeroth-order approximation of $p^\eps(x) - q^\eps(x)$ suffices. After rearranging terms, we take the limit $\eps \to 0$
\begin{align}
    2 \mathcal{R}^\eps = 2 \lim_{\eps \to 0} \frac{\braket{\sigma} - \braket{\sigma^\eps}}{\eps} 
    = & \, \sum_{x} (p(x) - q(x)) \ln \frac{p(x)}{q(x)} - \sum_{xy} p_{y \to x} (p(y) - q(y)) \ln \frac{p(x)}{q(x)} \nonumber \\
    & - \sum_x (p(x) - q(x)) \left( \frac{\sum_y p(y) p_{y \to x}}{p(x)} - \frac{\sum_y q(y) p_{y \to x}}{q(x)}  \right)
    \label{eq:app_a:general_res}
.\end{align}
The first term on the right hand side is $2 \braket{\sigma}$, but it will be convenient to artificially introduce a normalization $\sum_x p_{y \to x}=1$ to rewrite this term as $2 \braket{\sigma} = \sum_{yx} p_{y \to x}(p(y)-q(y) \ln [p(y)/q(y)]$. After dividing by $2$ and rewriting the third term on the right hand side, we arrive at
\begin{align}
    \mathcal{R}^\eps
    = \, \frac{1}{2} \left( \sum_{yx} p_{y \to x}(p(y)-q(y) \ln \frac{p(y)}{q(y)} - \sum_{xy} p_{y \to x} (p(y) - q(y)) \ln \frac{p(x)}{q(x)}
    - 2 +\sum_{xy} p_{y \to x} \left( \frac{q(x)}{p(x)} p(y) + \frac{p(x)}{q(x)} q(y) \right) \right)
    \label{eq:app_a:general_res_2}.
\end{align}
A more symmetric form can be obtained by combining the first two logarithmic terms, which yields
\begin{align}
    \mathcal{R}^\eps
    & = -1 + \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} (p(y) - q(y)) \ln \frac{p(y)q(x)}{q(y)p(x)} + \frac{1}{2} \sum_{xy} p_{y \to x} \left( \frac{q(x)}{p(x)} p(y) + \frac{p(x)}{q(x)} q(y) \right) \nonumber \\
    & = -1 + \frac{1}{2} \sum_{xy} p_{y \to x} p(y) \left[\frac{q(y)p(x)}{p(y)q(x)} + \ln \frac{p(y)q(x)}{q(y)p(x)} \right] + \frac{1}{2} \sum_{xy} p_{y \to x} q(y) \left[ \frac{p(y)q(x)}{q(y)p(x)} + \ln \frac{q(y)p(x)}{p(y)q(x)} \right]
    \label{eq:app_a:general_res_3} 
.\end{align}

\subsubsection{Response in terms of affinities}

The previous expression, Eq. \eqref{eq:app_a:general_res_3} contains two sums, into which we distribute the constant $-1$ symmetrically. After identifying $s(x) = \ln [p(x)/q(x)]$ and rearranging, we obtain
\begin{align}
\mathcal{R}^\eps
     & = \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} p(y) \left[e^{s(x) - s(y)} - (s(x) - s(y)) - 1 \right] + \frac{1}{2} \sum_{xy} p_{y \to x} q(y) \left[e^{s(y) - s(x)} - (s(y) - s(x)) - 1 \right] \nonumber \\
     & = \sum_{x,y \neq x} p_{y \to x} p(y) \left[e^{s(x) - s(y)} - (s(x) - s(y)) - 1 \right]
     \label{eq:app_a:resp_s}
,\end{align}
which corresponds to Eq. \eqref{eq:multitr:generalres} in the main text. In passing to the second line in Eq. \eqref{eq:app_a:resp_s}, we have replaced the summation indices $x,y$ by $\tilde{x}, \tilde{y}$ in the second sum. Using the symmetry condition $p_{y \to x} = p_{\tilde{y} \to \tilde{x}}$ and the antisymmetry $s(\tilde{x}) = - s(x)$,  we see that the two terms in Eq. \eqref{eq:app_a:resp_s} are identical, i.e.,
\begin{align}
    \frac{1}{2} \sum_{xy} p_{y \to x} q(y) \left[e^{s(y) - s(x)} - (s(y) - s(x)) - 1 \right] & = \frac{1}{2} \sum_{xy} p_{y \to x} q(\tilde{y}) \left[e^{s(\tilde{y}) - s(\tilde{x})} - (s(\tilde{y}) - s(\tilde{x})) - 1 \right] \nonumber \\
    & =  \frac{1}{2} \sum_{xy} p_{y \to x} p(y) \left[e^{s(x) - s(y)} - (s(x) - s(y)) - 1 \right]
.\end{align}

\subsubsection{Proof of the lower bound}

Starting from the result \eqref{eq:app_a:resp_s}, it suffices to use the inequality $e^z \geq z + 1$ to confirm nonnegativity of $\mathcal{R}^\eps$. To get a stronger lower bound in terms of
\begin{equation}
\Delta s_\text{min} = \min_{x \neq y} |s(x) - s(y)|
,\end{equation}
we include the second-order term in the expansion $e^z - z -1 \geq z^2/2$, valid for real $z$, which yields
\begin{align}
\mathcal{R}^\eps 
     & = \sum_{x,y \neq x} p_{y \to x} p(y) \left[e^{s(x) - s(y)} - (s(x) - s(y)) - 1 \right]
     \geq \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} p(y) \left( s(x) - s(y) \right)^2 \nonumber \\
     & \geq \frac{1}{2} (1 - \sum_y p(y) p_{y \to y}) \Delta s_\text{min}^2
.\end{align}
These results correspond to the respective bounds involving $\mathcal{R}^\eps_{\text{l.r.}}$ and $\mathcal{R}^\eps_{\text{min}} (\Delta s_\text{min})$ in the inequalities \eqref{eq:multitr:inequalities} and \eqref{eq:num:lb}.

\subsubsection{Proof of the upper bound}

Again, we start from Eq. \eqref{eq:app_a:resp_s}, which can be rewritten as
\begin{align}
    \mathcal{R}^\eps = \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} \left[ \left(p(y) - p(\rev{y}) \right) \left(s(y) - s(x) \right) + \left( - p(y) - p(\rev{y}) + p(y) e^{s(x) - s(y)} + p(\rev{y}) e^{s(y) - s(x)}  \right) \right]
.\end{align}
We discuss the two terms in the square brackets separately. First, since $s(y) = \ln[p(y)/p(\rev{y})]$, we have
\begin{equation}
    p(y) - p(\rev{y}) = \left(p(y) + p(\rev{y}) \right) \frac{e^{s(y)} - 1}{e^{s(y)} + 1} = \left(p(y) + p(\rev{y}) \right) \tanh \left( \frac{s(y)}{2} \right)
    \label{eq:app_a:upper:aux0}
.\end{equation}
This identity can be used to rewrite the term
\begin{align}
    \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} (p(y) - p(\rev{y}))(s(y) - s(x)) & = \frac{1}{2} \sum_{x,y \neq x} \left(p(y) + p(\rev{y}) \right) \tanh \left( \frac{s(y)}{2} \right) (s(y) - s(x))  \nonumber \\
    & \leq \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} \left(p(y) + p(\rev{y}) \right) \tanh \left( \frac{|s(y)|}{2} \right) |s(y) - s(x)|  \nonumber \\
    & \leq \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} \left(p(y) + p(\rev{y}) \right) \tanh \left( \frac{\smax}{4} \right) \smax  \nonumber \\
    & = 2 \left( \tanh \frac{\smax}{4} \right) \frac{\smax}{2} 
    \label{eq:app_a:upper:aux2}
.\end{align}
The first inequality involves taking the absolute value of each term, whereas the second one makes use of $\smax = \max_{x,y} |s(x) - s(y)| = 2 \max_{x} |s(x)|$. In passing to the final line, we use normalization in the form $\sum_{x,y \neq x} p_{y \to x} p(y) = \sum_{x,y \neq x} p_{y \to x} p(\rev{y}) = 1$.

Let us now discuss the second term, 
\begin{equation}
    R := \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} \left[ - p(y) - p(\rev{y}) + p(y) e^{s(x) - s(y)} + p(\rev{y}) e^{s(y) - s(x)}  \right]
    \label{eq:app_a:upper:aux1}
.\end{equation}
By using $p(y) e^{- s(y)} = p(\rev{y})$ and $p(\rev{y}) e^{s(y)} = p(y)$, the expression inside the square brackets can be rewritten as
\begin{align}
    - p(y) - p(\rev{y}) + & \, p(y) e^{s(x) - s(y)} + p(\rev{y}) e^{s(y) - s(x)} = 2 \sinh \frac{s(x)}{2} \left[  p(\rev{y}) e^{\frac{s(x)}{2}} - p(y) e^{- \frac{s(x)}{2}} \right] \nonumber \\
    & = 2 \sinh \frac{s(x)}{2} \left[ (p(\rev{y}) - p(y)) \cosh \frac{s(x)}{2} + (p(\rev{y}) + p(y)) \sinh \frac{s(x)}{2} \right] \nonumber \\
    & = 2 \sinh \frac{s(x)}{2} \cosh \frac{s(x)}{2} (p(\rev{y}) - p(y))  + 2 \sinh^2 \frac{s(x)}{2}  (p(\rev{y}) + p(y))
.\end{align}
We now make use of the identity $2 \sinh \frac{t}{2} \cosh \frac{t}{2} = \sinh t$ and its reformulation $2 \sinh^2 \frac{t}{2} = \tanh \frac{t}{2} \sinh t$ for $t = s(x)$. Substituting the result into Eq. \eqref{eq:app_a:upper:aux1}, we obtain
\begin{align}
    R = & \, \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} \left[ (p(\rev{y}) - p(y)) \sinh s(x) + (p(\rev{y}) + p(y)) \tanh \frac{s(x)}{2} \sinh s(x) \right] \nonumber \\
    = & \, \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} (p(\rev{y}) + p(y)) \sinh s(x) \left[- \tanh \frac{s(y)}{2} + \tanh \frac{s(x)}{2}  \right]
    %\label{eq:app_a:upper:aux1}
\end{align}
after using Eq. \eqref{eq:app_a:upper:aux0}. This expression can be bounded by its absolute value, which results in the bound
\begin{align}
    R \leq \frac{1}{2} \sum_{x,y \neq x} p_{y \to x} (p(\rev{y}) + p(y)) \sinh |s(x)| \left[\tanh \frac{|s(y)|}{2} + \tanh \frac{|s(x)|}{2}  \right]
    \leq 2 \sinh \frac{\smax}{2} \tanh \frac{\smax}{4}
\end{align}
after identifying the upper bound in terms of $\smax = \max_{x,y} |s(x) - s(y)| = 2 \max_{x} |s(x)|$ and using normalization $\sum_{x,y \neq x} p_{y \to x} p(y) = \sum_{x,y \neq x} p_{y \to x} p(\rev{y}) = 1$. Combining this result and Eq. \eqref{eq:app_a:upper:aux2}, we obtain the upper bound
\begin{align}
    \mathcal{R}^\eps \leq \mathcal{R}^\eps_{\text{max}} (\Delta s_\text{max}) = 2 \tanh \frac{\smax}{4} \left( \frac{\smax}{2} + \sinh \frac{\smax}{2} \right)
\end{align}
stated as Eq. \eqref{eq:multitr:inequalities} in the main text. 

In the case of the one-dimensional asymmetric random walk, there are only two possible transitions, i.e., $x,y = \pm$. Additionally, there are no degrees of freedom in $p_{x\to y}$, so that
\begin{align}
    p_{y\to x} = \begin{cases} 1 \quad & x=+, y=- \text{ or } y=+, x=- \\ 0 \quad & \text{ else} \end{cases}
.\end{align}
Additionally, $\ln [p(+)/p(-)] = s = \max_{x,y} |s(x) - s(y)|/2 = \Delta s_\text{max}/2$ and its negative are the only nontrivial affinities, so that one can confirm that the inequalities in the derivation of $\mathcal{R}^\eps \leq \mathcal{R}^\eps_{\text{max}} (\Delta s_\text{max})$ become equalities. Thus, we obtain
\begin{align}
    \mathcal{R}^\eps = 2 \tanh \frac{s}{2} \left( s + \sinh s \right)
\end{align}
for the asymmetric random walk.

\subsection{Appendix E: Simulation parameters}

This section presents the model parameters used in the simulations that generate the data shown in Figures 1 and 2 in the main paper.

\subsubsection{Figure 1}

For a given number $n = 1, 2, 3, 10$ of transition pairs, we generate $N = 5 \cdot 10^4$ systems with $p(x) = u(x)/\sum_x u(x)$ and i.i.d. $u(x)$ chosen from a uniform distribution $U(0,1)$. The error matrix is created according to $p_{y \to x} = u(y,x)/(\sum_x u(y,x))$ to ensure normalization. The $u(y,x)$ satisfy $u(y,x) = 0$ if $x = y$, $u(y,x) = u(\rev{y},\rev{x})$ to respect the symmetry condition (main text, Eq. (3)) and are otherwise i.i.d. and chosen from a uniform distribution $U(0,1)$. 

\subsubsection{Figure 2}

The microscopic model has the topology depicted in Fig. 2 (a). Transition rates $k_{ij}$ from state $i$ to state $j$ are given as $k_{31} = k_{12} = k_{24} = 2$, $k_{13} = k_{21} = k_{42} = 3$, $k_{46} = k_{64} = k_{65} = k_{56} = k_{53} = k_{35} = 0.4$. A variable affinity $f$ (in units of energy per $k_BT$) is applied at the transition $3 \to 4$, which must be incorporated into the model such that $\ln (k_{34}/k_{43}) = f$. In this model, we parametrize the transition rates as $k_{34}(f) = 3 \exp(f/2)$ and $k_{43}(f) = 2 \exp(-f/2)$. The error matrix $p_y \to x$ is given by
\begin{equation}
    p_{y \to x} = \begin{cases}
        0.6 \quad & x = \rev{y} \\
        0 \quad & x = y \\
        0.1 \quad & \text{else} \\
    \end{cases}
,\end{equation}
i.e., an erroneously detected transition has a higher probability to be detected as its reverse than to be detected as any of the other ones. The estimator for entropy production, 
\begin{equation}
    \hat{\sigma}^\eps = \sum_{IJ} p^\eps(I) \pi^\eps_{I \to J} \ln \frac{\pi^\eps_{I \to J}}{\pi^\eps_{\rev{J} \to \rev{I}}}
,\end{equation}
is evaluated as discussed in Appendix A in the End Matter, with the explicit expression for $\pi^\eps_{I \to J} = p^\eps(IJ)/p^\eps(I)$ (cf. Eq. \eqref{eq:end:p_split_eps}) given by
\begin{align}
    \pi^\eps_{I \to J} = \frac{(1 - \eps)^2 p(I) \pi_{I \to J} + \eps (1-\eps) \sum_X \left(p(I) \pi_{I \to X} p_{X \to J} + p(X) \pi_{X \to J} p_{X \to I}  \right) + \eps^2 \sum_{X,Y} p(X) \pi_{X \to Y} p_{X \to I} p_{Y \to J}}{(1 - \eps) p(I) + \eps \sum_X p(X) p_{X \to I}}
.\end{align}
The summation over the individual paths was performed according to Eq. \eqref{eq:end:decomposition} was performed up to $n = 5$, i.e., includes snippets with up to $5$ consecutive errors. Adding all contributions together, we numerically confirm that $\sum_{n = 0}^5 \sigma_n$ deviates from the true value $\sigma$ by less than $0.5\%$ relative error.

