\section{Tweedie's formula}
	For Tweedie's formula, we consider a random variable $v$, conditioned on a random variable $x$, such that
	\begin{equation}
		v\vert x = x+\varepsilon, \quad \varepsilon \sim \mathcal{N}(0,\sigma_0^2),
	\end{equation}
	which implies the conditional pdf
	\begin{equation}
		p(v\vert x) = \frac{1}{\sqrt{2\pi}\sigma_0}\exp\left(-\frac{1}{2} \left(\frac{v-x}{\sigma_0}\right)^2\right).
	\end{equation}
	We wish to compute 
	\begin{equation}
		\frac{\text{d}}{\text{d}v} \log p(v) = \frac{1}{p(v)}\frac{\text{d}}{\text{d}v}p(v).
	\end{equation}
	Using the fact that
	\begin{equation}
		p(v) = \int_{-\infty}^\infty p(v\vert x)p(x)\text{d}x,
	\end{equation}
	we find
	\begin{equation}
		\frac{\text{d}}{\text{d}v}p(v) = \int_{-\infty}^\infty\frac{x-v}{\sigma_0^2}p(v\vert x)p(x)\text{d}x.
	\end{equation}
	Thus
	\begin{equation}
		\frac{\text{d}}{\text{d}v} \log p(v) =  \int_{-\infty}^\infty\frac{x-v}{\sigma_0^2}
		\frac{p(v\vert x)p(x)}{p(v)}\text{d}x,
	\end{equation}
	which simplifies to
	\begin{equation}
		\frac{\text{d}}{\text{d}v} \log p(v) =  \int_{-\infty}^\infty\frac{x-v}{\sigma_0^2}
		p(x\vert v)\text{d}x,
	\end{equation}
	since
	\begin{equation}
		\frac{p(v\vert x)p(x)}{p(v)} = \frac{\frac{p(v, x)}{p(x)}p(x)}{p(v)}
		=\frac{p(v, x)}{p(v)} = p(x\vert v).
	\end{equation}
	Distributing the integral leads to
	\begin{equation}
		\frac{\text{d}}{\text{d}v} \log p(v) =  \frac{1}{\sigma_0^2}
		\int_{-\infty}^\infty x p(x\vert v)\text{d}x
		-v \int_{-\infty}^\infty  p(x\vert v)\text{d}x
		= \frac{1}{\sigma_0^2} \left( E[x\vert v] -v \right),
	\end{equation}
	which, upon rearrangement, gives Tweedie's formula:
	\begin{equation}
		E[x\vert v] = v+\sigma_0^2 \frac{\text{d}}{\text{d}v} \log(p(v)).
	\end{equation}


\section{Solution to the SDE in (\ref{reverse3})}
\label{app:sdeClimo}
	We begin with (\ref{reverse3}) and perform a few simple manipulations:
	\begin{align}
		\label{rever3}
		\text{d}v &= -\frac{2}{t}\left[\frac{\frac{r}{1+r}}{\frac{r}{1+r}+t^2}v+\frac{\frac{t^2}{1+r}}{\frac{r}{1+r}+t^2}y-v\right]\text{d}t + \sqrt{2t}\text{d}\overline{\beta}_t,\\
		\label{rever4}
		\text{d}v &= -\frac{2}{t}\Big[-\frac{t^2}{\frac{r}{1+r}+t^2}v+\frac{\frac{t^2}{1+r}}{\frac{r}{1+r}+t^2}y\Big]\text{d}t + \sqrt{2t}\text{d}\overline{\beta}_t,\\
		\label{rever5}
		\text{d}v - 2t\frac{1}{\frac{r}{1+r}+t^2}v\text{d}t &= -2t\frac{\frac{1}{1+r}}{\frac{r}{1+r}+t^2}y\text{d}t + \sqrt{2t}\text{d}\overline{\beta}_t,\\
		\label{rever6}
		\frac{1}{\frac{r}{1+r}+t^2}\text{d}v - 2t\frac{1}{(\frac{r}{1+r}+t^2)^2}v\text{d}t &= -2t\frac{\frac{1}{1+r}}{(\frac{r}{1+r}+t^2)^2}y\text{d}t + \frac{\sqrt{2t}}{\frac{r}{1+r}+t^2}\text{d}\overline{\beta}_t.
	\end{align}
	\begin{equation}
		\label{rever7}
		d\Big(\frac{1}{\frac{r}{1+r}+t^2}v\Big) = -2t\frac{\frac{1}{1+r}}{(\frac{r}{1+r}+t^2)^2}y\text{d}t + \frac{\sqrt{2t}}{\frac{r}{1+r}+t^2}\text{d}\overline{\beta}_t.
	\end{equation} 
	Integrating backwards in time, from $T$ to $0$,
	\begin{equation}
		\begin{split}
			\int_{T}^{0}\text{d}\left(\frac{1}{\frac{r}{1+r}+t^2}v(t)\right)=-2y\int_{T}^{0}\frac{\frac{1}{1+r}t}{(\frac{r}{1+r}+t^2)^2}\text{d}t + \int_{T}^{0}\frac{\sqrt{2t}}{\frac{r}{1+r}+t^2}\text{d}\overline{\beta}_t,
		\end{split}
	\end{equation}
	leads to an expression for $v$ at time 0:
	\begin{equation}
		\label{eq:v0Early}
		\begin{split}
			v(0) = \frac{\frac{r}{1+r}}{\frac{r}{1+r}+T^2}v(T) -2y\frac{r}{(1+r)^2}\int_{T}^{0}\frac{t}{(\frac{r}{1+r}+t^2)^2}\text{d}t + \frac{r}{1+r}\int_{T}^{0}\frac{\sqrt{2t}}{\frac{r}{1+r}+t^2}\text{d}\overline{\beta}_t
		\end{split}.
	\end{equation}
	Using the change-of-variable, $s = \frac{r}{1+r}+t^2$, one can show that
	\begin{equation}
		\label{intRule}
		2\int_{T}^{0}\frac{t}{(\frac{r}{1+r}+t^2)^2}\text{d}t = -\frac{T^2}{\frac{r}{1+r}(\frac{r}{1+r}+T^2)}.
	\end{equation}
	Using this result in~\eqref{eq:v0Early} simplifies the expression to
	\begin{equation}
		\begin{split}
			v(0) = \frac{\frac{r}{1+r}}{\frac{r}{1+r}+T^2}v(T) + \frac{r}{(1+r)^2}\frac{T^2}{\frac{r}{1+r}(\frac{r}{1+r}+T^2)}y + \frac{r}{1+r}\int_{T}^{0}\frac{\sqrt{2t}}{\frac{r}{1+r}+t^2}\text{d}\overline{\beta}_t
		\end{split},
	\end{equation}
	which is the desired result.



\section{Solution to the SDE in (\ref{rev3})}
\label{app:sdeIter}
	To solve the SDE
	\begin{equation}
		\label{reve3}
		\text{d}v = -\frac{2}{t}\Big[\frac{\frac{\alpha^jr}{\alpha^j+r}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}(v-\overline{x})+\frac{\frac{\alpha^jt^2}{\alpha^j+r}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}(y-\overline{x})-(v-\overline{x})\Big]\text{d}t + \sqrt{2t}\text{d}\overline{\beta}_t,
	\end{equation}
	we re-write it as
	\begin{equation}
		\label{rev4}
		\text{d}v = -\frac{2}{t}\Big[-\frac{t^2}{\frac{\alpha^jr}{\alpha^j+r}+t^2}(v-\overline{x})+\frac{\frac{\alpha^jt^2}{\alpha^j+r}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}(y-\overline{x})\Big]\text{d}t + \sqrt{2t}\text{d}\overline{\beta}_t,
	\end{equation}
	and use the change of variables $v' = v - \overline{x}$ to obtain
	\begin{equation}
		\label{rev5}
		\text{d}v' - 2t\frac{1}{\frac{\alpha^jr}{\alpha^j+r}+t^2}v'\text{d}t = -2t\frac{\frac{\alpha^j}{\alpha^j+r}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}(y-\overline{x})\text{d}t + \sqrt{2t}\text{d}\overline{\beta}_t.
	\end{equation}
	A few simple manipulations yield
	\begin{align}
		\label{rev6}
		\frac{1}{\frac{\alpha^jr}{\alpha^j+r}+t^2}\text{d}v' - 2t\frac{1}{(\frac{\alpha^jr}{\alpha^j+r}+t^2)^2}v'\text{d}t &= -2t\frac{\frac{\alpha^j}{\alpha^j+r}}{(\frac{\alpha^jr}{\alpha^j+r}+t^2)^2}(y-\overline{x})\text{d}t + \frac{\sqrt{2t}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}\text{d}\overline{\beta}_t,\\
		\label{rev7}
		d\Big(\frac{1}{\frac{\alpha^jr}{\alpha^j+r}+t^2}v'\Big) &= -2t\frac{\frac{\alpha^j}{\alpha^j+r}}{(\frac{\alpha^jr}{\alpha^j+r}+t^2)^2}(y-\overline{x})\text{d}t + \frac{\sqrt{2t}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}\text{d}\overline{\beta}_t.
	\end{align} 
	Integrating backwards in time, from $T$ to $0$,
	\begin{equation}
		\begin{split}
			\int_{T}^{0}d\Bigg(\frac{1}{\frac{\alpha^jr}{\alpha^j+r}+t^2}v'(t)\Bigg)=-2(y-\overline{x})\int_{T}^{0}\frac{\frac{\alpha^j}{\alpha^j+r}t}{(\frac{\alpha^jr}{\alpha^j+r}+t^2)^2}\text{d}t + \int_{T}^{0}\frac{\sqrt{2t}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}\text{d}\overline{\beta}_t,
		\end{split}
	\end{equation}
	yields
	\begin{equation}
		\begin{split}
			v'(0) = \frac{\frac{\alpha^jr}{\alpha^j+r}}{\frac{\alpha^jr}{\alpha^j+r}+T^2}v'(T) -2(y-\overline{x})\frac{(\alpha^j)^2r}{(\alpha^j+r)^2}\int_{T}^{0}\frac{t}{(\frac{\alpha^jr}{\alpha^j+r}+t^2)^2}\text{d}t + \frac{\alpha^jr}{\alpha^j+r}\int_{T}^{0}\frac{\sqrt{2t}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}\text{d}\overline{\beta}_t.
		\end{split}
	\end{equation}
	Making use of (\ref{intRule}) gives us
	\begin{equation}
		\begin{split}
			v'(0) = \frac{\frac{\alpha^jr}{\alpha^j+r}}{\frac{\alpha^jr}{\alpha^j+r}+T^2}v'(T) + \frac{(\alpha^j)^2r}{(\alpha^j+r)^2}\frac{T^2}{\frac{\alpha^jr}{\alpha^j+r}(\frac{\alpha^jr}{\alpha^j+r}+T^2)}(y-\overline{x}) + \frac{\alpha^jr}{\alpha^j+r}\int_{T}^{0}\frac{\sqrt{2t}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}\text{d}\overline{\beta}_t.
		\end{split}
	\end{equation}       
	Undoing the change of variables finally yields
	\begin{equation}
		\begin{split}
			v(0) = \overline{x} + \frac{\frac{\alpha^jr}{\alpha^j+r}}{\frac{\alpha^jr}{\alpha^j+r}+T^2}(v(T)-\overline{x}) + \frac{(\alpha^j)^2r}{(\alpha^j+r)^2}\frac{T^2}{\frac{\alpha^jr}{\alpha^j+r}(\frac{\alpha^jr}{\alpha^j+r}+T^2)}(y-\overline{x}) + \frac{\alpha^jr}{\alpha^j+r}\int_{T}^{0}\frac{\sqrt{2t}}{\frac{\alpha^jr}{\alpha^j+r}+t^2}\text{d}\overline{\beta}_t,
		\end{split}
	\end{equation} 
	which is the desired result.

