\section{Appendix}

\subsection{Derivation}
\label{A.1}

\paragraph{Variance Reduction in Deep Ensemble.}
Assume \(\mathbf{Var}[f_i(x)] = \sigma^2\) and \(\mathbf{Cov}[f_i, f_j] = \rho \sigma^2\) for $i \neq j$. Define the ensemble predictor as
\[
\bar{f}(x) = \frac{1}{m} \sum_{i=1}^{m} f_i(x).
\]
I then derive:
\begin{align}
\mathbf{Var}[\bar{f}(x)] &= \mathbf{Var}\!\Bigl[\frac{1}{m} \sum_{i=1}^m f_i(x)\Bigr] \\
&= \Bigl(\frac{1}{m}\Bigr)^2 \!\Bigl[\sum_{i=1}^m \mathbf{Var}\!\Bigl[f_i(x)\Bigr] + \sum_{i \neq j} \mathbf{Cov}\!\Bigl[f_i(x), f_j(x)\Bigr]\Bigr] \\
&= \Bigl(\frac{1}{m}\Bigr)^2 \Bigl[ m\sigma^2 + 2\Bigl(\frac{m(m-1)}{2}\Bigr)\rho\sigma^2 \Bigr]\\
&= \Bigl(\frac{1}{m}\Bigr)^2 \Bigl[ m\sigma^2 + m(m-1)\rho\sigma^2 \Bigr]\\
&= \frac{\sigma^2\bigl(1 + (m-1)\rho\bigr)}{m}.
\end{align}
Thus, if \(\rho < 1\), the overall variance decreases as \(m\) increases.

